// Italian translations of QUESTION_BANK, keyed by question id — managed with scripts/translations.js.
// AWS service and feature names stay in English. h = hash of the English text the translation was made from.

const QUESTION_BANK_IT = {
  "1": {"h":"22f5f6dd","question":"Un'azienda sta valutando di spostare i workload del proprio data center on-premises nel Cloud AWS. L'azienda vuole evitare il costo di acquisto e manutenzione dei server fisici. Quale vantaggio del cloud computing rappresenta MEGLIO questa situazione?","options":["Sostituire le spese di capitale fisse con spese variabili a consumo","Aumentare velocità e agilità nel provisioning di nuove risorse","Diventare globali in pochi minuti con deployment nelle Region di tutto il mondo","Smettere di spendere denaro per gestire e mantenere data center"],"explanation":"Uno dei sei vantaggi del cloud computing è «Smettere di spendere denaro per gestire e mantenere data center». Passando ad AWS, le aziende eliminano l'onere operativo dell'infrastruttura fisica. Anche «Sostituire le spese fisse con spese variabili» è un vantaggio valido del cloud, ma riguarda il modello di costo piuttosto che l'eliminazione dell'onere di manutenzione.","optionExplanations":["«Sostituire le spese di capitale fisse con spese variabili a consumo» riguarda il modello di pagamento (CapEx vs. OpEx): non descrive specificamente l'eliminazione del costo di acquisto e manutenzione dei server fisici.","«Aumentare velocità e agilità nel provisioning di nuove risorse» si riferisce a provisioning e sperimentazione più rapidi: riguarda il time-to-market, non l'onere di mantenere l'infrastruttura fisica.","«Diventare globali in pochi minuti con deployment nelle Region di tutto il mondo» si riferisce al deployment rapido nelle Region a livello mondiale: riguarda la copertura geografica, non l'eliminazione dei costi di manutenzione del data center.","Corretto — «Smettere di spendere denaro per gestire e mantenere data center» risponde direttamente al desiderio di evitare l'acquisto e la manutenzione di server fisici passando ad AWS."]},
  "2": {"h":"06fb95cd","question":"Una startup deve lanciare rapidamente una nuova applicazione. L'azienda non è sicura della domanda futura e non vuole sovradimensionare l'infrastruttura. Quale vantaggio del cloud computing risponde MEGLIO a questa esigenza?","options":["Alta disponibilità","Smettere di indovinare la capacità","Economie di scala","Sostituire le spese di capitale con spese operative"],"explanation":"«Smettere di indovinare la capacità» è un vantaggio fondamentale del cloud: si può scalare verso l'alto o verso il basso in base alla domanda effettiva, eliminando il rischio di sovradimensionamento (spesa sprecata) o sottodimensionamento (prestazioni scadenti). Auto Scaling e le risorse on-demand incarnano questo vantaggio.","optionExplanations":["L'alta disponibilità garantisce che il sistema resti accessibile, ma non risolve il problema della domanda futura incerta e del rischio di sovradimensionamento.","Corretto — «Smettere di indovinare la capacità» significa usare Auto Scaling e risorse on-demand per adeguare la capacità alla domanda effettiva, eliminando lo spreco da sovradimensionamento e il rischio di sottodimensionamento.","Le «Economie di scala» si riferiscono ai prezzi più bassi grazie al potere d'acquisto aggregato di AWS: non riguardano l'adeguamento dell'infrastruttura a una domanda incerta.","«Sostituire le spese di capitale con spese operative» si riferisce al cambiamento del modello di pagamento: non risolve specificamente il problema di incertezza sulla capacità descritto."]},
  "3": {"h":"b82b72e6","question":"Un'azienda vuole effettuare il deployment della propria applicazione in più paesi per servire i clienti con bassa latenza. In passato, predisporre l'infrastruttura in un nuovo paese richiedeva mesi. Quale vantaggio del Cloud AWS evidenzia questo scenario?","options":["Economie di scala","Elasticità","Diventare globali in pochi minuti","Tolleranza ai guasti"],"explanation":"AWS dispone di infrastruttura in Region in tutto il mondo. Il deployment in una nuova Region richiede solo pochi clic e può essere completato in pochi minuti, rispetto ai mesi necessari per un'espansione globale on-premises. Questo è il vantaggio «Diventare globali in pochi minuti» del cloud computing.","optionExplanations":["Le «Economie di scala» descrivono i prezzi più bassi dovuti alla base clienti aggregata di AWS: riguardano i costi, non la velocità di deployment dell'infrastruttura globale.","L'«Elasticità» si riferisce all'aumento e alla riduzione automatica della capacità: riguarda l'adeguamento delle risorse alla domanda, non la velocità di espansione geografica.","Corretto — «Diventare globali in pochi minuti» descrive la capacità di AWS di effettuare il deployment di applicazioni nelle Region di tutto il mondo in pochi minuti, eliminando i mesi di approvvigionamento necessari per un'espansione globale on-premises.","La «Tolleranza ai guasti» indica un sistema che continua a funzionare durante i guasti dei componenti: riguarda la resilienza, non la velocità di deployment globale."]},
  "4": {"h":"a2321e47","question":"Una banca regionale deve mantenere il proprio database bancario principale nel proprio data center per soddisfare le autorità di regolamentazione. Vuole realizzare una nuova app di mobile banking su AWS che legga e scriva dati in quel database on-premises. Come si definisce questo modello di deployment?","options":["Cloud pubblico","Cloud privato","Cloud ibrido","Multi-cloud"],"explanation":"La banca mantiene il database principale on-premises ed esegue la nuova app su AWS, con i due ambienti collegati che condividono i dati. Collegare l'infrastruttura on-premises con le risorse del Cloud AWS è un deployment cloud ibrido, comune quando normative o sistemi legacy mantengono alcuni workload on-premises.","optionExplanations":["La banca non esegue tutto nel cloud: il suo database principale deve restare nel proprio data center, quindi non si tratta di un modello esclusivamente di cloud pubblico.","Un cloud privato mantiene tutto su infrastruttura on-premises dedicata, ma la banca utilizza anche AWS per l'app mobile.","Corretto — la banca collega l'infrastruttura on-premises con le risorse AWS e condivide i dati tra loro, il che definisce un cloud ibrido.","Multi-cloud significa utilizzare più provider cloud. La banca combina il proprio data center con un unico provider, AWS."]},
  "5": {"h":"5cc47bd9","question":"Quale modello di servizio cloud offre ai clienti il MAGGIOR controllo sulle risorse sottostanti di calcolo, storage e rete?","options":["Software as a Service (SaaS)","Platform as a Service (PaaS)","Infrastructure as a Service (IaaS)","Function as a Service (FaaS)"],"explanation":"IaaS offre il massimo livello di flessibilità e controllo gestionale sulle risorse IT. I clienti gestiscono sistema operativo, middleware, runtime, dati e applicazioni. AWS EC2 ne è un esempio tipico. PaaS elimina la necessità di gestire l'infrastruttura sottostante e SaaS fornisce un'applicazione completa e gestita.","optionExplanations":["SaaS fornisce un'applicazione completamente gestita tramite internet: il provider gestisce tutto, dall'infrastruttura all'applicazione, lasciando al cliente il minor controllo.","PaaS fornisce una piattaforma per sviluppare applicazioni senza gestire l'infrastruttura sottostante: offre più controllo di SaaS ma meno di IaaS.","Corretto — IaaS offre il maggior controllo: il cliente gestisce sistema operativo, middleware, runtime, dati e applicazioni, mentre AWS gestisce solo l'hardware fisico e il livello di virtualizzazione.","FaaS (Function as a Service) esegue singole funzioni in un ambiente completamente gestito: il cliente gestisce solo la logica del codice, con un controllo sull'infrastruttura ancora minore rispetto a PaaS."]},
  "6": {"h":"6e105a93","question":"Uno sviluppatore vuole realizzare ed effettuare il deployment di un'applicazione web senza gestire l'infrastruttura server sottostante, il sistema operativo o il runtime. Quale modello di servizio cloud soddisfa MEGLIO questo requisito?","options":["Infrastructure as a Service (IaaS)","Platform as a Service (PaaS)","Software as a Service (SaaS)","Hosting bare metal"],"explanation":"PaaS fornisce agli sviluppatori una piattaforma per realizzare, eseguire e gestire applicazioni senza la complessità di mantenere l'infrastruttura sottostante. AWS Elastic Beanstalk ne è un esempio: gli sviluppatori effettuano il deployment del codice e AWS gestisce l'infrastruttura.","optionExplanations":["IaaS richiede al cliente di gestire sistema operativo, runtime e middleware: lo sviluppatore dovrebbe comunque occuparsi dell'infrastruttura server, non solo del codice applicativo.","Corretto — PaaS fornisce una piattaforma gestita (ad es. AWS Elastic Beanstalk) in cui gli sviluppatori effettuano il deployment del codice senza gestire sistema operativo, runtime o infrastruttura server sottostanti.","SaaS fornisce un'applicazione completa tramite internet: lo sviluppatore utilizzerebbe un'applicazione esistente, invece di realizzarne e distribuirne una propria.","L'hosting bare metal fornisce accesso a server fisici: lo sviluppatore dovrebbe gestire hardware, sistema operativo e tutti i livelli software, l'opposto di quanto richiesto."]},
  "7": {"h":"bb635a6e","question":"Un sito di notizie utilizza Amazon CloudFront affinché i lettori di tutto il mondo carichino rapidamente immagini e video. CloudFront memorizza copie in cache di questi contenuti vicino ai lettori, invece di servire ogni richiesta dall'origine. In quale componente dell'infrastruttura globale AWS vengono memorizzate queste copie in cache?","options":["AWS Region","Availability Zone","Edge location","Local Zone"],"explanation":"CloudFront memorizza i contenuti in cache nelle edge location, siti presenti in molte città del mondo, distinti dalle Region e dalle Availability Zone. Servire le copie in cache dalla edge location più vicina a ciascun lettore riduce la latenza e il carico sull'origine.","optionExplanations":["Una Region è il luogo in cui vengono eseguiti l'origine e i workload principali del sito. CloudFront esiste proprio per evitare di inviare ogni richiesta alla Region, quindi la Region non è il luogo in cui vengono conservate le copie in cache.","Una Availability Zone è costituita da uno o più data center all'interno di una Region che ospitano l'applicazione distribuita. Non è il livello di caching di CloudFront vicino ai lettori.","Corretto — CloudFront memorizza i contenuti in cache nelle edge location vicine agli utenti, così i lettori vengono serviti da un sito vicino invece che dall'origine.","Una Local Zone esegue workload di calcolo e storage (come EC2) vicino a una specifica area metropolitana. Non è il luogo in cui CloudFront conserva i contenuti in cache."]},
  "8": {"h":"9b62a22c","question":"Un'azienda di e-commerce ha bisogno che la propria applicazione resti disponibile anche se un intero data center subisce un'interruzione di corrente. Quale concetto dell'infrastruttura AWS consente questa resilienza?","options":["AWS Regions","Availability Zones","Edge Locations","AWS Local Zones"],"explanation":"Ogni AWS Region è composta da più Availability Zone (AZ). Le AZ sono data center fisicamente separati all'interno di una Region, con alimentazione, raffreddamento e rete indipendenti. Il deployment su più AZ garantisce che un guasto in una AZ non blocchi l'intera applicazione.","optionExplanations":["Le AWS Region sono ampie aree geografiche che contengono più AZ: un guasto a livello di Region è estremamente raro, ma è il deployment su più AZ all'interno di una Region a fornire la protezione dai guasti del data center descritta.","Corretto — Le Availability Zone sono data center fisicamente separati con alimentazione e rete indipendenti. Il deployment su più AZ garantisce che l'interruzione di un data center non blocchi l'applicazione.","Le Edge Location servono per il caching dei contenuti (CloudFront): non ospitano i workload applicativi e non forniscono resilienza contro le interruzioni di corrente di un data center.","Le AWS Local Zone estendono il calcolo alle aree metropolitane per applicazioni a bassa latenza: non sono progettate per la resilienza generale su più data center."]},
  "9": {"h":"ecc7d5a9","question":"Quale pilastro dell'AWS Well-Architected Framework si concentra sulla capacità di un sistema di riprendersi dai guasti e di acquisire dinamicamente risorse per soddisfare la domanda?","options":["Security","Performance Efficiency","Reliability","Operational Excellence"],"explanation":"Il pilastro Reliability dell'AWS Well-Architected Framework si concentra sulla capacità di riprendersi da interruzioni dell'infrastruttura o dei servizi, di acquisire dinamicamente risorse per soddisfare la domanda e di mitigare interruzioni come configurazioni errate o problemi di rete temporanei.","optionExplanations":["Il pilastro Security si concentra sulla protezione di dati, sistemi e asset tramite gestione delle identità, controlli di rilevamento e protezione dei dati, non sul ripristino dai guasti o sullo scaling dinamico delle risorse.","Il pilastro Performance Efficiency si concentra sull'uso efficiente delle risorse di calcolo e sul mantenimento dell'efficienza al variare della domanda, non specificamente sul ripristino dai guasti.","Corretto — Il pilastro Reliability si concentra sulla capacità di un sistema di riprendersi dai guasti, acquisire dinamicamente risorse per soddisfare la domanda e mitigare le interruzioni.","Il pilastro Operational Excellence si concentra sull'esecuzione e il monitoraggio dei sistemi, sull'automazione delle modifiche e sul miglioramento continuo dei processi, non sul ripristino dai guasti dell'infrastruttura."]},
  "10": {"h":"38bf4871","question":"Un'azienda vuole progettare la propria architettura cloud in modo che i workload adeguino automaticamente la capacità per mantenere prestazioni stabili e prevedibili al minor costo possibile. Quale concetto del cloud descrive MEGLIO questa situazione?","options":["Alta disponibilità","Tolleranza ai guasti","Elasticità","Durabilità"],"explanation":"L'elasticità è la capacità di scalare automaticamente le risorse verso l'alto o verso il basso in base alla domanda effettiva. Ciò evita il sovradimensionamento (spreco di costi) e il sottodimensionamento (degrado delle prestazioni). AWS Auto Scaling è il servizio principale che fornisce elasticità.","optionExplanations":["L'alta disponibilità garantisce che un sistema resti accessibile con tempi di inattività minimi: riguarda uptime e ridondanza, non l'adeguamento automatico della capacità alla domanda.","La tolleranza ai guasti indica che un sistema continua a funzionare anche quando i componenti si guastano: riguarda la resilienza durante i guasti, non l'adeguamento della capacità per ottimizzare prestazioni e costi.","Corretto — L'elasticità è la capacità di scalare automaticamente le risorse verso l'alto o verso il basso in base alla domanda, evitando lo spreco da sovradimensionamento e i problemi di prestazioni da sottodimensionamento.","La durabilità si riferisce alla persistenza dei dati (ad es. la durabilità del 99,999999999% di S3): riguarda la protezione dei dati dalla perdita, non l'adeguamento della capacità di calcolo."]},
  "11": {"h":"3bed6747","question":"Il team operativo di un'azienda vuole migliorare la gestione quotidiana dei propri workload AWS. Intende documentare le procedure come runbook, apportare modifiche piccole e frequenti e svolgere una revisione dopo ogni incidente, così da migliorare continuamente i propri processi. Quale pilastro dell'AWS Well-Architected Framework fornisce indicazioni per questi obiettivi?","options":["Reliability","Operational Excellence","Performance Efficiency","Cost Optimization"],"explanation":"Il pilastro Operational Excellence riguarda l'esecuzione e il monitoraggio dei sistemi per generare valore di business e il miglioramento continuo dei processi e delle procedure di supporto. Runbook, modifiche piccole e frequenti e l'apprendimento da ogni evento operativo sono pratiche fondamentali di questo pilastro.","optionExplanations":["Reliability si concentra sul ripristino di un workload dai guasti e sul soddisfacimento della domanda. Non è il pilastro incentrato su runbook, pratiche di gestione delle modifiche e miglioramento dei processi dopo gli incidenti.","Corretto — Operational Excellence riguarda il modo in cui il team esegue e monitora i workload, apporta modifiche piccole e frequenti e impara dagli incidenti per migliorare continuamente le proprie procedure.","Performance Efficiency si concentra sulla selezione e sull'uso efficiente delle risorse al variare della domanda, non sulle procedure operative e sulle revisioni post-incidente.","Cost Optimization si concentra sull'evitare spese inutili, non sul modo in cui il team gestisce le operazioni e migliora i propri processi."]},
  "12": {"h":"1559ae38","question":"Grazie all'enorme scala di AWS, i clienti possono beneficiare di prezzi a consumo più bassi di quanto potrebbero ottenere da soli. Quale vantaggio del cloud computing rappresenta questa situazione?","options":["Aumentare velocità e agilità","Smettere di indovinare la capacità","Enormi economie di scala","Diventare globali in pochi minuti"],"explanation":"Poiché nel cloud viene aggregato l'utilizzo di centinaia di migliaia di clienti, AWS può ottenere economie di scala maggiori, che si traducono in prezzi a consumo più bassi. Le singole aziende non potrebbero ottenere da sole queste efficienze di costo.","optionExplanations":["«Aumentare velocità e agilità» si riferisce a provisioning e time-to-market più rapidi: non descrive la riduzione di prezzo derivante dal potere d'acquisto aggregato di AWS.","«Smettere di indovinare la capacità» si riferisce all'adeguamento delle risorse alla domanda effettiva: riguarda la pianificazione della capacità, non la riduzione dei costi derivante dalla scala aggregata.","Corretto — Le enormi economie di scala di AWS fanno sì che l'utilizzo aggregato di centinaia di migliaia di clienti permetta ad AWS di ottenere prezzi più bassi di quanto potrebbe fare qualsiasi singola organizzazione.","«Diventare globali in pochi minuti» si riferisce al deployment rapido nelle Region di tutto il mondo: riguarda la velocità geografica, non il vantaggio di costo derivante dalla scala aggregata."]},
  "13": {"h":"9ce899c9","question":"Un sistema progettato per continuare a funzionare anche quando uno o più componenti si guastano è descritto MEGLIO da quale delle seguenti definizioni?","options":["Altamente disponibile","Tollerante ai guasti","Elastico","Scalabile"],"explanation":"Tolleranza ai guasti significa che un sistema può continuare a funzionare correttamente anche quando alcuni dei suoi componenti si guastano. Alta disponibilità significa che un sistema è accessibile con tempi di inattività minimi, ma può subire brevi interruzioni. La tolleranza ai guasti implica nessuna interruzione durante il guasto di un componente.","optionExplanations":["Alta disponibilità significa che il sistema resta accessibile con tempi di inattività minimi, ma può avere brevi interruzioni durante il failover: non garantisce zero interruzioni quando i componenti si guastano.","Corretto — Tolleranza ai guasti significa che il sistema continua a funzionare correttamente anche quando uno o più componenti si guastano, senza interruzioni per l'utente finale.","Elastico significa che il sistema scala la capacità verso l'alto o verso il basso in base alla domanda: riguarda l'adeguamento delle risorse, non la continuità operativa nonostante i guasti dei componenti.","Scalabile significa che il sistema può gestire un carico maggiore aggiungendo risorse: riguarda la crescita della capacità, non la resilienza ai guasti dei componenti."]},
  "14": {"h":"e3d311c1","question":"Quale pilastro dell'AWS Well-Architected Framework raccomanda l'uso di servizi gestiti per ridurre l'onere operativo sull'infrastruttura?","options":["Cost Optimization","Reliability","Performance Efficiency","Operational Excellence"],"explanation":"Il pilastro Performance Efficiency include l'uso di architetture serverless e servizi gestiti per eliminare l'onere operativo della gestione dell'infrastruttura, consentendo ai team di concentrarsi sulla generazione di valore di business. Riguarda anche la scelta dei tipi di risorse adatti ai workload.","optionExplanations":["Cost Optimization si concentra sulla riduzione dei costi tramite right-sizing, prezzi con prenotazione ed eliminazione degli sprechi: non riguarda specificamente l'uso di servizi gestiti per ridurre l'onere operativo.","Reliability si concentra sul ripristino dai guasti e sullo scaling dinamico, non sulla scelta dei tipi di risorse o sull'uso di servizi gestiti per ridurre il carico di gestione dell'infrastruttura.","Corretto — Performance Efficiency include la democratizzazione delle tecnologie avanzate tramite servizi gestiti, l'eliminazione della necessità di gestire l'infrastruttura e la scelta dei tipi di risorse adatti.","Operational Excellence si concentra sull'esecuzione e il monitoraggio dei sistemi e sul miglioramento continuo dei processi, non specificamente sull'adozione di servizi gestiti per ridurre l'onere dell'infrastruttura."]},
  "15": {"h":"877ff24c","question":"Una startup sta realizzando il suo primo prodotto e non ha data center né server on-premises. Tutti i componenti dell'applicazione, inclusi calcolo, database e storage, verranno eseguiti su AWS fin dal primo giorno. Come si definisce questo modello di deployment?","options":["Cloud ibrido","Cloud privato","Cloud (cloud-native)","Multi-cloud"],"explanation":"Quando ogni componente di un'applicazione viene eseguito nel cloud e non esiste infrastruttura on-premises, il modello di deployment è cloud (detto anche cloud-native o all-in cloud). Le nuove applicazioni realizzate direttamente su AWS ne sono un esempio tipico.","optionExplanations":["Il cloud ibrido collega l'infrastruttura on-premises con il cloud, ma la startup non ha alcun server on-premises.","Un cloud privato funziona su infrastruttura dedicata, solitamente on-premises, che la startup non possiede.","Corretto — tutti i componenti vengono eseguiti su AWS senza infrastruttura on-premises, il che corrisponde al modello di deployment cloud (cloud-native).","Multi-cloud significa distribuire i workload su più provider cloud, ma la startup esegue tutto solo su AWS."]},
  "16": {"h":"0c3a0d32","question":"Da quali elementi infrastrutturali è composta una AWS Region?","options":["Più Edge Location collegate dalla rete globale privata di AWS","Due o più Availability Zone isolate collegate da reti a bassa latenza","Un unico grande data center con alimentazione, raffreddamento e rete ridondanti","Più Local Zone distribuite in un'area metropolitana"],"explanation":"Una AWS Region è composta da due o più Availability Zone fisicamente separate. Ogni AZ è costituita da uno o più data center distinti con alimentazione e rete ridondanti. Le AZ all'interno di una Region sono collegate da reti ad alta larghezza di banda e bassa latenza per consentire la replica sincrona.","optionExplanations":["Le Edge Location sono endpoint CDN per il caching dei contenuti vicino agli utenti: non sono gli elementi che compongono una AWS Region.","Corretto — Una Region è composta da due o più Availability Zone fisicamente separate (data center isolati) collegate da link privati ad alta larghezza di banda e bassa latenza.","Una AWS Region non è un singolo data center: è progettata intenzionalmente con più AZ fisicamente separate per fornire resilienza contro i guasti dei data center.","Le Local Zone estendono l'infrastruttura AWS alle aree metropolitane per il calcolo a bassa latenza: sono estensioni di una Region, non i componenti che ne definiscono la struttura."]},
  "17": {"h":"3ed8f9cb","question":"Quale pilastro dell'AWS Well-Architected Framework si concentra sull'evitare costi inutili e sull'uso dei tipi e delle dimensioni di risorse adeguati in base alla domanda effettiva?","options":["Reliability","Cost Optimization","Sustainability","Operational Excellence"],"explanation":"Il pilastro Cost Optimization si concentra sull'esecuzione dei sistemi al prezzo più basso. Tra i temi principali: comprendere la spesa, selezionare risorse convenienti, scalare per soddisfare la domanda e ottimizzare nel tempo, ad esempio usando Reserved Instances o effettuando il right-sizing delle istanze EC2.","optionExplanations":["Reliability si concentra sulla capacità di un sistema di riprendersi dai guasti e scalare dinamicamente, non sulla gestione dei costi o sulla scelta di tipi di risorse convenienti.","Corretto — Cost Optimization si concentra sull'evitare costi inutili, sul right-sizing delle risorse, sull'uso di modelli di prezzo appropriati (RI, Savings Plans) e sulla comprensione dell'andamento della spesa.","Sustainability si concentra sulla riduzione dell'impatto ambientale, non sulla gestione dei costi o sui prezzi delle risorse.","Operational Excellence si concentra sull'esecuzione, il monitoraggio e il miglioramento dei processi operativi, non sulla gestione dei costi o sulla scelta delle configurazioni di risorse più economiche."]},
  "18": {"h":"6536bc95","question":"Quale concetto del cloud si riferisce alla capacità di effettuare rapidamente il deployment di nuove applicazioni e portarle sul mercato più velocemente, riducendo il tempo dall'idea alla produzione da settimane o mesi a pochi minuti?","options":["Scalabilità","Agilità","Tolleranza ai guasti","Elasticità"],"explanation":"Agilità nel cloud significa che un'ampia gamma di tecnologie è disponibile on-demand: si possono avviare risorse e sperimentare in pochi minuti anziché in settimane. Ciò accelera l'innovazione perché il costo della sperimentazione è basso e il time-to-market si riduce drasticamente.","optionExplanations":["La scalabilità si riferisce alla capacità di aumentare o ridurre la capacità per gestire le variazioni di carico: riguarda la gestione della domanda, non un time-to-market più rapido o tempi di sperimentazione ridotti.","Corretto — Agilità significa che le risorse cloud possono essere predisposte in pochi minuti, riducendo drasticamente il tempo dall'idea alla produzione e abbassando il costo della sperimentazione.","La tolleranza ai guasti indica che un sistema continua a funzionare durante i guasti dei componenti: riguarda la resilienza, non la velocità di deployment di nuove applicazioni.","L'elasticità si riferisce all'adeguamento automatico delle risorse alla domanda: riguarda l'allineamento della capacità al workload, non l'accelerazione dei cicli di innovazione."]},
  "19": {"h":"c3e33097","question":"Una startup si prepara a lanciare il suo primo prodotto. I fondatori non vogliono spendere i propri fondi in server prima di sapere quanti clienti si iscriveranno e vogliono che i costi seguano l'utilizzo effettivo. Quale vantaggio del cloud computing risponde MEGLIO a questa esigenza?","options":["Elimina tutte le responsabilità di sicurezza a carico del cliente","Richiede un grande investimento iniziale in capacità","Sostituisce le spese di capitale con spese variabili","Garantisce un uptime del 100% per ogni servizio AWS"],"explanation":"Sostituire le spese di capitale con spese variabili significa che la startup non acquista server in anticipo. Paga solo per le risorse che utilizza effettivamente, quindi i costi crescono con il numero di clienti invece di essere impegnati in anticipo.","optionExplanations":["In base al modello di responsabilità condivisa il cliente deve comunque proteggere i propri dati, identità e configurazioni, quindi la responsabilità della sicurezza non viene eliminata. Inoltre non ha nulla a che fare con l'evitare spese iniziali.","È l'opposto di ciò che vogliono i fondatori. Un grande investimento iniziale è una caratteristica dei data center on-premises, non del cloud.","Corretto — Con il cloud la startup paga per ciò che utilizza invece di acquistare server prima di conoscere la domanda.","AWS non garantisce un uptime del 100%: i servizi hanno SLA e la resilienza dipende in parte dall'architettura del cliente. Inoltre non risolve il problema dei costi iniziali."]},
  "20": {"h":"a100fa73","question":"Quale servizio AWS fornisce una connessione costante e a bassa latenza tra il data center on-premises di un'azienda e AWS, evitando l'internet pubblico?","options":["AWS VPN","AWS Direct Connect","Amazon CloudFront","AWS Transit Gateway"],"explanation":"AWS Direct Connect stabilisce una connessione di rete privata dedicata tra il data center del cliente e AWS. Offre prestazioni di rete più costanti, latenza inferiore e potenzialmente una larghezza di banda maggiore rispetto alle connessioni via internet. È comunemente usato nelle architetture ibride.","optionExplanations":["AWS VPN crea un tunnel cifrato attraverso l'internet pubblico: non evita internet e non fornisce la larghezza di banda costante e dedicata di una connessione fisica privata.","Corretto — AWS Direct Connect fornisce un collegamento di rete privato e dedicato tra on-premises e AWS, evitando l'internet pubblico per ottenere prestazioni costanti e latenza inferiore.","Amazon CloudFront è una CDN che memorizza i contenuti in cache nelle Edge Location vicine agli utenti: non fornisce una connessione privata dedicata tra un data center e AWS.","AWS Transit Gateway collega VPC e reti on-premises tramite un hub centrale: è un servizio di routing e non stabilisce di per sé il collegamento fisico privato verso AWS."]},
  "21": {"h":"d261d47a","question":"In base allo AWS Shared Responsibility Model, quale delle seguenti attività è responsabilità di AWS?","options":["Configurare security group e network ACL","Gestire i dati del cliente e le chiavi di cifratura","Applicare le patch all'hypervisor e all'hardware fisico degli host","Impostare permessi e policy degli utenti IAM"],"explanation":"AWS è responsabile della «sicurezza DEL cloud»: infrastruttura fisica, hardware, rete e hypervisor. I clienti sono responsabili della «sicurezza NEL cloud»: configurazione dei security group, gestione degli utenti IAM, cifratura dei dati e applicazione delle patch ai sistemi operativi guest.","optionExplanations":["La configurazione di security group e network ACL è responsabilità del cliente («sicurezza NEL cloud»): AWS non configura mai la rete VPC per conto del cliente.","La gestione dei dati del cliente e delle chiavi di cifratura è sempre responsabilità del cliente: AWS fornisce gli strumenti (KMS) ma non gestisce mai quali dati archiviano i clienti né le loro chiavi di cifratura.","Corretto — L'applicazione delle patch all'hypervisor e all'hardware fisico degli host è responsabilità di AWS («sicurezza DEL cloud»). I clienti non intervengono mai sull'hardware fisico o sull'hypervisor.","L'impostazione di permessi e policy degli utenti IAM è responsabilità del cliente: AWS fornisce IAM ma non gestisce mai chi ha quali permessi all'interno dell'account di un cliente."]},
  "22": {"h":"e887dd14","question":"In base allo AWS Shared Responsibility Model, quale delle seguenti attività è SEMPRE responsabilità del cliente?","options":["Applicare le patch al sistema operativo host sottostante di Amazon RDS","Gestire i dati del cliente e controllarne l'accesso","Sicurezza fisica dei data center","Manutenzione dell'infrastruttura di rete e dell'hardware"],"explanation":"I clienti sono sempre responsabili dei propri dati, incluso chi vi ha accesso, come sono classificati e come sono cifrati. Anche con servizi completamente gestiti come RDS o S3, il cliente è proprietario dei propri dati e dei controlli di accesso, e ne è responsabile.","optionExplanations":["L'applicazione delle patch al sistema operativo host sottostante di Amazon RDS è responsabilità di AWS: RDS è un servizio gestito, quindi è AWS a occuparsi delle patch del sistema operativo, non il cliente.","Corretto — I clienti sono sempre responsabili dei propri dati (classificazione, controlli di accesso, cifratura), indipendentemente dal servizio AWS utilizzato.","La sicurezza fisica dei data center è sempre responsabilità di AWS: i clienti non hanno accesso alle strutture fisiche né alcuna responsabilità su di esse.","La manutenzione dell'infrastruttura di rete e dell'hardware è responsabilità di AWS: le apparecchiature di rete fisiche fanno parte del livello infrastrutturale gestito da AWS."]},
  "23": {"h":"07924817","question":"Il team di sicurezza di un'azienda richiede che le chiamate API AWS effettuate nell'account AWS vengano registrate a fini di audit. Quale servizio AWS dovrebbe utilizzare?","options":["Amazon CloudWatch","AWS Config","AWS CloudTrail","Amazon GuardDuty"],"explanation":"AWS CloudTrail registra le chiamate API effettuate nell'account AWS, inclusi identità del chiamante, ora, IP di origine, parametri della richiesta e risposta. È lo strumento principale per governance, conformità, audit operativo e audit dei rischi dell'account AWS.","optionExplanations":["Amazon CloudWatch monitora metriche e log per le prestazioni operative: non registra la cronologia delle chiamate API né l'identità di chi ha effettuato ogni chiamata.","AWS Config traccia le modifiche alla configurazione delle risorse nel tempo: monitora com'è configurata una risorsa, non le specifiche chiamate API e chi le ha effettuate.","Corretto — AWS CloudTrail registra ogni chiamata API con identità del chiamante, timestamp, IP di origine e parametri: è il servizio principale per l'audit e la registrazione delle chiamate API.","Amazon GuardDuty analizza i log di CloudTrail (tra gli altri) per rilevare minacce: utilizza i dati di CloudTrail ma non registra né archivia di per sé il log delle chiamate API."]},
  "24": {"h":"ce5adfb6","question":"Un'azienda assume uno stagista che deve solo leggere file da un bucket Amazon S3. L'amministratore crea una policy IAM che consente solo azioni di lettura su quel singolo bucket, senza altri permessi. Quale best practice di sicurezza sta applicando l'amministratore?","options":["Difesa in profondità","Privilegio minimo","Separazione dei compiti","Rete zero trust"],"explanation":"Privilegio minimo significa concedere solo i permessi di cui un utente o un'applicazione ha bisogno per svolgere il proprio lavoro. Limitare lo stagista all'accesso in sola lettura su un bucket riduce i danni in caso di uso improprio delle sue credenziali.","optionExplanations":["Difesa in profondità significa usare più livelli di controlli di sicurezza (rete, identità, dati). Non riguarda specificamente la limitazione dei permessi di un utente.","Corretto — Concedere allo stagista solo l'accesso in lettura all'unico bucket necessario è privilegio minimo.","La separazione dei compiti suddivide le attività critiche tra persone diverse, così che nessuno controlli da solo un intero processo. Lo scenario riguarda i permessi minimi per un singolo utente.","La rete zero trust consiste nel non fidarsi delle richieste in base alla posizione di rete e nel verificarle una per una. Non descrive il dimensionamento dei permessi di un utente."]},
  "25": {"h":"fbab6d8e","question":"Un'azienda vuole fornire accesso temporaneo ad AWS a una società di audit esterna senza creare credenziali di lungo periodo per utenti IAM. Quale funzionalità di IAM dovrebbe utilizzare?","options":["IAM Groups","IAM Roles","IAM Users con rotazione delle password","Service Control Policies (SCPs)"],"explanation":"Gli IAM Role forniscono credenziali temporanee tramite AWS STS (Security Token Service) e possono essere assunti da account o servizi esterni. Sono il metodo consigliato per concedere accesso cross-account senza condividere credenziali di lungo periodo come access key o password.","optionExplanations":["Gli IAM Group organizzano gli utenti e applicano loro permessi comuni: non possono essere assunti da account esterni e non forniscono accesso temporaneo a terze parti.","Corretto — Gli IAM Role forniscono credenziali temporanee tramite AWS STS che possono essere assunte da account esterni senza creare credenziali di lungo periodo per utenti IAM.","Gli IAM User con rotazione delle password creano comunque credenziali di lungo periodo: condividerle con soggetti esterni crea un rischio di sicurezza continuo, l'opposto di quanto richiesto.","Le Service Control Policy limitano ciò che gli account AWS di una Organization possono fare: sono guardrail di governance, non un meccanismo per concedere accesso temporaneo a soggetti esterni."]},
  "26": {"h":"55eea598","question":"Quale servizio AWS monitora continuamente gli account AWS alla ricerca di attività dannose e comportamenti non autorizzati, utilizzando machine learning e threat intelligence?","options":["AWS Shield","Amazon Inspector","Amazon GuardDuty","AWS WAF"],"explanation":"Amazon GuardDuty è un servizio di rilevamento delle minacce che monitora continuamente attività dannose e comportamenti non autorizzati. Analizza i log di CloudTrail, i VPC Flow Logs e i log DNS usando machine learning e feed di threat intelligence per identificare minacce come crypto-mining, compromissione delle credenziali o attività di ricognizione.","optionExplanations":["AWS Shield protegge dagli attacchi DDoS ai livelli di rete e di trasporto: non monitora attività dannose o comportamenti non autorizzati all'interno dell'account AWS.","Amazon Inspector analizza istanze EC2 e immagini di container alla ricerca di vulnerabilità software: si concentra sulla valutazione delle vulnerabilità, non sul rilevamento continuo delle minacce tramite machine learning.","Corretto — Amazon GuardDuty analizza continuamente CloudTrail, VPC Flow Logs e log DNS usando ML e threat intelligence per rilevare attività dannose e comportamenti non autorizzati.","AWS WAF filtra il traffico delle applicazioni web in base a regole: protegge dagli exploit web, non effettua il rilevamento delle minacce a livello di account."]},
  "27": {"h":"d9207f8e","question":"Un'azienda vuole proteggere la propria applicazione web da exploit web comuni come SQL injection e cross-site scripting (XSS). Quale servizio AWS dovrebbe utilizzare?","options":["AWS Shield Standard","Regole AWS WAF","Amazon GuardDuty","AWS Firewall Manager"],"explanation":"AWS WAF è un web application firewall che permette di creare regole per bloccare exploit web comuni come SQL injection, XSS e altre minacce della OWASP Top 10. Può essere associato ad Amazon CloudFront, Application Load Balancer o API Gateway.","optionExplanations":["AWS Shield Standard protegge dagli attacchi DDoS ai livelli di rete e di trasporto: non ispeziona né blocca exploit a livello applicativo web come SQL injection o XSS.","Corretto — AWS WAF è un web application firewall che ispeziona le richieste HTTP/S e blocca exploit web comuni (SQL injection, XSS, OWASP Top 10) in base a regole configurabili.","Amazon GuardDuty è un servizio di rilevamento delle minacce che analizza i log alla ricerca di attività dannose: rileva le minacce a posteriori ma non blocca in tempo reale le richieste web in ingresso.","AWS Firewall Manager gestisce centralmente regole WAF e policy di sicurezza tra più account: orchestra le policy WAF ma non è di per sé il servizio che blocca gli exploit web."]},
  "28": {"h":"ad19b1ae","question":"Una piccola impresa ospita il proprio sito di marketing su Amazon EC2 dietro Amazon CloudFront. Vuole protezione dagli attacchi DDoS comuni ai livelli di rete e di trasporto, come i SYN flood, ma non ha budget per un abbonamento a pagamento o un servizio di sicurezza aggiuntivo. Quale servizio AWS fornisce già questa protezione?","options":["AWS WAF","Amazon GuardDuty","AWS Shield Advanced","AWS Shield Standard"],"explanation":"AWS Shield Standard è abilitato automaticamente per tutti i clienti AWS senza costi aggiuntivi. Protegge dagli attacchi DDoS più comuni ai livelli di rete e di trasporto, come i SYN flood, quindi l'impresa è già protetta senza pagare nulla in più.","optionExplanations":["AWS WAF filtra le richieste web tramite regole (ad esempio contro la SQL injection) ed è tariffato per web ACL e per regola. Non è la protezione DDoS gratuita e automatica di cui l'impresa ha bisogno.","Amazon GuardDuty è un servizio a pagamento di rilevamento delle minacce che analizza i log alla ricerca di attività dannose. Non mitiga gli attacchi DDoS.","AWS Shield Advanced aggiunge una protezione DDoS avanzata e l'accesso all'AWS Shield Response Team, ma è un abbonamento a pagamento che l'impresa non può permettersi.","Corretto — AWS Shield Standard è incluso automaticamente senza costi aggiuntivi e protegge dagli attacchi DDoS comuni ai livelli di rete e di trasporto."]},
  "29": {"h":"60f43dcf","question":"Un ingegnere della sicurezza deve eseguire valutazioni di sicurezza automatizzate delle istanze EC2 per identificare vulnerabilità software ed esposizioni di rete non intenzionali. Quale servizio AWS dovrebbe utilizzare?","options":["Amazon Macie","Amazon Inspector","AWS Security Hub","Amazon Detective"],"explanation":"Amazon Inspector è un servizio di valutazione automatizzata della sicurezza che controlla istanze EC2 e immagini di container alla ricerca di vulnerabilità software (CVE) ed esposizioni di rete non intenzionali. Si integra con AWS Systems Manager e individua e analizza automaticamente i workload.","optionExplanations":["Amazon Macie è un servizio di sicurezza dei dati che individua e classifica i dati sensibili in S3: non analizza le istanze EC2 alla ricerca di vulnerabilità software.","Corretto — Amazon Inspector esegue valutazioni automatizzate delle vulnerabilità su istanze EC2 e immagini di container, verificando CVE ed esposizioni di rete non intenzionali.","AWS Security Hub aggrega i finding di sicurezza di più servizi: utilizza i finding di Inspector ma non esegue di per sé la scansione delle vulnerabilità.","Amazon Detective indaga su potenziali problemi di sicurezza usando i dati dei log: aiuta ad analizzare la causa principale dei finding ma non esegue valutazioni proattive delle vulnerabilità."]},
  "30": {"h":"258576f7","question":"Un'azienda archivia dati sensibili dei clienti in Amazon S3 e vuole individuare e classificare automaticamente le informazioni di identificazione personale (PII). Quale servizio AWS offre questa funzionalità?","options":["Amazon GuardDuty","Amazon Inspector","Amazon Macie","AWS Secrets Manager"],"explanation":"Amazon Macie è un servizio di sicurezza dei dati che usa il machine learning per individuare, classificare e proteggere automaticamente i dati sensibili in S3. Identifica PII come nomi, numeri di carte di credito e informazioni sanitarie, e fornisce dashboard e avvisi sui rischi per la sicurezza dei dati.","optionExplanations":["Amazon GuardDuty rileva attività dannose e comportamenti non autorizzati: analizza i log, non il contenuto degli oggetti S3, quindi non può individuare e classificare le PII nei dati.","Amazon Inspector analizza istanze EC2 e immagini di container alla ricerca di vulnerabilità: non analizza il contenuto dei bucket S3 alla ricerca di dati sensibili.","Corretto — Amazon Macie usa il machine learning per individuare e classificare automaticamente i dati sensibili (PII, dati finanziari) nei bucket S3 e segnala i rischi per la sicurezza dei dati.","AWS Secrets Manager archivia e ruota i secret delle applicazioni: non analizza né classifica i dati sensibili archiviati nei bucket S3."]},
  "31": {"h":"50813f57","question":"Quale servizio AWS viene utilizzato per gestire e archiviare centralmente le chiavi di cifratura usate per proteggere i dati nei servizi AWS?","options":["AWS Certificate Manager (ACM)","AWS Secrets Manager","AWS Key Management Service (KMS)","AWS CloudHSM"],"explanation":"AWS KMS è un servizio gestito che semplifica la creazione e il controllo delle chiavi crittografiche usate per cifrare i dati. Si integra con la maggior parte dei servizi AWS (S3, EBS, RDS, ecc.) per fornire la cifratura lato server e aiuta a soddisfare i requisiti di conformità.","optionExplanations":["AWS Certificate Manager (ACM) gestisce i certificati SSL/TLS per HTTPS: non viene usato per gestire le chiavi di cifratura dei dati a riposo nei servizi AWS.","AWS Secrets Manager archivia e ruota i secret delle applicazioni (password, API key): non è il servizio per gestire le chiavi di cifratura usate per cifrare i dati dei servizi AWS.","Corretto — AWS KMS gestisce centralmente le chiavi crittografiche per la cifratura dei dati, integrandosi con S3, EBS, RDS e altri servizi AWS per la cifratura lato server.","AWS CloudHSM fornisce hardware security module dedicati per la gestione delle chiavi: viene usato per requisiti di controllo delle chiavi più stringenti in cui i clienti devono possedere l'HSM, a differenza del servizio condiviso KMS."]},
  "32": {"h":"c34f61e9","question":"Uno sviluppatore deve archiviare e ruotare automaticamente le password dei database e le API key usate dalle applicazioni. Quale servizio AWS è PIÙ adatto a questo compito?","options":["AWS Key Management Service (KMS)","AWS Systems Manager Parameter Store","AWS Secrets Manager","AWS Identity and Access Management (IAM)"],"explanation":"AWS Secrets Manager è progettato specificamente per archiviare, gestire e ruotare automaticamente secret come credenziali di database, API key e token OAuth. Si integra nativamente con RDS, Redshift e DocumentDB per la rotazione automatica senza alcuna modifica al codice.","optionExplanations":["AWS KMS gestisce le chiavi crittografiche per la cifratura dei dati: non è progettato per archiviare password di database o API key e non esegue la rotazione automatica dei secret.","AWS Systems Manager Parameter Store può archiviare dati di configurazione e secret, ma non supporta nativamente la rotazione automatica delle credenziali di database senza funzioni Lambda personalizzate.","Corretto — AWS Secrets Manager archivia i secret e si integra nativamente con RDS per ruotare automaticamente credenziali di database e API key senza modifiche al codice.","AWS IAM gestisce le identità degli utenti e le policy di accesso: non archivia né ruota secret a livello applicativo come le password dei database."]},
  "33": {"h":"f615e69b","question":"Il team di sicurezza di un'azienda usa Amazon GuardDuty, Amazon Inspector e Amazon Macie in un account AWS. Gli analisti devono controllare separatamente la console di ciascun servizio. Il team vuole un unico punto che raccolga e assegni priorità a tutti questi finding e verifichi l'account rispetto agli standard di sicurezza. Quale servizio AWS dovrebbe utilizzare?","options":["AWS Config","AWS Security Hub","Amazon Detective","AWS Trusted Advisor"],"explanation":"AWS Security Hub aggrega, organizza e assegna priorità ai finding di sicurezza provenienti da servizi come GuardDuty, Inspector e Macie e da strumenti di partner. Esegue inoltre controlli automatizzati rispetto a standard di sicurezza e best practice, offrendo un'unica vista della postura di sicurezza dell'account.","optionExplanations":["AWS Config registra le configurazioni delle risorse e le valuta rispetto a regole, ma non aggrega i finding di GuardDuty, Inspector e Macie.","Corretto — Security Hub raccoglie e assegna priorità ai finding di questi servizi in un unico punto ed esegue controlli rispetto agli standard di sicurezza.","Detective aiuta a indagare sulla causa principale di uno specifico finding; non è una dashboard centrale per tutti i finding e i controlli di conformità.","Trusted Advisor fornisce raccomandazioni di best practice, ma non raccoglie i finding di GuardDuty, Inspector e Macie."]},
  "34": {"h":"58e3f1df","question":"Qual è la best practice consigliata per l'utente root dell'account AWS?","options":["Usare l'utente root per le attività amministrative quotidiane per garantire pieno accesso","Condividere le credenziali dell'utente root con membri fidati del team","Abilitare l'autenticazione a più fattori (MFA) ed evitarne l'uso per le attività di routine","Creare una policy IAM che limiti i permessi dell'utente root"],"explanation":"AWS raccomanda vivamente di abilitare MFA sull'account root e di non usarlo per le attività di routine. Per il lavoro quotidiano vanno invece creati utenti IAM con i permessi appropriati. L'account root va usato solo per le attività che richiedono specificamente l'accesso root, come la modifica dell'indirizzo email dell'account o del piano di fatturazione.","optionExplanations":["Usare l'utente root per le attività quotidiane viola le best practice AWS: l'utente root ha accesso illimitato e non va usato abitualmente, per ridurre al minimo l'esposizione in caso di compromissione delle credenziali.","Condividere le credenziali dell'utente root con i membri del team è un grave rischio di sicurezza: le credenziali non vanno mai condivise; ogni utente deve avere la propria identità IAM.","Corretto — La best practice è abilitare MFA sull'account root ed evitarne l'uso per le attività di routine, creando invece singoli utenti IAM con i permessi appropriati.","Non è possibile creare una policy IAM che limiti i permessi dell'utente root: per progettazione l'utente root ignora tutte le policy IAM e ha pieno accesso. Le uniche protezioni sono MFA e il non utilizzo."]},
  "35": {"h":"adf57643","question":"Un'azienda di software ospita il proprio prodotto su AWS. Un grande cliente invia un questionario di valutazione del rischio fornitori in cui chiede report di audit indipendenti, come SOC 2 e ISO 27001, relativi ai data center AWS in cui sono archiviati i suoi dati. Quale servizio AWS consente all'azienda di scaricare questi report on-demand?","options":["AWS Config","AWS Trusted Advisor","AWS Artifact","AWS Security Hub"],"explanation":"AWS Artifact è un portale self-service per i documenti di conformità di AWS, come report SOC, certificazioni ISO e attestazioni PCI DSS, e per gli accordi con AWS. L'azienda può scaricare i report e condividerli con il proprio cliente.","optionExplanations":["AWS Config valuta le configurazioni delle risorse dell'azienda stessa. Non fornisce report di audit di terze parti su AWS.","Trusted Advisor fornisce raccomandazioni di best practice per l'account dell'azienda. Non fornisce i report di audit di AWS.","Corretto — Artifact consente di scaricare on-demand i report di audit di AWS, come SOC 2 e le certificazioni ISO.","Security Hub mostra finding di sicurezza e controlli di conformità per gli account dell'azienda stessa. Non fornisce i report di audit di AWS."]},
  "36": {"h":"369f5570","question":"Un'azienda deve garantire che le proprie risorse AWS siano sempre conformi alle policy di sicurezza interne. Ad esempio, tutti i bucket S3 devono avere la cifratura lato server abilitata. Quale servizio AWS valuta continuamente le configurazioni delle risorse rispetto alle regole desiderate?","options":["AWS CloudTrail","Amazon Inspector","AWS Config","AWS Systems Manager"],"explanation":"AWS Config monitora e registra continuamente le configurazioni delle risorse AWS e le valuta rispetto alle regole desiderate. Se una risorsa si discosta dalla configurazione desiderata (ad es. cifratura del bucket S3 disabilitata), Config può segnalarla e, facoltativamente, avviare la correzione tramite AWS Systems Manager Automation.","optionExplanations":["AWS CloudTrail registra le chiamate API (chi ha fatto cosa e quando): non valuta continuamente se le configurazioni delle risorse sono conformi alle regole di policy desiderate.","Amazon Inspector cerca vulnerabilità software in istanze EC2 e container: non verifica le impostazioni di cifratura dei bucket S3 né la conformità della configurazione delle risorse.","Corretto — AWS Config monitora continuamente le configurazioni delle risorse e le valuta rispetto a regole (ad es. il bucket S3 deve avere la cifratura abilitata), segnalando e facoltativamente correggendo gli scostamenti.","AWS Systems Manager fornisce strumenti di gestione operativa: può eseguire azioni di correzione avviate da Config, ma è Config il servizio che rileva e valuta la conformità della configurazione."]},
  "37": {"h":"d171bfe7","question":"Quale dei seguenti controlli di sicurezza opera a livello di subnet in un VPC e funziona come firewall stateless?","options":["Security Groups","Network ACLs","AWS WAF","AWS Shield"],"explanation":"Le Network ACL (NACL) operano a livello di subnet in un VPC e sono stateless: sia le regole in ingresso sia quelle in uscita devono consentire esplicitamente il traffico. I Security Group sono stateful (il traffico di ritorno è consentito automaticamente) e operano a livello di istanza.","optionExplanations":["I Security Group operano a livello di istanza/ENI (non di subnet) e sono stateful: consentono automaticamente il traffico di ritorno per le connessioni in ingresso autorizzate.","Corretto — Le Network ACL operano a livello di subnet e sono stateless: sia le regole in ingresso SIA quelle in uscita devono autorizzare esplicitamente il traffico in entrambe le direzioni.","AWS WAF è un web application firewall che filtra il traffico HTTP/S a livello applicativo: non opera a livello di subnet all'interno di un VPC.","AWS Shield protegge dagli attacchi DDoS a livello di rete: non è un controllo firewall per singola subnet all'interno di un VPC."]},
  "38": {"h":"888ec09b","question":"Quali DUE delle seguenti attività sono responsabilità del cliente in base allo AWS Shared Responsibility Model?","options":["Mantenere la sicurezza fisica dei data center AWS","Applicare le patch al sistema operativo delle istanze EC2","Gestire l'hardware di rete e il cablaggio in fibra","Configurare utenti IAM e policy di accesso","Sostituire i dischi guasti nei sistemi di storage AWS"],"explanation":"I clienti sono responsabili della sicurezza NEL cloud: ciò include l'applicazione delle patch al sistema operativo guest delle istanze EC2 e la gestione delle configurazioni IAM (utenti, gruppi, ruoli e policy). AWS è responsabile dell'infrastruttura fisica, dell'hardware di rete e dell'hypervisor sottostante.","optionExplanations":["Mantenere la sicurezza fisica dei data center AWS è responsabilità di AWS («sicurezza DEL cloud»): i clienti non gestiscono né accedono mai alle strutture fisiche dei data center.","Corretto — L'applicazione delle patch al sistema operativo delle istanze EC2 è responsabilità del cliente (il cliente gestisce il sistema operativo guest sulle risorse IaaS).","La gestione dell'hardware di rete e del cablaggio in fibra è responsabilità di AWS: l'infrastruttura di rete fisica fa parte di ciò che gestisce AWS.","Corretto — La configurazione di utenti IAM e policy di accesso è sempre responsabilità del cliente: AWS fornisce IAM come servizio ma non gestisce mai chi ha quali permessi.","La sostituzione dei dischi guasti nei sistemi di storage AWS è responsabilità di AWS: la manutenzione hardware delle apparecchiature dei data center fa parte della «sicurezza DEL cloud»."]},
  "39": {"h":"f2e8c14b","question":"Un'azienda vuole aggiungere un ulteriore livello di sicurezza che richieda agli utenti di presentare un dispositivo fisico o virtuale quando accedono alla AWS Management Console. Quale funzionalità dovrebbe abilitare?","options":["Password policy IAM con rotazione","Multi-Factor Authentication","AWS Single Sign-On","Identità federata con SAML 2.0"],"explanation":"La Multi-Factor Authentication (MFA) richiede una seconda forma di verifica oltre alla password. AWS supporta app MFA virtuali (come le app di autenticazione), token TOTP hardware e security key FIDO2. MFA va abilitata su tutti gli utenti IAM, in particolare sull'account root.","optionExplanations":["La password policy IAM impone complessità e rotazione delle password: controlla la password stessa ma non aggiunge un secondo dispositivo fisico o virtuale come fattore aggiuntivo.","Corretto — La Multi-Factor Authentication (MFA) richiede una seconda forma di verifica (dispositivo fisico o virtuale) oltre alla password, aggiungendo un ulteriore livello di sicurezza.","AWS Single Sign-On centralizza la gestione degli accessi: può integrarsi con provider MFA ma non è di per sé la funzionalità che abilita il requisito di verifica con secondo fattore.","L'identità federata consente agli utenti di usare identity provider esterni (come il SSO aziendale): è un metodo di autenticazione, non specificamente la funzionalità che richiede un dispositivo fisico o virtuale."]},
  "40": {"h":"40ad1d1f","question":"Un'azienda con 2.000 dipendenti gestisce le identità nel proprio Microsoft Active Directory on-premises. Vuole che i dipendenti accedano una sola volta con le credenziali aziendali esistenti e poi utilizzino la AWS Management Console e la AWS CLI nei numerosi account AWS dell'azienda, senza creare utenti IAM. Quale servizio AWS dovrebbe utilizzare l'azienda?","options":["User pool di Amazon Cognito","AWS IAM Identity Center","AWS Directory Service","AWS Organizations"],"explanation":"AWS IAM Identity Center (successore di AWS Single Sign-On) fornisce il single sign-on per la forza lavoro verso più account AWS e applicazioni. Può usare Microsoft Active Directory come fonte di identità, così i dipendenti accedono con le credenziali aziendali e ottengono accesso a console e CLI senza utenti IAM separati.","optionExplanations":["Gli user pool di Amazon Cognito gestiscono registrazione e accesso per i clienti di applicazioni web e mobile, non l'accesso della forza lavoro alla AWS Management Console e alla CLI.","Corretto — IAM Identity Center si collega all'Active Directory dell'azienda e offre ai dipendenti l'accesso single sign-on a console e CLI su molti account AWS.","AWS Directory Service fornisce Active Directory gestito o connettori verso uno esistente, ma non offre di per sé il single sign-on e l'assegnazione dei permessi su molti account AWS.","AWS Organizations gestisce centralmente account e policy, ma non autentica i dipendenti con le loro credenziali aziendali."]},
  "41": {"h":"4ffb09df","question":"Quale affermazione sulla conformità in AWS è CORRETTA?","options":["AWS è conforme a tutti gli standard, quindi i clienti non devono preoccuparsi della conformità","AWS mantiene certificazioni di conformità e i clienti ereditano alcuni controlli ma restano responsabili di altri","I clienti sono gli unici responsabili di tutta la conformità e AWS non ha certificazioni di conformità","La conformità è rilevante solo per i settori regolamentati e non riguarda la maggior parte dei clienti AWS"],"explanation":"AWS mantiene numerose certificazioni di conformità (PCI DSS, HIPAA, SOC, ISO, ecc.) e la responsabilità della conformità è condivisa. AWS controlla il livello fisico e infrastrutturale, ma i clienti devono garantire che le proprie applicazioni e configurazioni siano conformi agli standard pertinenti. La conformità è una responsabilità condivisa.","optionExplanations":["Le certificazioni di conformità di AWS non significano che i clienti non abbiano responsabilità: i clienti ereditano alcuni controlli ma devono comunque garantire che configurazioni applicative, gestione dei dati e policy IAM siano conformi agli standard pertinenti.","Corretto — La conformità è condivisa: AWS mantiene le certificazioni per la propria infrastruttura e i clienti ereditano alcuni controlli ma restano responsabili di configurare applicazioni e dati in modo conforme.","AWS possiede numerose certificazioni di conformità (PCI DSS, HIPAA, SOC, ISO, FedRAMP): l'affermazione che AWS non ne abbia è del tutto falsa.","La conformità riguarda tutti i settori e i casi d'uso: anche i settori non regolamentati hanno requisiti di conformità (ad es. GDPR, leggi sulla protezione dei dati) che interessano la maggior parte dei clienti AWS."]},
  "42": {"h":"50f9af19","question":"Lo scorso anno il sito di un negozio online è andato offline quando il suo certificato HTTPS è scaduto senza che nessuno se ne accorgesse. Il sito funziona dietro un Application Load Balancer e il negozio vuole certificati pubblici gratuiti che vengano rinnovati automaticamente. Quale servizio AWS dovrebbe utilizzare il negozio?","options":["AWS Key Management Service (KMS)","AWS Certificate Manager (ACM)","AWS Secrets Manager","AWS CloudHSM"],"explanation":"AWS Certificate Manager (ACM) emette, gestisce e rinnova automaticamente certificati SSL/TLS pubblici e privati. Si integra con Elastic Load Balancing, Amazon CloudFront e Amazon API Gateway, e i certificati pubblici usati con questi servizi integrati sono forniti senza costi aggiuntivi.","optionExplanations":["KMS crea e gestisce chiavi di cifratura; non emette né rinnova certificati SSL/TLS per siti web.","Corretto — ACM emette certificati SSL/TLS pubblici per il load balancer e li rinnova automaticamente, evitando interruzioni dovute a certificati scaduti.","Secrets Manager archivia e ruota secret come le password dei database; non emette certificati SSL/TLS per HTTPS.","CloudHSM fornisce hardware security module dedicati per l'archiviazione delle chiavi; non emette né rinnova automaticamente certificati per siti web."]},
  "43": {"h":"d51e6e63","question":"L'amministratore di un account AWS vuole garantire che gli utenti del gruppo Development non possano avviare istanze EC2 più grandi di t3.medium. Come si può imporre questo vincolo?","options":["Creare una Service Control Policy (SCP) in AWS Organizations","Associare al gruppo una policy IAM che consenta solo t3.medium o tipi inferiori","Abilitare regole AWS Config per rilevare e segnalare tipi di istanza non conformi","Usare AWS Trusted Advisor per bloccare l'avvio di istanze di grandi dimensioni"],"explanation":"Una policy IAM con condizioni può limitare i tipi di istanza EC2 che un utente o un gruppo può avviare. Si possono usare le condition key aws:RequestedRegion ed ec2:InstanceType per limitare i tipi di istanza consentiti. Le policy IAM applicano i permessi a livello di identità.","optionExplanations":["Una SCP in AWS Organizations limita ciò che gli account di un'organizzazione possono fare: opera a livello di account e non applica restrizioni granulari per gruppo all'interno di un singolo account.","Corretto — Associare al gruppo Development una policy IAM con condition key ec2:InstanceType consente solo i tipi di istanza autorizzati, imponendo la restrizione a livello di identità.","Le regole AWS Config possono rilevare tipi di istanza non conformi dopo l'avvio, ma non impediscono l'avvio: segnalano le violazioni a posteriori.","AWS Trusted Advisor fornisce raccomandazioni ma non può bloccare o impedire specifiche configurazioni delle risorse: ha funzione consultiva, non di enforcement."]},
  "44": {"h":"79d2329f","question":"Quale concetto di sicurezza AWS descrive la pratica di suddividere un VPC in sezioni separate, in modo che una violazione della sicurezza in una sezione non possa propagarsi facilmente alle altre?","options":["Difesa in profondità","Segmentazione della rete tramite subnet","Principio del privilegio minimo","Sicurezza zero-knowledge"],"explanation":"La segmentazione della rete tramite subnet (pubbliche e private) è un pattern fondamentale di progettazione della sicurezza nei VPC. Isolando le risorse, ad esempio collocando i database in subnet private senza accesso a internet, si limita il raggio d'impatto di una potenziale violazione e si impedisce il movimento laterale.","optionExplanations":["La difesa in profondità applica più livelli di controlli di sicurezza: le subnet sono uno di questi livelli, ma la difesa in profondità è la strategia più ampia, non specificamente la pratica di suddividere un VPC in segmenti.","Corretto — La segmentazione della rete tramite subnet (pubbliche/private) isola le risorse, così che una violazione in una subnet (ad es. il livello web) non possa propagarsi facilmente alle altre (ad es. il livello database).","Il principio del privilegio minimo concede solo i permessi minimi necessari: è un concetto di IAM/controllo degli accessi, non una tecnica di isolamento di rete tramite subnet del VPC.","La sicurezza zero-knowledge è un concetto crittografico in cui una parte dimostra di conoscere un'informazione senza rivelarla: non è una pratica di segmentazione della rete in un VPC."]},
  "45": {"h":"acd5672e","question":"Un rivenditore online ha subito un grande attacco DDoS durante una promozione. La sua infrastruttura ha scalato orizzontalmente per assorbire il traffico e la fattura AWS è aumentata notevolmente. L'azienda vuole assistenza 24/7 da parte degli esperti DDoS di AWS durante attacchi futuri e protezione dai costi di scaling causati dai DDoS. Quale servizio AWS dovrebbe utilizzare?","options":["AWS Shield Standard","AWS WAF","AWS Shield Advanced","Amazon GuardDuty"],"explanation":"AWS Shield Advanced è il livello a pagamento di AWS Shield. Aggiunge l'accesso 24/7 all'AWS Shield Response Team, visibilità dettagliata sugli attacchi e protezione dai costi di scaling derivanti dagli attacchi DDoS.","optionExplanations":["Shield Standard è automatico e gratuito per tutti i clienti e protegge dagli attacchi comuni a livello di rete. Non include l'accesso al response team né la protezione dei costi.","AWS WAF filtra le richieste web tramite regole. Non fornisce un team di risposta DDoS né protezione dai costi di scaling.","Corretto — Shield Advanced aggiunge l'accesso 24/7 agli esperti DDoS di AWS e la protezione dei costi per lo scaling dovuto ai DDoS.","GuardDuty rileva le minacce analizzando i log. Non è un servizio di mitigazione DDoS e non offre protezione dei costi."]},
  "46": {"h":"52be45fb","question":"Un'azienda esegue ogni notte, per 2 ore, un job di elaborazione batch che richiede una notevole potenza di calcolo. Il job può essere interrotto e riavviato senza perdita di dati. Quale opzione di prezzo EC2 offre il costo PIÙ BASSO per questo caso d'uso?","options":["On-Demand Instances","Reserved Instances","Spot Instances","Dedicated Hosts"],"explanation":"Le Spot Instances usano la capacità EC2 inutilizzata e possono costare fino al 90% in meno rispetto a On-Demand. Sono ideali per workload flessibili e tolleranti ai guasti come job batch, analisi dei dati e rendering, che possono tollerare interruzioni. Se il prezzo Spot supera l'offerta o la capacità è necessaria, l'istanza può essere interrotta.","optionExplanations":["Le On-Demand Instances offrono prezzi flessibili con pagamento al secondo, ma hanno il costo orario più alto e non prevedono sconti per workload batch interrompibili.","Le Reserved Instances offrono sconti per workload stabili con impegno di utilizzo: non sono la scelta più economica per un job batch notturno di 2 ore che non viene eseguito in modo continuativo.","Corretto — Le Spot Instances usano la capacità EC2 inutilizzata con sconti fino al 90% e sono ideali per job batch tolleranti ai guasti che possono essere interrotti e riavviati senza perdita di dati.","I Dedicated Hosts forniscono server fisici dedicati per la conformità delle licenze: non sono una strategia di ottimizzazione dei costi e sono l'opzione EC2 più costosa."]},
  "47": {"h":"b75aa970","question":"Uno sviluppatore vuole eseguire codice di backend in risposta a eventi (come una chiamata API o il caricamento di un file su S3) senza effettuare il provisioning né gestire alcun server. Quale servizio AWS dovrebbe utilizzare?","options":["Amazon EC2","AWS Lambda","Amazon ECS","AWS Elastic Beanstalk"],"explanation":"AWS Lambda è un servizio di calcolo serverless che esegue codice in risposta a eventi senza richiedere il provisioning o la gestione di server. Si paga solo per il tempo di calcolo consumato. Lambda è ideale per architetture event-driven, backend di API e attività di automazione.","optionExplanations":["Amazon EC2 fornisce macchine virtuali che richiedono provisioning, configurazione e gestione del server: lo sviluppatore dovrebbe comunque gestire l'infrastruttura sottostante.","Corretto — AWS Lambda esegue codice in risposta a eventi (chiamate API, caricamenti su S3, ecc.) senza richiedere provisioning o gestione dei server, addebitando solo il tempo di calcolo effettivo.","Amazon ECS esegue applicazioni containerizzate ma richiede comunque un'infrastruttura (istanze EC2 o Fargate): non è la soluzione più semplice per l'esecuzione di codice event-driven.","AWS Elastic Beanstalk gestisce il deployment di applicazioni web, ma dietro le quinte effettua comunque il provisioning e la gestione di istanze EC2: non è un vero modello serverless event-driven."]},
  "48": {"h":"33fb913d","question":"Un sito di biglietteria per concerti funziona su Amazon EC2. Il traffico è basso per gran parte della settimana ma aumenta bruscamente quando vengono messi in vendita biglietti molto richiesti. L'azienda vuole che il numero di istanze aumenti e diminuisca automaticamente in base alla domanda. Quale servizio AWS dovrebbe utilizzare?","options":["Elastic Load Balancing","AWS Auto Scaling","Amazon CloudWatch","Amazon EC2 Fleet"],"explanation":"AWS Auto Scaling (tramite Amazon EC2 Auto Scaling) aggiunge istanze quando la domanda aumenta e le rimuove quando diminuisce, in base a metriche, pianificazioni o scaling predittivo. Ciò mantiene stabili le prestazioni durante la vendita dei biglietti ed evita di pagare istanze inattive nel resto della settimana.","optionExplanations":["Elastic Load Balancing distribuisce il traffico tra le istanze esistenti, ma non aggiunge né rimuove istanze.","Corretto — Auto Scaling adegua automaticamente il numero di istanze EC2 alla domanda variabile.","CloudWatch fornisce le metriche e gli allarmi che possono attivare lo scaling, ma non avvia né termina istanze direttamente.","EC2 Fleet avvia un gruppo di istanze per raggiungere una capacità target specificata; non segue di per sé la domanda variabile."]},
  "49": {"h":"bc11baf3","question":"Un'azienda vuole effettuare il deployment su AWS di un'applicazione a microservizi basata su Docker senza gestire l'infrastruttura server sottostante. Quale servizio fornisce un'orchestrazione di container completamente gestita?","options":["Amazon EC2 con Docker installato","AWS Fargate","Amazon Lightsail","AWS Elastic Beanstalk"],"explanation":"AWS Fargate è un motore di calcolo serverless per container che funziona sia con Amazon ECS sia con Amazon EKS. Con Fargate si definiscono i container senza dover effettuare provisioning, configurazione o scaling di istanze EC2. AWS gestisce l'infrastruttura sottostante.","optionExplanations":["Amazon EC2 con Docker installato richiede al cliente di effettuare il provisioning e gestire l'infrastruttura server sottostante: lo sviluppatore deve occuparsi di patch, scaling e pianificazione della capacità.","Corretto — AWS Fargate è un motore serverless per container in cui si definiscono i container e AWS gestisce l'infrastruttura sottostante: nessuna istanza EC2 da predisporre o scalare.","Amazon Lightsail fornisce server privati virtuali semplificati per applicazioni semplici: non è un servizio di orchestrazione di container per microservizi.","AWS Elastic Beanstalk effettua il deployment di applicazioni web: pur nascondendo parte della complessità infrastrutturale, effettua comunque il provisioning di istanze EC2 e non è progettato per microservizi containerizzati."]},
  "50": {"h":"bdd73b9c","question":"Quale servizio AWS consente agli sviluppatori di effettuare il deployment ed eseguire applicazioni web senza preoccuparsi del provisioning di server, load balancer o gruppi di auto-scaling, mantenendo comunque il pieno controllo sulle risorse AWS sottostanti?","options":["Amazon Lightsail","AWS Lambda","AWS Elastic Beanstalk","Amazon ECS"],"explanation":"AWS Elastic Beanstalk è un servizio PaaS che gestisce deployment, provisioning della capacità, bilanciamento del carico, auto-scaling e monitoraggio dello stato di salute. Gli sviluppatori caricano semplicemente il codice ed Elastic Beanstalk ne effettua il deployment. Si mantiene tuttavia l'accesso alle risorse AWS sottostanti, come le istanze EC2, che possono essere configurate direttamente.","optionExplanations":["Amazon Lightsail fornisce VPS semplificati per piccole applicazioni: non gestisce auto-scaling e bilanciamento del carico né offre pieno accesso alle risorse AWS sottostanti.","AWS Lambda esegue singole funzioni di codice in risposta a eventi: non è progettato per il deployment di intere applicazioni web con bilanciamento del carico e infrastruttura persistente.","Corretto — AWS Elastic Beanstalk gestisce automaticamente deployment, bilanciamento del carico, auto-scaling e monitoraggio dello stato di salute, mantenendo il pieno accesso alle risorse AWS sottostanti.","Amazon ECS esegue applicazioni containerizzate: non gestisce automaticamente i flussi di deployment o la gestione a livello applicativo senza configurazioni aggiuntive."]},
  "51": {"h":"82a7e243","question":"Un'azienda conserva i backup di disaster recovery in Amazon S3. I backup vengono letti circa una volta al mese per i test, ma quando serve un ripristino i dati devono essere disponibili immediatamente. I dati devono inoltre sopravvivere alla perdita di una Availability Zone. Quale classe di storage S3 è la PIÙ conveniente per questi requisiti?","options":["S3 Standard","S3 Standard-IA","S3 Glacier Flexible Retrieval","S3 One Zone-IA"],"explanation":"S3 Standard-IA è progettata per dati a cui si accede di rado ma che richiedono un accesso in millisecondi quando servono. Lo storage costa meno di S3 Standard (con un addebito per GB recuperato) e i dati vengono conservati su più Availability Zone.","optionExplanations":["S3 Standard soddisfa i requisiti di accesso e durabilità, ma per dati letti raramente lo storage costa più di Standard-IA.","Corretto — Standard-IA offre accesso immediato, conserva i dati in più AZ ed è più economica di Standard per dati a cui si accede di rado.","Glacier Flexible Retrieval richiede da minuti a ore per recuperare i dati, quindi non soddisfa il requisito di ripristino immediato.","One Zone-IA conserva i dati in una sola Availability Zone, quindi i backup andrebbero persi se quella AZ venisse distrutta."]},
  "52": {"h":"2487ffa9","question":"Un'azienda vuole archiviare dati a cui si accede raramente e che possono tollerare tempi di recupero di diverse ore. Quale classe di storage S3 è la PIÙ adatta?","options":["S3 Standard","S3 Standard-IA","S3 Glacier Flexible Retrieval","S3 Intelligent-Tiering"],"explanation":"S3 Glacier Flexible Retrieval (in precedenza S3 Glacier) è pensata per l'archiviazione dei dati, con tempi di recupero che vanno da minuti a ore. Offre il costo di storage più basso tra i livelli facilmente accessibili. Per dati a cui si accede raramente e che possono attendere ore per essere recuperati, è la scelta più conveniente.","optionExplanations":["S3 Standard è per dati a cui si accede frequentemente — ha il costo di storage per GB più alto e non è pensata per l'archiviazione a lungo termine.","S3 Standard-IA offre accesso immediato per dati usati di rado — ha costi di storage più alti di Glacier e non è ottimale per dati che possono attendere ore per il recupero.","Corretto — S3 Glacier Flexible Retrieval offre costi di storage molto bassi per dati archiviati a cui si accede raramente, con tempi di recupero da minuti a ore.","S3 Intelligent-Tiering sposta automaticamente gli oggetti tra i livelli in base ai pattern di accesso — è utile con pattern di accesso variabili, ma non è la soluzione più conveniente per dati che già si sa essere usati raramente."]},
  "53": {"h":"ed38361f","question":"Quale servizio di storage AWS fornisce un file system completamente gestito e scalabile, che può essere montato contemporaneamente da più istanze EC2 e cresce automaticamente?","options":["Amazon EBS","Amazon S3","Amazon EFS","AWS Storage Gateway"],"explanation":"Amazon EFS (Elastic File System) fornisce un file system NFS semplice, scalabile e completamente gestito per i servizi AWS Cloud e le risorse on-premises. Più istanze EC2 possono montare e accedere contemporaneamente allo stesso file system EFS, il che lo rende ideale per workload condivisi come la gestione dei contenuti e il web serving.","optionExplanations":["Amazon EBS fornisce storage a blocchi collegato a una singola istanza EC2 — non può essere montato contemporaneamente da più istanze (salvo Multi-Attach io1/io2, con limitazioni).","Amazon S3 è uno storage a oggetti accessibile tramite API — non fornisce un'interfaccia di file system che le istanze EC2 possano montare e usare come un tradizionale file system condiviso.","Corretto — Amazon EFS fornisce un file system NFS gestito che più istanze EC2 possono montare contemporaneamente, e che cresce automaticamente man mano che si aggiungono dati.","AWS Storage Gateway collega lo storage on-premises al cloud AWS — non fornisce un file system condiviso montabile direttamente dalle istanze EC2 all'interno di AWS."]},
  "54": {"h":"78e5b0a5","question":"Un'azienda deve conservare grandi quantità di dati non strutturati, come immagini, video e backup, in un servizio di storage a oggetti durevole e ad alta disponibilità. Quale servizio AWS soddisfa MEGLIO questo requisito?","options":["Amazon EBS","Amazon EFS","Amazon S3","Amazon RDS"],"explanation":"Amazon S3 è il servizio di storage a oggetti di AWS, progettato per l'archiviazione di dati su scala internet. Offre una durabilità di 11 nove (99,999999999%), alta disponibilità e capacità di storage praticamente illimitata. È ideale per backup, file multimediali, data lake, siti web statici e archiviazione.","optionExplanations":["Amazon EBS fornisce storage a blocchi collegato alle istanze EC2 — ha limiti di capacità, è legato a una specifica AZ e non è pensato per lo storage a oggetti non strutturato su scala internet.","Amazon EFS fornisce un file system condiviso per le istanze EC2 — è un servizio di file storage, non ottimizzato per lo storage a oggetti non strutturato su larga scala come immagini, video e backup.","Corretto — Amazon S3 è il servizio di storage a oggetti dedicato, con durabilità di 11 nove e capacità praticamente illimitata, ideale per immagini, video, backup e data lake.","Amazon RDS è un servizio di database relazionale gestito — è pensato per dati strutturati e interrogabili, non per conservare grandi file non strutturati come immagini, video e backup."]},
  "55": {"h":"7bb3c188","question":"Un negozio online esegue il proprio database degli ordini su Amazon RDS for MySQL in una sola Availability Zone. L'azienda vuole che il database continui a funzionare se quella Availability Zone si guasta, con failover automatico e senza interventi manuali. Quale funzionalità di RDS dovrebbe abilitare l'azienda?","options":["Read Replica","Deployment Multi-AZ","Aurora Global Database","Snapshot automatici del database"],"explanation":"Un deployment RDS Multi-AZ mantiene una copia standby sincrona del database in un'altra Availability Zone. Se il database primario o la sua Availability Zone si guastano, Amazon RDS esegue automaticamente il failover sullo standby, senza interventi manuali.","optionExplanations":["Le Read Replica servono principalmente a scalare il traffico in lettura. Replicano in modo asincrono e non sono la funzionalità di RDS che fornisce il failover automatico per l'alta disponibilità.","Corretto — Multi-AZ mantiene uno standby in un'altra Availability Zone ed esegue automaticamente il failover su di esso se il primario si guasta.","Aurora Global Database è una funzionalità di Amazon Aurora per la replica tra Region. L'azienda usa RDS for MySQL e ha bisogno di protezione contro il guasto di una Availability Zone.","Gli snapshot sono backup che vanno ripristinati manualmente su una nuova istanza di database, il che comporta downtime e interventi manuali."]},
  "56": {"h":"dbdf8b9c","question":"Un'azienda ha bisogno di un database NoSQL key-value e a documenti completamente gestito, che offra prestazioni nell'ordine di pochi millisecondi a qualsiasi scala. Quale servizio AWS dovrebbe usare?","options":["Amazon RDS","Amazon Aurora","Amazon DynamoDB","Amazon Redshift"],"explanation":"Amazon DynamoDB è un servizio di database NoSQL serverless completamente gestito che offre prestazioni nell'ordine di pochi millisecondi a qualsiasi scala. È ideale per applicazioni web ad alto traffico, gaming, IoT e backend mobile che richiedono un accesso ai dati a bassa latenza su larga scala.","optionExplanations":["Amazon RDS è un servizio di database relazionale gestito — supporta dati strutturati basati su SQL e non è pensato per il modello flessibile NoSQL key-value/a documenti su scala web.","Amazon Aurora è un database relazionale gestito compatibile con MySQL/PostgreSQL — è basato su SQL e non è uno store NoSQL key-value.","Corretto — Amazon DynamoDB è un database NoSQL completamente gestito che offre prestazioni nell'ordine di pochi millisecondi a qualsiasi scala per dati key-value e a documenti.","Amazon Redshift è un data warehouse per query SQL analitiche — è pensato per workload OLAP, non per applicazioni NoSQL transazionali a bassa latenza."]},
  "57": {"h":"e60ef288","question":"Un'azienda vuole eseguire query analitiche su petabyte di dati strutturati usando SQL standard. Quale servizio di database AWS è progettato per questo caso d'uso?","options":["Amazon DynamoDB","Amazon RDS for MySQL","Amazon Redshift","Amazon ElastiCache"],"explanation":"Amazon Redshift è un servizio di data warehouse in cloud completamente gestito, su scala di petabyte. È progettato per l'elaborazione analitica online (OLAP) e per workload di business intelligence, e consente query complesse su grandi dataset con SQL standard, integrandosi con i più diffusi strumenti di BI.","optionExplanations":["Amazon DynamoDB è un database NoSQL key-value/a documenti — non è pensato per query analitiche SQL complesse su petabyte di dati strutturati.","Amazon RDS for MySQL è un database relazionale transazionale OLTP — può gestire un po' di analisi, ma non è ottimizzato per query analitiche su scala di petabyte.","Corretto — Amazon Redshift è un data warehouse su scala di petabyte progettato per workload analitici OLAP con SQL standard, integrato con i più diffusi strumenti di BI.","Amazon ElastiCache è un servizio di caching in memoria — conserva i dati usati di frequente per letture a latenza bassissima, non per query analitiche su grandi dataset."]},
  "58": {"h":"dbc19129","question":"Quale servizio AWS fornisce un livello di caching in memoria gestito per migliorare le prestazioni dei workload di database con molte letture?","options":["Amazon RDS","Amazon DynamoDB DAX","Amazon ElastiCache","Amazon Redshift"],"explanation":"Amazon ElastiCache è un servizio di caching in memoria completamente gestito che supporta Redis e Memcached. Mettendo in cache in memoria i dati letti di frequente, ElastiCache riduce il carico sul database e la latenza. DynamoDB Accelerator (DAX) è specifico per DynamoDB; ElastiCache è per il caching di uso generale, inclusi i workload RDS.","optionExplanations":["Amazon RDS è un database relazionale gestito — è il database di backend alleggerito da una cache, non il livello di caching stesso.","Amazon DynamoDB DAX è un livello di accelerazione in memoria specifico per DynamoDB — non mette in cache dati per RDS o per altri workload di uso generale.","Corretto — Amazon ElastiCache fornisce Redis/Memcached gestiti per il caching in memoria di uso generale, riducendo carico e latenza del database per i workload con molte letture.","Amazon Redshift è un data warehouse per l'analisi — non è un servizio di caching in memoria per ridurre la latenza del database."]},
  "59": {"h":"8973bff5","question":"Un sito di notizie ospita le proprie immagini e i propri video in una sola Region AWS in Europa. I lettori in Asia e Sud America lamentano che le pagine si caricano lentamente. L'azienda vuole distribuire questi contenuti da posizioni vicine ai lettori senza spostare i propri server di origine. Quale servizio AWS dovrebbe usare?","options":["Amazon Route 53","AWS Direct Connect","Amazon CloudFront","Elastic Load Balancing"],"explanation":"Amazon CloudFront è una content delivery network (CDN) che mette in cache i contenuti nelle Edge Location di tutto il mondo. I lettori vengono serviti da una Edge Location vicina, il che riduce la latenza mentre l'origine resta nella Region originale.","optionExplanations":["Route 53 è un servizio DNS; indirizza gli utenti verso gli endpoint ma non mette in cache i contenuti vicino ai lettori.","Direct Connect è un collegamento di rete privato tra il data center di un'azienda e AWS; non velocizza la distribuzione ai lettori su internet.","Corretto — CloudFront mette in cache immagini e video nelle Edge Location vicine ai lettori, riducendo i tempi di caricamento in tutto il mondo.","Elastic Load Balancing distribuisce il traffico tra i target all'interno di una Region; non mette in cache i contenuti vicino agli utenti lontani."]},
  "60": {"h":"c9cb6af1","question":"Quale servizio AWS fornisce una risoluzione DNS (domain name system) scalabile e può anche instradare il traffico in base a health check, latenza e posizione geografica?","options":["Amazon CloudFront","Elastic Load Balancing","Amazon Route 53","AWS Global Accelerator"],"explanation":"Amazon Route 53 è un servizio DNS altamente disponibile e scalabile. Supporta diverse routing policy: Simple, Weighted, Latency-based, Failover, Geolocation, Geoproximity e Multi-value answer. Fornisce inoltre funzionalità di registrazione dei domini e di health check.","optionExplanations":["Amazon CloudFront è una CDN che distribuisce contenuti in cache agli utenti — non fornisce risoluzione DNS, registrazione dei domini né instradamento del traffico basato su health check.","Elastic Load Balancing instrada il traffico verso le istanze di backend — opera a livello applicativo o di rete all'interno di AWS, non a livello DNS globale per la risoluzione dei nomi di dominio.","Corretto — Amazon Route 53 fornisce una risoluzione DNS scalabile con diverse routing policy (latenza, geolocalizzazione, failover), health check e registrazione dei domini.","AWS Global Accelerator migliora le prestazioni delle applicazioni usando la rete globale di AWS — instrada il traffico tramite IP anycast, non tramite DNS, e non fornisce la registrazione dei domini."]},
  "61": {"h":"a03885fb","question":"Un'azienda vuole monitorare l'utilizzo della CPU delle proprie istanze EC2 e inviare automaticamente un avviso via email quando l'utilizzo supera l'80%. Quali servizi AWS verrebbero usati insieme a questo scopo?","options":["AWS CloudTrail e AWS SNS","Amazon CloudWatch e Amazon SNS","AWS Config e AWS Lambda","Amazon GuardDuty e Amazon SES"],"explanation":"Amazon CloudWatch raccoglie metriche (come l'utilizzo della CPU di EC2), consente di creare allarmi basati su soglie e può attivare azioni quando tali soglie vengono superate. Un topic SNS (Simple Notification Service) può essere configurato come azione dell'allarme per inviare notifiche via email.","optionExplanations":["AWS CloudTrail registra la cronologia delle chiamate API — non monitora le metriche di prestazione né invia avvisi quando l'utilizzo della CPU supera una soglia.","Corretto — Amazon CloudWatch monitora l'utilizzo della CPU di EC2 e attiva gli allarmi; Amazon SNS è il servizio di notifica che invia l'avviso via email quando scatta l'allarme.","AWS Config valuta la conformità delle configurazioni delle risorse — non monitora metriche di prestazione in tempo reale come l'utilizzo della CPU.","Amazon GuardDuty rileva minacce alla sicurezza — non monitora le metriche di prestazione operative, e SES serve per inviare email in massa, non per i flussi di notifica degli allarmi."]},
  "62": {"h":"dd4f9407","question":"Quale servizio AWS consente di definire ed effettuare il provisioning dell'infrastruttura AWS tramite codice (template), consentendo deployment coerenti e ripetibili?","options":["AWS Elastic Beanstalk","AWS CodeDeploy","AWS CloudFormation","AWS Systems Manager"],"explanation":"AWS CloudFormation è un servizio di Infrastructure as Code (IaC) che consente di modellare, effettuare il provisioning e gestire le risorse AWS tramite template JSON o YAML. Gli stack CloudFormation garantiscono deployment dell'infrastruttura coerenti e ripetibili e consentono il controllo di versione dell'infrastruttura.","optionExplanations":["AWS Elastic Beanstalk distribuisce il codice applicativo e gestisce l'infrastruttura circostante — non è uno strumento IaC per definire l'infrastruttura tramite template.","AWS CodeDeploy automatizza il deployment del codice applicativo sulle risorse di calcolo — non definisce né effettua il provisioning dell'infrastruttura da template.","Corretto — AWS CloudFormation usa template JSON/YAML per definire, effettuare il provisioning e gestire interi stack di infrastruttura AWS in modo ripetibile e coerente.","AWS Systems Manager si occupa della gestione operativa (patching, inventario, esecuzione di comandi) — non è un servizio IaC per definire e distribuire l'infrastruttura tramite template."]},
  "63": {"h":"53e1944b","question":"Una piccola azienda con un solo account AWS vuole un unico servizio che ispezioni l'account e suggerisca miglioramenti: risorse inattive che sprecano denaro, Security Group con porte aperte e servizi vicini alle proprie quote. Quale servizio AWS dovrebbe usare l'azienda?","options":["AWS Config","Amazon CloudWatch","AWS Trusted Advisor","AWS Security Hub"],"explanation":"AWS Trusted Advisor ispeziona l'ambiente AWS e fornisce raccomandazioni in categorie come ottimizzazione dei costi, prestazioni, sicurezza, tolleranza ai guasti e limiti dei servizi (quote). Il numero di controlli disponibili dipende dal piano di supporto.","optionExplanations":["AWS Config valuta le configurazioni delle risorse rispetto a regole definite dall'azienda. Non suggerisce risparmi sui costi né avvisa riguardo alle quote dei servizi.","CloudWatch raccoglie metriche e log e genera allarmi. Non fornisce raccomandazioni di best practice su costi, sicurezza e quote.","Corretto — Trusted Advisor controlla l'account e suggerisce miglioramenti per costi, sicurezza, quote e altro.","Security Hub si concentra sui finding di sicurezza e sugli standard di sicurezza. Non individua risparmi sui costi né problemi di quote."]},
  "64": {"h":"9b6ca288","question":"Quale servizio AWS consente ai clienti di migrare database on-premises su AWS con un downtime minimo e supporta migrazioni tra motori di database diversi (ad es. da Oracle ad Amazon Aurora)?","options":["AWS Snowball","AWS Application Migration Service","AWS Database Migration Service (DMS)","AWS Schema Conversion Tool (SCT)"],"explanation":"AWS DMS (Database Migration Service) aiuta a migrare i database su AWS in modo rapido e sicuro. Supporta migrazioni omogenee (ad es. da MySQL a RDS MySQL) ed eterogenee (ad es. da Oracle ad Aurora). Il database di origine resta operativo durante la migrazione, riducendo al minimo il downtime.","optionExplanations":["AWS Snowball serve a trasferire fisicamente grandi quantità di dati su AWS — non supporta migrazioni di database a caldo né la conversione dello schema tra motori diversi.","AWS Application Migration Service effettua il rehost di interi server su Amazon EC2; non è pensato per migrazioni di database tra motori diversi.","Corretto — AWS DMS migra i database con downtime minimo, supportando migrazioni sia omogenee sia eterogenee (tra motori diversi) mantenendo operativa l'origine.","AWS Schema Conversion Tool (SCT) converte lo schema del database da un motore a un altro — lavora insieme a DMS ma non è il servizio che esegue la migrazione vera e propria dei dati."]},
  "65": {"h":"923dfe5e","question":"Un'azienda deve trasferire 80 TB di dati su AWS. La sua banda di rete è limitata e il trasferimento richiederebbe settimane. Quale servizio AWS dovrebbe usare per trasferire fisicamente i dati?","options":["AWS Direct Connect","AWS DataSync","AWS Snowball","AWS Storage Gateway"],"explanation":"AWS Snowball è una soluzione di trasporto fisico dei dati che usa dispositivi sicuri e robusti. È ideale quando trasferire grandi quantità di dati (da terabyte a petabyte) via rete sarebbe impraticabile o troppo lento. I dati vengono copiati sul dispositivo, che viene spedito ad AWS per l'importazione in S3.","optionExplanations":["AWS Direct Connect fornisce un collegamento di rete privato dedicato — per 80 TB con banda limitata, un dispositivo fisico è più rapido e pratico che attendere il provisioning di una connessione di rete.","AWS DataSync trasferisce i dati online via internet o Direct Connect — con banda limitata, trasferire online 80 TB richiederebbe settimane o mesi.","Corretto — AWS Snowball spedisce un dispositivo fisico presso la sede del cliente; vi si caricano gli 80 TB di dati e lo si rispedisce ad AWS, che li importa in S3 — più rapido del trasferimento via rete.","AWS Storage Gateway collega lo storage on-premises ad AWS — è pensato per un accesso ibrido continuativo allo storage cloud, non per una migrazione massiva una tantum di 80 TB."]},
  "66": {"h":"bc544feb","question":"Il sito web di un'azienda deve inviare le richieste per /api a un gruppo di server, le richieste per /images a un secondo gruppo e le richieste per l'hostname shop.example.com a un terzo gruppo. Quale tipo di Elastic Load Balancer dovrebbe usare l'azienda?","options":["Classic Load Balancer","Network Load Balancer","Application Load Balancer","Gateway Load Balancer"],"explanation":"Un Application Load Balancer opera a livello applicativo (Layer 7) e può instradare le richieste HTTP e HTTPS verso target group diversi in base al percorso dell'URL, all'hostname, agli header e altro. Questo instradamento basato sul contenuto è esattamente ciò di cui il sito ha bisogno.","optionExplanations":["Il Classic Load Balancer è un load balancer di generazione precedente che non supporta l'instradamento verso target group diversi in base al percorso o all'hostname.","Un Network Load Balancer opera a livello di trasporto (Layer 4) con TCP e UDP. Non può esaminare percorsi URL o hostname per instradare le richieste.","Corretto — Un Application Load Balancer supporta l'instradamento delle richieste HTTP e HTTPS basato su percorso e su host verso target group diversi.","Un Gateway Load Balancer serve a distribuire e scalare appliance virtuali di terze parti come i firewall, non a instradare richieste web per percorso o hostname."]},
  "67": {"h":"1539943a","question":"Un'azienda vuole collegare la propria rete on-premises a un Amazon VPC tramite un tunnel cifrato attraverso la rete internet pubblica. Quale servizio AWS dovrebbe usare?","options":["AWS Direct Connect","AWS Site-to-Site VPN","Amazon CloudFront","AWS Transit Gateway"],"explanation":"AWS Site-to-Site VPN crea un tunnel IPsec cifrato tra la rete on-premises e il VPC AWS attraverso la rete internet pubblica. Rispetto a Direct Connect è un'opzione economica e rapida da configurare, anche se le prestazioni sono variabili a causa dell'instradamento su internet.","optionExplanations":["AWS Direct Connect fornisce un collegamento di rete privato dedicato — evita completamente la rete internet pubblica e non usa un tunnel cifrato su internet.","Corretto — AWS Site-to-Site VPN crea un tunnel IPsec cifrato attraverso la rete internet pubblica, fornendo una connettività sicura tra on-premises e VPC.","Amazon CloudFront è una CDN per distribuire contenuti agli utenti finali — non è un servizio VPN o di connettività di rete tra on-premises e AWS.","AWS Transit Gateway collega più VPC e reti on-premises tramite un hub centrale — instrada il traffico tra le reti collegate ma non è di per sé la tecnologia di tunnel."]},
  "68": {"h":"fc549c7d","question":"Quale servizio di calcolo AWS è il MIGLIORE per eseguire semplici applicazioni web, database e server privati virtuali gestiti, destinato a sviluppatori e piccole imprese che desiderano un'esperienza cloud semplificata?","options":["Istanze Amazon EC2","AWS Lambda","Amazon Lightsail","Container AWS Fargate"],"explanation":"Amazon Lightsail è pensato per sviluppatori, piccole imprese e studenti che vogliono un modo semplice ed economico per eseguire server privati virtuali, applicazioni e database. Offre una console di gestione semplificata con risorse incluse in pacchetto (calcolo, storage, DNS, IP statico) a un prezzo mensile basso e prevedibile.","optionExplanations":["Amazon EC2 fornisce macchine virtuali flessibili e configurabili — richiede più competenze per la configurazione e la gestione, e il prezzo è variabile, non un semplice canone mensile a pacchetto.","AWS Lambda è un servizio serverless di esecuzione di funzioni — è basato su eventi e non è adatto a eseguire applicazioni web persistenti, database o server privati virtuali.","Corretto — Amazon Lightsail fornisce VPS semplificati con risorse incluse in pacchetto (calcolo, storage, DNS, IP statico) a un prezzo mensile prevedibile, ideali per casi d'uso semplici.","AWS Fargate è un motore serverless per container — richiede conoscenze di containerizzazione ed è pensato per eseguire applicazioni containerizzate, non per semplici casi d'uso VPS."]},
  "69": {"h":"3fa7b22b","question":"Il servizio di upload di un'app di condivisione foto riceve improvvisi picchi di immagini che i worker di elaborazione non riescono a gestire tutti insieme. L'azienda vuole che gli upload vengano conservati come job che i worker prelevano ed elaborano al proprio ritmo, in modo che nessun job vada perso durante i picchi. Quale servizio AWS dovrebbe usare?","options":["Amazon SNS","Amazon SQS","Amazon MQ","Amazon EventBridge"],"explanation":"Amazon SQS è un servizio di accodamento dei messaggi completamente gestito. Il servizio di upload inserisce un messaggio in coda per ogni immagine, e i worker interrogano la coda ed elaborano i messaggi in modo indipendente. I messaggi restano conservati finché non vengono elaborati, il che disaccoppia i componenti e assorbe i picchi di traffico.","optionExplanations":["SNS invia immediatamente i messaggi ai sottoscrittori (publish/subscribe); non trattiene i job in una coda da cui i worker possano prelevarli al proprio ritmo.","Corretto — SQS conserva ogni job in una coda, così i worker possono prelevarli ed elaborarli al proprio ritmo senza perdere lavoro durante i picchi.","Amazon MQ è un message broker gestito pensato soprattutto per migrare applicazioni che usano già protocolli come JMS o AMQP; per una nuova app con una semplice esigenza di coda SQS è più adatto.","EventBridge instrada gli eventi verso i target in base a regole; non è pensato come coda di lavoro da cui i worker prelevano i job."]},
  "70": {"h":"52b097de","question":"Un'azienda deve inviare notifiche a milioni di sottoscrittori via email, SMS e push mobile contemporaneamente quando si verifica un determinato evento nella propria applicazione. Quale servizio AWS è il PIÙ adatto?","options":["Amazon SQS","Amazon SNS","Amazon SES","Amazon Pinpoint"],"explanation":"Amazon SNS (Simple Notification Service) è un servizio di messaggistica pub/sub completamente gestito. I publisher inviano messaggi ai topic SNS, e SNS distribuisce (fan-out) il messaggio contemporaneamente a tutti gli endpoint sottoscritti — tra cui email, SMS, code SQS, funzioni Lambda, endpoint HTTP e notifiche push mobile.","optionExplanations":["Amazon SQS è una coda di messaggi punto-punto — ogni messaggio viene elaborato da un solo consumer; non distribuisce contemporaneamente a più sottoscrittori su canali diversi.","Corretto — Amazon SNS distribuisce contemporaneamente i messaggi a tutti gli endpoint sottoscritti, tra cui email, SMS, SQS, Lambda, HTTP e push mobile, quando un publisher invia a un topic.","Amazon SES (Simple Email Service) è pensato per inviare email transazionali o di marketing in massa — non supporta la distribuzione multicanale verso SMS e push mobile.","Amazon Pinpoint è un servizio di comunicazione di marketing per campagne mirate di coinvolgimento degli utenti — non è pensato per la distribuzione multicanale di notifiche in tempo reale basata su eventi."]},
  "71": {"h":"74ff393e","question":"Quale servizio AWS fornisce un control plane Kubernetes gestito, consentendo agli utenti di eseguire applicazioni containerizzate senza gestire l'infrastruttura Kubernetes?","options":["Amazon ECS","AWS Fargate","Amazon EKS","AWS App Runner"],"explanation":"Amazon EKS (Elastic Kubernetes Service) è un servizio Kubernetes completamente gestito che semplifica l'esecuzione di Kubernetes su AWS senza dover installare e gestire un proprio control plane o propri worker node Kubernetes. AWS gestisce la disponibilità e la scalabilità del control plane Kubernetes.","optionExplanations":["Amazon ECS è il servizio di orchestrazione di container proprietario di AWS — usa API specifiche di AWS, non l'API Kubernetes, quindi non fornisce un control plane Kubernetes gestito.","AWS Fargate è un motore di calcolo serverless per container — è un fornitore di infrastruttura che può eseguire container per EKS o ECS, non un servizio di control plane Kubernetes.","Corretto — Amazon EKS è il servizio Kubernetes completamente gestito, in cui AWS gestisce la disponibilità e la scalabilità del control plane Kubernetes.","AWS App Runner è un servizio completamente gestito per distribuire applicazioni web containerizzate — astrae tutta l'infrastruttura ma non è un servizio Kubernetes gestito."]},
  "72": {"h":"5e2605ae","question":"Quale funzionalità di Amazon Aurora consente di replicare i dati in un massimo di altre cinque Region AWS con una latenza tipica inferiore a un secondo, offrendo disaster recovery tra Region?","options":["Deployment Multi-AZ","Aurora Read Replicas","Aurora Global Database","Aurora Serverless"],"explanation":"Amazon Aurora Global Database consente a un singolo database Aurora di estendersi su più Region AWS. Replica i dati nelle Region secondarie con una latenza tipica inferiore al secondo e può promuovere una Region secondaria a gestire l'intero carico di lettura/scrittura in meno di un minuto, per il disaster recovery.","optionExplanations":["Il deployment Multi-AZ fornisce failover automatico all'interno di una singola Region — non replica su più Region AWS per il disaster recovery tra Region.","Le Aurora Read Replicas scalano il traffico in lettura all'interno di una Region o tra Region — ma le read replica standard hanno una latenza di replica maggiore e non possono essere promosse a lettura/scrittura con la stessa rapidità di Global Database.","Corretto — Aurora Global Database replica su un massimo di 5 Region con latenza inferiore al secondo e può promuovere una Region secondaria a lettura/scrittura in meno di un minuto per il DR.","Aurora Serverless regola automaticamente la capacità di Aurora in base alla domanda — è una funzionalità di autoscaling, non una tecnologia di replica multi-Region."]},
  "73": {"h":"158af45f","question":"I file server on-premises di un'azienda stanno esaurendo lo spazio su disco. L'azienda vuole che le applicazioni locali continuino a usare normali condivisioni di file, mentre i dati vengono conservati in Amazon S3 e i file usati di frequente vengono tenuti in cache localmente per un accesso rapido. Quale servizio AWS dovrebbe usare l'azienda?","options":["AWS DataSync","AWS Storage Gateway","Amazon S3 Transfer Acceleration","AWS Snowball Edge"],"explanation":"AWS Storage Gateway è un servizio di storage ibrido che dà alle applicazioni on-premises l'accesso allo storage cloud. Con S3 File Gateway, le applicazioni usano condivisioni di file NFS o SMB, i dati vengono conservati in S3 e quelli usati di recente vengono tenuti in cache localmente.","optionExplanations":["DataSync sposta o copia dati tra lo storage on-premises e AWS, ad esempio durante una migrazione. Non fornisce condivisioni di file locali continuative basate su S3.","Corretto — Storage Gateway consente alle applicazioni locali di continuare a usare le condivisioni di file mentre i dati sono conservati in S3 con una cache locale.","Transfer Acceleration velocizza gli upload su S3 su lunghe distanze. Non fornisce alle applicazioni on-premises una condivisione di file basata su S3.","Snowball Edge è un dispositivo fisico per spostare grandi quantità di dati o per l'edge computing. Non è un'estensione permanente dello storage on-premises verso S3."]},
  "74": {"h":"ccb995b8","question":"Quale servizio AWS fornisce un servizio di query serverless che consente di analizzare i dati conservati in Amazon S3 con SQL standard, senza dover configurare o gestire infrastruttura?","options":["Amazon Redshift","Amazon EMR","Amazon Athena","AWS Glue"],"explanation":"Amazon Athena è un servizio di query interattivo e serverless che usa SQL standard per analizzare i dati direttamente in S3. Non c'è infrastruttura da configurare o gestire — basta puntare Athena sui dati in S3, definire lo schema e iniziare a eseguire query. Si paga solo per le query eseguite.","optionExplanations":["Amazon Redshift è un data warehouse gestito — richiede il provisioning di cluster, il caricamento dei dati in Redshift e la gestione dell'infrastruttura, a differenza dell'approccio serverless di Athena che interroga i dati dove si trovano.","Amazon EMR è una piattaforma big data gestita (Hadoop, Spark) — richiede provisioning e gestione dei cluster, il che la rende più complessa di un servizio di query SQL serverless.","Corretto — Amazon Athena è un servizio di query SQL serverless che analizza i dati direttamente in S3 senza infrastruttura da gestire, pagando solo per le query eseguite.","AWS Glue è un servizio ETL che trasforma e carica dati — si usa per la preparazione dei dati, non come interfaccia di query SQL per analizzare dati già presenti in S3."]},
  "75": {"h":"a3c0fe61","question":"Un'azienda ha un workload stabile e prevedibile che verrà eseguito ininterrottamente per 3 anni. Quale opzione di prezzo EC2 offre lo sconto MAGGIORE rispetto ai prezzi On-Demand?","options":["Istanze On-Demand","Spot Instances","Reserved Instances di 1 anno (All Upfront)","Reserved Instances di 3 anni (All Upfront)"],"explanation":"Le Reserved Instances di 3 anni con pagamento All Upfront offrono lo sconto più alto possibile (fino al 72%) rispetto ai prezzi On-Demand. Più lungo è il periodo e più alto è il pagamento anticipato, maggiore è lo sconto. Sono ideali per workload stabili e prevedibili.","optionExplanations":["On-Demand non prevede alcun impegno e ha il prezzo orario più alto — non offre alcuno sconto per i workload stabili.","Le Spot Instances possono offrire prezzi più bassi ma possono essere interrotte da AWS in qualsiasi momento, il che le rende inadatte a workload stabili e continui.","Le RI di 1 anno All Upfront offrono uno sconto significativo (~40%), ma la durata di 3 anni con pagamento interamente anticipato consente un risparmio nettamente maggiore.","Corretto — Le Reserved Instances di 3 anni All Upfront offrono lo sconto massimo (fino al 72%) per workload che girano in modo continuo e prevedibile per 3 anni."]},
  "76": {"h":"0176a2c6","question":"Un'azienda vuole la flessibilità di usare qualsiasi tipo di istanza EC2 in qualsiasi Region, impegnandosi comunque su un certo livello di utilizzo di calcolo per ottenere prezzi scontati. Quale modello di prezzo offre questa flessibilità?","options":["Reserved Instances","Spot Instances","Compute Savings Plans","Dedicated Hosts"],"explanation":"I Compute Savings Plans offrono la massima flessibilità — si applicano automaticamente a qualsiasi istanza EC2 indipendentemente da Region, famiglia di istanze, sistema operativo o tenancy, oltre che ad AWS Fargate e Lambda. Offrono risparmi fino al 66% rispetto a On-Demand in cambio di un impegno di 1 o 3 anni su una determinata spesa di calcolo.","optionExplanations":["Le Reserved Instances sono legate a una specifica famiglia di istanze e a una Region — non hanno la flessibilità tra famiglie, tra Region e tra servizi descritta.","Le Spot Instances non sono un modello di prezzo basato su un impegno; usano la capacità EC2 inutilizzata e possono essere interrotte in qualsiasi momento.","Corretto — I Compute Savings Plans si applicano automaticamente a qualsiasi tipo, famiglia, sistema operativo e Region di istanze EC2, oltre a Lambda e Fargate, in cambio di un impegno di spesa in $/ora.","I Dedicated Hosts sono server fisici assegnati in esclusiva per esigenze di licenza o di conformità — non sono un modello flessibile di impegno sui costi."]},
  "77": {"h":"e8dcd008","question":"Il team finance di un'azienda vuole vedere come è cambiata la spesa AWS negli ultimi mesi, suddividerla per servizio e per cost allocation tag, individuare le tendenze e consultare una previsione per i mesi successivi — il tutto in un'interfaccia grafica. Quale strumento AWS dovrebbe usare?","options":["AWS Budgets","AWS Cost and Usage Report","AWS Cost Explorer","AWS Pricing Calculator"],"explanation":"AWS Cost Explorer è uno strumento interattivo per visualizzare e analizzare nel tempo i costi e l'utilizzo di AWS. Gli utenti possono filtrare e raggruppare per servizio, Region, account o tag, creare report personalizzati e consultare le previsioni dei costi.","optionExplanations":["Budgets invia avvisi quando costi o utilizzo superano soglie definite; non è lo strumento principale per esplorare l'andamento storico della spesa.","Il Cost and Usage Report fornisce dati di fatturazione grezzi molto dettagliati in Amazon S3; per analizzarli servono altri strumenti, quindi non è un'interfaccia grafica pronta all'uso.","Corretto — Cost Explorer mostra la spesa storica in grafici, la filtra per servizio o tag e fornisce previsioni.","Pricing Calculator stima il costo di workload pianificati; non analizza i costi già sostenuti dall'azienda."]},
  "78": {"h":"44d15262","question":"Un'azienda vuole ricevere un avviso quando la propria spesa mensile su AWS supera i 500 $. Quale servizio AWS dovrebbe usare?","options":["AWS Cost Explorer","AWS Budgets","AWS Cost and Usage Report","Amazon CloudWatch"],"explanation":"AWS Budgets consente di impostare budget personalizzati di costo e di utilizzo e di ricevere avvisi (via email o SNS) quando i costi superano — o si prevede che superino — una soglia definita. È possibile creare budget per costi, utilizzo, utilizzo delle Reserved Instances e Savings Plans.","optionExplanations":["Cost Explorer visualizza e prevede la spesa ma non invia direttamente notifiche di avviso basate su soglie quando viene raggiunto un limite di spesa.","Corretto — AWS Budgets consente di impostare una soglia in dollari (ad es. 500 $/mese) e invia avvisi via email o SNS quando i costi effettivi o previsti la superano.","Il Cost and Usage Report fornisce dati di fatturazione dettagliati in S3 — non invia avvisi o notifiche in base ai livelli di spesa.","Amazon CloudWatch invia allarmi basati su metriche operative (CPU, latenza, tassi di errore) — per gli avvisi basati sui costi il servizio corretto è AWS Budgets."]},
  "79": {"h":"25aabaf8","question":"Quale servizio AWS consente ai clienti di stimare il costo dei workload AWS pianificati prima di impegnarsi su qualsiasi risorsa?","options":["AWS Cost Explorer","AWS Budgets","AWS Pricing Calculator","AWS Trusted Advisor"],"explanation":"AWS Pricing Calculator è uno strumento web gratuito che consente di stimare il costo dell'infrastruttura AWS pianificata prima di distribuirla. È possibile modellare la soluzione, configurare le risorse e consultare una stima della fattura mensile senza creare un account.","optionExplanations":["Cost Explorer analizza la spesa storica effettiva — non può stimare il costo di una nuova architettura non ancora distribuita.","AWS Budgets monitora la spesa corrente rispetto a limiti definiti — non è uno strumento di pianificazione o di stima per architetture future.","Corretto — AWS Pricing Calculator (calc.aws) consente di configurare qualsiasi combinazione di servizi AWS e di ottenere una stima del costo mensile prima di creare qualsiasi risorsa.","Trusted Advisor fornisce controlli di best practice sull'ambiente esistente — non stima il costo di nuovi workload."]},
  "80": {"h":"c59058de","question":"Un'azienda manifatturiera globale esegue su AWS workload critici per il business in diverse business unit. Vuole supporto tecnico 24/7 più un Technical Account Manager (TAM) dedicato che conosca il suo ambiente e fornisca indicazioni proattive. Non ha bisogno di ingegneri dedicati alla gestione degli incidenti né di ingegneri specialisti di dominio. Quale piano AWS Support è il PIÙ adatto?","options":["AWS Business Support+","AWS Enterprise Support","AWS Unified Operations","Basic Support"],"explanation":"AWS Enterprise Support è rivolto ai workload critici per il business in organizzazioni che desiderano una guida esperta, e include un Technical Account Manager dedicato. Business Support+ offre supporto tecnico 24/7 senza TAM, mentre Unified Operations aggiunge ingegneri per la gestione degli incidenti e specialisti di dominio per workload mission-critical.","optionExplanations":["Business Support+ è il piano minimo consigliato per i workload di produzione e offre supporto tecnico 24/7, ma non include un TAM dedicato.","Corretto — Enterprise Support è pensato per workload critici per il business nelle organizzazioni e include un TAM dedicato che fornisce indicazioni proattive.","Unified Operations aggiunge ingegneri specialisti di dominio e ingegneri per la gestione degli incidenti dedicati, per workload mission-critical, di cui l'azienda dichiara di non aver bisogno.","Basic Support include assistenza clienti, documentazione e AWS re:Post, ma nessun ingegnere di supporto tecnico e nessun TAM."]},
  "81": {"h":"783a4dc0","question":"Il team operativo di un'azienda usa un proprio sistema di gestione degli incidenti. Invece di far controllare una console al personale, vuole che il sistema recuperi automaticamente le informazioni sulla manutenzione programmata di AWS e sui problemi dei servizi che riguardano le risorse dell'azienda. Cosa dovrebbe usare l'azienda?","options":["AWS Health API","AWS CloudTrail","AWS Trusted Advisor","AWS Config"],"explanation":"AWS Health fornisce una vista personalizzata degli eventi, come manutenzioni programmate e problemi dei servizi, che riguardano le risorse di un account. L'AWS Health Dashboard mostra questi eventi nella console, mentre l'AWS Health API consente a strumenti e sistemi di recuperarli in modo programmatico.","optionExplanations":["Corretto — l'AWS Health API offre l'accesso programmatico agli stessi eventi personalizzati mostrati nell'AWS Health Dashboard.","CloudTrail registra le chiamate API effettuate nell'account a fini di audit. Non segnala problemi dei servizi AWS né manutenzioni programmate.","Trusted Advisor controlla l'account rispetto alle best practice su costi, sicurezza e quote. Non segnala gli eventi dei servizi AWS.","AWS Config registra e valuta le configurazioni delle risorse. Non fornisce informazioni su manutenzioni o problemi dei servizi AWS."]},
  "82": {"h":"aa68e78b","question":"Quale servizio AWS consente di gestire centralmente più account AWS e di applicare policy di governance a tutti gli account di un'organizzazione?","options":["AWS IAM Identity Center","AWS Control Tower","AWS Organizations","AWS Config"],"explanation":"AWS Organizations consente di gestire e governare centralmente più account AWS. Abilita la fatturazione consolidata, l'applicazione di Service Control Policies (SCP) per limitare le azioni che gli account possono eseguire e il raggruppamento degli account in Organizational Unit (OU) per la gestione delle policy.","optionExplanations":["IAM Identity Center centralizza l'accesso degli utenti e il single sign-on tra account — gestisce chi può accedere, non come gli account sono strutturati o governati.","AWS Control Tower automatizza la configurazione di una landing zone multi-account sicura usando Organizations, ma è Organizations il servizio di base che fornisce la gerarchia degli account e le SCP.","Corretto — AWS Organizations fornisce la gerarchia degli account (OU), le Service Control Policies per la governance e la fatturazione consolidata su tutti gli account membri.","AWS Config traccia le modifiche alla configurazione delle risorse e le regole di conformità — non gestisce la struttura multi-account né applica policy di governance a livello di organizzazione."]},
  "83": {"h":"b4a3509e","question":"Una holding ha acquisito due startup, e ciascuna azienda ha il proprio account AWS e una fattura mensile separata. Il team finance vuole un'unica fattura per tutti e tre gli account, e vuole che l'utilizzo combinato concorra ai livelli di prezzo a volume e che gli sconti delle Reserved Instances vengano condivisi. Quale funzionalità di AWS Organizations dovrebbe usare l'azienda?","options":["Service control policies (SCP)","Fatturazione consolidata (consolidated billing)","AWS Budgets","AWS Cost Explorer"],"explanation":"La fatturazione consolidata di AWS Organizations riunisce gli addebiti di tutti gli account membri in un'unica fattura pagata dal management account. L'utilizzo viene aggregato tra gli account per i livelli di prezzo a volume, e gli sconti di Reserved Instances e Savings Plans possono essere condivisi tra gli account.","optionExplanations":["Le SCP definiscono le autorizzazioni massime per gli account di un'organizzazione. Non hanno nulla a che vedere con l'unificazione delle fatture o la condivisione degli sconti.","Corretto — La fatturazione consolidata fornisce un'unica fattura per tutti gli account, aggrega l'utilizzo per i prezzi a volume e condivide gli sconti delle Reserved Instances tra gli account.","AWS Budgets invia avvisi quando costi o utilizzo superano delle soglie. Non unifica le fatture né aggrega l'utilizzo per ottenere sconti.","AWS Cost Explorer visualizza e analizza i costi. Non unisce le fatture né fa condividere agli account i prezzi a volume e gli sconti."]},
  "84": {"h":"899cc0ac","question":"Una studentessa sta creando un nuovo account AWS per imparare le competenze cloud. Vuole usare i crediti che AWS offre ai nuovi clienti e deve avere la certezza che l'account non possa generare alcun addebito. Quale opzione dovrebbe scegliere al momento della registrazione?","options":["Il piano di account Paid","Il piano di account Free","Il piano Basic Support","Un Savings Plan No Upfront"],"explanation":"I nuovi clienti AWS scelgono tra un piano Free e un piano Paid. Il piano Free fornisce crediti utilizzabili per un massimo di sei mesi e non comporta addebiti; al termine di quel periodo o all'esaurimento dei crediti l'account viene chiuso, a meno che non venga aggiornato al piano Paid. Le offerte sempre gratuite sono disponibili con entrambi i piani.","optionExplanations":["Il piano Paid consente all'account di usare AWS oltre le offerte gratuite e di ricevere addebiti per tale utilizzo, quindi non garantisce l'assenza di addebiti.","Corretto — il piano Free offre ai nuovi clienti crediti per esplorare AWS e non comporta addebiti sull'account.","Basic Support è il piano di supporto incluso in ogni account. Non determina se l'account possa ricevere addebiti per l'utilizzo di AWS.","Un Savings Plan è un impegno su un livello costante di utilizzo in cambio di prezzi più bassi. Genera addebiti anziché impedirli."]},
  "85": {"h":"39bfb6e8","question":"Un'azienda ha diversi account AWS in un'unica organizzazione AWS Organizations con fatturazione consolidata. Un account ha acquistato delle Reserved Instances, ma di notte le sue istanze vengono fermate mentre un altro account esegue istanze corrispondenti. Cosa succede allo sconto delle Reserved Instances non utilizzato?","options":["Va perso per quelle ore","Può applicarsi all'altro account","Viene rimborsato come crediti AWS","Passa al mese di fatturazione successivo"],"explanation":"Con la fatturazione consolidata, gli sconti di Reserved Instances e Savings Plans sono condivisi per impostazione predefinita tra gli account dell'organizzazione, quindi gli sconti non utilizzati in un account possono applicarsi all'utilizzo corrispondente in un altro account. La condivisione degli sconti può essere disattivata se necessario.","optionExplanations":["Gli sconti non vanno semplicemente persi se altri account dell'organizzazione hanno un utilizzo corrispondente, perché la condivisione è attiva per impostazione predefinita.","Corretto — la fatturazione consolidata condivide per impostazione predefinita gli sconti di Reserved Instances e Savings Plans tra gli account dell'organizzazione.","AWS non rimborsa come crediti le ore di Reserved Instances non utilizzate.","Le ore di Reserved Instances non utilizzate non vengono riportate a un periodo di fatturazione successivo."]},
  "86": {"h":"fc6e80a9","question":"Un'azienda del retail si è data l'obiettivo aziendale di ridurre l'impronta di carbonio delle proprie operazioni IT. I suoi architetti vogliono indicazioni su come massimizzare l'utilizzo delle risorse e ridurre l'energia e le risorse consumate dai workload AWS. Su quale pilastro dell'AWS Well-Architected Framework dovrebbero concentrarsi?","options":["Cost Optimization","Operational Excellence","Sustainability","Performance Efficiency"],"explanation":"Il pilastro Sustainability si concentra sulla riduzione al minimo dell'impatto ambientale dell'esecuzione dei workload nel cloud. Le sue pratiche comprendono comprendere il proprio impatto, fissare obiettivi di sostenibilità, massimizzare l'utilizzo e usare hardware e servizi gestiti più efficienti — esattamente ciò che serve all'obiettivo di riduzione delle emissioni dell'azienda.","optionExplanations":["Cost Optimization può ridurre gli sprechi come effetto collaterale, ma il suo obiettivo è ridurre la spesa, non l'impatto ambientale.","Operational Excellence riguarda l'esecuzione, il monitoraggio e il miglioramento delle operazioni. Non affronta l'obiettivo di impronta di carbonio dell'azienda.","Corretto — Sustainability è il pilastro dedicato a ridurre l'impatto ambientale dei workload cloud, anche massimizzando l'utilizzo e riducendo le risorse consumate.","Performance Efficiency riguarda l'uso efficiente delle risorse per soddisfare i requisiti di prestazione, non gli obiettivi ambientali."]},
  "87": {"h":"a749fa99","question":"Quale servizio AWS consente ai clienti di confrontare la propria architettura con le best practice AWS e fornisce un piano di miglioramento con priorità sui sei pilastri del Well-Architected Framework?","options":["AWS Trusted Advisor","AWS Well-Architected Tool","AWS Config","AWS Security Hub"],"explanation":"L'AWS Well-Architected Tool è un servizio che consente di confrontare lo stato dei propri workload con le più recenti best practice architetturali di AWS. Pone domande su tutti e sei i pilastri e fornisce un piano di miglioramento con raccomandazioni in ordine di priorità.","optionExplanations":["AWS Trusted Advisor fornisce controlli automatici di best practice in tempo reale su cinque categorie — non guida in una revisione architetturale strutturata su tutti e sei i pilastri Well-Architected.","Corretto — L'AWS Well-Architected Tool conduce revisioni strutturate ponendo domande su tutti e sei i pilastri e produce un piano di miglioramento con priorità e i rischi individuati.","AWS Config registra le configurazioni delle risorse e valuta la conformità — non esegue revisioni architetturali né fornisce indicazioni sui pilastri Well-Architected.","AWS Security Hub aggrega i finding di sicurezza di più servizi — è focalizzato sul livello di sicurezza, non sulle revisioni architetturali su tutti e sei i pilastri."]},
  "88": {"h":"eeae9709","question":"Il data center on-premises di un'azienda richiede un investimento in conto capitale di 2 milioni di dollari per nuovi server. Quale vantaggio del cloud computing AWS risponde direttamente a questa preoccupazione?","options":["Aumentare velocità e agilità","Diventare globali in pochi minuti","Sostituire le spese fisse con spese variabili","Beneficiare di enormi economie di scala"],"explanation":"Sostituire le spese fisse (CapEx) con spese variabili (OpEx) significa pagare solo ciò che si usa invece di investire in anticipo nell'infrastruttura del data center. Questo elimina il grande esborso di capitale necessario per i server fisici.","optionExplanations":["«Aumentare velocità e agilità» si riferisce a un provisioning e un time-to-market più rapidi — riguarda i tempi, non il modello finanziario che evita grandi investimenti di capitale.","«Diventare globali in pochi minuti» si riferisce alla distribuzione rapida nelle Region di tutto il mondo — riguarda la copertura geografica, non l'eliminazione delle spese in conto capitale anticipate.","Corretto — «Sostituire le spese fisse con spese variabili» evita direttamente l'esborso di capitale di 2 milioni pagando solo ciò che si usa (OpEx) invece di acquistare hardware in anticipo.","«Beneficiare di enormi economie di scala» si riferisce a prezzi più bassi grazie al potere d'acquisto aggregato di AWS — è un vantaggio di prezzo, non riguarda direttamente l'eliminazione dell'investimento di capitale."]},
  "89": {"h":"9eb7cc4a","question":"In quale modello di servizio cloud il provider gestisce tutto — inclusa l'applicazione — lasciando al cliente la responsabilità solo dei propri dati e di come usa il servizio?","options":["Infrastructure as a Service (IaaS)","Platform as a Service (PaaS)","Software as a Service (SaaS)","Container as a Service (CaaS)"],"explanation":"Nel modello SaaS il provider gestisce infrastruttura, sistema operativo, runtime, middleware e l'applicazione stessa. I clienti gestiscono solo i propri dati e l'accesso degli utenti. Esempi sono Gmail, Salesforce e Microsoft 365. Offre il minor controllo al cliente ma anche il minor onere operativo.","optionExplanations":["IaaS (ad es. EC2) richiede al cliente di gestire sistema operativo, middleware, runtime e applicazione — il cliente mantiene responsabilità significative, non solo i dati e l'uso del servizio.","PaaS (ad es. Elastic Beanstalk) richiede al cliente di gestire applicazione e dati — il cliente continua a distribuire e mantenere il proprio codice applicativo.","Corretto — SaaS significa che il provider gestisce tutto, inclusa l'applicazione; i clienti gestiscono solo i propri dati e configurano come usano il servizio (ad es. Gmail, Salesforce).","Container as a Service richiede comunque al cliente di gestire le applicazioni containerizzate — non è un modello in cui il provider gestisce tutto."]},
  "90": {"h":"e7833730","question":"Un ospedale deve mantenere le cartelle cliniche dei pazienti e i sistemi che le elaborano all'interno del proprio edificio. Il suo team IT vuole eseguire Amazon EC2 e Amazon EBS on-premises e gestirli con le stesse API, gli stessi strumenti e la stessa console AWS che usa nel cloud. Quale servizio AWS dovrebbe usare l'ospedale?","options":["AWS Local Zones","AWS Wavelength","AWS Outposts","AWS Snow Family"],"explanation":"AWS Outposts è un servizio completamente gestito che installa infrastruttura progettata da AWS nella sede del cliente. Esegue localmente servizi AWS come EC2 ed EBS con le stesse API, gli stessi strumenti e la stessa console dell'AWS Cloud, così i dati e l'elaborazione dell'ospedale restano nel suo edificio.","optionExplanations":["Le Local Zones collocano infrastruttura AWS in siti gestiti da AWS vicino alle grandi città, non all'interno dell'edificio dell'ospedale.","Wavelength integra il calcolo AWS nelle reti 5G degli operatori di telecomunicazioni per le applicazioni mobili, non nella sede del cliente.","Corretto — Outposts porta infrastruttura, servizi, API e strumenti AWS nella sede dell'ospedale, così dati ed elaborazione restano on-premises.","I dispositivi Snow Family servono soprattutto a spostare dati e all'edge computing in luoghi difficili o non connessi, non a eseguire un'estensione permanente di AWS on-premises."]},
  "91": {"h":"4de478d1","question":"Quale componente dell'infrastruttura AWS estende il calcolo e lo storage AWS all'edge delle reti 5G, all'interno dei data center degli operatori di telecomunicazioni, consentendo una latenza bassissima per le applicazioni mobili?","options":["AWS Local Zones","AWS Wavelength","AWS Outposts","Edge Location"],"explanation":"AWS Wavelength integra il calcolo e lo storage AWS nelle reti 5G dei fornitori di servizi di comunicazione, consentendo latenze nell'ordine di pochi millisecondi verso i dispositivi mobili. Casi d'uso comuni sono AR/VR, gaming in tempo reale e applicazioni per veicoli connessi.","optionExplanations":["Le AWS Local Zones estendono AWS alle aree metropolitane per un calcolo a bassa latenza, ma non sono integrate nelle reti 5G degli operatori e non forniscono mobile edge computing.","Corretto — AWS Wavelength integra calcolo e storage AWS nelle reti 5G degli operatori di telecomunicazioni, consentendo latenze di pochi millisecondi verso dispositivi mobili e connessi.","AWS Outposts porta AWS nella sede on-premises del cliente — non è integrato nelle reti 5G né pensato per casi d'uso di mobile edge.","Le Edge Location sono endpoint della CDN CloudFront per il caching dei contenuti — non forniscono capacità di calcolo integrata nelle reti 5G per applicazioni mobili."]},
  "92": {"h":"5c14912a","question":"Un'azienda del settore media vuole eseguire applicazioni sensibili alla latenza più vicino a una specifica area metropolitana che non ha una Region AWS completa nelle vicinanze. Quale opzione dell'infrastruttura AWS dovrebbe usare?","options":["AWS Wavelength","AWS Outposts","AWS Local Zones","Una Edge Location AWS"],"explanation":"Le AWS Local Zones sono estensioni di una Region AWS collocate nelle principali aree metropolitane, che consentono di eseguire workload sensibili alla latenza più vicino a grandi centri abitati lontani dalle Region AWS esistenti. Offrono un sottoinsieme di servizi AWS con latenze di pochi millisecondi per gli utenti locali.","optionExplanations":["AWS Wavelength è integrato nelle reti 5G degli operatori per il mobile edge computing — è pensato per la latenza dei dispositivi mobili, non per workload di un'area metropolitana vicino ai centri abitati.","AWS Outposts porta hardware AWS nel data center del cliente — è per l'uso on-premises, non per avvicinare l'infrastruttura AWS alla popolazione di una città.","Corretto — Le AWS Local Zones sono infrastruttura di proprietà AWS collocata nelle grandi città, che fornisce un sottoinsieme di servizi AWS con latenze di pochi millisecondi agli utenti di quell'area metropolitana.","Le Edge Location servono CloudFront CDN e Route 53 — mettono in cache i contenuti ma non eseguono workload di calcolo generici per applicazioni sensibili alla latenza."]},
  "93": {"h":"ffbe5671","question":"Qual è la differenza tra «scalabilità» ed «elasticità» nel cloud computing?","options":["La scalabilità indica l'adeguamento automatico delle risorse; l'elasticità l'adeguamento manuale delle risorse","La scalabilità aggiunge capacità per la crescita; l'elasticità scala automaticamente in su e in giù con la domanda","La scalabilità è un vantaggio del cloud; l'elasticità è un vantaggio dei data center on-premises","Sono termini sinonimi, usati in modo intercambiabile quando si descrive il cloud computing"],"explanation":"La scalabilità è la capacità di gestire un carico maggiore aggiungendo risorse. L'elasticità la estende ridimensionando automaticamente anche VERSO IL BASSO quando la domanda diminuisce, così si paga solo ciò che si usa in ogni momento. L'elasticità è dinamica e bidirezionale.","optionExplanations":["La scalabilità non indica un adeguamento automatico — può essere manuale o automatizzata. E l'elasticità non si limita all'adeguamento manuale; implica proprio una scalabilità automatica bidirezionale.","Corretto — La scalabilità aggiunge capacità per gestire la crescita; l'elasticità la estende scalando automaticamente sia verso l'alto SIA verso il basso in base alla domanda effettiva.","Sia la scalabilità sia l'elasticità sono vantaggi del cloud — l'affermazione che una sia propria dell'on-premises e l'altra del cloud è errata.","NON sono sinonimi — la scalabilità si concentra sull'aumento della capacità, mentre l'elasticità aggiunge la possibilità di ridurla automaticamente quando la domanda cala."]},
  "94": {"h":"ea4bb9e7","question":"I dirigenti di un'azienda del retail stanno avviando un programma di adozione del cloud. Vogliono assicurarsi che il passaggio ad AWS supporti la strategia aziendale: lanciare nuovi prodotti digitali, trovare nuovi ricavi dai dati e costruire un business case chiaro per l'investimento. Quale prospettiva dell'AWS Cloud Adoption Framework (AWS CAF) si concentra su questi obiettivi?","options":["Prospettiva People","Prospettiva Business","Prospettiva Platform","Prospettiva Operations"],"explanation":"La prospettiva Business dell'AWS CAF aiuta a garantire che gli investimenti nel cloud accelerino i risultati di business. Le sue capacità includono gestione della strategia, gestione dei prodotti, innovazione e monetizzazione dei dati, che corrispondono agli obiettivi dei dirigenti.","optionExplanations":["La prospettiva People riguarda cultura, struttura organizzativa, leadership e competenze del personale durante la trasformazione, non la strategia e il business case.","Corretto — La prospettiva Business allinea l'adozione del cloud alla strategia e ai risultati di business, come nuovi prodotti e nuovi ricavi.","La prospettiva Platform riguarda la progettazione e la realizzazione dell'ambiente cloud tecnico e dell'architettura, non la strategia di business.","La prospettiva Operations si concentra sull'esecuzione e il supporto dei workload cloud secondo i livelli di servizio concordati, non sul business case."]},
  "95": {"h":"ce41836d","question":"Quale strategia di migrazione al cloud prevede di spostare un'applicazione nel cloud con modifiche minime o nulle — nota anche come «lift and shift»?","options":["Replatform","Refactor","Rehost","Repurchase"],"explanation":"Il rehosting (lift and shift) migra le applicazioni nel cloud senza modificarne l'architettura sottostante. È il percorso di migrazione più rapido, non richiede modifiche al codice ed è spesso usato come primo passo verso la modernizzazione nel cloud.","optionExplanations":["Replatform («lift, tinker, and shift») introduce piccole ottimizzazioni come il passaggio a un database gestito — comporta alcune modifiche, non è una migrazione con modifiche minime o nulle.","Refactor (re-architect) riprogetta completamente l'applicazione con servizi cloud-native — è la strategia più complessa, l'opposto di modifiche minime.","Corretto — Rehost (lift and shift) migra le applicazioni su AWS senza modifiche all'architettura, ed è quindi la strategia di migrazione più rapida e semplice.","Repurchase (drop and shop) sostituisce un'applicazione on-premises con un prodotto SaaS — comporta un cambio di software, non la migrazione dell'applicazione esistente."]},
  "96": {"h":"5873560b","question":"Un'azienda sta migrando su AWS e vuole sostituire un sistema CRM on-premises su licenza con un'alternativa SaaS. Quale strategia di migrazione rappresenta questa scelta?","options":["Rehost","Replatform","Repurchase","Refactor"],"explanation":"Il repurchasing (detto anche «drop and shop») consiste nel passare da una licenza tradizionale a un modello SaaS — ad esempio sostituendo un CRM on-premises con Salesforce. Semplifica le operazioni passando a un prodotto SaaS completamente gestito.","optionExplanations":["Rehost (lift and shift) migra l'applicazione esistente nel cloud senza modifiche — non sostituisce l'applicazione con un'alternativa SaaS.","Replatform introduce piccole ottimizzazioni nell'applicazione esistente (ad es. il passaggio a database gestiti) — non comporta la sostituzione dell'applicazione con un prodotto SaaS.","Corretto — Repurchase (drop and shop) sostituisce un'applicazione on-premises su licenza con un'alternativa SaaS, ad esempio passando da un CRM on-premises a Salesforce.","Refactor riprogetta e ricostruisce completamente l'applicazione con servizi cloud-native — è una profonda riprogettazione, non la sostituzione con un prodotto SaaS esistente."]},
  "97": {"h":"e54df6c7","question":"Un'azienda sta spostando un'applicazione web on-premises su Amazon EC2. Durante il trasferimento sostituirà il proprio database MySQL autogestito con Amazon RDS per ridurre il lavoro di amministrazione, ma non riprogetterà l'architettura dell'applicazione né ne riscriverà il codice. Quale strategia di migrazione sta usando l'azienda?","options":["Rehost (lift and shift)","Replatform","Refactor (re-architect)","Retire"],"explanation":"Il replatforming («lift, tinker, and shift») sposta un'applicazione con alcune ottimizzazioni per il cloud — come il passaggio da un database autogestito ad Amazon RDS — senza modificarne l'architettura di base. L'azienda ottiene alcuni vantaggi dei servizi gestiti senza una riprogettazione completa.","optionExplanations":["Il rehosting sposta l'applicazione così com'è, senza modifiche. Il passaggio del database ad Amazon RDS è un'ottimizzazione, quindi si va oltre un semplice lift and shift.","Corretto — Il replatforming mantiene l'architettura di base ma introduce ottimizzazioni mirate, come lo spostamento del database su Amazon RDS.","Il refactoring significa riprogettare l'applicazione con funzionalità cloud-native come microservizi o serverless. L'azienda dichiara esplicitamente di non riprogettare l'architettura.","Il retire significa dismettere un'applicazione non più necessaria. L'azienda sta migrando l'applicazione, non spegnendola."]},
  "98": {"h":"efe7140c","question":"Quale strategia di migrazione al cloud prevede di riprogettare e ricostruire completamente un'applicazione usando funzionalità cloud-native, come microservizi e architetture serverless?","options":["Rehost","Replatform","Repurchase","Refactor"],"explanation":"Il refactoring (re-architecting) consiste nel ripensare la progettazione di un'applicazione usando funzionalità cloud-native. È la strategia più complessa, ma offre i maggiori vantaggi a lungo termine in termini di agilità, prestazioni e scalabilità.","optionExplanations":["Rehost migra senza alcuna modifica al codice o all'architettura — non riprogetta l'applicazione con pattern cloud-native.","Replatform introduce piccole ottimizzazioni all'architettura esistente — non riprogetta completamente l'applicazione con microservizi o serverless.","Repurchase sostituisce un'applicazione con un prodotto SaaS — non comporta la ricostruzione di un'applicazione esistente con servizi cloud-native.","Corretto — Refactor (re-architect) ripensa completamente la progettazione dell'applicazione con funzionalità cloud-native come microservizi, serverless e servizi gestiti, per il massimo vantaggio a lungo termine."]},
  "99": {"h":"07e2261e","question":"Un piano di business continuity richiede che un'azienda ripristini i propri sistemi entro 4 ore da un disastro. Quale termine descrive MEGLIO questo requisito?","options":["Recovery Point Objective (RPO)","Recovery Time Objective (RTO)","Maximum Tolerable Downtime (MTD)","Mean Time to Recovery (MTTR)"],"explanation":"Il Recovery Time Objective (RTO) è il tempo massimo accettabile per ripristinare i servizi dopo un disastro — risponde alla domanda «quanto velocemente dobbiamo ripartire?». Il Recovery Point Objective (RPO) risponde a «quanti dati possiamo permetterci di perdere?» e misura l'età massima dei dati recuperabili.","optionExplanations":["Il Recovery Point Objective (RPO) misura la quantità massima accettabile di dati persi, espressa come intervallo di tempo (ad es. fino a 1 ora di dati) — riguarda i dati, non il tempo di ripristino dei servizi.","Corretto — Il Recovery Time Objective (RTO) è la durata massima accettabile per ripristinare i sistemi dopo un disastro — risponde direttamente a «quanto velocemente dobbiamo tornare operativi?»","Il Maximum Tolerable Downtime (MTD) è un concetto più ampio che indica il downtime totale massimo che un'azienda può sopportare — è correlato, ma non è il termine standard per «ripristinare entro 4 ore».","Il Mean Time to Recovery (MTTR) è una metrica operativa che misura il tempo medio di riparazione per guasti ricorrenti — non è un obiettivo di pianificazione della business continuity per il disaster recovery."]},
  "100": {"h":"df8eebae","question":"Un retailer online ha bisogno di un piano di disaster recovery in una seconda Region AWS. Per contenere i costi, vuole mantenere lì solo il database principale, replicato in modo continuo e in esecuzione, e avviare i server applicativi solo quando si verifica un disastro. Quale strategia di disaster recovery descrive questo scenario?","options":["Backup and restore","Pilot light","Warm standby","Multi-site active/active"],"explanation":"Nella strategia pilot light, nella Region di ripristino sono sempre in esecuzione solo i componenti principali più critici (come un database replicato). Il resto dell'ambiente viene avviato e scalato durante un disastro. Il ripristino è più rapido rispetto a backup and restore e costa meno del warm standby.","optionExplanations":["Backup and restore non mantiene alcun sistema in esecuzione nella Region di ripristino; tutto viene ricostruito dai backup, il che è più lento che mantenere attivo il database.","Corretto — mantenere in esecuzione solo il database principale e avviare i server applicativi durante un disastro è la strategia pilot light.","Warm standby mantiene in esecuzione una copia ridotta ma pienamente funzionante dell'intero ambiente, compresi i server applicativi, cosa che il retailer vuole evitare.","Multi-site active/active esegue la produzione completa in entrambe le Region in ogni momento, che è l'opzione più costosa e non corrisponde a quanto descritto dal retailer."]},
  "101": {"h":"5398784f","question":"Quale componente dell'infrastruttura globale AWS funge da endpoint per le distribuzioni CDN di Amazon CloudFront e per le query DNS di Amazon Route 53?","options":["AWS Availability Zone","AWS Local Zone","AWS Edge Location","AWS Wavelength Zone"],"explanation":"Le AWS Edge Location sono siti distribuiti nelle principali città del mondo. Fungono da endpoint per CloudFront (memorizzando in cache i contenuti più vicino agli utenti) e per Route 53 (rispondendo alle query DNS). Le edge location sono molto più numerose delle Region e formano una rete distribuita a livello globale.","optionExplanations":["Una AWS Availability Zone è un data center isolato all'interno di una Region: ospita workload di calcolo, non l'infrastruttura di endpoint CDN/DNS.","Una AWS Local Zone estende il calcolo AWS a un'area metropolitana per workload a bassa latenza: esegue il calcolo applicativo, non servizi CDN/DNS.","Corretto — Le AWS Edge Location fungono da endpoint per CloudFront (caching CDN) e Route 53 (risoluzione DNS) e sono distribuite in centinaia di città nel mondo.","Le AWS Wavelength Zone sono integrate nelle reti di telecomunicazione 5G per l'edge computing mobile: non sono endpoint per CloudFront o Route 53."]},
  "102": {"h":"daedb4e3","question":"Un'azienda progetta la propria architettura in modo che, se un componente si guasta, il traffico venga reindirizzato automaticamente verso istanze integre senza alcuna interruzione per gli utenti. Quale principio di progettazione cloud rappresenta?","options":["Progettare per il guasto (design for failure)","Loose coupling","Implementare l'elasticità","Pensare in parallelo"],"explanation":"Il principio 'design for failure' incoraggia a costruire i sistemi presupponendo che i singoli componenti si guasteranno. Usando più AZ, health check e sostituzione automatica, il sistema nel suo complesso resta altamente disponibile nonostante i guasti dei singoli componenti.","optionExplanations":["Corretto — 'Design for failure' significa presupporre che i componenti si guasteranno e usare più AZ, health check e sostituzione automatica, così che il traffico venga reindirizzato automaticamente senza disagi per gli utenti.","Il loose coupling significa che i componenti interagiscono tramite interfacce ben definite e possono funzionare in modo indipendente: favorisce la resilienza, ma non descrive specificamente il reindirizzamento automatico del traffico dopo un guasto.","Implementare l'elasticità significa aumentare o ridurre automaticamente la capacità in base alla domanda: riguarda l'adeguamento delle risorse, non il failover automatico e il reindirizzamento del traffico.","'Pensare in parallelo' significa elaborare le attività in modo concorrente anziché sequenziale: riguarda prestazioni e throughput, non il ripristino automatico dai guasti."]},
  "103": {"h":"93558a9c","question":"Quale delle seguenti opzioni descrive MEGLIO il 'loose coupling' come best practice dell'architettura cloud?","options":["Combinare più servizi in un'unica applicazione monolitica per semplicità","I componenti interagiscono tramite interfacce ben definite e operano in modo indipendente","Legare strettamente i livelli applicativi tra loro per ridurre la latenza di rete","Usare un unico database condiviso per memorizzare tutto lo stato dell'applicazione"],"explanation":"Il loose coupling significa che i componenti interagiscono tramite interfacce ben definite (API, code di messaggi) e non dipendono strettamente dall'implementazione interna degli altri. Questo permette di aggiornare, scalare o sostituire i singoli componenti in modo indipendente, migliorando resilienza e agilità.","optionExplanations":["Combinare i servizi in un'applicazione monolitica è tight coupling: è l'opposto del loose coupling e crea dipendenze che rendono difficile aggiornare o scalare i singoli componenti.","Corretto — Il loose coupling significa che i componenti interagiscono tramite API ben definite o code di messaggi e possono operare in modo indipendente, così da poter essere scalati, aggiornati o sostituiti senza impatti sugli altri.","Legare strettamente i livelli applicativi è tight coupling: riduce resilienza e agilità, perché una modifica a un livello si ripercuote su tutti i livelli dipendenti.","Usare un unico database per tutto lo stato dell'applicazione crea tight coupling: tutti i componenti condividono lo stesso data store e ne dipendono, creando un collo di bottiglia e un single point of failure."]},
  "104": {"h":"69b9c0e6","question":"Il team operativo di un'azienda applica modifiche di configurazione e patch manualmente dalla AWS Management Console. I risultati variano da un ambiente all'altro e gli errori causano interruzioni del servizio. Il team vuole che ogni modifica venga effettuata tramite codice, in modo da poterla ripetere sempre allo stesso modo. Quale principio di progettazione dovrebbe adottare il team?","options":["Elasticità","Automazione","Loose coupling","Pensare in parallelo"],"explanation":"Automazione significa sostituire i passaggi manuali con il codice, usando strumenti come AWS CloudFormation e AWS Systems Manager. Le modifiche diventano ripetibili e coerenti e l'errore umano si riduce: è esattamente il problema del team.","optionExplanations":["L'elasticità consiste nell'aggiungere e rimuovere risorse al variare della domanda. Non risolve il problema delle modifiche manuali incoerenti.","Corretto — Automatizzare le modifiche tramite codice elimina gli errori manuali e rende ripetibile ogni modifica.","Il loose coupling riduce le dipendenze tra i componenti, così che un guasto non si propaghi. Non sostituisce il lavoro manuale in console.","Pensare in parallelo significa suddividere il lavoro in modo che venga eseguito in parallelo su molte risorse. Non riguarda la ripetibilità delle modifiche."]},
  "105": {"h":"351d6ae2","question":"Quali DUE delle seguenti sono caratteristiche del cloud computing secondo la definizione del NIST?","options":["Self-service on-demand","Prezzo mensile fisso indipendente dall'utilizzo","Ampio accesso tramite rete","Hardware fisico dedicato per ogni cliente","Provisioning manuale che richiede l'approvazione dell'IT"],"explanation":"Il NIST definisce cinque caratteristiche del cloud computing: self-service on-demand, ampio accesso tramite rete, condivisione delle risorse (resource pooling), elasticità rapida e servizio misurato. Self-service on-demand significa che gli utenti effettuano il provisioning delle risorse senza interazione umana. Ampio accesso tramite rete significa che i servizi sono raggiungibili via rete da dispositivi diversi.","optionExplanations":["Corretto — Il self-service on-demand è una delle cinque caratteristiche cloud del NIST: gli utenti possono effettuare il provisioning delle risorse senza interazione umana con il provider.","Il prezzo mensile fisso non è una caratteristica del cloud: il cloud computing usa il servizio misurato (si paga ciò che si usa), l'opposto di un prezzo fisso.","Corretto — L'ampio accesso tramite rete è una delle cinque caratteristiche del NIST: i servizi sono disponibili via rete e accessibili da dispositivi standard (telefoni, laptop, tablet).","L'hardware fisico dedicato per ogni cliente descrive un'infrastruttura dedicata/privata: la caratteristica di resource pooling del NIST implica che le risorse siano condivise tra più clienti (multi-tenant).","Il provisioning manuale con approvazione dell'IT è il modello tradizionale on-premises: la caratteristica del cloud è il self-service on-demand (senza interazione umana)."]},
  "106": {"h":"348104a2","question":"Il pilastro Performance Efficiency dell'AWS Well-Architected Framework raccomanda l'uso di architetture serverless. Qual è il motivo PRINCIPALE?","options":["I servizi serverless costano sempre meno rispetto all'uso di istanze EC2","Il serverless elimina la gestione dei server e i team si concentrano sul codice","Il serverless garantisce un uptime del 100% per ogni applicazione","I servizi serverless cifrano automaticamente tutti i dati memorizzati"],"explanation":"Le architetture serverless (Lambda, Fargate, DynamoDB, ecc.) eliminano il lavoro pesante e indifferenziato della gestione dei server: patching, scaling, capacity planning. I team si concentrano sulla scrittura di codice che genera valore per il business. Il pilastro Performance Efficiency sottolinea la democratizzazione delle tecnologie avanzate per eliminare il carico operativo.","optionExplanations":["I servizi serverless non costano sempre meno di EC2: per workload elevati e costanti EC2 può risultare più conveniente. Il vantaggio chiave è la riduzione del carico operativo, non un costo inferiore garantito.","Corretto — Il motivo principale per adottare il serverless nel pilastro Performance Efficiency è eliminare la gestione dei server (patching, scaling, capacity planning), lasciando che i team si concentrino sulla logica di business.","Il serverless non garantisce un uptime del 100%: AWS pubblica SLA per i servizi serverless, ma nessuno garantisce una disponibilità assoluta del 100%.","I servizi serverless non cifrano automaticamente tutti i dati: la configurazione della cifratura (cifratura lato server, integrazione con KMS) resta a carico del cliente."]},
  "107": {"h":"186de426","question":"Un'organizzazione rileva che il passaggio ad AWS le permetterebbe di smettere di dedicare tempo ad attività di manutenzione dell'hardware, come la sostituzione dei server guasti. Quale vantaggio del cloud computing rappresenta?","options":["Economie di scala","Diventare globali in pochi minuti","Smettere di spendere per gestire e mantenere data center","Sostituire le spese in conto capitale con spese variabili"],"explanation":"'Smettere di spendere per gestire e mantenere data center' permette alle organizzazioni di concentrarsi sui clienti e sugli elementi distintivi del business anziché sul lavoro di infrastruttura IT. AWS gestisce le operazioni dei data center (sostituzione dell'hardware, alimentazione, raffreddamento, sicurezza fisica), lasciando i team liberi di concentrarsi sull'innovazione.","optionExplanations":["Le 'economie di scala' si riferiscono ai prezzi AWS più bassi grazie al potere d'acquisto aggregato: riguardano la riduzione dei costi, non l'eliminazione del tempo dedicato alla manutenzione dell'hardware.","'Diventare globali in pochi minuti' si riferisce alla possibilità di distribuire rapidamente in Region di tutto il mondo: riguarda la rapidità di espansione geografica, non l'eliminazione della manutenzione hardware.","Corretto — 'Smettere di spendere per gestire e mantenere data center' riguarda direttamente l'eliminazione delle attività di manutenzione hardware, come la sostituzione dei server guasti.","'Sostituire le spese in conto capitale con spese variabili' si riferisce al cambiamento del modello di pagamento: riguarda l'investimento di capitale, non specificamente il carico operativo della manutenzione hardware."]},
  "108": {"h":"915ddb14","question":"Un'azienda di biglietteria online esegue il proprio livello web su un unico server di grandi dimensioni. Durante le vendite di biglietti più richieste il server va in sovraccarico, e l'azienda non vuole che un singolo server resti un single point of failure. Prevede di eseguire diversi server identici dietro un load balancer e di aggiungerne altri man mano che il traffico cresce. Quale approccio di scaling sta adottando l'azienda?","options":["Scaling verticale (scale up)","Scaling orizzontale (scale out)","Sovradimensionamento per il carico di picco","Passaggio a un tipo di istanza più piccolo"],"explanation":"Lo scaling orizzontale (scale out) aggiunge altre istanze dello stesso tipo per distribuire il carico. Elimina il single point of failure ed evita il limite di dimensione di una singola macchina, motivo per cui le architetture cloud in genere lo preferiscono.","optionExplanations":["Lo scaling verticale rende più grande un singolo server. L'azienda dipenderebbe comunque da un solo server, cosa che vuole evitare.","Corretto — Aggiungere altri server identici dietro un load balancer è scaling orizzontale, che distribuisce il carico ed elimina il single point of failure.","Sovradimensionare significa acquistare in anticipo la capacità per il picco massimo previsto. L'azienda vuole invece aggiungere server man mano che il traffico cresce.","Passare a un'istanza più piccola ridurrebbe la capacità, peggiorando il sovraccarico durante le vendite di biglietti."]},
  "109": {"h":"33ab9f96","question":"Quale servizio AWS aiuta le organizzazioni a pianificare le migrazioni al cloud usando un framework strutturato in sei prospettive: Business, People, Governance, Platform, Security e Operations?","options":["AWS Well-Architected Tool","AWS Control Tower","AWS Cloud Adoption Framework","Consulenti di AWS Professional Services"],"explanation":"L'AWS Cloud Adoption Framework (CAF) organizza le indicazioni in sei prospettive che coprono le responsabilità dei diversi gruppi di stakeholder. Aiuta le organizzazioni a sviluppare un piano completo di adozione del cloud, allineato ai propri obiettivi di business e al proprio grado di preparazione.","optionExplanations":["L'AWS Well-Architected Tool valuta le architetture dei workload esistenti rispetto alle best practice dei sei pilastri: non fornisce un framework di pianificazione della migrazione con prospettive organizzative.","AWS Control Tower configura e governa un ambiente AWS multi-account: non fornisce indicazioni organizzative né un framework strutturato di adozione.","Corretto — L'AWS CAF organizza le indicazioni per l'adozione del cloud in sei prospettive (Business, People, Governance, Platform, Security, Operations) per aiutare a pianificare una strategia completa di adozione del cloud.","AWS Professional Services è un team di consulenza diretto di AWS: non è un framework o uno strumento che le organizzazioni usano in autonomia per pianificare l'adozione del cloud."]},
  "110": {"h":"1d81479c","question":"Uno studio legale sta trasferendo decenni di contratti firmati su uno storage cloud. I soci dicono di poter attendere un po' per aprire un vecchio file, ma perdere o danneggiare un qualsiasi documento è inaccettabile. Quale caratteristica dello storage conta di PIÙ per lo studio?","options":["Bassa latenza in lettura e scrittura dei dati","Scalabilità automatica della capacità di storage","Durabilità, perché i dati non vengano mai persi né danneggiati","Disponibilità, perché lo storage resti raggiungibile durante i guasti"],"explanation":"La durabilità è la probabilità che i dati memorizzati non vengano persi o danneggiati nel tempo. Lo studio accetta un accesso più lento ma non può accettare la perdita di dati, quindi la durabilità è la caratteristica che gli interessa di più. Amazon S3, ad esempio, è progettato per una durabilità molto elevata memorizzando i dati in modo ridondante su più dispositivi e strutture.","optionExplanations":["I soci hanno detto di poter attendere per aprire i vecchi file, quindi un accesso rapido e a bassa latenza non è la priorità.","La preoccupazione dello studio è mantenere integro ogni documento, non il modo in cui cresce la capacità di storage.","Corretto — il requisito principale dello studio è che nessun documento venga mai perso o danneggiato, ovvero la durabilità.","La disponibilità riguarda la possibilità di raggiungere i dati quando servono. Lo studio accetta un certo ritardo nell'accesso; la sua preoccupazione è non perdere dati."]},
  "111": {"h":"516a6972","question":"Un'azienda vuole imporre un guardrail di governance che garantisca che nessun account AWS della sua organizzazione possa disattivare AWS CloudTrail. Quale strumento impone MEGLIO questo controllo?","options":["IAM permission boundary","Regole di AWS Config per rilevare le modifiche","SCP in AWS Organizations","AWS CloudFormation StackSets"],"explanation":"Le Service Control Policy (SCP) definiscono guardrail sui permessi degli account all'interno di AWS Organizations. Una SCP può negare la possibilità di disattivare CloudTrail in tutti gli account, e nemmeno gli amministratori degli account possono aggirarla. Le SCP rappresentano i permessi massimi disponibili per gli account.","optionExplanations":["Le IAM permission boundary fissano i permessi massimi per singole entità IAM (utenti/ruoli) all'interno di un unico account: non possono imporre guardrail a livello di organizzazione che gli amministratori degli account non possano aggirare.","Le regole di AWS Config rilevano e segnalano le configurazioni non conformi a posteriori: non possono impedire a un amministratore dell'account di disattivare CloudTrail.","Corretto — Le SCP in AWS Organizations fissano i permessi massimi consentiti per tutti gli account di una OU. Un deny in una SCP sulla disattivazione di CloudTrail non può essere aggirato nemmeno dagli amministratori degli account.","CloudFormation StackSets distribuisce template di infrastruttura su più account: non è un meccanismo di imposizione che impedisce agli amministratori di modificare le configurazioni."]},
  "112": {"h":"1168a0eb","question":"Quale delle seguenti opzioni è un esempio di sostituzione delle 'spese in conto capitale' con 'spese variabili' nel cloud computing?","options":["Acquistare una Reserved Instance con durata di 3 anni","Pagare EC2 al secondo di uso effettivo invece di acquistare server fisici","Firmare con AWS un accordo di sconto enterprise a lungo termine","Usare AWS Direct Connect invece di una VPN su internet"],"explanation":"Pagare EC2 al secondo di uso effettivo (prezzi On-Demand) invece di acquistare in anticipo server fisici è l'esempio tipico del passaggio da CapEx a OpEx. Anziché un grande investimento di capitale iniziale, si sostengono spese operative variabili che crescono con l'utilizzo, migliorando il flusso di cassa ed eliminando il rischio di sovradimensionamento.","optionExplanations":["L'acquisto di una Reserved Instance triennale è un modello basato su un impegno: pur essendo più economico di On-Demand, comporta comunque un impegno anticipato e non è un esempio puro di spesa variabile 'paghi solo ciò che usi'.","Corretto — Pagare EC2 al secondo di uso effettivo (On-Demand) invece di acquistare server fisici è l'esempio classico di sostituzione delle spese in conto capitale (acquisto anticipato di hardware) con spese operative variabili.","Un accordo di sconto enterprise con AWS prevede condizioni di prezzo negoziate: pur garantendo risparmi, rappresenta comunque un impegno, non il concetto puro di passaggio da CapEx a OpEx.","Usare AWS Direct Connect invece di una VPN è una scelta di architettura di rete: non illustra direttamente la sostituzione delle spese in conto capitale con spese variabili."]},
  "113": {"h":"119a3abd","question":"Quale approccio della progettazione cloud tratta i componenti dell'infrastruttura come usa e getta e ricostruisce dal codice le risorse guaste anziché ripararle manualmente?","options":["Pensare in parallelo per eseguire attività in modo concorrente","Implementare l'elasticità per adeguarsi alla domanda","Trattare le risorse come usa e getta","Mantenere le cose semplici"],"explanation":"Trattare le risorse come usa e getta (infrastruttura immutabile) significa terminare un server guasto e avviarne uno nuovo da una AMI o da un template CloudFormation, anziché accedervi per ripararlo. Questo garantisce coerenza, elimina la deriva di configurazione ed è fondamentale per le operazioni cloud-native e DevOps.","optionExplanations":["'Pensare in parallelo' significa eseguire attività in modo concorrente per migliorare le prestazioni: non descrive il concetto di terminare e ricostruire dal codice le risorse guaste.","'Implementare l'elasticità' si riferisce all'aumento e alla riduzione automatici della capacità: riguarda l'adeguamento delle risorse alla domanda, non il trattare l'infrastruttura come usa e getta e immutabile.","Corretto — Trattare le risorse come usa e getta (infrastruttura immutabile) significa ricostruire dal codice (AMI, CloudFormation) i server guasti o obsoleti anziché applicarvi patch manualmente sul posto.","'Mantenere le cose semplici' è un principio di progettazione generale: pur favorendo l'infrastruttura immutabile, non descrive specificamente la pratica di ricostruire dal codice le risorse guaste."]},
  "114": {"h":"03616d9a","question":"Quale entità IAM si dovrebbe usare per concedere a un'istanza EC2 il permesso di accedere a un bucket S3, invece di memorizzare chiavi di accesso a lungo termine sull'istanza?","options":["IAM User con chiavi di accesso salvate in un file di configurazione","IAM Group associato all'istanza","IAM Role associato all'instance profile EC2","IAM Policy applicata direttamente al bucket S3"],"explanation":"Gli IAM Role associati agli instance profile EC2 forniscono credenziali temporanee ruotate automaticamente da AWS. Questo elimina la necessità di memorizzare chiavi di accesso a lungo termine sull'istanza. L'istanza EC2 assume il ruolo e le applicazioni ottengono credenziali temporanee tramite l'instance metadata service.","optionExplanations":["Memorizzare chiavi di accesso in un file di configurazione crea credenziali a lungo termine sull'istanza: se l'istanza o il file vengono compromessi, le credenziali possono essere estratte e usate in modo improprio per un tempo indefinito.","Gli IAM Group non possono essere associati alle istanze EC2: i gruppi servono a organizzare gli utenti IAM, non a concedere permessi ai servizi AWS o alle istanze EC2.","Corretto — Un IAM Role associato a un instance profile EC2 fornisce credenziali temporanee ruotate automaticamente tramite l'instance metadata service, eliminando la necessità di chiavi di accesso a lungo termine.","Una IAM Policy applicata direttamente al bucket S3 controlla chi può accedere al bucket: non fornisce all'istanza EC2 le credenziali di identità necessarie per chiamare l'API di S3."]},
  "115": {"h":"f9151ee5","question":"Qual è lo scopo di una AWS Service Control Policy (SCP) in AWS Organizations?","options":["Concedere permessi aggiuntivi agli utenti IAM negli account membri","Definire i permessi massimi disponibili per gli account di una unità organizzativa","Configurare le regole dei security group per i VPC di tutta un'organizzazione","Verificare e riportare lo stato di conformità di tutti gli account membri"],"explanation":"Le SCP definiscono i permessi massimi per gli account di AWS Organizations. Agiscono come guardrail sui permessi: anche se un utente IAM di un account membro ha accesso completo da amministratore, una SCP può limitare le azioni che può eseguire. Le SCP NON concedono permessi; si limitano a restringerli.","optionExplanations":["Le SCP NON concedono permessi: si limitano a restringere ciò che è consentito. Anche se una SCP consente un'azione, l'utente IAM deve avere quell'azione consentita anche nelle proprie policy IAM.","Corretto — Le SCP definiscono i permessi massimi disponibili per gli account di una OU: agiscono come guardrail sui permessi che nemmeno gli amministratori degli account possono aggirare.","Le SCP agiscono sui permessi IAM e sulle azioni API: non configurano le regole dei security group dei VPC, che sono controlli di rete a livello di risorsa.","La reportistica di conformità è gestita da AWS Config e Security Hub: le SCP sono un meccanismo di gestione dei permessi, non uno strumento di audit o di reportistica di conformità."]},
  "116": {"h":"1bcb13cf","question":"Un'azienda usa Amazon Cognito per consentire a milioni di utenti di registrarsi e accedere alla propria app mobile tramite Google e Facebook. Quale funzionalità di Amazon Cognito lo rende possibile?","options":["Cognito User Pools","Cognito Identity Pools (Federated Identities)","Cognito Sync","Cognito Streams"],"explanation":"Gli Amazon Cognito User Pools forniscono una directory utenti completamente gestita per app mobile e web. Gli User Pools supportano registrazione/accesso con identity provider social (Google, Facebook, Apple), provider SAML/OIDC e flussi di autenticazione personalizzati.","optionExplanations":["Corretto — I Cognito User Pools forniscono funzionalità di directory utenti con supporto integrato per identity provider social (Google, Facebook, Apple), permettendo a milioni di utenti di registrarsi e accedere.","I Cognito Identity Pools forniscono credenziali AWS temporanee a utenti autenticati o anonimi per accedere direttamente ai servizi AWS: servono ad autorizzare l'accesso alle risorse AWS, non ai flussi di registrazione/accesso degli utenti.","Cognito Sync (deprecato, sostituito da AppSync) serviva a sincronizzare i dati utente tra dispositivi: non ad autenticare gli utenti con identity provider social.","Cognito Streams non è una funzionalità principale di Cognito: lo streaming dei dati sugli eventi degli user pool è gestito tramite trigger Lambda, non da un servizio 'Cognito Streams'."]},
  "117": {"h":"54bd8108","question":"Dopo un'interruzione del servizio, il team operativo di un'azienda deve vedere esattamente com'erano le regole di un security group la settimana scorsa e come sono cambiate da allora. Il team vuole anche ricevere una notifica ogni volta che una risorsa si discosta dalle impostazioni richieste dall'azienda. Quale servizio AWS dovrebbe usare il team?","options":["AWS CloudTrail","AWS Config","Amazon Inspector","AWS Security Hub"],"explanation":"AWS Config mantiene un inventario delle risorse AWS, registra come cambiano nel tempo le loro configurazioni e le valuta rispetto a delle regole. Il team può visualizzare la cronologia della configurazione del security group in qualsiasi momento e ricevere una notifica quando le risorse diventano non conformi.","optionExplanations":["AWS CloudTrail registra le chiamate API (chi ha effettuato una modifica e quando), ma non fornisce una vista della configurazione di una risorsa in un dato momento né la valuta rispetto alle impostazioni richieste.","Corretto — AWS Config registra la cronologia della configurazione di risorse come i security group e le valuta rispetto a delle regole, segnalando qualsiasi scostamento dalle impostazioni richieste.","Amazon Inspector analizza i workload alla ricerca di vulnerabilità software ed esposizione di rete. Non mantiene una cronologia della configurazione delle risorse.","AWS Security Hub aggrega i finding di sicurezza ed esegue controlli sulle best practice, ma non mostra com'era la configurazione di una risorsa in un momento passato."]},
  "118": {"h":"1d8afc03","question":"Un team di sicurezza vuole analizzare automaticamente i log del traffico di rete dei VPC per rilevare potenziali minacce, come connessioni in uscita insolite o port scanning. Quale servizio AWS fornisce questa funzionalità?","options":["AWS WAF","Amazon Macie","Amazon GuardDuty","AWS Config"],"explanation":"Amazon GuardDuty analizza i VPC Flow Logs (insieme ai log di CloudTrail e DNS) usando il machine learning per rilevare schemi insoliti come port scanning, connessioni in uscita anomale verso IP malevoli o mining di criptovalute. Effettua un monitoraggio continuo senza richiedere agent.","optionExplanations":["AWS WAF filtra il traffico web in ingresso in base a regole: non analizza i log del traffico di rete dei VPC né usa il ML per rilevare comportamenti di rete anomali.","Amazon Macie analizza il contenuto degli oggetti S3 alla ricerca di dati sensibili: non analizza il traffico di rete dei VPC alla ricerca di minacce.","Corretto — Amazon GuardDuty analizza i VPC Flow Logs e i log di CloudTrail e DNS usando il ML per rilevare minacce come port scanning, connessioni in uscita insolite e cryptomining.","AWS Config valuta le configurazioni delle risorse rispetto a regole di conformità: non analizza il traffico di rete né rileva minacce comportamentali."]},
  "119": {"h":"c7aa0178","question":"Qual è la differenza principale tra i Security Group e le Network ACL in un Amazon VPC?","options":["I Security Group operano a livello di subnet; le NACL a livello di istanza","I Security Group sono stateful; le NACL sono stateless","I Security Group supportano regole deny; le NACL supportano solo regole allow","I Security Group sono solo per IPv4; le NACL supportano IPv6"],"explanation":"I Security Group sono stateful: se si consente il traffico in ingresso, il traffico di ritorno in uscita è automaticamente consentito. Le NACL sono stateless: occorre definire esplicitamente sia le regole in ingresso sia quelle in uscita. I Security Group operano a livello di istanza/ENI; le NACL a livello di subnet.","optionExplanations":["I Security Group operano a livello di istanza/ENI (non di subnet) e le NACL a livello di subnet: questa risposta inverte i due.","Corretto — I Security Group sono stateful (il traffico di ritorno è consentito automaticamente), mentre le NACL sono stateless (sia le regole in ingresso sia quelle in uscita devono consentire esplicitamente il traffico).","I Security Group supportano solo regole allow (nessun deny esplicito); le NACL supportano sia regole allow sia deny: questa risposta inverte i due.","Sia i Security Group sia le NACL supportano IPv4 e IPv6: questa distinzione non differenzia correttamente i due."]},
  "120": {"h":"cd888ab1","question":"Le normative di un ente governativo richiedono che le sue chiavi di cifratura siano memorizzate su hardware dedicato single-tenant controllato esclusivamente dall'ente, senza che AWS abbia accesso alle chiavi. Quale servizio AWS soddisfa questo requisito?","options":["AWS Key Management Service (KMS)","AWS Certificate Manager (ACM)","AWS CloudHSM","AWS Secrets Manager"],"explanation":"AWS CloudHSM fornisce hardware security module (HSM) dedicati nel cloud AWS. Il cliente ha il controllo esclusivo degli HSM e gestisce le proprie chiavi e i propri utenti, soddisfacendo i requisiti di hardware single-tenant controllato dal cliente.","optionExplanations":["Le chiavi KMS sono memorizzate in HSM gestiti da AWS e condivisi tra i clienti, quindi KMS non fornisce all'ente hardware dedicato sotto il suo controllo esclusivo.","ACM emette e rinnova certificati SSL/TLS; non fornisce hardware dedicato per memorizzare le chiavi dell'ente.","Corretto — CloudHSM fornisce all'ente HSM dedicati single-tenant, in cui solo l'ente gestisce le proprie chiavi.","Secrets Manager memorizza segreti come password e chiavi API; non fornisce hardware dedicato per la memorizzazione delle chiavi."]},
  "121": {"h":"14f5a595","question":"Un'azienda vuole garantire che nessun bucket S3 del proprio account AWS possa mai essere reso accessibile pubblicamente, indipendentemente dalle singole bucket policy o dalle ACL degli oggetti. Quale funzionalità dovrebbe attivare?","options":["S3 Server-Side Encryption con chiavi KMS","S3 Object Lock","S3 Block Public Access a livello di account","Regola di AWS Config che rileva i bucket S3 pubblici"],"explanation":"Le impostazioni di S3 Block Public Access applicate a livello di account prevalgono su qualsiasi policy a livello di bucket o di oggetto che concederebbe l'accesso pubblico. Attivare tutte e quattro le impostazioni a livello di account garantisce che nessun bucket possa essere reso pubblico per errore.","optionExplanations":["S3 Server-Side Encryption cifra i dati at rest: non impedisce che i bucket vengano resi accessibili pubblicamente.","S3 Object Lock impedisce l'eliminazione o la modifica degli oggetti: riguarda la conservazione dei dati e la conformità, non i controlli sull'accesso pubblico.","Corretto — S3 Block Public Access a livello di account prevale su tutte le bucket policy e le ACL degli oggetti che concederebbero l'accesso pubblico, garantendo che nessun bucket possa diventare accessibile pubblicamente.","Le regole S3 di AWS Config rilevano a posteriori le impostazioni non conformi dei bucket: segnalano le violazioni esistenti dell'accesso pubblico, ma non impediscono che i bucket vengano resi pubblici."]},
  "122": {"h":"51863695","question":"Un audit di sicurezza AWS rileva che la chiave di accesso di un utente IAM è stata esposta in un repository GitHub pubblico. Cosa si dovrebbe fare PER PRIMA COSA?","options":["Eliminare immediatamente l'utente IAM","Ruotare la chiave di accesso e poi indagare","Disattivare o eliminare immediatamente la chiave di accesso esposta","Attivare la MFA sull'account dell'utente IAM"],"explanation":"La prima e più urgente azione è disattivare o eliminare la chiave di accesso esposta per impedirne l'uso non autorizzato. Successivamente si indaga su quali azioni sono state eseguite con la chiave (tramite CloudTrail), si eliminano le eventuali risorse non autorizzate e si creano nuove credenziali. Attivare la MFA è una buona azione successiva.","optionExplanations":["Eliminare l'utente IAM è troppo drastico come prima azione: prima si blocca la minaccia immediata disattivando la chiave esposta, poi si indaga prima di decidere se eliminare l'utente.","Ruotare la chiave (crearne una nuova ed eliminare la vecchia) è corretto, ma la domanda chiede cosa fare PER PRIMA COSA. La sequenza corretta è disattivare/eliminare subito la chiave esposta prima di ruotarla.","Corretto — Disattivare o eliminare la chiave di accesso esposta è la prima azione più urgente, perché blocca immediatamente qualsiasi uso non autorizzato in corso delle credenziali.","Attivare la MFA è un buon miglioramento della sicurezza, ma non blocca immediatamente un attaccante che sta già usando la chiave di accesso esposta. Disattivare la chiave è il primo passo più urgente."]},
  "123": {"h":"7f9778ac","question":"Quale funzionalità AWS permette agli amministratori di connettersi in modo sicuro alle istanze EC2 senza aprire porte SSH/RDP in ingresso né usare bastion host?","options":["AWS VPN","AWS Systems Manager Session Manager","Amazon EC2 Instance Connect","AWS Direct Connect"],"explanation":"AWS Systems Manager Session Manager fornisce l'accesso a una shell interattiva da browser e da CLI alle istanze EC2 senza richiedere porte in ingresso aperte, bastion host o chiavi SSH. Tutte le sessioni vengono registrate in CloudTrail e CloudWatch Logs e l'accesso è controllato tramite policy IAM.","optionExplanations":["AWS VPN crea un tunnel cifrato tra l'ambiente on-premises e AWS: di norma richiede comunque porte SSH/RDP aperte sulle istanze EC2 una volta all'interno del VPC.","Corretto — AWS Systems Manager Session Manager fornisce un accesso sicuro alla shell da browser senza porte in ingresso, bastion host o chiavi SSH, con registrazione completa delle sessioni.","Amazon EC2 Instance Connect invia chiavi pubbliche SSH temporanee alle istanze: usa comunque SSH e richiede che la porta 22 sia aperta, a differenza di Session Manager.","AWS Direct Connect fornisce un collegamento di rete privato dedicato dall'ambiente on-premises ad AWS: è un servizio di connettività, non un metodo per accedere in modo sicuro alle istanze EC2 senza porte SSH/RDP."]},
  "124": {"h":"c3d1a694","question":"Un'azienda sanitaria ha un'app mobile che invia informazioni sui pazienti a un'API ospitata su AWS. Per soddisfare un requisito normativo, l'azienda configura l'app e l'API in modo che ogni connessione usi HTTPS (TLS). Quale tipo di protezione fornisce questa configurazione?","options":["Cifratura at rest","Cifratura in transit","Cifratura lato client","Envelope encryption"],"explanation":"HTTPS usa TLS per cifrare i dati mentre viaggiano in rete tra l'app e l'API. Si tratta di cifratura in transit, che impedisce che i dati vengano letti o modificati durante il trasferimento.","optionExplanations":["La cifratura at rest protegge i dati memorizzati, ad esempio su volumi EBS o in S3. HTTPS protegge i dati mentre si spostano, non dove sono memorizzati.","Corretto — TLS/HTTPS cifra i dati mentre si spostano tra l'app e l'API: si tratta di cifratura in transit.","La cifratura lato client significa che l'app cifra autonomamente i dati prima di inviarli. Attivare HTTPS sulla connessione non fa questo.","L'envelope encryption è una tecnica di gestione delle chiavi in cui le data key vengono cifrate con una master key. Non descrive la protezione di una connessione di rete."]},
  "125": {"h":"5454e749","question":"Un'azienda vuole usare le proprie chiavi di cifratura, conservate on-premises, per cifrare i dati in Amazon S3 invece delle chiavi gestite da AWS. Quale opzione di cifratura di S3 lo consente?","options":["SSE-S3 (Server-Side Encryption con chiavi gestite da S3)","SSE-KMS (Server-Side Encryption con chiavi KMS)","SSE-C (Server-Side Encryption con chiavi fornite dal cliente)","Cifratura lato client con l'AWS SDK"],"explanation":"SSE-C permette ai clienti di fornire la propria chiave di cifratura a ogni richiesta. Amazon S3 esegue la cifratura/decifratura con la chiave fornita, ma non la memorizza. I clienti sono responsabili della gestione e della rotazione delle proprie chiavi.","optionExplanations":["SSE-S3 usa chiavi gestite da S3 e controllate interamente da AWS: il cliente non ha modo di usare le proprie chiavi on-premises.","SSE-KMS usa chiavi gestite in AWS KMS: anche se i clienti possono usare chiavi KMS gestite dal cliente, le chiavi restano memorizzate e gestite in AWS, non on-premises.","Corretto — SSE-C permette ai clienti di fornire a ogni richiesta le proprie chiavi di cifratura conservate on-premises; S3 esegue la cifratura/decifratura con quelle chiavi ma non le memorizza mai.","La cifratura lato client con l'AWS SDK cifra i dati sul client prima del caricamento: anche se tecnicamente consente di usare chiavi on-premises, SSE-C è l'opzione lato server che supporta esplicitamente le chiavi fornite dal cliente."]},
  "126": {"h":"d1b75398","question":"Quale servizio AWS usa il machine learning e la teoria dei grafi per costruire automaticamente un insieme di dati collegati a partire dai log, permettendo ai team di sicurezza di indagare sulla causa principale e sulla portata dei finding di sicurezza?","options":["Amazon GuardDuty","Amazon Detective","AWS Security Hub","Amazon Inspector"],"explanation":"Amazon Detective raccoglie automaticamente i dati di log dalle risorse AWS e usa ML, analisi statistica e teoria dei grafi per aiutare gli analisti a determinare rapidamente la causa principale dei finding di sicurezza e a condurre indagini di sicurezza efficienti.","optionExplanations":["Amazon GuardDuty rileva le minacce analizzando i log: identifica attività sospette e genera finding, ma non offre l'indagine interattiva approfondita e l'analisi della causa principale di Detective.","Corretto — Amazon Detective costruisce un dataset collegato a partire dai log usando ML e teoria dei grafi, permettendo agli analisti di sicurezza di indagare rapidamente sulla causa principale e sulla portata dei finding.","AWS Security Hub aggrega e assegna priorità ai finding di più servizi: offre una vista centralizzata, ma non esegue direttamente l'indagine approfondita e l'analisi causale di Detective.","Amazon Inspector cerca vulnerabilità software: non analizza i dati di log né esegue flussi di indagine di sicurezza."]},
  "127": {"h":"989ba8b1","question":"Secondo l'AWS Shared Responsibility Model, per quale tipo di servizio AWS si assume la responsabilità dell'applicazione delle patch al sistema operativo oltre che dell'hardware sottostante?","options":["Amazon EC2","Amazon RDS for MySQL","Amazon ECS eseguito su EC2","VPS Amazon Lightsail"],"explanation":"Per Amazon RDS, AWS gestisce il patching del sistema operativo e del motore di database come parte del servizio gestito. I clienti sono responsabili delle impostazioni del database, dell'accesso degli utenti e dei dati. Per EC2, invece, i clienti sono responsabili del patching del sistema operativo guest. Questa distinzione è centrale nel Shared Responsibility Model.","optionExplanations":["Amazon EC2 è IaaS: il cliente è responsabile del patching del sistema operativo guest in esecuzione sulla macchina virtuale. AWS gestisce solo l'hypervisor e l'hardware.","Corretto — Amazon RDS è un servizio di database gestito, quindi AWS si occupa del patching del sistema operativo e del motore di database. I clienti gestiscono solo schema, impostazioni, accesso degli utenti e dati del database.","Amazon ECS su EC2 usa comunque istanze EC2 come host dei container: il cliente è responsabile del patching del sistema operativo degli host EC2 sottostanti, come per EC2 tradizionale.","Il VPS Amazon Lightsail è un servizio di tipo IaaS: il cliente è responsabile della gestione e del patching del sistema operativo in esecuzione sul server privato virtuale."]},
  "128": {"h":"a3abc123","question":"Quali DUE servizi AWS aiutano a rilevare e rispondere alle minacce alla sicurezza analizzando log e modelli di utilizzo?","options":["Amazon GuardDuty","AWS Certificate Manager","Amazon Detective","AWS Secrets Manager","Amazon Macie"],"explanation":"Amazon GuardDuty rileva le minacce alla sicurezza analizzando i log di CloudTrail, i VPC Flow Logs e i log DNS tramite ML e threat intelligence. Amazon Macie rileva i rischi per la sicurezza dei dati in S3 individuando dati sensibili come le PII. Entrambi sono servizi di rilevamento delle minacce. ACM gestisce i certificati; Secrets Manager gestisce i segreti.","optionExplanations":["Corretto — Amazon GuardDuty analizza i log tramite ML e threat intelligence per rilevare minacce come la compromissione delle credenziali, attività di rete insolite e cryptomining.","AWS Certificate Manager gestisce i certificati SSL/TLS: non è un servizio di rilevamento delle minacce.","Amazon Detective aiuta a indagare sui finding di sicurezza dopo il rilevamento: pur analizzando i log, il suo scopo principale è l'indagine successiva al rilevamento, non il rilevamento iniziale delle minacce.","AWS Secrets Manager memorizza e ruota i segreti delle applicazioni: non è un servizio di rilevamento delle minacce.","Corretto — Amazon Macie usa il ML per rilevare dati sensibili (PII, dati finanziari) in S3 e segnala i rischi per la sicurezza dei dati, il che lo rende un servizio di rilevamento delle minacce focalizzato sui dati."]},
  "129": {"h":"9fedb6a7","question":"Un'azienda sta passando da un solo account AWS a decine di account per i diversi team. Vuole un modo rapido e automatizzato per configurare un ambiente multi-account sicuro che segua le best practice AWS, con guardrail preconfigurati e un processo standard per la creazione di nuovi account. Quale servizio AWS soddisfa MEGLIO questi requisiti?","options":["SCP in AWS Organizations","AWS Control Tower","Aggregatori di AWS Config","AWS Security Hub"],"explanation":"AWS Control Tower automatizza la configurazione di un ambiente multi-account ben architettato (una landing zone). Applica controlli preventivi e di rilevamento preconfigurati (guardrail) e fornisce Account Factory per effettuare il provisioning di nuovi account in modo standard, con una dashboard per monitorare la conformità.","optionExplanations":["Le SCP sono uno dei mattoni per i guardrail, ma l'azienda dovrebbe progettare e costruire da sé l'intero ambiente multi-account e il processo di provisioning degli account.","Corretto — AWS Control Tower configura automaticamente una landing zone conforme alle best practice, applica guardrail preconfigurati e standardizza la creazione di nuovi account.","Gli aggregatori di AWS Config raccolgono dati di configurazione e conformità da molti account, ma non configurano l'ambiente né effettuano il provisioning degli account.","AWS Security Hub aggrega i finding di sicurezza tra gli account, ma non crea una landing zone né effettua il provisioning di nuovi account."]},
  "130": {"h":"737e47dc","question":"Quale strumento AWS aiuta a identificare le risorse condivise con entità esterne e genera policy a privilegio minimo basate sull'attività di accesso effettiva, per dimensionare correttamente i permessi?","options":["AWS Trusted Advisor","IAM Access Analyzer","Amazon GuardDuty","AWS Config"],"explanation":"IAM Access Analyzer identifica le risorse condivise con entità esterne (finding di accesso esterno) e genera policy a privilegio minimo basate sull'attività di accesso (finding di accesso inutilizzato). Aiuta a individuare gli accessi eccessivamente permissivi e a dimensionare correttamente i permessi IAM.","optionExplanations":["AWS Trusted Advisor fornisce controlli generali sulle best practice, incluse alcune raccomandazioni IAM, ma non identifica le risorse condivise con l'esterno né genera policy a privilegio minimo dall'attività di accesso effettiva.","Corretto — IAM Access Analyzer identifica le risorse accessibili da entità esterne e può generare policy IAM a privilegio minimo basate sui modelli di accesso effettivi registrati in CloudTrail.","Amazon GuardDuty rileva comportamenti malevoli tramite l'analisi dei log: non analizza la condivisione delle risorse con entità esterne né genera raccomandazioni sulle policy di permesso.","AWS Config valuta le configurazioni rispetto a regole di conformità: non identifica specificamente la condivisione di risorse con l'esterno né genera policy IAM a privilegio minimo."]},
  "131": {"h":"0713f533","question":"Un team operativo vuole essere avvisato quasi in tempo reale quando AWS pianifica una manutenzione sulle sue istanze EC2 o quando un problema di un servizio AWS interessa risorse del proprio account, insieme a indicazioni su cosa fare. Quale servizio AWS fornisce questa funzionalità?","options":["Allarmi di Amazon CloudWatch","AWS Health Dashboard","AWS Config","Amazon EventBridge"],"explanation":"L'AWS Health Dashboard mostra gli eventi AWS che possono interessare il proprio account e le proprie risorse, come manutenzioni pianificate o problemi dei servizi, insieme a indicazioni per la risoluzione. Fornisce una vista personalizzata, non solo lo stato generale dei servizi AWS.","optionExplanations":["Gli allarmi di CloudWatch monitorano metriche rispetto a soglie definite dall'utente; non segnalano manutenzioni pianificate da AWS né problemi dei servizi AWS.","Corretto — l'AWS Health Dashboard notifica al team gli eventi AWS che interessano le sue risorse e fornisce indicazioni per la risoluzione.","AWS Config tiene traccia delle modifiche di configurazione delle risorse; non segnala manutenzioni AWS né interruzioni dei servizi.","EventBridge può instradare gli eventi di AWS Health verso dei target, ma è un event bus, non il servizio che fornisce le informazioni sullo stato specifiche dell'account e le relative indicazioni."]},
  "132": {"h":"15a058db","question":"Un'azienda di servizi finanziari deve essere conforme a PCI DSS e ha bisogno di scaricare l'Attestation of Compliance di AWS da presentare ai revisori. Quale servizio AWS lo fornisce?","options":["AWS Config","AWS Trusted Advisor","AWS Artifact","AWS Security Hub"],"explanation":"AWS Artifact è un portale self-service che fornisce accesso on-demand alla documentazione di conformità di AWS, inclusi l'Attestation of Compliance (AOC) PCI DSS, i report SOC, i certificati ISO e i BAA HIPAA. Questi documenti possono essere scaricati e usati nei processi di audit del cliente.","optionExplanations":["AWS Config registra le modifiche alla configurazione delle risorse e ne valuta la conformità: genera finding di conformità per le proprie risorse, ma non rende scaricabili le certificazioni di conformità di AWS.","AWS Trusted Advisor fornisce raccomandazioni sulle best practice: non fornisce certificazioni di conformità o documenti di attestazione scaricabili.","Corretto — AWS Artifact è il portale self-service per consultare e scaricare i report di conformità di AWS, inclusi AOC PCI DSS, report SOC, certificazioni ISO e accordi di conformità.","AWS Security Hub aggrega i finding di sicurezza: non fornisce report di conformità o documenti di attestazione scaricabili."]},
  "133": {"h":"831a52f1","question":"Cosa stabilisce la policy di AWS sui penetration test riguardo ai clienti che testano le proprie risorse AWS?","options":["Il penetration test di qualsiasi risorsa AWS è severamente vietato","I clienti possono testare alcuni servizi sulle proprie risorse senza approvazione preventiva","I clienti devono sempre ottenere un permesso scritto da AWS prima di qualsiasi test di sicurezza","Solo i partner certificati AWS possono eseguire penetration test sulle risorse dei clienti"],"explanation":"AWS consente ai clienti di effettuare valutazioni di sicurezza sulle proprie risorse AWS senza approvazione preventiva per un elenco definito di servizi (EC2, RDS, CloudFront, API Gateway, Lambda, Lightsail, Elastic Beanstalk, ecc.). Alcune attività, come la simulazione di attacchi DDoS, richiedono un'approvazione separata.","optionExplanations":["Il penetration test NON è severamente vietato: AWS consente ai clienti di testare le proprie risorse su un elenco definito di servizi senza approvazione preventiva.","Corretto — La policy di AWS consente ai clienti di eseguire test di sicurezza sulle proprie risorse per un insieme definito di servizi senza approvazione preventiva, nel rispetto della policy di utilizzo accettabile.","I clienti NON hanno sempre bisogno di un permesso scritto da AWS per i test di sicurezza: l'approvazione preventiva è richiesta solo per attività specifiche come la simulazione DDoS, non per i normali penetration test.","L'affermazione che solo i partner certificati AWS possano eseguire i test è errata: i clienti possono eseguire i propri test di sicurezza o incaricare qualsiasi società di sicurezza di testare le proprie risorse AWS."]},
  "134": {"h":"96b4fe23","question":"Il team di sicurezza di un'azienda usa già on-premises il prodotto di endpoint protection di un determinato fornitore. Vuole distribuire lo stesso prodotto nei propri account AWS, scegliendo da offerte selezionate a cui abbonarsi rapidamente, con i costi addebitati sulla fattura AWS. Dove dovrebbe trovare il prodotto il team?","options":["AWS Security Hub","AWS Marketplace","AWS Artifact","AWS Firewall Manager"],"explanation":"AWS Marketplace è un catalogo digitale curato in cui i clienti trovano, acquistano e distribuiscono software di terze parti, inclusi molti prodotti di sicurezza come endpoint protection, firewall e scanner di vulnerabilità. I costi compaiono sulla fattura AWS e i prodotti possono essere distribuiti direttamente negli account AWS.","optionExplanations":["Security Hub raccoglie e assegna priorità ai finding, compresi quelli degli strumenti dei partner, ma non vende né distribuisce prodotti di terze parti.","Corretto — AWS Marketplace offre software di sicurezza di terze parti che i clienti possono trovare, sottoscrivere e distribuire, con i costi addebitati sulla fattura AWS.","AWS Artifact fornisce i report e gli accordi di conformità di AWS. Non offre prodotti di sicurezza di terze parti.","Firewall Manager gestisce in modo centralizzato le regole firewall, come le regole di AWS WAF, su più account. Non è un catalogo di software di sicurezza di terze parti."]},
  "135": {"h":"5ab69240","question":"Un'azienda vuole garantire che tutte le istanze EC2 in ogni account AWS della sua organizzazione vengano aggiornate automaticamente con le patch e siano conformi alla sua policy di patching. Quale servizio AWS lo consente?","options":["Scansioni di vulnerabilità di Amazon Inspector","Systems Manager Patch Manager","Regole gestite di AWS Config","Amazon GuardDuty"],"explanation":"AWS Systems Manager Patch Manager automatizza il processo di applicazione delle patch alle istanze EC2 (e ai server on-premises), sia per gli aggiornamenti di sicurezza sia per altri tipi di aggiornamento. Può essere gestito centralmente su più account tramite l'integrazione con AWS Organizations, garantendo una conformità coerente del patching.","optionExplanations":["Amazon Inspector identifica le vulnerabilità software (CVE) nei workload in esecuzione: rileva che servono delle patch, ma non le distribuisce né automatizza il processo di patching.","Corretto — AWS Systems Manager Patch Manager automatizza il patching delle istanze EC2 e può essere gestito centralmente su più account tramite l'integrazione con AWS Organizations.","AWS Config rileva le configurazioni non conformi, incluse le istanze senza patch, ma riporta lo stato di conformità: non distribuisce patch né automatizza il processo di patching.","Amazon GuardDuty rileva le minacce tramite l'analisi dei log: non cerca patch mancanti né automatizza la distribuzione delle patch."]},
  "136": {"h":"143f4789","question":"Qual è lo scopo dei VPC Flow Logs in AWS?","options":["Acquisire i dettagli di richieste e risposte HTTP a livello applicativo","Acquisire informazioni sul traffico IP per le interfacce di rete di un VPC","Registrare tutte le chiamate API effettuate da utenti e servizi nell'account AWS","Monitorare le prestazioni delle query del database e le query lente"],"explanation":"I VPC Flow Logs acquisiscono informazioni sul traffico IP in entrata e in uscita dalle interfacce di rete di un VPC, inclusi IP di origine/destinazione, porte, protocollo e se il traffico è stato accettato o rifiutato. Sono preziosi per il troubleshooting di rete, l'analisi di sicurezza e come fonte di dati per GuardDuty.","optionExplanations":["I dettagli di richieste e risposte HTTP a livello applicativo vengono acquisiti dagli access log (log di ALB/CloudFront): i VPC Flow Logs operano a livello di rete/IP, non a livello applicativo.","Corretto — I VPC Flow Logs acquisiscono i metadati del traffico IP (IP di origine/destinazione, porte, protocollo, accettato/rifiutato) per le interfacce di rete, utili per l'analisi di sicurezza e il troubleshooting.","Registrare tutte le chiamate API nell'account AWS è lo scopo di AWS CloudTrail: i VPC Flow Logs acquisiscono il traffico IP a livello di rete, non l'attività delle chiamate API.","Il monitoraggio delle prestazioni delle query del database si effettua con servizi come Amazon RDS Performance Insights o CloudWatch Database Insights, non con i VPC Flow Logs."]},
  "137": {"h":"f524bed5","question":"Un'azienda vuole verificare costantemente che tutti gli utenti IAM abbiano la MFA attivata e che le chiavi di accesso vengano ruotate ogni 90 giorni. Quale servizio AWS può automatizzare questi controlli di conformità?","options":["AWS CloudTrail","Amazon GuardDuty","AWS Config con regole gestite","Controlli di sicurezza di AWS Trusted Advisor"],"explanation":"AWS Config dispone di regole gestite come 'iam-user-mfa-enabled' e 'access-keys-rotated' che valutano continuamente se gli utenti IAM hanno la MFA attivata e se le chiavi di accesso sono state ruotate entro il numero di giorni specificato. Le risorse non conformi vengono segnalate e possono attivare una remediation automatica.","optionExplanations":["AWS CloudTrail registra la cronologia delle chiamate API: può mostrare quando è stata usata la MFA o sono state create le chiavi, ma non valuta continuamente la conformità rispetto a policy definite come lo stato della MFA o l'età della rotazione.","Amazon GuardDuty analizza i log alla ricerca di minacce: può rilevare attività sospette legate alle credenziali, ma non valuta la conformità IAM, come i requisiti di MFA o la rotazione delle chiavi.","Corretto — Le regole gestite di AWS Config (iam-user-mfa-enabled, access-keys-rotated) valutano continuamente la conformità della configurazione IAM e segnalano automaticamente gli utenti non conformi.","AWS Trusted Advisor verifica alcune best practice IAM, ma non offre le regole granulari e valutate continuamente sullo stato della MFA e sull'età della rotazione delle chiavi che offrono le regole gestite di Config."]},
  "138": {"h":"23cf99e4","question":"Quale best practice di sicurezza raccomanda di progettare i sistemi in modo che, se un componente viene compromesso, il danno resti confinato all'area più piccola possibile?","options":["Principio del privilegio minimo","Defense in depth","Riduzione del blast radius","Architettura zero trust"],"explanation":"Ridurre il blast radius significa contenere l'impatto di una compromissione. Le tecniche includono la segmentazione della rete (subnet private), policy IAM a privilegio minimo e account AWS separati per i diversi ambienti (dev, staging, prod), così che una violazione in uno non si ripercuota sugli altri.","optionExplanations":["Il principio del privilegio minimo riduce al minimo i permessi per limitare l'esposizione: pur contribuendo alla riduzione del blast radius, è una tecnica specifica e non il concetto generale di contenimento del danno.","La defense in depth applica più livelli di sicurezza: pur sovrapponendosi, si riferisce all'approccio a livelli, non specificamente al concetto di confinare il danno all'area più piccola possibile.","Corretto — La riduzione del blast radius si riferisce specificamente alla progettazione di sistemi in cui la compromissione di un componente resta contenuta e non può propagarsi facilmente ad altri sistemi o account.","L'architettura zero trust verifica ogni richiesta di accesso indipendentemente dalla provenienza: riguarda autenticazione e autorizzazione, non specificamente il contenimento dell'impatto di una compromissione riuscita."]},
  "139": {"h":"1ac9c33c","question":"Amazon Inspector v2 individua e valuta automaticamente i workload per quali tipi di vulnerabilità di sicurezza?","options":["Problemi di raggiungibilità di rete solo per le istanze EC2","CVE del software e raggiungibilità di rete per EC2 e container","Configurazioni errate delle policy IAM e impostazioni di accesso pubblico dei bucket S3","Attacchi DDoS e tentativi di SQL injection contro le app web"],"explanation":"Amazon Inspector v2 individua automaticamente le istanze EC2 e le immagini dei container in ECR e le valuta alla ricerca di vulnerabilità software (CVE note) e di esposizioni di rete non intenzionali. Esegue scansioni continue senza richiedere finestre di manutenzione pianificate e si integra con AWS Security Hub.","optionExplanations":["La sola raggiungibilità di rete è troppo limitativa: Inspector v2 cerca sia le vulnerabilità dei pacchetti software (CVE) sia i problemi di raggiungibilità di rete.","Corretto — Amazon Inspector v2 cerca le vulnerabilità dei pacchetti software (CVE) E i problemi di raggiungibilità di rete per le istanze EC2 e le immagini dei container in ECR.","Le configurazioni IAM errate e l'accesso pubblico a S3 vengono verificati da altri servizi (IAM Access Analyzer, S3 Block Public Access): Inspector si concentra sulla scansione delle vulnerabilità di calcolo e container.","Gli attacchi DDoS e le SQL injection sono gestiti rispettivamente da Shield e WAF: Inspector si concentra sulla valutazione delle vulnerabilità software, non sul rilevamento degli attacchi in fase di esecuzione."]},
  "140": {"h":"36d4ffdf","question":"Un'azienda deve ispezionare tutto il traffico in entrata e in uscita dai propri Amazon VPC, compreso il traffico che non usa HTTP. Ha bisogno di regole di filtraggio stateful e di prevenzione delle intrusioni applicate a livello di VPC tramite un servizio AWS gestito. Quale servizio dovrebbe usare l'azienda?","options":["AWS WAF","AWS Shield Advanced","AWS Network Firewall","Security group e network ACL"],"explanation":"AWS Network Firewall è un servizio gestito di firewall e prevenzione delle intrusioni distribuito a livello di VPC. Supporta regole stateful e stateless, prevenzione delle intrusioni e filtraggio dei domini per il traffico di qualsiasi protocollo in entrata e in uscita dal VPC.","optionExplanations":["AWS WAF ispeziona solo le richieste HTTP/HTTPS verso risorse come CloudFront e gli Application Load Balancer. Non può filtrare tutto il traffico del VPC, compresi i protocolli non HTTP.","AWS Shield Advanced fornisce una protezione DDoS avanzata. Non fornisce regole di filtraggio stateful né prevenzione delle intrusioni per tutto il traffico del VPC.","Corretto — AWS Network Firewall fornisce ispezione stateful gestita e prevenzione delle intrusioni per tutto il traffico in entrata e in uscita dal VPC.","Security group e network ACL filtrano il traffico in base a indirizzo IP, porta e protocollo, ma non forniscono prevenzione delle intrusioni né deep packet inspection."]},
  "141": {"h":"f67ab899","question":"Quali DUE delle seguenti opzioni sono esempi di controlli sui dati e sugli accessi di cui i clienti sono SEMPRE responsabili secondo l'AWS Shared Responsibility Model?","options":["Dischi rigidi fisici nei data center AWS","Dati del cliente memorizzati in Amazon S3","Il livello hypervisor di Amazon EC2","Credenziali degli utenti IAM e gestione degli accessi","Hardware di rete tra le Region AWS"],"explanation":"I dati del cliente memorizzati in S3 e la gestione degli utenti IAM sono sempre responsabilità del cliente. Il cliente controlla quali dati memorizza, come vengono cifrati e chi può accedervi. La gestione IAM (creare utenti, assegnare permessi, attivare la MFA) è sempre responsabilità del cliente. L'hardware fisico e l'hypervisor sono sempre responsabilità di AWS.","optionExplanations":["I dischi rigidi fisici nei data center AWS sono responsabilità di AWS: i clienti non hanno accesso fisico né alcuna responsabilità sull'hardware di storage nei data center AWS.","Corretto — I dati del cliente memorizzati in S3 sono sempre responsabilità del cliente: cosa viene memorizzato, come viene cifrato e chi può accedervi.","Il livello hypervisor di EC2 è responsabilità di AWS: AWS gestisce il livello di virtualizzazione e i clienti non interagiscono mai con l'hypervisor né lo gestiscono.","Corretto — Le credenziali degli utenti IAM e la gestione degli accessi sono sempre responsabilità del cliente: AWS fornisce IAM come strumento, ma non gestisce mai i permessi degli utenti.","L'hardware di rete tra le Region AWS è responsabilità di AWS: i clienti non gestiscono mai l'infrastruttura di rete fisica."]},
  "142": {"h":"c6f1c5bb","question":"Un'azienda teme che un singolo account di un dipendente compromesso possa distribuire modifiche malevole in produzione. Decide che una persona debba approvare ogni deployment in produzione e una persona diversa debba eseguirlo. Quale principio di sicurezza sta applicando l'azienda?","options":["Autenticazione a più fattori (MFA)","Separazione dei compiti","Principio del privilegio minimo","Rotazione delle chiavi di accesso"],"explanation":"La separazione dei compiti garantisce che nessuna singola persona o ruolo controlli un processo critico dall'inizio alla fine. Richiedere che una persona approvi e un'altra esegua un deployment in produzione limita i danni che una singola identità compromessa o malintenzionata può causare.","optionExplanations":["La MFA rende più difficile il furto di un singolo account, ma non richiede il coinvolgimento di due persone diverse in un deployment.","Corretto — suddividere approvazione ed esecuzione tra persone diverse è separazione dei compiti.","Il privilegio minimo limita ogni identità ai permessi di cui ha bisogno, ma da solo non richiede che una seconda persona partecipi alle azioni ad alto privilegio.","Ruotare le chiavi di accesso riduce il rischio legato a chiavi a lungo termine trapelate; non coinvolge più persone in un deployment."]},
  "143": {"h":"847308a9","question":"Un'azienda usa AWS Organizations e vuole garantire che nessun account membro possa disattivare AWS Security Hub, indipendentemente dai permessi di amministratore di quell'account. Cosa dovrebbe usare?","options":["Policy IAM associate in ciascun account membro","Una SCP applicata alla root dell'organizzazione o a una OU","Regole di AWS Config a livello del management account","AWS CloudTrail con remediation Lambda basata su eventi"],"explanation":"Una Service Control Policy (SCP) applicata a livello di root dell'organizzazione o di OU può negare l'azione securityhub:DisableSecurityHub in tutti gli account membri. Poiché le SCP definiscono i permessi massimi, nemmeno l'amministratore di un account può aggirare la SCP.","optionExplanations":["Le policy IAM negli account membri possono essere modificate dagli amministratori degli account: la domanda richiede un controllo che NESSUN amministratore di account membro possa aggirare.","Corretto — Una SCP applicata a livello di root dell'organizzazione o di OU nega l'azione di disattivazione e non può essere aggirata da alcun amministratore di account membro, perché le SCP definiscono i permessi massimi.","Le regole di AWS Config rilevano e segnalano le configurazioni non conformi, ma non possono impedire in tempo reale a un amministratore dell'account di disattivare Security Hub.","CloudTrail con remediation Lambda può rilevare la disattivazione e tentare di riattivare Security Hub, ma esiste un intervallo tra disattivazione e riattivazione in cui il servizio resterebbe spento: non è realmente preventivo."]},
  "144": {"h":"42d26bc3","question":"Quale servizio AWS si integra con AWS Organizations per gestire centralmente le regole di AWS WAF, le protezioni di Shield Advanced e i Security Group in tutti gli account di un'organizzazione?","options":["AWS Security Hub","AWS Config","AWS Firewall Manager","Amazon GuardDuty"],"explanation":"AWS Firewall Manager è un servizio di gestione della sicurezza che permette di configurare e gestire centralmente le regole firewall (AWS WAF, Shield Advanced, Security Group, policy di Network Firewall) su più account e risorse in AWS Organizations, garantendo policy di sicurezza coerenti.","optionExplanations":["AWS Security Hub aggrega i finding di sicurezza: offre un monitoraggio centralizzato della postura di sicurezza, ma non gestisce né distribuisce regole firewall tra gli account.","AWS Config valuta le configurazioni delle risorse: può rilevare configurazioni firewall non conformi, ma non gestisce né impone centralmente regole WAF o policy di Shield.","Corretto — AWS Firewall Manager gestisce centralmente regole WAF, protezioni Shield Advanced, Security Group e policy di Network Firewall in tutti gli account di AWS Organizations.","Amazon GuardDuty rileva le minacce tramite l'analisi dei log: è un servizio di rilevamento delle minacce, non uno strumento di gestione delle regole firewall per ambienti multi-account."]},
  "145": {"h":"24b17167","question":"Un team di sicurezza ha scoperto che la bucket policy di un bucket Amazon S3 è stata modificata la settimana scorsa. Il team deve scoprire quale identità IAM ha effettuato la modifica, quando è avvenuta e da quale indirizzo IP. Prevede di attivare AWS CloudTrail in tutti gli account. Cosa fornisce CloudTrail che soddisfa questa esigenza?","options":["Monitoraggio di metriche di prestazione come CPU e memoria","Un registro delle chiamate API che mostra chi ha fatto cosa e quando","Rilevamento tramite machine learning delle attività malevole nell'account","Valutazione continua delle impostazioni delle risorse rispetto a regole di conformità"],"explanation":"AWS CloudTrail registra le chiamate API effettuate nell'account, inclusi l'identità del chiamante, l'orario, l'indirizzo IP di origine e i parametri della richiesta. Questo audit trail risponde alle domande su chi ha modificato la bucket policy, quando e da dove.","optionExplanations":["Le metriche di prestazione provengono da Amazon CloudWatch. Le metriche non mostrano chi ha modificato una bucket policy.","Corretto — CloudTrail conserva una cronologia dell'attività API con chiamante, orario e IP di origine, cioè ciò di cui il team ha bisogno.","Il rilevamento delle minacce tramite machine learning è fornito da Amazon GuardDuty, che analizza i log di CloudTrail e altri log. Non è lo scopo di CloudTrail.","Valutare le configurazioni delle risorse rispetto a regole è ciò che fa AWS Config. Non è lo scopo principale di CloudTrail."]},
  "146": {"h":"bb2701c3","question":"Un'azienda ha un requisito di conformità secondo cui tutti i dati PII memorizzati in S3 devono essere sempre cifrati. Quale regola gestita di AWS Config rileva i bucket S3 che non applicano la cifratura lato server?","options":["s3-bucket-ssl-requests-only","s3-default-encryption-kms","s3-bucket-server-side-encryption-enabled","s3-bucket-public-read-prohibited"],"explanation":"La regola gestita di AWS Config 's3-bucket-server-side-encryption-enabled' verifica se i bucket S3 hanno la cifratura lato server predefinita attivata. I bucket senza cifratura vengono segnalati come non conformi, contribuendo a garantire che tutti gli oggetti memorizzati in S3 siano cifrati automaticamente at rest.","optionExplanations":["s3-bucket-ssl-requests-only verifica se le bucket policy S3 richiedono HTTPS (SSL) per tutte le richieste: riguarda la cifratura in transit, non la cifratura lato server at rest.","s3-default-encryption-kms verifica specificamente se i bucket S3 usano chiavi gestite da KMS: è più specifica del controllo generale sull'attivazione della cifratura lato server.","Corretto — s3-bucket-server-side-encryption-enabled verifica se i bucket S3 hanno la cifratura lato server predefinita attivata (di qualsiasi tipo), segnalando i bucket non cifrati.","s3-bucket-public-read-prohibited verifica se i bucket S3 bloccano l'accesso pubblico in lettura: riguarda i controlli sull'accesso pubblico, non la cifratura lato server."]},
  "147": {"h":"e60690c6","question":"Quale approccio raccomanda AWS per distribuire i permessi IAM in modo da prevenire accessi non autorizzati e garantire la responsabilità individuale?","options":["Usare un unico utente IAM amministratore e condividerne le credenziali con il team","Creare utenti IAM individuali con credenziali univoche e assegnare i permessi tramite gruppi e ruoli","Assegnare la policy AdministratorAccess a tutti gli sviluppatori per la massima flessibilità","Conservare le credenziali dell'account root in un password manager condiviso"],"explanation":"AWS raccomanda di creare utenti IAM individuali con credenziali univoche (senza mai condividerle), assegnando i permessi tramite IAM Group (permessi comuni) e IAM Role (accesso da servizio a servizio). Questo garantisce la responsabilità individuale e supporta il principio del privilegio minimo.","optionExplanations":["Usare un unico utente IAM amministratore condividendone le credenziali viola la responsabilità individuale: le credenziali condivise rendono impossibile verificare chi ha eseguito determinate azioni.","Corretto — Utenti IAM individuali con credenziali univoche e permessi gestiti tramite gruppi e ruoli sono la best practice AWS per la gestione degli accessi e la responsabilità individuale.","Assegnare AdministratorAccess a tutti gli sviluppatori viola il privilegio minimo: un accesso eccessivamente permissivo aumenta il blast radius se le credenziali di uno sviluppatore vengono compromesse.","Conservare le credenziali dell'account root in un password manager condiviso viola la best practice di sicurezza per l'account root: l'account root deve avere la MFA ed essere usato solo per attività specifiche, senza mai essere condiviso."]},
  "148": {"h":"ea93ddaf","question":"Quale servizio AWS permette a un'organizzazione di gestire l'accesso alle risorse AWS usando il proprio Microsoft Active Directory aziendale, senza creare utenti IAM duplicati per ogni dipendente?","options":["Amazon Cognito User Pools","AWS IAM Identity Center (ex AWS SSO)","AWS Directory Service for Microsoft Active Directory","Amazon Cloud Directory"],"explanation":"AWS IAM Identity Center (ex AWS Single Sign-On) consente un accesso SSO centralizzato a più account AWS e applicazioni aziendali. Si integra con Microsoft Active Directory e con provider SAML/OIDC esterni, permettendo ai dipendenti di usare le credenziali aziendali esistenti per accedere ad AWS.","optionExplanations":["Gli Amazon Cognito User Pools gestiscono le identità degli utenti per applicazioni web e mobile rivolte ai clienti: non sono pensati per l'accesso dei dipendenti ad AWS con le credenziali di Active Directory aziendale.","Corretto — AWS IAM Identity Center fornisce un accesso SSO centralizzato tramite Microsoft Active Directory o SAML/OIDC, permettendo ai dipendenti di usare le credenziali aziendali esistenti per accedere a più account AWS.","AWS Directory Service for Microsoft Active Directory gestisce la directory AD vera e propria: fornisce la directory sottostante, ma è IAM Identity Center a fornire il portale SSO e il livello di gestione degli accessi.","Amazon Cloud Directory è una directory cloud-native per dati gerarchici: non si usa per l'SSO né per l'integrazione con Microsoft Active Directory per l'accesso dei dipendenti ad AWS."]},
  "149": {"h":"e202a801","question":"Un workload di machine learning richiede una grande quantità di potenza di calcolo GPU per l'addestramento dei modelli. Quale famiglia di istanze EC2 è ottimizzata per questo caso d'uso?","options":["Uso generico (famiglia M)","Ottimizzate per il calcolo (famiglia C)","Ottimizzate per la memoria (famiglia R)","Calcolo accelerato (famiglia P/G)"],"explanation":"Le istanze a calcolo accelerato (famiglie P, G, Inf, Trn) usano acceleratori hardware (GPU, FPGA, AWS Trainium) per eseguire calcoli in virgola mobile e deep learning in modo più efficiente rispetto alle CPU. Sono ideali per addestramento e inferenza ML, HPC e workload grafici.","optionExplanations":["Le istanze a uso generico (famiglia M) offrono un equilibrio tra calcolo, memoria e rete: non sono ottimizzate per workload di addestramento ML che richiedono un uso intensivo di GPU.","Le istanze ottimizzate per il calcolo (famiglia C) offrono un elevato rapporto calcolo/memoria per workload vincolati dalla CPU: usano CPU, non GPU, e non sono adatte all'addestramento di modelli ML.","Le istanze ottimizzate per la memoria (famiglia R) offrono un elevato rapporto memoria/calcolo per database in memoria: non sono progettate per l'addestramento ML accelerato da GPU.","Corretto — Le istanze a calcolo accelerato (famiglie P, G, Inf, Trn) includono GPU, FPGA e chip ML specializzati, fornendo l'accelerazione hardware necessaria per l'addestramento dei modelli ML."]},
  "150": {"h":"16036a56","question":"Un'applicazione richiede un I/O su disco estremamente elevato con latenza molto bassa. I dati NON devono persistere se l'istanza EC2 viene arrestata. Quale opzione di storage offre le prestazioni di I/O più elevate?","options":["Amazon EBS gp3","Amazon EBS io2 Block Express","Amazon EC2 instance store","Amazon EFS"],"explanation":"L'EC2 instance store fornisce storage a blocchi temporaneo collegato fisicamente al computer host, offrendo le prestazioni di I/O più elevate tra tutte le opzioni di storage EC2. Tuttavia, i dati vanno persi quando l'istanza viene arrestata, ibernata o terminata. È ideale per dati temporanei, buffer, cache e spazio di lavoro temporaneo.","optionExplanations":["Amazon EBS gp3 offre buone prestazioni SSD a uso generico, ma è un volume di storage collegato via rete, che introduce latenza di rete rispetto all'instance store collegato fisicamente.","Amazon EBS io2 Block Express offre IOPS molto elevati e storage persistente, ma essendo collegato via rete non può eguagliare le prestazioni di I/O pure dell'instance store collegato fisicamente.","Corretto — L'EC2 instance store è collegato fisicamente all'host e fornisce le prestazioni di I/O più elevate possibili senza overhead di rete, anche se i dati non sono persistenti.","Amazon EFS è un file system NFS condiviso: vi si accede tramite rete e ha una latenza molto più alta rispetto allo storage instance store collegato fisicamente."]},
  "151": {"h":"f21b08d3","question":"Un'azienda sta spostando su Amazon EC2 un database mission-critical con un uso intensivo di I/O. Il database richiede gli IOPS sostenuti più elevati e la latenza inferiore al millisecondo più costante offerti da Amazon EBS. Quale tipo di volume EBS dovrebbe scegliere l'azienda?","options":["gp3 (General Purpose SSD)","st1 (Throughput Optimized HDD)","io2 Block Express","sc1 (Cold HDD)"],"explanation":"io2 Block Express è il tipo di volume Amazon EBS con le prestazioni più elevate (Provisioned IOPS SSD). È progettato per i database più esigenti e con uso intensivo di I/O, che richiedono IOPS sostenuti molto elevati e una latenza costante inferiore al millisecondo.","optionExplanations":["gp3 è un SSD general purpose conveniente, adatto alla maggior parte dei workload, ma non offre gli IOPS più elevati e la latenza più costante di cui ha bisogno il database critico.","st1 è un volume su disco rigido progettato per workload con throughput sequenziale elevato, come i big data, non per l'I/O di database sensibile alla latenza.","Corretto — io2 Block Express offre gli IOPS più elevati e una latenza costante inferiore al millisecondo tra tutti i tipi di volume EBS, ed è progettato per database critici.","sc1 è il volume su disco rigido più economico, per dati a cui si accede raramente. È decisamente troppo lento per un database con uso intensivo di I/O."]},
  "152": {"h":"3f70265c","question":"Quale classe di storage S3 sposta automaticamente i dati tra i livelli di accesso in base al variare dei pattern di accesso, senza impatto sulle prestazioni né oneri operativi?","options":["S3 Standard","S3 Standard-Infrequent Access (S3 Standard-IA)","S3 Intelligent-Tiering","S3 Glacier Instant Retrieval"],"explanation":"S3 Intelligent-Tiering sposta automaticamente gli oggetti tra i livelli in base all'utilizzo effettivo. Gli oggetti non acceduti per 30 giorni passano a Infrequent Access; quelli non acceduti per 90 giorni passano ad Archive Instant Access. Non ci sono costi di recupero, il che lo rende conveniente per dati con pattern di accesso imprevedibili.","optionExplanations":["S3 Standard memorizza gli oggetti in un unico livello indipendentemente dalla frequenza di accesso: non sposta automaticamente i dati tra livelli in base ai pattern di accesso.","S3 Standard-IA è un livello di storage fisso per dati a cui si accede raramente: è il cliente a collocare manualmente i dati in questo livello, che non si adatta automaticamente al variare dei pattern di accesso.","Corretto — S3 Intelligent-Tiering monitora i pattern di accesso e sposta automaticamente gli oggetti tra i livelli di accesso senza costi di recupero, ottimizzando i costi in caso di accesso imprevedibile.","S3 Glacier Instant Retrieval è un livello di archiviazione fisso per dati a cui si accede raramente: non si adatta automaticamente al variare dei pattern di accesso."]},
  "153": {"h":"570131c5","question":"Un'azienda vuole replicare automaticamente il contenuto del proprio bucket S3 in un'altra AWS Region a fini di disaster recovery. Quale funzionalità di S3 dovrebbe configurare?","options":["Solo S3 Versioning","S3 Cross-Region Replication","S3 Transfer Acceleration","S3 Lifecycle policies per le classi di storage"],"explanation":"S3 Cross-Region Replication (CRR) replica automaticamente gli oggetti da un bucket di origine in una Region a un bucket di destinazione in una Region diversa. Richiede il versioning su entrambi i bucket e viene usata per conformità normativa, disaster recovery e per ridurre la latenza per utenti distribuiti geograficamente.","optionExplanations":["Il solo S3 Versioning conserva più versioni degli oggetti all'interno dello stesso bucket: non replica il contenuto in un'altra Region per il disaster recovery.","Corretto — S3 Cross-Region Replication copia automaticamente i nuovi oggetti in un bucket di una Region diversa (richiede il versioning), consentendo disaster recovery e distribuzione geografica dei dati.","S3 Transfer Acceleration velocizza gli upload verso un bucket specifico usando le edge location: non replica il contenuto in un altro bucket in un'altra Region.","Le S3 Lifecycle policies spostano o fanno scadere gli oggetti in base all'età o a regole di transizione: gestiscono l'ottimizzazione dei costi all'interno o tra le classi di storage, non la replica tra Region."]},
  "154": {"h":"2f50d37e","question":"Una società di intermediazione deve conservare per diversi anni i registri delle operazioni in Amazon S3, e le autorità di vigilanza richiedono che nessuno, nemmeno un amministratore, possa eliminarli o sovrascriverli durante quel periodo. Quale funzionalità di S3 dovrebbe usare la società?","options":["S3 Versioning","S3 Replication","S3 Object Lock","S3 Lifecycle policies"],"explanation":"S3 Object Lock memorizza gli oggetti secondo un modello write once, read many (WORM) e impedisce che vengano eliminati o sovrascritti per un periodo di conservazione stabilito. In modalità compliance nessun utente, nemmeno l'utente root, può rimuovere la protezione prima della fine del periodo di conservazione.","optionExplanations":["Il versioning conserva le versioni precedenti degli oggetti, ma gli utenti autorizzati possono comunque eliminare le versioni, quindi non impone un periodo di conservazione.","La replica copia gli oggetti in un altro bucket; non impedisce a nessuno di eliminare o sovrascrivere gli originali.","Corretto — Object Lock impone una conservazione WORM, così i registri delle operazioni non possono essere eliminati o sovrascritti per il periodo richiesto.","Le Lifecycle policies spostano o fanno scadere gli oggetti automaticamente; non impediscono l'eliminazione o la sovrascrittura."]},
  "155": {"h":"06764db4","question":"Con quali due motori di database open source è compatibile Amazon Aurora?","options":["PostgreSQL e Oracle","MySQL e PostgreSQL","MySQL e Microsoft SQL Server","PostgreSQL e MongoDB"],"explanation":"Amazon Aurora è un database relazionale compatibile con MySQL e PostgreSQL, progettato per il cloud. Aurora offre fino a 5 volte le prestazioni di MySQL standard e 3 volte quelle di PostgreSQL standard, con la semplicità e l'economicità dei database open source.","optionExplanations":["Aurora non è compatibile con Oracle: Oracle è un motore di database commerciale proprietario che richiede un modello di licenza separato ed è supportato da RDS, non da Aurora.","Corretto — Amazon Aurora è compatibile sia con MySQL sia con PostgreSQL e offre fino a 5 volte le prestazioni di MySQL e 3 volte quelle di PostgreSQL, con i costi tipici dei database open source.","Aurora non è compatibile con Microsoft SQL Server: SQL Server è un database proprietario supportato da Amazon RDS for SQL Server, non da Aurora.","Aurora non è compatibile con MongoDB: MongoDB è un database documentale supportato da Amazon DocumentDB, non da Aurora, che è un database relazionale."]},
  "156": {"h":"70159ae6","question":"Quale servizio di database AWS è progettato per memorizzare e interrogare dati altamente interconnessi, come social network, motori di raccomandazione e grafi per il rilevamento delle frodi?","options":["Amazon DynamoDB","Amazon RDS","Amazon Neptune","Amazon DocumentDB"],"explanation":"Amazon Neptune è un servizio di database a grafo completamente gestito che supporta property graph (Gremlin) e grafi RDF (SPARQL). È ottimizzato per memorizzare miliardi di relazioni e interrogare il grafo con latenza nell'ordine dei millisecondi, il che lo rende ideale per social network, raccomandazioni e rilevamento delle frodi.","optionExplanations":["Amazon DynamoDB è un database NoSQL chiave-valore/documentale: può memorizzare dati interconnessi ma non è ottimizzato per attraversamenti di grafo o query sulle relazioni su larga scala.","Amazon RDS è un database relazionale: usa tabelle e SQL, che non sono ottimizzati per interrogare miliardi di relazioni altamente interconnesse.","Corretto — Amazon Neptune è un database a grafo gestito, ottimizzato per memorizzare e interrogare miliardi di relazioni, ideale per social network, motori di raccomandazione e rilevamento delle frodi.","Amazon DocumentDB è un database documentale compatibile con MongoDB: memorizza documenti in stile JSON, non relazioni di grafo con linguaggi di query specializzati per l'attraversamento."]},
  "157": {"h":"ffe377b2","question":"Un'azienda usa on-premises un'applicazione basata su MongoDB e vuole migrare a un servizio AWS completamente gestito con modifiche minime al codice. Quale servizio è il PIÙ compatibile?","options":["Amazon DynamoDB","Amazon DocumentDB (with MongoDB compatibility)","Amazon RDS","Amazon Keyspaces (for Apache Cassandra)"],"explanation":"Amazon DocumentDB è un database documentale completamente gestito compatibile con MongoDB. Consente di migrare i workload MongoDB con modifiche minime al codice, aumenta automaticamente lo storage fino a 128 TiB e garantisce alta disponibilità con sei copie dei dati distribuite su tre AZ.","optionExplanations":["Amazon DynamoDB è un database NoSQL chiave-valore/documentale: pur potendo memorizzare dati in stile JSON, usa API specifiche di DynamoDB e non è compatibile con MongoDB, quindi richiede più modifiche al codice.","Corretto — Amazon DocumentDB offre API compatibili con MongoDB, consentendo di migrare i workload MongoDB con modifiche minime al codice e ottenendo scalabilità e disponibilità gestite da AWS.","Amazon RDS è un database relazionale SQL: usa un modello dati e un linguaggio di query completamente diversi da MongoDB e richiederebbe riscritture significative del codice.","Amazon Keyspaces è compatibile con Apache Cassandra (NoSQL wide-column): non è compatibile con MongoDB e richiederebbe modifiche significative al codice per una migrazione da MongoDB."]},
  "158": {"h":"2f7cc09b","question":"Quale servizio AWS offre una soluzione di backup centralizzata per automatizzare e gestire i backup di più servizi AWS (EC2, RDS, EFS, DynamoDB) da un unico punto?","options":["AWS Storage Gateway","Amazon S3 Lifecycle policies","AWS Backup","Amazon Data Lifecycle Manager"],"explanation":"AWS Backup è un servizio di backup completamente gestito che centralizza e automatizza la protezione dei dati tra i servizi AWS. Si creano piani di backup che definiscono frequenza, conservazione e regole di lifecycle. Supporta EC2, EBS, RDS, Aurora, DynamoDB, EFS, FSx e Storage Gateway da un'unica console.","optionExplanations":["AWS Storage Gateway collega lo storage on-premises ad AWS: non è un servizio di gestione centralizzata dei backup per i workload AWS su più servizi.","Le Amazon S3 Lifecycle policies automatizzano le transizioni tra classi di storage e la scadenza degli oggetti: gestiscono i dati S3 esistenti ma non offrono un backup centralizzato per EC2, RDS, DynamoDB, ecc.","Corretto — AWS Backup centralizza e automatizza la gestione dei backup di EC2, EBS, RDS, Aurora, DynamoDB, EFS e altri servizi da un'unica console, con piani di backup unificati.","Amazon Data Lifecycle Manager automatizza la gestione del ciclo di vita degli snapshot EBS: copre solo volumi EBS e AMI, non l'intera gamma di servizi AWS supportati da AWS Backup."]},
  "159": {"h":"930a0f8a","question":"Un'azienda sta spostando dal proprio data center ad AWS diverse applicazioni basate su Windows. Le applicazioni usano cartelle condivise che richiedono il protocollo SMB, i permessi NTFS e l'integrazione con Microsoft Active Directory. L'azienda vuole un file system completamente gestito in AWS. Quale servizio AWS dovrebbe usare?","options":["Amazon EFS","Amazon FSx for Windows File Server","Amazon S3","AWS Storage Gateway"],"explanation":"Amazon FSx for Windows File Server offre storage di file condiviso completamente gestito e nativo Windows. Supporta SMB, i permessi NTFS e l'integrazione con Active Directory, così le applicazioni Windows possono usarlo senza modifiche.","optionExplanations":["Amazon EFS è un file system gestito per workload Linux che usano NFS. Non offre SMB e NTFS nativi per Windows.","Corretto — FSx for Windows File Server fornisce alle applicazioni Windows un file system SMB gestito con supporto per NTFS e Active Directory.","Amazon S3 è uno storage a oggetti a cui si accede tramite API. Non è una cartella condivisa Windows con SMB e permessi NTFS.","Storage Gateway collega le applicazioni on-premises allo storage cloud. L'azienda sta spostando le applicazioni in AWS, quindi le serve un file system in AWS, non un gateway ibrido."]},
  "160": {"h":"d687fb8b","question":"Qual è lo scopo PRINCIPALE di un Internet Gateway in un VPC?","options":["Instradare il traffico tra le subnet all'interno dello stesso VPC","Fornire connettività Internet alle risorse delle subnet pubbliche ed eseguire il NAT per le istanze con IP pubblico","Consentire alle istanze nelle subnet private di avviare connessioni Internet in uscita restando irraggiungibili","Collegare più VPC tra loro usando indirizzi IP privati"],"explanation":"Un Internet Gateway (IGW) è un componente del VPC ridondante e scalabile orizzontalmente che consente la comunicazione tra le istanze di un VPC e Internet. Fornisce una destinazione nelle route table per il traffico instradabile su Internet ed esegue il NAT per le istanze a cui sono assegnati indirizzi IPv4 pubblici.","optionExplanations":["L'instradamento del traffico tra subnet è svolto dalle route table all'interno del VPC: l'Internet Gateway gestisce specificamente il traffico tra il VPC e Internet pubblico.","Corretto — Un Internet Gateway fornisce connettività Internet alle risorse delle subnet pubbliche ed esegue il NAT per le istanze con indirizzi IP pubblici.","Consentire alle istanze di subnet private di avviare connessioni Internet in uscita restando irraggiungibili descrive un NAT Gateway, non un Internet Gateway.","Collegare più VPC tra loro usando IP privati descrive il VPC Peering: l'Internet Gateway collega un VPC a Internet pubblico."]},
  "161": {"h":"3cf280e2","question":"Un'azienda ha istanze EC2 in una subnet privata che devono scaricare aggiornamenti software da Internet ma NON devono essere raggiungibili direttamente da Internet. Quale servizio AWS lo consente?","options":["Internet Gateway","NAT Gateway","VPC Peering","AWS Direct Connect"],"explanation":"Un NAT Gateway consente alle istanze nelle subnet private di avviare connessioni in uscita verso Internet, impedendo però che da Internet si avviino connessioni verso quelle istanze. Traduce gli IP privati nell'IP pubblico del NAT Gateway per il traffico in uscita ed è gestito, ad alta disponibilità e scalabile automaticamente.","optionExplanations":["Un Internet Gateway consente la comunicazione Internet bidirezionale per le risorse con IP pubblici: collocare le istanze di una subnet privata direttamente dietro un IGW le renderebbe raggiungibili da Internet.","Corretto — Un NAT Gateway consente alle istanze di subnet private di avviare connessioni Internet in uscita (per aggiornamenti, chiamate API) restando irraggiungibili dal traffico Internet in ingresso.","Il VPC Peering collega VPC tra loro per comunicazioni private: non fornisce accesso a Internet alle istanze di subnet private.","AWS Direct Connect fornisce un collegamento privato dedicato tra on-premises e AWS: non consente alle istanze EC2 nelle subnet private di accedere a Internet."]},
  "162": {"h":"46dff037","question":"Quale servizio AWS migliora la disponibilità e le prestazioni delle applicazioni globali instradando il traffico degli utenti verso l'endpoint integro più vicino tramite la rete globale AWS anziché Internet pubblico?","options":["Amazon CloudFront","Amazon Route 53","AWS Global Accelerator","Elastic Load Balancing"],"explanation":"AWS Global Accelerator usa la rete globale AWS per instradare il traffico degli utenti verso l'endpoint ottimale in base a stato di salute, posizione geografica e policy di routing. A differenza di CloudFront (che mette in cache i contenuti), Global Accelerator opera a livello TCP/UDP e fornisce indirizzi IP anycast statici per l'applicazione.","optionExplanations":["Amazon CloudFront è una CDN che mette in cache i contenuti nelle edge location: è ottimizzata per la distribuzione di contenuti, non per instradare il traffico applicativo TCP/UDP verso l'endpoint integro più vicino.","Amazon Route 53 è un servizio DNS: può effettuare routing geografico ma dipende dalla propagazione DNS, mentre Global Accelerator usa la rete AWS per miglioramenti immediati del routing.","Corretto — AWS Global Accelerator instrada il traffico degli utenti sulla rete globale AWS verso l'endpoint integro più vicino usando IP anycast, migliorando disponibilità e prestazioni.","Elastic Load Balancing distribuisce il traffico all'interno di una Region: non instrada il traffico tra Region a livello globale né fornisce indirizzi IP anycast per le prestazioni delle applicazioni globali."]},
  "163": {"h":"757e5f48","question":"Un'azienda ha 40 VPC distribuiti su diversi account AWS più due data center on-premises. Gestire una rete magliata sempre più ampia di connessioni punto-punto tra di essi è diventato complesso. L'azienda vuole un unico hub centrale che colleghi tutti i suoi VPC e le reti on-premises. Quale servizio AWS dovrebbe usare l'azienda?","options":["VPC peering","AWS PrivateLink","AWS Transit Gateway","AWS Direct Connect gateway"],"explanation":"AWS Transit Gateway funge da router cloud centrale in un modello hub-and-spoke. Ogni VPC e ogni rete on-premises si collega una sola volta al transit gateway anziché a ciascuna delle altre reti, sostituendo la complessa rete magliata di connessioni punto-punto.","optionExplanations":["Il VPC peering crea connessioni uno-a-uno tra coppie di VPC. È proprio la rete magliata che l'azienda trova troppo complessa, e non collega le reti on-premises.","AWS PrivateLink espone privatamente servizi specifici ad altri VPC. Non è un hub per l'instradamento tra intere reti.","Corretto — Transit Gateway è un hub centrale che collega molti VPC e reti on-premises, semplificando l'architettura di rete.","Un Direct Connect gateway collega le connessioni Direct Connect ai VPC, ma non instrada il traffico tra i VPC dell'azienda come hub centrale."]},
  "164": {"h":"5bdcc706","question":"Un'azienda vuole esporre un servizio interno a consumatori in altri account AWS senza usare Internet pubblico né il VPC peering. Quale funzionalità di rete consente questa connettività privata?","options":["VPC Peering","AWS Transit Gateway","AWS PrivateLink","Internet Gateway"],"explanation":"AWS PrivateLink fornisce connettività privata tra VPC, servizi AWS e applicazioni on-premises attraverso la rete Amazon. Crea un interface VPC endpoint (una ENI nel proprio VPC) che instrada privatamente verso il servizio, senza richiedere Internet Gateway, NAT, IP pubblici o VPN.","optionExplanations":["Il VPC Peering collega due VPC in modo bidirezionale: espone reciprocamente tutte le risorse di entrambi i VPC, non solo un servizio specifico, e può non essere desiderabile per esporre servizi tra account.","AWS Transit Gateway collega più VPC e reti tramite un hub centrale: instrada tutto il traffico tra le reti collegate, non si limita a esporre privatamente un singolo servizio.","Corretto — AWS PrivateLink crea un endpoint privato (ENI) nel VPC del consumatore che si collega privatamente a un servizio specifico sulla rete AWS, senza passare da Internet pubblico.","Un Internet Gateway instrada il traffico da e verso Internet pubblico: è l'opposto di ciò che serve per una connettività privata a un servizio tra account."]},
  "165": {"h":"261f40bf","question":"Quale servizio AWS funge da «porta d'ingresso» per le applicazioni, consentendo di creare, pubblicare, mantenere, monitorare e proteggere API REST e WebSocket su qualsiasi scala?","options":["AWS AppSync","Amazon API Gateway","AWS App Runner","Elastic Load Balancing"],"explanation":"Amazon API Gateway è un servizio completamente gestito per creare, pubblicare, mantenere, monitorare e proteggere API. Gestisce il traffico, il supporto CORS, l'autorizzazione e il controllo degli accessi, il throttling, il monitoraggio e il versioning delle API, il tutto senza gestire alcun server.","optionExplanations":["AWS AppSync è un servizio GraphQL gestito: è pensato per la sincronizzazione dei dati in tempo reale e le API GraphQL, non come porta d'ingresso generica per la gestione di API REST/WebSocket.","Corretto — Amazon API Gateway è il servizio completamente gestito per creare, pubblicare, proteggere e monitorare API REST e WebSocket su qualsiasi scala senza gestire server.","AWS App Runner esegue il deployment di applicazioni web containerizzate: non è un servizio di gestione delle API per crearle e proteggerle.","Elastic Load Balancing distribuisce il traffico ai server di backend: non offre funzionalità di gestione delle API come throttling, versioning, autorizzazione o monitoraggio a livello di API."]},
  "166": {"h":"afdbe03f","question":"Un negozio online elabora ogni ordine con diverse funzioni AWS Lambda: addebito del pagamento, prenotazione dell'inventario e organizzazione della spedizione. Gli sviluppatori vogliono coordinare questi passaggi come un workflow visualizzabile graficamente, con retry automatici e gestione degli errori, senza scrivere codice di orchestrazione proprio. Quale servizio AWS dovrebbero usare?","options":["Amazon SQS","Amazon EventBridge","AWS Step Functions","AWS Batch"],"explanation":"AWS Step Functions orchestra workflow serverless come macchine a stati. Ogni passaggio può invocare una funzione Lambda o un altro servizio AWS, e il workflow gestisce sequenza, retry, gestione degli errori e passaggi paralleli, con una vista grafica di ogni esecuzione.","optionExplanations":["SQS mette in coda i messaggi tra componenti, ma non definisce l'ordine dei passaggi, i retry o la gestione degli errori di un workflow a più passaggi.","EventBridge instrada eventi verso destinazioni in base a regole; non gestisce un workflow a più passaggi con stato visualizzabile e retry.","Corretto — Step Functions coordina le funzioni Lambda come workflow visuale con retry e gestione degli errori integrati.","AWS Batch esegue grandi quantità di job di calcolo batch; non è progettato per orchestrare una sequenza di funzioni Lambda per ogni ordine."]},
  "167": {"h":"167937cc","question":"Quale servizio AWS abilita architetture event-driven instradando eventi da servizi AWS e applicazioni SaaS verso destinazioni in base a regole definite, eliminando la necessità di codice di polling personalizzato?","options":["Amazon SQS","Amazon SNS","Amazon EventBridge","AWS Step Functions"],"explanation":"Amazon EventBridge è un event bus serverless che collega applicazioni usando dati provenienti da servizi AWS, applicazioni SaaS integrate e sorgenti personalizzate. Gli eventi vengono instradati verso le destinazioni in base a regole, abilitando architetture event-driven e disaccoppiando i produttori di eventi dai consumatori.","optionExplanations":["Amazon SQS è una coda di messaggi punto-punto: memorizza temporaneamente i messaggi per un singolo consumatore, non è un event bus che instrada verso più destinazioni in base a regole.","Amazon SNS è un servizio di notifica pub/sub: distribuisce i messaggi a sottoscrittori preconfigurati, non è un router di eventi basato su regole integrato con applicazioni SaaS.","Corretto — Amazon EventBridge è un event bus serverless che instrada eventi da servizi AWS, app SaaS e sorgenti personalizzate verso destinazioni in base a regole configurabili.","AWS Step Functions orchestra workflow a più passaggi: è un servizio di workflow che consuma eventi, non un event bus per instradare eventi tra produttori e consumatori."]},
  "168": {"h":"e3ab2091","question":"Quale servizio AWS offre una piattaforma completamente gestita per eseguire job di calcolo batch paralleli su larga scala, effettuando automaticamente il provisioning dinamico delle risorse di calcolo ottimali?","options":["AWS Lambda","Amazon ECS","AWS Batch","AWS Fargate"],"explanation":"AWS Batch effettua il provisioning dinamico di istanze EC2 e Spot Instances in base ai requisiti dei job batch inviati. Elimina la necessità di installare e gestire software di calcolo batch, permettendo di concentrarsi sull'analisi dei risultati anziché sulla gestione dell'infrastruttura per workload batch su larga scala.","optionExplanations":["AWS Lambda ha un limite di esecuzione di 15 minuti: non è adatto a job batch su larga scala che possono durare ore e richiedono il provisioning di risorse di calcolo specifiche.","Amazon ECS esegue applicazioni containerizzate ma richiede di configurare manualmente la capacità di calcolo per i workload batch: non effettua automaticamente il provisioning delle risorse ottimali per i job batch.","Corretto — AWS Batch effettua il provisioning dinamico delle risorse di calcolo ottimali (EC2 e Spot Instances) per i job batch, eliminando la necessità di gestire l'infrastruttura di calcolo batch.","AWS Fargate esegue container in modalità serverless, ma è pensato per applicazioni containerizzate persistenti, non per il modello di provisioning basato su code di job necessario per workload batch su larga scala."]},
  "169": {"h":"c290a55d","question":"Un team di data engineering esegue cluster Apache Hadoop e Apache Spark nel proprio data center per elaborare grandi dataset. La manutenzione dei cluster richiede troppo tempo, quindi il team vuole spostare questi job su AWS continuando a usare gli stessi framework open source su una piattaforma di cluster gestita. Quale servizio AWS dovrebbe usare il team?","options":["Amazon Redshift","Amazon Athena","Amazon EMR","Amazon Kinesis Data Streams"],"explanation":"Amazon EMR è una piattaforma big data gestita per eseguire framework open source come Apache Hadoop, Spark, Hive e HBase. AWS esegue il provisioning e la configurazione dei cluster, così il team mantiene i propri framework senza dover gestire l'infrastruttura.","optionExplanations":["Redshift è un data warehouse per analisi SQL. Non esegue job Hadoop e Spark esistenti.","Athena esegue query SQL serverless sui dati in S3. Non è una piattaforma per eseguire cluster Hadoop e Spark.","Corretto — EMR esegue Hadoop e Spark su cluster gestiti, così il team mantiene i propri framework senza dover gestire i cluster.","Kinesis Data Streams raccoglie ed elabora dati in streaming in tempo reale. Non è una piattaforma gestita di cluster Hadoop e Spark."]},
  "170": {"h":"19157592","question":"Quale servizio AWS è un servizio ETL (Extract, Transform, Load) serverless per individuare, preparare e combinare dati per analytics e machine learning?","options":["Amazon EMR","Amazon Kinesis","AWS Glue","Amazon Redshift Spectrum"],"explanation":"AWS Glue è un servizio ETL serverless completamente gestito. Include un data catalog (per individuare e catalogare i dati), job ETL (per trasformare e spostare i dati) e crawler (per dedurre automaticamente lo schema dalle sorgenti dati), eliminando la gestione dell'infrastruttura per la preparazione dei dati.","optionExplanations":["Amazon EMR esegue framework big data open source (Spark, Hive) ma richiede la gestione dei cluster: AWS Glue è serverless e specificamente progettato per l'ETL, con data catalog e crawler.","Amazon Kinesis elabora dati in streaming in tempo reale: è progettato per l'acquisizione di dati in tempo reale, non per job ETL batch serverless e la catalogazione dei dati.","Corretto — AWS Glue è un servizio ETL serverless completamente gestito con data catalog integrato, creazione di job ETL e crawler per l'individuazione degli schemi e la preparazione dei dati.","Amazon Redshift Spectrum interroga i dati in S3 senza spostarli: è una funzionalità di query di Redshift, non un servizio ETL dedicato con catalog, crawler e creazione di job."]},
  "171": {"h":"0cdf8acc","question":"Un'azienda vuole acquisire ed elaborare su larga scala dati in streaming in tempo reale provenienti da sensori IoT. Quale servizio AWS è progettato per lo streaming di dati in tempo reale?","options":["Code standard di Amazon SQS","Amazon Kinesis Data Streams","Ambienti di calcolo AWS Batch","Cluster Amazon EMR"],"explanation":"Amazon Kinesis Data Streams è un servizio di streaming di dati in tempo reale, scalabile e durevole, in grado di acquisire in modo continuo gigabyte di dati al secondo da centinaia di migliaia di sorgenti, abilitando l'elaborazione in tempo reale per casi d'uso di analytics, monitoraggio e telemetria IoT.","optionExplanations":["Amazon SQS è una coda di messaggi punto-punto per l'elaborazione asincrona: memorizza temporaneamente i messaggi per un consumo successivo, non per lo streaming di dati in tempo reale ad alta velocità da sensori IoT.","Corretto — Amazon Kinesis Data Streams acquisisce ed elabora su larga scala dati in streaming in tempo reale da sensori IoT e altre sorgenti ad alta velocità.","AWS Batch serve per job di calcolo batch su larga scala: elabora i dati in batch pianificati o su richiesta, non in tempo reale man mano che i dati arrivano dalle sorgenti in streaming.","Amazon EMR elabora grandi dataset con Spark/Hadoop: è una piattaforma di elaborazione batch, non specificamente progettata per l'acquisizione di flussi di dati in tempo reale da sensori IoT."]},
  "172": {"h":"786126c8","question":"Un rivenditore online vuole che i clienti possano eseguire rapide ricerche full-text nel catalogo prodotti, con risultati ordinati per pertinenza. Il team operativo vuole inoltre analizzare i log applicativi in modo interattivo e quasi in tempo reale. Quale servizio AWS soddisfa entrambe le esigenze?","options":["Data warehouse Amazon Redshift","Amazon RDS for PostgreSQL","Amazon OpenSearch Service","AWS Glue"],"explanation":"Amazon OpenSearch Service è un motore di ricerca e analytics gestito. Offre ricerca full-text ordinata per pertinenza per il catalogo prodotti e analisi dei log quasi in tempo reale con OpenSearch Dashboards per il team operativo.","optionExplanations":["Amazon Redshift è un data warehouse per query SQL analitiche complesse su dati strutturati. Non è progettato per la ricerca full-text dei prodotti ordinata per pertinenza.","Amazon RDS è un database relazionale per workload transazionali. Non è un motore di ricerca ottimizzato per la ricerca full-text ordinata per pertinenza e l'analisi interattiva dei log.","Corretto — OpenSearch Service offre ricerca full-text con ordinamento per pertinenza e analisi dei log quasi in tempo reale in un unico servizio gestito.","AWS Glue è un servizio serverless di integrazione dei dati (ETL). Prepara e sposta i dati ma non gestisce query di ricerca né analisi interattive dei log."]},
  "173": {"h":"3976e2aa","question":"Un'azienda vuole usare il machine learning per analizzare immagini e rilevare oggetti, persone, testo e scene senza richiedere competenze di ML. Quale servizio AI di AWS offre questa funzionalità?","options":["Amazon Textract","Amazon Comprehend","Amazon Rekognition","Amazon Polly"],"explanation":"Amazon Rekognition è un servizio gestito di computer vision che offre analisi di immagini e video: rileva oggetti, scene, volti, testo e attività, esegue il confronto facciale e rileva contenuti inappropriati. Non sono richieste competenze di ML: si chiama l'API e Rekognition restituisce l'analisi.","optionExplanations":["Amazon Textract estrae testo, moduli e tabelle da documenti scansionati: è un servizio di OCR/document intelligence, non un servizio generico di rilevamento di oggetti e scene in immagini e video.","Amazon Comprehend analizza testi per l'elaborazione del linguaggio naturale (sentiment, entità, frasi chiave): elabora contenuti testuali, non immagini o video.","Corretto — Amazon Rekognition offre funzionalità di computer vision, tra cui il rilevamento di oggetti, scene, volti e testo in immagini e video, senza richiedere competenze di ML.","Amazon Polly converte il testo in parlato realistico: è un servizio text-to-speech, non un servizio di analisi di immagini e video."]},
  "174": {"h":"6f6f8c07","question":"Quale servizio AI di AWS usa il machine learning per estrarre automaticamente testo, coppie chiave-valore, tabelle e dati strutturati da documenti scansionati?","options":["Amazon Rekognition","Amazon Textract","Amazon Comprehend","Amazon Transcribe"],"explanation":"Amazon Textract estrae automaticamente testo, moduli, tabelle e dati strutturati da documenti scansionati. A differenza di un semplice OCR, Textract comprende la struttura del documento e può estrarre coppie chiave-valore dai moduli e dati dalle tabelle, eliminando l'inserimento manuale dei dati dai documenti.","optionExplanations":["Amazon Rekognition è un servizio di computer vision per analizzare immagini e video: può rilevare testo nelle immagini ma non è specializzato nell'estrazione di dati strutturati dai documenti (moduli, tabelle).","Corretto — Amazon Textract estrae testo, coppie chiave-valore dai moduli e dati dalle tabelle nei documenti scansionati, comprendendone la struttura a differenza di un semplice OCR.","Amazon Comprehend analizza testi per attività di NLP (sentiment, entità): elabora testo semplice, non estrae dati strutturati da moduli scansionati.","Amazon Transcribe converte il parlato (audio) in testo: trascrive le parole pronunciate, non il testo da immagini di documenti scansionati."]},
  "175": {"h":"d5a4545a","question":"Un sito di notizie vuole aggiungere un pulsante «ascolta questo articolo» per permettere ai visitatori di sentire ogni articolo letto ad alta voce con una voce naturale. L'azienda non vuole registrare gli articoli con speaker umani. Quale servizio AWS dovrebbe usare?","options":["Amazon Transcribe","Amazon Lex","Amazon Polly","Amazon Translate"],"explanation":"Amazon Polly è un servizio text-to-speech che usa il deep learning per trasformare il testo in parlato realistico in molte lingue e voci. Il sito può inviare a Polly il testo di ogni articolo e riprodurre l'audio generato.","optionExplanations":["Transcribe esegue la conversione opposta: trasforma il parlato in testo.","Lex crea chatbot conversazionali e voice bot; leggere ad alta voce articoli interi è un compito di text-to-speech.","Corretto — Polly converte il testo dell'articolo in parlato dal suono naturale senza speaker umani.","Translate converte il testo da una lingua all'altra; non produce audio."]},
  "176": {"h":"799a3afb","question":"Quale servizio AWS offre una piattaforma di machine learning completamente gestita che copre l'intero workflow di ML: etichettatura dei dati, preparazione, creazione dei modelli, addestramento, ottimizzazione e deployment?","options":["Amazon Rekognition","Amazon Comprehend","Amazon SageMaker","AWS Deep Learning AMIs"],"explanation":"Amazon SageMaker è un servizio completamente gestito che copre l'intero workflow di ML: etichettatura dei dati, preparazione dei dati, creazione dei modelli, addestramento, ottimizzazione, hosting e monitoraggio. Fornisce algoritmi integrati, notebook Jupyter e infrastruttura gestita, eliminando il lavoro gravoso di gestione dell'infrastruttura di ML.","optionExplanations":["Amazon Rekognition è un servizio AI specializzato per la computer vision: fornisce modelli pre-addestrati per casi d'uso specifici, non una piattaforma di ML end-to-end per sviluppare modelli personalizzati.","Amazon Comprehend è un servizio AI di elaborazione del linguaggio naturale: fornisce funzionalità NLP predefinite, non una piattaforma di ML completa per creare, addestrare ed eseguire il deployment di modelli personalizzati.","Corretto — Amazon SageMaker copre l'intero workflow di ML, dall'etichettatura dei dati all'addestramento, ottimizzazione, deployment e monitoraggio dei modelli, con notebook Jupyter e infrastruttura gestita.","Le AWS Deep Learning AMIs sono istanze EC2 preconfigurate con framework di ML: richiedono di gestire autonomamente l'infrastruttura, a differenza del workflow completamente gestito di SageMaker."]},
  "177": {"h":"a58c6c51","question":"Gli sviluppatori di un'azienda scaricano pacchetti software open source (ad esempio pacchetti npm, Maven e Python) da repository pubblici durante le build. L'azienda vuole un repository privato completamente gestito in AWS per conservare i pacchetti approvati e condividere i propri pacchetti interni, senza gestire server di repository propri. Quale strumento AWS per sviluppatori dovrebbe usare l'azienda?","options":["AWS CodeBuild","AWS CodeArtifact","AWS CodeDeploy","AWS CodePipeline"],"explanation":"AWS CodeArtifact è un servizio di repository di artefatti completamente gestito. Conserva e condivide pacchetti software per i package manager più diffusi come npm, Maven e pip, e può recuperare pacchetti dai repository pubblici, così l'azienda non deve gestire server di repository propri.","optionExplanations":["CodeBuild compila il codice ed esegue i test. Può scaricare pacchetti durante una build, ma non li conserva né li condivide come un repository.","Corretto — CodeArtifact è un repository privato gestito per pacchetti software, inclusi pacchetti pubblici approvati e pacchetti interni.","CodeDeploy automatizza i deployment su EC2, Lambda, ECS e server on-premises. Non ospita pacchetti software.","CodePipeline orchestra le fasi di una pipeline CI/CD. Non conserva pacchetti software."]},
  "178": {"h":"1701e07f","question":"Quale servizio AWS offre un servizio di continuous integration completamente gestito che compila il codice sorgente, esegue i test e produce pacchetti software pronti per il deployment senza gestire server di build?","options":["AWS CodeCommit","AWS CodeBuild","AWS CodeDeploy","AWS CodePipeline"],"explanation":"AWS CodeBuild è un servizio di CI completamente gestito che compila il codice sorgente, esegue i test e produce pacchetti pronti per il deployment. Scala in modo continuo, elabora più build in parallelo e si paga solo il tempo di build consumato: nessun server di build da predisporre o gestire.","optionExplanations":["AWS CodeCommit ospita repository Git di codice sorgente: conserva il codice ma non lo compila, non esegue test e non produce artefatti di deployment.","Corretto — AWS CodeBuild compila il codice sorgente, esegue i test e produce pacchetti pronti per il deployment senza dover predisporre o gestire server di build.","AWS CodeDeploy distribuisce il software su server/funzioni esistenti: esegue il deployment degli artefatti già compilati, ma non compila codice né esegue test.","AWS CodePipeline orchestra le fasi della pipeline: collega CodeBuild e altri servizi, ma non esegue direttamente compilazione, test o creazione degli artefatti."]},
  "179": {"h":"ac4e091e","question":"Quale servizio AWS automatizza i deployment software su istanze EC2, funzioni Lambda, servizi ECS e server on-premises con strategie come blue/green e rolling?","options":["AWS CodeCommit","AWS CodeBuild","AWS CodeDeploy","AWS CloudFormation"],"explanation":"AWS CodeDeploy è un servizio di deployment completamente gestito che automatizza i deployment software su EC2, Lambda, ECS e server on-premises. Supporta le strategie di deployment blue/green e rolling, consente il rollback in caso di errori e non richiede downtime per i deployment.","optionExplanations":["AWS CodeCommit è un repository di codice sorgente: conserva il codice, non è un servizio di deployment per automatizzare i rilasci software.","AWS CodeBuild compila il codice ed esegue i test: produce artefatti di deployment ma non li distribuisce su destinazioni EC2, Lambda o ECS.","Corretto — AWS CodeDeploy automatizza i deployment su EC2, Lambda, ECS e server on-premises con strategie blue/green e rolling e rollback automatico in caso di errori.","AWS CloudFormation esegue il deployment dell'infrastruttura (creando/aggiornando risorse AWS): predispone gli ambienti ma non è il servizio specializzato per automatizzare il deployment del codice applicativo."]},
  "180": {"h":"a8525f9c","question":"Un team di sviluppo conserva il proprio codice in un repository Git. Vuole che ogni commit avvii automaticamente un processo di rilascio che compili il codice, esegua i test e distribuisca l'applicazione, con ogni fase mostrata in un workflow visuale. Quale servizio AWS dovrebbe orchestrare questo processo?","options":["AWS CodeBuild","AWS CodeDeploy","AWS CodePipeline","AWS CloudFormation"],"explanation":"AWS CodePipeline è un servizio di continuous delivery completamente gestito che modella il processo di rilascio come una pipeline di fasi (source, build, test, deploy). Si avvia automaticamente a ogni modifica del codice e coordina servizi come CodeBuild e CodeDeploy.","optionExplanations":["AWS CodeBuild compila il codice ed esegue i test, ma è solo una fase. Non orchestra l'intero processo di rilascio dal codice sorgente al deployment.","AWS CodeDeploy automatizza i deployment, ma gestisce solo la fase di deploy, non la build, i test e il coordinamento dell'intero workflow.","Corretto — CodePipeline orchestra le fasi di source, build, test e deploy e si avvia automaticamente a ogni commit.","AWS CloudFormation predispone l'infrastruttura a partire da template. Può essere un'azione di deploy in una pipeline, ma non orchestra il processo di rilascio."]},
  "181": {"h":"ef99a7f3","question":"Quale servizio AWS offre un hub operativo per gestire centralmente istanze EC2 e server on-premises, inclusi gestione delle patch, esecuzione di comandi e gestione della configurazione?","options":["AWS CloudFormation","Amazon CloudWatch","AWS Systems Manager","AWS Config"],"explanation":"AWS Systems Manager è un hub operativo che offre visibilità e controllo sull'infrastruttura in AWS e on-premises. Tra le sue funzionalità ci sono Session Manager (accesso shell sicuro senza SSH), Patch Manager (patching automatizzato), Run Command (esecuzione remota di comandi) e Parameter Store (dati di configurazione).","optionExplanations":["AWS CloudFormation distribuisce e gestisce l'infrastruttura come codice: predispone le risorse ma non offre gestione operativa come l'automazione delle patch o l'esecuzione remota di comandi.","Amazon CloudWatch monitora metriche e log: offre osservabilità, ma non include gestione delle sessioni, automazione delle patch o gestione della configurazione sulle istanze.","Corretto — AWS Systems Manager offre gestione operativa con Session Manager, Patch Manager, Run Command, Parameter Store e inventario su istanze EC2 e server on-premises.","AWS Config valuta la conformità delle configurazioni delle risorse: monitora lo stato della configurazione ma non offre funzionalità di gestione operativa come patching o accesso tramite sessione."]},
  "182": {"h":"4d2e432f","question":"Attualmente, durante il troubleshooting, gli sviluppatori accedono separatamente a ogni istanza EC2 per cercare nei file di log applicativi. L'azienda vuole inviare questi log, insieme ai log dei servizi AWS, in un unico punto centrale in cui sia possibile cercarli e analizzarli. Quale funzionalità di Amazon CloudWatch dovrebbe usare?","options":["CloudWatch metrics","CloudWatch alarms","CloudWatch Logs","CloudWatch dashboards"],"explanation":"Amazon CloudWatch Logs raccoglie e conserva in un unico punto i dati di log provenienti da istanze EC2, applicazioni e servizi AWS. Gli sviluppatori possono cercare e filtrare i log, creare metric filter ed eseguire query interattive con CloudWatch Logs Insights invece di accedere a ogni server.","optionExplanations":["Le metriche sono dati numerici come l'utilizzo della CPU; non conservano né permettono di cercare il testo dei file di log.","Gli allarmi osservano le metriche e reagiscono al superamento di soglie; non raccolgono né cercano i file di log.","Corretto — CloudWatch Logs centralizza i file di log, così gli sviluppatori possono cercarli e analizzarli in un unico punto.","Le dashboard mostrano grafici e widget dei dati di monitoraggio; non sono il luogo in cui i file di log vengono raccolti e cercati."]},
  "183": {"h":"4caf4f34","question":"A cosa serve una Amazon Machine Image (AMI) in AWS?","options":["Fornisce la risoluzione DNS per le istanze EC2 in un VPC","È un template usato per avviare istanze EC2","Gestisce i permessi IAM per le istanze EC2","È un agente di monitoraggio installato sulle istanze EC2"],"explanation":"Una Amazon Machine Image (AMI) è un template contenente una configurazione software (sistema operativo, application server, applicazioni) usato per avviare istanze EC2. Si possono usare AMI fornite da AWS, AMI del Marketplace oppure creare AMI personalizzate catturando lo stato di un'istanza EC2 configurata, per deployment coerenti e ripetibili.","optionExplanations":["La risoluzione DNS per le istanze EC2 è fornita da Amazon Route 53 o dal resolver DNS integrato del VPC, non dalle AMI.","Corretto — Una AMI è un template preconfigurato contenente sistema operativo, software e impostazioni, usato per avviare in modo coerente istanze EC2 configurate in modo identico.","I permessi IAM per le istanze EC2 sono gestiti tramite IAM Roles e instance profile, non tramite AMI.","Un agente di monitoraggio installato sulle istanze EC2 è il CloudWatch Agent, non una AMI, che è un template di avvio e non un software di monitoraggio."]},
  "184": {"h":"feb8280b","question":"Un piccolo team ha impacchettato la propria API web come immagine container. Il team non ha competenze infrastrutturali e non vuole gestire server, istanze o cluster. Vuole distribuire l'immagine e ottenere scalabilità automatica, bilanciamento del carico e HTTPS. Quale servizio AWS è il modo PIÙ SEMPLICE per soddisfare questi requisiti?","options":["Amazon ECS","Amazon EKS","AWS App Runner","AWS Elastic Beanstalk"],"explanation":"AWS App Runner è un servizio completamente gestito per eseguire applicazioni web e API containerizzate. Il team fornisce un'immagine container o il codice sorgente, e App Runner compila, distribuisce, scala e bilancia il carico dell'applicazione con HTTPS, senza infrastruttura da gestire.","optionExplanations":["ECS può eseguire container, ma il team deve definire cluster, servizi, task definition, rete e un load balancer. Ciò richiede più competenze infrastrutturali rispetto ad App Runner.","EKS esegue Kubernetes, la cui gestione richiede competenze significative. Non è l'opzione più semplice per un team senza competenze infrastrutturali.","Corretto — App Runner distribuisce direttamente l'immagine container e gestisce scalabilità, bilanciamento del carico e HTTPS senza infrastruttura da gestire.","Elastic Beanstalk crea nell'account istanze EC2 e altre risorse che il team continua a vedere e deve comprendere. Richiede più intervento rispetto ad App Runner."]},
  "185": {"h":"befee76e","question":"Quale funzionalità di AWS accelera l'upload di file di grandi dimensioni su Amazon S3 instradando gli upload attraverso le edge location di CloudFront distribuite a livello globale?","options":["S3 Cross-Region Replication","S3 Transfer Acceleration","AWS DataSync","AWS Snowball"],"explanation":"Amazon S3 Transfer Acceleration usa le edge location di CloudFront distribuite a livello globale per accelerare gli upload su S3 su lunghe distanze. Gli utenti caricano i dati sulla edge location più vicina e i dati raggiungono S3 attraverso la rete backbone ottimizzata di AWS. È particolarmente utile quando si carica su un bucket centralizzato da tutto il mondo.","optionExplanations":["S3 Cross-Region Replication copia oggetti da un bucket a un altro in una Region diversa: non accelera gli upload da utenti distribuiti geograficamente verso un singolo bucket.","Corretto — S3 Transfer Acceleration instrada gli upload attraverso la edge location di CloudFront più vicina e poi sulla rete backbone AWS, accelerando gli upload su S3 su lunghe distanze.","AWS DataSync trasferisce dati tra on-premises e AWS: è progettato per migrazione e sincronizzazione, non per accelerare gli upload degli utenti tramite le edge location di CloudFront.","AWS Snowball spedisce fisicamente i dati ad AWS: serve per trasferimenti massivi di grandi quantità di dati, non per accelerare le prestazioni degli upload continui da utenti distribuiti."]},
  "186": {"h":"83e8f722","question":"Quali DUE servizi AWS vengono comunemente usati insieme per disaccoppiare i componenti applicativi e abilitare una comunicazione asincrona e a basso accoppiamento?","options":["Amazon SQS","Amazon RDS","Amazon SNS","Amazon EBS","AWS CloudFormation"],"explanation":"Amazon SQS (code di messaggi punto-punto per l'elaborazione asincrona) e Amazon SNS (messaggistica pub/sub per distribuire i messaggi a più sottoscrittori) sono i principali servizi AWS per disaccoppiare i componenti applicativi. Abilitano architetture resilienti e a basso accoppiamento in cui i componenti possono operare in modo indipendente.","optionExplanations":["Corretto — Amazon SQS fornisce code punto-punto per l'elaborazione asincrona, disaccoppiando produttori e consumatori così che i componenti operino in modo indipendente.","Amazon RDS è un database relazionale: conserva i dati applicativi ma non offre messaggistica né comunicazione asincrona tra i componenti applicativi.","Corretto — Amazon SNS fornisce messaggistica pub/sub che distribuisce gli eventi a più sottoscrittori, abilitando architetture event-driven a basso accoppiamento.","Amazon EBS è storage a blocchi per istanze EC2: rende persistenti i dati ma non facilita la comunicazione né il disaccoppiamento tra componenti applicativi.","AWS CloudFormation distribuisce l'infrastruttura come codice: è uno strumento di provisioning dell'infrastruttura, non un servizio di messaggistica per disaccoppiare componenti applicativi."]},
  "187": {"h":"634e3965","question":"Un'azienda sta spostando le proprie applicazioni su AWS. Ha bisogno di una propria rete logicamente isolata in cui scegliere l'intervallo di indirizzi IP privati, creare subnet pubbliche e private e controllare l'instradamento con le route table. Quale servizio AWS dovrebbe usare l'azienda?","options":["AWS Direct Connect","Amazon Route 53","Amazon VPC","AWS Transit Gateway"],"explanation":"Amazon Virtual Private Cloud (Amazon VPC) consente all'azienda di avviare risorse in una rete virtuale logicamente isolata da essa definita, con pieno controllo su intervalli di indirizzi IP, subnet, route table e gateway.","optionExplanations":["AWS Direct Connect è una connessione dedicata da on-premises ad AWS. Non crea la rete isolata in cui vengono eseguite le risorse.","Amazon Route 53 è un servizio DNS. Risolve i nomi di dominio ma non definisce intervalli IP, subnet o route table.","Corretto — Amazon VPC fornisce una rete logicamente isolata in cui l'azienda definisce il proprio intervallo IP, le subnet e le route table.","AWS Transit Gateway collega più VPC e reti esistenti. L'azienda ha prima bisogno della rete isolata stessa."]},
  "188": {"h":"e4fb4b7c","question":"Un rivenditore regionale vuole un supporto operativo per migrare le proprie applicazioni su AWS. La direzione preferisce incaricare una società di consulenza terza locale con competenze convalidate da AWS piuttosto che consulenti dipendenti di AWS. Dove dovrebbe cercare una società di questo tipo?","options":["AWS Professional Services","AWS Partner Network","Community AWS re:Post","Team AWS Trust & Safety"],"explanation":"L'AWS Partner Network (APN) è la community globale di partner, comprese le società di consulenza, che sviluppano soluzioni e forniscono servizi su AWS. AWS convalida le competenze dei partner tramite programmi come AWS Competencies, aiutando i clienti a scegliere un partner qualificato. AWS Professional Services, invece, è composto da dipendenti AWS.","optionExplanations":["AWS Professional Services è un team di esperti dipendenti di AWS, ed è proprio ciò che la direzione vuole evitare.","Corretto — l'AWS Partner Network include partner di consulenza le cui competenze sono convalidate da AWS, così il rivenditore può trovare una società locale qualificata.","re:Post è un servizio di domande e risposte della community. Risponde alle domande ma non fornisce una società che esegua la migrazione.","Il team Trust & Safety gestisce le segnalazioni di abusi provenienti da risorse AWS. Non raccomanda società di consulenza."]},
  "189": {"h":"608bf9d4","question":"Un'azienda di medie dimensioni sta per spostare su AWS i propri sistemi di produzione rivolti ai clienti. Oggi dispone solo del piano di supporto incluso in ogni account. Vuole accesso 24/7 al supporto tecnico AWS via telefono, chat ed email, e vuole il piano che AWS raccomanda come minimo per i workload di produzione. Quale piano dovrebbe scegliere?","options":["Basic Support","AWS Business Support+","AWS Enterprise Support","AWS Unified Operations"],"explanation":"AWS posiziona Business Support+ come piano minimo raccomandato per i workload di produzione. Offre supporto tecnico 24/7 via telefono, web, chat ed email, con risposte più rapide quando un sistema di produzione è fuori servizio. Enterprise Support e Unified Operations aggiungono ulteriori competenze per workload business-critical e mission-critical.","optionExplanations":["Basic Support è il piano che l'azienda ha già. Include il servizio clienti e la documentazione, ma non il supporto tecnico 24/7 da parte degli ingegneri AWS.","Corretto — Business Support+ è il piano minimo raccomandato per i workload di produzione e include supporto tecnico 24/7 via telefono, web, chat ed email.","Anche Enterprise Support include il supporto tecnico 24/7, ma è rivolto ai workload business-critical e aggiunge un TAM dedicato che l'azienda non ha richiesto.","Unified Operations è progettato per workload mission-critical che richiedono gestione degli incidenti e ingegneri specializzati di dominio, ben oltre l'esigenza indicata."]},
  "190": {"h":"437f8eed","question":"Quale opzione di acquisto EC2 fornisce un server fisico interamente dedicato a un singolo cliente, offrendo visibilità sui dettagli a livello di host e supportando software BYOL (Bring Your Own License)?","options":["Dedicated Instances","Dedicated Hosts","Reserved Instances","Spot Instances"],"explanation":"I Dedicated Hosts sono server fisici EC2 dedicati al proprio uso, che offrono visibilità e controllo sul posizionamento delle istanze sull'host. Supportano licenze software BYOL (Windows Server, SQL Server) legate a core o socket fisici. Le Dedicated Instances vengono eseguite su hardware dedicato ma senza visibilità a livello di host.","optionExplanations":["Le Dedicated Instances vengono eseguite su hardware dedicato a un singolo cliente ma non espongono i dettagli a livello di host (socket, core) richiesti dalle licenze BYOL per core o per socket.","Corretto — I Dedicated Hosts offrono piena visibilità sul server fisico (socket, core, ID dell'host), consentendo licenze software BYOL legate alle caratteristiche dell'hardware fisico.","Le Reserved Instances sono un modello di prezzo che di norma viene eseguito su hardware condiviso: di per sé non offrono visibilità sull'host fisico né supportano le licenze BYOL.","Le Spot Instances usano la capacità EC2 inutilizzata a prezzo scontato e possono essere interrotte in qualsiasi momento: non sono adatte al BYOL né a requisiti che richiedono hardware fisico dedicato."]},
  "191": {"h":"20d31f3d","question":"Un'azienda intende impegnarsi su una Reserved Instance per il proprio workload Amazon EC2 al fine di ridurre i costi. Durante il periodo contrattuale prevede di passare a una famiglia di istanze diversa e forse a un sistema operativo diverso. L'azienda accetta uno sconto minore in cambio di questa flessibilità. Quale opzione dovrebbe acquistare?","options":["Standard Reserved Instances","Convertible Reserved Instances","EC2 Instance Savings Plans","Spot Instances"],"explanation":"Le Convertible Reserved Instances possono essere scambiate durante il periodo contrattuale con Reserved Instances di una famiglia di istanze, un sistema operativo o una tenancy diversi. In cambio offrono uno sconto minore rispetto alle Standard Reserved Instances.","optionExplanations":["Le Standard Reserved Instances offrono lo sconto più elevato tra le Reserved Instances, ma non possono essere scambiate con una famiglia di istanze diversa.","Corretto — Le Convertible Reserved Instances possono essere scambiate con un'altra famiglia di istanze o un altro sistema operativo, con uno sconto minore.","Gli EC2 Instance Savings Plans si applicano a una sola famiglia di istanze in una Region scelta. Non coprono il passaggio a una famiglia di istanze diversa e non sono una Reserved Instance.","Le Spot Instances usano capacità inutilizzata senza impegno e possono essere interrotte. Non sono una prenotazione."]},
  "192": {"h":"57bb511d","question":"Quale modello di prezzo AWS consente ai clienti di pagare la capacità di calcolo al secondo senza impegni a lungo termine, offrendo la massima flessibilità per workload imprevedibili?","options":["Reserved Instances","Savings Plans","On-Demand Instances","Spot Instances"],"explanation":"Il prezzo On-Demand consente di pagare all'ora o al secondo (minimo 60 secondi) senza impegni a lungo termine né pagamenti anticipati. È ideale per workload irregolari, sviluppo/test e applicazioni che non possono essere interrotte, anche se ha il costo unitario più alto rispetto ai prezzi basati su un impegno.","optionExplanations":["Le Reserved Instances richiedono un impegno di 1 o 3 anni: non sono adatte a workload imprevedibili che richiedono la massima flessibilità di avvio e arresto in qualsiasi momento.","I Savings Plans richiedono un impegno di spesa in $/ora per 1 o 3 anni: riducono la flessibilità rispetto al puro modello pay-as-you-go On-Demand.","Corretto — Il prezzo On-Demand addebita al secondo (Linux, minimo 60 s) senza costi anticipati né impegni, offrendo la massima flessibilità per workload irregolari.","Le Spot Instances usano la capacità EC2 inutilizzata e possono essere interrotte con un preavviso di 2 minuti: non sono adatte a workload che richiedono un funzionamento continuo e senza interruzioni."]},
  "193": {"h":"ba55edc8","question":"Quale strumento AWS di gestione dei costi fornisce i dati di costo e utilizzo più granulari, che possono essere consegnati su S3 per l'analisi con Athena o QuickSight?","options":["Report salvati di AWS Cost Explorer","AWS Budgets","AWS Cost and Usage Report","AWS Pricing Calculator"],"explanation":"L'AWS Cost and Usage Report (CUR) fornisce i dati di costo e utilizzo più completi disponibili, inclusi metadati su servizi, prezzi e prenotazioni. Consegnato su S3 con granularità oraria o giornaliera, può essere analizzato con Athena, Redshift o QuickSight per analisi dei costi personalizzate.","optionExplanations":["Cost Explorer fornisce visualizzazioni riepilogative dei costi e filtri di base: non esporta i dati grezzi riga per riga per analisi personalizzate con strumenti come Athena.","AWS Budgets monitora la spesa rispetto a soglie: non fornisce dati granulari riga per riga né funzionalità di esportazione dei dati grezzi.","Corretto — L'AWS CUR fornisce i dati di fatturazione più dettagliati (voci orarie/giornaliere, ID delle risorse, metadati sui prezzi), consegnati su S3 per l'analisi con Athena, Redshift o QuickSight.","AWS Pricing Calculator stima i costi futuri: non dispone di dati sull'utilizzo effettivo delle risorse né sugli addebiti storici."]},
  "194": {"h":"b350f65f","question":"Un'azienda vuole monitorare i costi AWS per progetto e reparto etichettando le risorse con metadati. Quale funzionalità di AWS consente di attribuire i costi nei report di fatturazione?","options":["OU di AWS Organizations","AWS Cost Allocation Tags","Avvisi di AWS Budgets","Filtri di AWS Cost Explorer"],"explanation":"I Cost Allocation Tags consentono di etichettare le risorse AWS con coppie chiave-valore (ad es. Project=Ecommerce, Department=Finance). Dopo averli attivati nella console Billing, i costi etichettati compaiono come categorie separate nei report di Cost Explorer, CUR e Budgets, consentendo di attribuire i costi a team o progetti specifici.","optionExplanations":["Le OU di AWS Organizations organizzano gli account ai fini della governance: ripartiscono i costi a livello di account ma non a livello di singola risorsa all'interno di un account.","Corretto — I Cost Allocation Tags (coppie chiave-valore sulle risorse) fanno comparire i costi suddivisi per categoria in Cost Explorer e nel CUR, consentendo l'attribuzione dei costi per progetto o per reparto.","Gli avvisi di AWS Budgets notificano quando la spesa supera determinate soglie: non etichettano le risorse né classificano i costi ai fini dell'attribuzione.","I filtri di Cost Explorer permettono di suddividere i dati di costo esistenti per dimensione, ma i tag devono prima essere applicati alle risorse e attivati nella console Billing."]},
  "195": {"h":"0de4e9d8","question":"Un'azienda ha bisogno di un'appliance firewall di terze parti e di uno strumento di monitoraggio SaaS per il proprio ambiente AWS. Vuole trovarli, provarli e acquistarli rapidamente, con gli addebiti sulla fattura AWS, e distribuire il software direttamente nel proprio account AWS. Quale offerta AWS dovrebbe usare l'azienda?","options":["AWS Partner Network (APN)","AWS Marketplace","AWS Service Catalog","AWS License Manager"],"explanation":"AWS Marketplace è un catalogo digitale curato in cui i clienti possono trovare, provare, acquistare e distribuire software di terze parti, prodotti SaaS, dati e servizi professionali. Gli acquisti vengono addebitati sulla fattura AWS e molti prodotti possono essere distribuiti direttamente nell'account AWS del cliente.","optionExplanations":["L'AWS Partner Network è la community globale di partner che sviluppano soluzioni e servizi su AWS. Non è il negozio in cui l'azienda acquista e distribuisce software.","Corretto — AWS Marketplace consente all'azienda di trovare, provare, acquistare e distribuire software di terze parti e prodotti SaaS, con addebiti sulla fattura AWS.","AWS Service Catalog consente a un'organizzazione di offrire ai propri utenti prodotti interni pre-approvati. Non è un negozio per acquistare software di terze parti.","AWS License Manager traccia e controlla l'utilizzo delle licenze software. Non consente all'azienda di trovare e acquistare nuovo software di terze parti."]},
  "196": {"h":"d86545eb","question":"Quale tipo di Savings Plan AWS offre la MAGGIORE flessibilità, applicandosi a qualsiasi famiglia, dimensione e Region di istanze EC2, oltre che ad AWS Lambda e AWS Fargate?","options":["EC2 Instance Savings Plans","Compute Savings Plans","SageMaker Savings Plans","Standard Reserved Instances"],"explanation":"I Compute Savings Plans sono l'impegno di risparmio più flessibile e si applicano automaticamente a qualsiasi istanza EC2 indipendentemente da famiglia, dimensione, Region, sistema operativo o tenancy, oltre che a Lambda e Fargate. Offrono fino al 66% di risparmio rispetto a On-Demand. Gli EC2 Instance Savings Plans offrono sconti maggiori (fino al 72%) ma solo per una specifica famiglia di istanze in una Region.","optionExplanations":["Gli EC2 Instance Savings Plans offrono sconti maggiori (fino al 72%) ma sono limitati a una specifica famiglia di istanze in una specifica Region: non hanno flessibilità tra famiglie, tra Region e tra servizi.","Corretto — I Compute Savings Plans si applicano automaticamente a qualsiasi istanza EC2 (qualsiasi famiglia, dimensione, Region, sistema operativo), oltre che a Lambda e Fargate, in cambio di un impegno di spesa in $/ora.","I SageMaker Savings Plans si applicano esclusivamente al calcolo ML di SageMaker: non coprono EC2, Lambda o Fargate.","Le Standard Reserved Instances sono vincolate a un tipo di istanza e a una Region specifici e non si applicano a Lambda o Fargate: molto meno flessibili dei Savings Plans."]},
  "197": {"h":"75116b1d","question":"Un'azienda riceve un'unica fattura AWS mensile che copre gli addebiti di tutti gli account della propria organizzazione. Quale funzionalità di AWS Organizations lo consente?","options":["Service Control Policies","AWS Control Tower","Consolidated Billing","AWS Config Aggregator"],"explanation":"Consolidated Billing riunisce l'utilizzo e gli addebiti AWS di tutti gli account membri in un'unica fattura pagata dal management account. Ciò semplifica la gestione della fatturazione e consente di beneficiare dei prezzi a volume, perché l'utilizzo di tutti gli account viene aggregato ai fini degli sconti a scaglioni.","optionExplanations":["Le Service Control Policies limitano le azioni API che gli account di un'organizzazione possono eseguire: sono uno strumento di governance, non una funzionalità di fatturazione.","AWS Control Tower automatizza la configurazione di un ambiente multi-account e si basa su Organizations, ma non è di per sé la funzionalità di aggregazione della fatturazione.","Corretto — Consolidated Billing in AWS Organizations riunisce gli addebiti di tutti gli account membri in un'unica fattura mensile pagata dal management account, consentendo sconti a volume.","AWS Config Aggregator raccoglie dati di configurazione e conformità delle risorse tra account: è uno strumento di audit, non legato alla fatturazione."]},
  "198": {"h":"ae66ae14","question":"Una sviluppatrice sta progettando un piccolo progetto personale che dovrà restare attivo per anni. Vuole basarsi solo su offerte AWS Free Tier che non scadono dopo un periodo introduttivo. Quale tipo di offerta AWS Free Tier dovrebbe cercare?","options":["Offerte always free","Crediti di iscrizione del Free plan","Prove gratuite a breve termine","Restare sul Free plan"],"explanation":"L'AWS Free Tier include offerte always free per oltre 30 servizi, disponibili entro limiti mensili sia sul Free plan sia sul Paid plan. I crediti e le prove a breve termine terminano dopo un periodo stabilito, e un account Free plan viene chiuso dopo sei mesi a meno che non venga aggiornato, quindi un progetto di lunga durata dovrebbe restare entro i limiti always free su un account Paid plan.","optionExplanations":["Corretto — le offerte always free restano disponibili entro limiti di utilizzo mensili e non scadono, sia sul Free plan sia sul Paid plan.","I crediti del Free plan possono essere usati per un massimo di sei mesi e si esauriscono man mano che vengono spesi, quindi non possono mantenere gratuito un progetto per anni.","Le prove gratuite a breve termine si applicano a servizi selezionati per un periodo limitato, quindi terminano molto prima del progetto.","Un account Free plan viene chiuso dopo sei mesi o quando i crediti si esauriscono, a meno che non venga aggiornato, quindi non può ospitare un progetto per anni."]},
  "199": {"h":"98452e59","question":"Una sviluppatrice di una piccola azienda con Basic Support è bloccata su una domanda di configurazione non urgente. Vuole pubblicare la domanda in modo pubblico e ricevere risposte da esperti AWS e da altri membri della community, senza aprire un caso di supporto a pagamento. Quale risorsa AWS dovrebbe usare?","options":["AWS re:Post","AWS Knowledge Center","Team AWS Trust & Safety","AWS Health Dashboard"],"explanation":"AWS re:Post è un servizio di domande e risposte gestito dalla community in cui i clienti ricevono risposte da esperti AWS e membri della community. È disponibile per ogni cliente AWS come parte di Basic Support, quindi non serve alcun piano a pagamento.","optionExplanations":["Corretto — AWS re:Post consente a chiunque di porre domande e ricevere risposte da esperti AWS e dalla community, ed è incluso in Basic Support.","Il Knowledge Center offre articoli e video redatti da AWS sulle domande più comuni. Non è il luogo in cui pubblicare la propria domanda per ricevere risposte dalla community.","Il team Trust & Safety gestisce le segnalazioni di abusi provenienti da risorse AWS. Non risponde a domande tecniche di configurazione.","L'AWS Health Dashboard mostra gli eventi che interessano i servizi AWS e le risorse dell'account. Non è un forum di domande e risposte."]},
  "200": {"h":"4a35b4d7","question":"Una startup ha usato il piano Basic Support durante lo sviluppo del prodotto. Prima del lancio in produzione passa ad AWS Business Support+. Quali vantaggi ottiene la startup che Basic Support NON include? (Seleziona DUE)","options":["Accesso alla documentazione AWS e ai whitepaper tecnici","Supporto tecnico 24/7 via telefono, chat ed email","Indicazioni architetturali adattate ai propri casi d'uso","Accesso alla community AWS re:Post","Un Technical Account Manager (TAM) dedicato"],"explanation":"Basic Support offre a ogni cliente servizio clienti, documentazione, whitepaper, AWS re:Post, i controlli core di AWS Trusted Advisor e AWS Health. Business Support+, il piano minimo raccomandato per i workload di produzione, aggiunge supporto tecnico 24/7 e indicazioni architetturali contestualizzate ai casi d'uso del cliente. Un TAM dedicato richiede Enterprise Support.","optionExplanations":["Documentazione e whitepaper sono disponibili per ogni cliente tramite Basic Support, quindi la startup li ha già.","Corretto — Business Support+ aggiunge supporto tecnico 24/7 via telefono, web, chat ed email, non incluso in Basic Support.","Corretto — Business Support+ fornisce indicazioni architetturali contestualizzate ai casi d'uso specifici del cliente.","AWS re:Post fa parte di Basic Support ed è aperto a tutti i clienti, quindi la startup lo ha già.","Un TAM dedicato è una funzionalità di Enterprise Support, non di Business Support+."]},
  "201": {"h":"bb31da24","question":"Quale modello di deployment cloud esegue l'infrastruttura esclusivamente presso le sedi dell'azienda ed è gestito internamente?","options":["Cloud pubblico","Cloud ibrido","Cloud privato","Cloud di comunità"],"explanation":"Un cloud privato viene implementato e gestito esclusivamente per una singola organizzazione, on-premises o in un ambiente ospitato dedicato. Offre il pieno controllo, ma richiede che l'azienda acquisti e gestisca tutto l'hardware.","optionExplanations":["L'infrastruttura del cloud pubblico è di proprietà di un provider terzo (come AWS), che la gestisce e la condivide tra più organizzazioni: non è gestita esclusivamente da e per una singola azienda.","Il cloud ibrido combina infrastruttura on-premises/privata E un cloud pubblico: non viene eseguito esclusivamente presso le sedi dell'azienda.","Corretto — Il cloud privato viene eseguito esclusivamente su un'infrastruttura dedicata a una singola organizzazione, on-premises o in un ambiente ospitato dedicato.","Il cloud di comunità è condiviso tra diverse organizzazioni con esigenze comuni (ad es. pubblica amministrazione o sanità): non è gestito internamente in modo esclusivo da una singola azienda."]},
  "202": {"h":"57ecf689","question":"Un'azienda vuole mantenere i workload sensibili on-premises, usando al contempo AWS per la capacità aggiuntiva nei picchi. Quale modello di deployment descrive questa situazione?","options":["Cloud pubblico","Cloud privato","Cloud ibrido","Multi-cloud"],"explanation":"Un cloud ibrido combina un'infrastruttura on-premises (o un cloud privato) con un cloud pubblico, consentendo a dati e applicazioni di spostarsi tra i due. È ideale per requisiti di compliance o per workload sensibili alla latenza che devono restare on-premises.","optionExplanations":["Il cloud pubblico viene eseguito interamente sull'infrastruttura condivisa di un cloud provider: non include una componente on-premises per i workload sensibili.","Il cloud privato viene eseguito esclusivamente su un'infrastruttura dedicata, on-premises o ospitata: non include la componente di capacità aggiuntiva su AWS descritta.","Corretto — Il cloud ibrido collega l'infrastruttura on-premises (per i workload sensibili) con AWS (per la capacità aggiuntiva nei picchi), permettendo ai workload di spostarsi tra i due ambienti.","Il multi-cloud utilizza contemporaneamente più provider di cloud pubblico: non descrive specificamente la combinazione di on-premises e di un singolo cloud provider per la capacità nei picchi."]},
  "203": {"h":"8cab2f0f","question":"Un'azienda brasiliana di mobile gaming ha un gioco di successo. Ora vuole servire i giocatori in Giappone e in Europa con bassa latenza e prevede di avviare l'infrastruttura in quelle aree entro questa settimana, senza costruire né affittare data center. Quale vantaggio del Cloud AWS descrive questa situazione?","options":["Beneficiare di enormi economie di scala","Smettere di stimare la capacità","Diventare globali in pochi minuti","Aumentare velocità e agilità"],"explanation":"«Diventare globali in pochi minuti» descrive l'uso delle Region AWS in tutto il mondo per distribuire rapidamente un'applicazione vicino agli utenti di nuove aree geografiche, senza costruire data center in ogni località.","optionExplanations":["Le economie di scala spiegano perché AWS può offrire prezzi più bassi grazie alle sue dimensioni. Non descrivono il deployment rapido in nuove aree geografiche.","Smettere di stimare la capacità significa scalare in base alla domanda effettiva invece di prevederla. Non descrive l'espansione in nuovi paesi.","Corretto — L'azienda può effettuare il deployment nelle Region AWS in Asia ed Europa in poco tempo, portando il gioco vicino ai nuovi giocatori.","Velocità e agilità si riferiscono al rendere disponibili le risorse agli sviluppatori in pochi minuti, così da sperimentare più rapidamente. L'espansione globale vicino agli utenti è qui il vantaggio più specifico."]},
  "204": {"h":"9a20d14a","question":"Poiché AWS aggrega l'utilizzo di centinaia di migliaia di clienti, può ottenere prezzi pay-as-you-go più bassi. Quale vantaggio del cloud rappresenta questo?","options":["Sostituire le spese fisse con spese variabili","Enormi economie di scala","Smettere di stimare la capacità","Aumentare velocità e agilità"],"explanation":"La scala enorme di AWS le consente di acquistare hardware e gestire data center a costi molto inferiori rispetto a una singola azienda. Questi risparmi vengono trasferiti ai clienti sotto forma di prezzi variabili più bassi: è il vantaggio delle «enormi economie di scala».","optionExplanations":["«Sostituire le spese fisse con spese variabili» descrive il passaggio da CapEx a OpEx: riguarda il modello di pagamento, non i prezzi più bassi derivanti dal potere d'acquisto aggregato.","Corretto — «Enormi economie di scala» significa che AWS trasferisce i risparmi derivanti dall'aggregazione dell'utilizzo di centinaia di migliaia di clienti sotto forma di prezzi variabili più bassi.","«Smettere di stimare la capacità» descrive l'uso di Auto Scaling per risorse dimensionate correttamente: riguarda la pianificazione della capacità, non la riduzione dei prezzi dovuta alla scala aggregata.","«Aumentare velocità e agilità» descrive un time-to-market più rapido: riguarda la velocità di provisioning, non i vantaggi di prezzo derivanti dalla scala."]},
  "205": {"h":"e5b4daac","question":"Uno sviluppatore può creare un nuovo ambiente di test su AWS in pochi minuti, invece di attendere settimane per l'acquisto dell'hardware. Quale vantaggio del cloud illustra MEGLIO questa situazione?","options":["Diventare globali in pochi minuti","Smettere di stimare la capacità","Aumentare velocità e agilità","Sostituire le spese fisse con spese variabili"],"explanation":"«Aumentare velocità e agilità» si riferisce alla capacità di effettuare rapidamente il provisioning di nuove risorse, sperimentare velocemente e ridurre il tempo necessario per portare nuove idee sul mercato. Nel cloud, ciò che prima richiedeva settimane ora richiede minuti.","optionExplanations":["«Diventare globali in pochi minuti» si riferisce al deployment nelle Region di tutto il mondo: riguarda la copertura geografica, non la velocità di creazione di un ambiente di test locale.","«Smettere di stimare la capacità» si riferisce all'adeguamento dell'infrastruttura alla domanda effettiva con Auto Scaling: riguarda l'accuratezza della capacità, non un provisioning più rapido degli ambienti.","Corretto — «Aumentare velocità e agilità» significa che gli sviluppatori possono creare ambienti di test in pochi minuti invece di attendere settimane per l'acquisto dell'hardware.","«Sostituire le spese fisse con spese variabili» si riferisce al passaggio finanziario da CapEx a OpEx: riguarda il modello di costo, non la velocità di deployment."]},
  "206": {"h":"f268d805","question":"Quale dei seguenti è un esempio di Infrastructure as a Service (IaaS)?","options":["AWS Lambda","Amazon RDS","Amazon EC2","AWS Elastic Beanstalk"],"explanation":"Amazon EC2 fornisce macchine virtuali di base (calcolo, rete e storage) in cui il cliente gestisce il sistema operativo e tutto ciò che sta sopra. Questo è IaaS. Lambda è FaaS, RDS è PaaS/database gestito ed Elastic Beanstalk è PaaS.","optionExplanations":["AWS Lambda è un servizio serverless/FaaS: gli sviluppatori scrivono solo il codice delle funzioni e AWS gestisce tutta l'infrastruttura sottostante.","Amazon RDS è un servizio di database gestito (PaaS): AWS si occupa del sistema operativo, delle patch del motore di database e dei backup; i clienti gestiscono solo gli schemi del database e i dati.","Corretto — Amazon EC2 è IaaS: AWS fornisce l'hardware virtuale, ma il cliente gestisce sistema operativo, middleware, runtime e applicazioni.","AWS Elastic Beanstalk è un servizio PaaS: gli sviluppatori distribuiscono il codice dell'applicazione e AWS gestisce l'infrastruttura, eliminando la necessità di gestire server o sistema operativo."]},
  "207": {"h":"fcfa1e63","question":"Un piccolo studio legale vuole un'applicazione di posta elettronica e collaborazione documentale che il personale usi tramite browser web. Lo studio non vuole gestire server, sistemi operativi, middleware o aggiornamenti dell'applicazione, ma solo i propri dati e gli account utente. Quale modello di servizio cloud soddisfa MEGLIO questi requisiti?","options":["Infrastructure as a Service (IaaS)","Platform as a Service (PaaS)","Software as a Service (SaaS)","Function as a Service (FaaS)"],"explanation":"Il Software as a Service (SaaS) fornisce un'applicazione completa via internet, con il provider che gestisce l'infrastruttura, il middleware e l'applicazione stessa. Il cliente gestisce solo i propri dati e il modo in cui gli utenti accedono al servizio: esattamente ciò che vuole lo studio legale.","optionExplanations":["Con IaaS lo studio dovrebbe comunque gestire sistemi operativi, middleware e applicazione, cosa che vuole evitare.","Con PaaS il provider gestisce la piattaforma, ma lo studio dovrebbe comunque sviluppare o distribuire e mantenere la propria applicazione.","Corretto — Il SaaS offre allo studio un'applicazione pronta all'uso nel browser, con il provider che gestisce tutto tranne i dati e gli account utente dello studio.","Con FaaS lo studio dovrebbe scrivere e mantenere il proprio codice delle funzioni. Vuole un'applicazione finita, non una piattaforma su cui eseguire codice."]},
  "208": {"h":"13667349","question":"Secondo lo Shared Responsibility Model di AWS, di quale dei seguenti aspetti è responsabile AWS?","options":["Applicare le patch al sistema operativo guest su EC2","Gestire le autorizzazioni degli utenti IAM","Sicurezza fisica delle strutture dei data center","Crittografare i dati delle applicazioni"],"explanation":"AWS è responsabile della «sicurezza DEL cloud»: l'infrastruttura fisica, inclusi data center, hardware, rete e hypervisor. I clienti sono responsabili della «sicurezza NEL cloud»: patch del sistema operativo, IAM e crittografia dei dati.","optionExplanations":["Applicare le patch al sistema operativo guest su EC2 è responsabilità del cliente: AWS gestisce solo il livello di hypervisor e hardware, non il sistema operativo in esecuzione nella macchina virtuale.","Gestire le autorizzazioni degli utenti IAM è sempre responsabilità del cliente: AWS fornisce il servizio IAM ma non decide mai chi ottiene quali autorizzazioni nell'account di un cliente.","Corretto — La sicurezza fisica delle strutture dei data center è responsabilità di AWS («sicurezza DEL cloud»): i clienti non hanno mai accesso fisico ai data center AWS.","Crittografare i dati delle applicazioni è responsabilità del cliente: AWS fornisce gli strumenti (KMS, ACM), ma la decisione di crittografare e la gestione delle chiavi spettano al cliente."]},
  "209": {"h":"3eff859f","question":"Un'azienda vuole una strategia di disaster recovery in cui una copia ridotta ma pienamente funzionante del proprio ambiente di produzione sia sempre in esecuzione in un'altra Region AWS, pronta per essere scalata rapidamente in caso di disastro. Quale strategia corrisponde MEGLIO a questa descrizione?","options":["Backup and restore","Pilot light","Warm standby","Multi-site active/active"],"explanation":"Il warm standby mantiene una copia ridotta ma completa e in esecuzione del workload in un'altra località, così da poter servire subito il traffico ed essere scalata alla piena capacità in caso di disastro. Offre un RTO inferiore al pilot light a un costo maggiore, ma costa meno del multi-site active/active.","optionExplanations":["Il backup and restore mantiene solo i backup nella località di ripristino; l'infrastruttura deve essere creata e i dati ripristinati dopo un disastro, quindi nulla è in esecuzione in anticipo.","Il pilot light mantiene in esecuzione i componenti principali, come la replica dei dati, ma i server applicativi sono spenti e devono essere avviati prima che l'ambiente possa servire traffico.","Corretto — Il warm standby esegue in ogni momento una copia più piccola ma pienamente funzionante della produzione, che viene scalata quando si verifica un disastro.","Il multi-site active/active esegue la piena capacità di produzione in più Region e serve traffico da tutte, invece di mantenere una copia ridotta in standby."]},
  "210": {"h":"69ea8cef","question":"Quale pilastro dell'AWS Well-Architected Framework si concentra sull'uso efficiente delle risorse per soddisfare i requisiti del sistema al costo più basso possibile?","options":["Reliability","Security","Cost Optimization","Sustainability"],"explanation":"Il pilastro Cost Optimization aiuta le organizzazioni a evitare spese inutili dimensionando correttamente le risorse, usando capacità riservata e sfruttando i servizi gestiti. Include la comprensione dei modelli di spesa e la scelta delle opzioni più convenienti.","optionExplanations":["Reliability si concentra sul ripristino del sistema dopo i guasti e sul rispetto degli obiettivi di disponibilità, non sull'evitare spese inutili o ottimizzare i costi delle risorse.","Security si concentra sulla protezione di dati e sistemi tramite controlli di accesso e rilevamento delle minacce, non sull'efficienza delle risorse e sulla gestione dei costi.","Corretto — Cost Optimization si concentra sull'evitare spese inutili tramite right-sizing, capacità riservata, servizi gestiti e ottimizzazione continua della spesa.","Sustainability si concentra sulla riduzione dell'impatto ambientale: pur essendo legato all'efficienza, il suo obiettivo è ridurre l'impronta di carbonio, non ottimizzare i costi economici."]},
  "211": {"h":"e1ecc8df","question":"Un'azienda vuole progettare il proprio workload AWS in modo che un guasto in una Availability Zone non comprometta l'intera applicazione. Quale principio di progettazione rappresenta questo approccio?","options":["Progettare per il guasto","Implementare l'elasticità","Disaccoppiare i componenti","Ottimizzare i costi"],"explanation":"«Progettare per il guasto» (o «presumere che tutto possa guastarsi») è un principio chiave della progettazione cloud. Il deployment su più AZ garantisce l'alta disponibilità: se una zona si guasta, il traffico si sposta automaticamente sulle zone funzionanti.","optionExplanations":["Corretto — «Progettare per il guasto» significa presumere che qualsiasi AZ possa guastarsi e progettare l'architettura su più AZ, così che il traffico si sposti automaticamente sulle zone funzionanti senza interruzioni.","«Implementare l'elasticità» significa aumentare/ridurre automaticamente le risorse in base alla domanda: riguarda la gestione della capacità, non la resilienza multi-AZ.","«Disaccoppiare i componenti» significa usare code/API tra i componenti: riduce le dipendenze e migliora la resilienza, ma non riguarda specificamente il failover multi-AZ.","«Ottimizzare i costi» significa ridurre le spese inutili: non descrive l'architettura di isolamento dei guasti multi-AZ."]},
  "212": {"h":"5d798629","question":"Dopo un lungo disservizio, il team operativo di un'azienda ha scoperto che nessuno riusciva a tracciare le richieste non riuscite e che i passaggi di ripristino venivano eseguiti a mano. Il team ora prevede di aggiungere il tracciamento delle richieste, automatizzare i runbook e tenere revisioni post-incidente. Quale pilastro dell'AWS Well-Architected Framework sta seguendo il team?","options":["Security","Reliability","Performance Efficiency","Operational Excellence"],"explanation":"Il pilastro Operational Excellence si concentra sull'esecuzione e il monitoraggio dei sistemi e sul miglioramento continuo dei processi. Le sue pratiche includono l'osservabilità (come il tracciamento delle richieste), l'esecuzione delle operazioni come codice (runbook automatizzati) e l'apprendimento dagli eventi operativi tramite revisioni post-incidente.","optionExplanations":["Il pilastro Security riguarda la protezione di dati, sistemi e identità, non il tracciamento delle richieste o il miglioramento delle procedure operative quotidiane.","Reliability si concentra sulla capacità di un workload di riprendersi dai guasti e soddisfare la domanda. Automatizzare i runbook e imparare dagli incidenti sono pratiche operative di Operational Excellence.","Performance Efficiency riguarda l'uso efficiente delle risorse di calcolo e la scelta dei tipi di risorse adeguati, non le procedure operative.","Corretto — tracciare le richieste, automatizzare le procedure operative e imparare dagli incidenti sono pratiche di Operational Excellence."]},
  "213": {"h":"6b08a423","question":"Quale termine descrive il concetto AWS di aggiungere o rimuovere automaticamente risorse in base alla domanda corrente?","options":["Alta disponibilità","Tolleranza ai guasti","Elasticità","Durabilità"],"explanation":"L'elasticità è la capacità di aumentare o ridurre automaticamente le risorse in risposta alla domanda. Gli Auto Scaling group sono uno dei principali meccanismi AWS per l'elasticità e garantiscono di avere esattamente la capacità necessaria in ogni momento.","optionExplanations":["Alta disponibilità significa che un sistema resta accessibile con tempi di inattività minimi: riguarda uptime e ridondanza, non l'adeguamento automatico della capacità alla domanda.","Tolleranza ai guasti significa continuare a funzionare anche quando dei componenti si guastano: riguarda la resilienza durante i guasti, non l'aumento e la riduzione della capacità.","Corretto — L'elasticità è l'adeguamento automatico delle risorse (in aumento o in diminuzione) in base alla domanda corrente, usando servizi come Auto Scaling per allineare la capacità al fabbisogno.","La durabilità si riferisce all'integrità a lungo termine dei dati archiviati (che non vengano persi o corrotti): riguarda la persistenza dei dati, non l'adeguamento della capacità."]},
  "214": {"h":"71355f50","question":"Che cosa significa «alta disponibilità» nel contesto dell'architettura cloud AWS?","options":["Un sistema che non subisce mai alcun downtime in nessuna circostanza","Un sistema progettato per restare operativo nonostante i guasti dei componenti","Un sistema che può scalare all'infinito per gestire qualsiasi carico","Un sistema con il costo di esercizio più basso possibile"],"explanation":"Alta disponibilità significa progettare sistemi che riducano al minimo il downtime usando ridondanza e failover automatico. Non significa zero downtime (quella è la tolleranza ai guasti), ma che il sistema può riprendersi rapidamente o reindirizzare il traffico quando i componenti si guastano.","optionExplanations":["Un sistema che non ha mai alcun downtime descrive la tolleranza ai guasti: l'alta disponibilità ammette brevi interruzioni minime durante il failover, non uno zero downtime assoluto.","Corretto — L'alta disponibilità riduce al minimo il downtime tramite ridondanza e failover automatico; il sistema resta operativo nonostante i guasti, anche se possono verificarsi brevi interruzioni.","Un sistema che scala all'infinito descrive l'elasticità o la scalabilità: l'alta disponibilità riguarda uptime e ridondanza, non una crescita illimitata della capacità.","Un sistema con il costo di esercizio più basso descrive l'ottimizzazione dei costi: l'alta disponibilità ha un costo intrinseco dovuto alle risorse ridondanti."]},
  "215": {"h":"bf7473c3","question":"Un'azienda di pagamenti online comunica ai propri architetti che il sistema di checkout deve continuare a elaborare i pagamenti senza interruzioni, anche se si guasta un server o un'intera Availability Zone. Gli architetti descrivono questo obiettivo come tolleranza ai guasti. Quale affermazione descrive MEGLIO ciò che devono ottenere?","options":["Aumentare e ridurre automaticamente le risorse al variare della domanda","Continuare a funzionare senza downtime quando i componenti si guastano","Distribuire l'applicazione nelle Region di tutto il mondo in pochi minuti","Pagare solo per le risorse effettivamente utilizzate dal sistema"],"explanation":"Tolleranza ai guasti significa che il sistema continua a funzionare correttamente, senza downtime, quando uno o più componenti si guastano. Di solito si ottiene con componenti ridondanti distribuiti su più Availability Zone. È più rigorosa dell'alta disponibilità, che può ammettere brevi interruzioni.","optionExplanations":["Scalare automaticamente in base alla domanda è elasticità. Non garantisce che il sistema continui a funzionare quando un componente si guasta.","Corretto — Un sistema tollerante ai guasti continua a funzionare senza downtime anche quando si guastano dei server o una Availability Zone.","Distribuire rapidamente in tutto il mondo è il vantaggio «diventare globali in pochi minuti». Riguarda la copertura, non la sopravvivenza ai guasti dei componenti.","Pagare solo per ciò che si usa è il modello di prezzo pay-as-you-go. Non dice nulla sulla sopravvivenza ai guasti."]},
  "216": {"h":"4f83deed","question":"Quale concetto AWS si riferisce alla conservazione a lungo termine dei dati archiviati in servizi come Amazon S3, espressa come probabilità che i dati non vadano persi?","options":["Disponibilità","Elasticità","Durabilità","Resilienza"],"explanation":"La durabilità è la probabilità che i dati restino integri per un lungo periodo. Amazon S3 Standard è progettato per una durabilità del 99,999999999% (11 nove), archiviando i dati in modo ridondante su più dispositivi in più strutture.","optionExplanations":["La disponibilità è la probabilità di poter accedere ai dati quando servono: riguarda l'uptime dell'accesso, non la permanenza dei dati stessi.","L'elasticità è la capacità di aumentare e ridurre automaticamente la capacità: riguarda l'adeguamento delle risorse, non la persistenza o l'integrità dei dati.","Corretto — La durabilità è la probabilità che i dati archiviati non vengano persi o corrotti nel tempo. S3 Standard offre una durabilità del 99,999999999% (11 nove).","La resilienza descrive la capacità di un sistema di riprendersi dai guasti: è un concetto più ampio rispetto alla specifica metrica probabilistica di integrità dei dati espressa dalla durabilità."]},
  "217": {"h":"f541094a","question":"Una startup sta valutando se costruire un proprio data center o usare AWS. Vuole evitare un grande acquisto iniziale di hardware e prevede di servire clienti in Europa e Asia entro pochi mesi dal lancio. Quali vantaggi di AWS rispondono a queste esigenze? (Seleziona DUE)","options":["Sostituire le spese in conto capitale con spese variabili","Pieno controllo sull'hardware fisico","Possibilità di diventare globali in pochi minuti","Nessuna responsabilità di sicurezza per il cliente"],"explanation":"Due vantaggi di AWS corrispondono alle esigenze della startup: sostituire le spese in conto capitale con spese variabili elimina il grande acquisto iniziale di hardware, e diventare globali in pochi minuti le consente di distribuire rapidamente nelle Region AWS vicine ai clienti in Europa e Asia.","optionExplanations":["Corretto — Con AWS la startup paga solo per ciò che usa invece di effettuare un grande investimento iniziale in hardware.","AWS gestisce l'hardware fisico; i clienti non ne hanno il controllo fisico. Questa è una caratteristica di un data center on-premises, non un vantaggio di AWS.","Corretto — La startup può distribuire la propria applicazione nelle Region AWS in Europa e Asia in pochi minuti invece di costruirvi data center.","Secondo il modello di responsabilità condivisa, il cliente resta sempre responsabile della sicurezza nel cloud, ad esempio dei propri dati e della gestione degli accessi."]},
  "218": {"h":"df3cf6be","question":"Quale modello di cloud computing consente agli sviluppatori di concentrarsi solo sulla scrittura del codice, senza gestire server, sistema operativo o ambienti di runtime?","options":["Infrastructure as a Service (IaaS)","Platform as a Service (PaaS)","Software as a Service (SaaS)","Serverless / FaaS"],"explanation":"Il serverless / Function as a Service (FaaS), di cui AWS Lambda è un esempio, astrae tutta l'infrastruttura. Gli sviluppatori scrivono solo il codice; AWS gestisce automaticamente provisioning, scalabilità, patch e disponibilità.","optionExplanations":["IaaS (ad es. EC2) richiede che il cliente gestisca sistema operativo, runtime, middleware e applicazione: lo sviluppatore gestisce comunque server e infrastruttura.","PaaS (ad es. Elastic Beanstalk) gestisce l'infrastruttura dei server, ma gli sviluppatori distribuiscono e gestiscono comunque l'intero codice applicativo, non solo singole funzioni.","Il SaaS fornisce un'applicazione completa e pronta all'uso: gli sviluppatori la usano come utenti finali, non scrivono codice da distribuire.","Corretto — Serverless/FaaS (ad es. AWS Lambda) astrae completamente l'infrastruttura; gli sviluppatori scrivono solo funzioni e AWS gestisce provisioning, scalabilità e disponibilità."]},
  "219": {"h":"59fcfdb6","question":"Un'azienda sta valutando il Total Cost of Ownership (TCO) del passaggio ad AWS. Quale costo verrebbe ELIMINATO migrando da on-premises al cloud?","options":["Costi di licenza software per i sistemi operativi","Costi di trasferimento dati","Costi dell'hardware e delle strutture del data center","Costi di sviluppo e manutenzione delle applicazioni"],"explanation":"L'analisi del TCO mostra che il passaggio al cloud elimina i costi legati all'acquisto di server, hardware di rete, spazio nel data center, alimentazione e raffreddamento. AWS assorbe questi costi infrastrutturali e li distribuisce tra i clienti.","optionExplanations":["I costi di licenza software non vengono necessariamente eliminati migrando ad AWS: occorre comunque pagare le licenze, a meno di scegliere servizi gestiti da AWS o il BYOL.","I costi di trasferimento dati non vengono eliminati: AWS addebita il trasferimento dati in USCITA verso internet. Questi costi possono cambiare natura ma non scompaiono.","Corretto — I costi di acquisto dell'hardware (server, apparati di rete, spazio nel data center, alimentazione e raffreddamento) vengono eliminati migrando ad AWS.","I costi di sviluppo delle applicazioni non vengono eliminati migrando al cloud: servono comunque sviluppatori per creare e mantenere le applicazioni."]},
  "220": {"h":"da95f8e7","question":"Un'azienda gestisce centinaia di server nel proprio data center e vuole un business case basato sui dati per il passaggio ad AWS. Vuole che AWS raccolga i dati di utilizzo dai server esistenti e confronti i costi on-premises attuali con i costi AWS previsti, invece di inserire a mano ogni configurazione. Quale servizio AWS dovrebbe usare?","options":["AWS Pricing Calculator","AWS Cost Explorer","AWS Migration Evaluator","AWS Budgets"],"explanation":"AWS Migration Evaluator analizza l'infrastruttura on-premises effettiva di un'azienda e il suo utilizzo, e produce un business case che confronta l'attuale costo di proprietà con il costo previsto per eseguire workload equivalenti su AWS.","optionExplanations":["Pricing Calculator stima i costi AWS per le configurazioni inserite manualmente; non raccoglie dati dai server on-premises esistenti.","Cost Explorer analizza i costi e l'utilizzo AWS già sostenuti, quindi non può valutare workload che sono ancora on-premises.","Corretto — Migration Evaluator raccoglie dati sui server on-premises esistenti e costruisce un confronto dei costi per la migrazione ad AWS.","Budgets imposta soglie di costo e utilizzo per la spesa AWS e invia avvisi; non confronta i costi on-premises con quelli AWS."]},
  "221": {"h":"b388351c","question":"Quale delle seguenti affermazioni descrive MEGLIO una Region AWS?","options":["Un singolo data center gestito da AWS","Un'area geografica che contiene più Availability Zone","Un insieme di edge location usate per la distribuzione dei contenuti","Una connessione di rete dedicata tra on-premises e AWS"],"explanation":"Una Region AWS è un'area geografica che contiene due o più Availability Zone isolate. Ogni AZ è composta da uno o più data center. Le Region sono separate tra loro per garantire l'isolamento dei guasti e confini di compliance.","optionExplanations":["Un singolo data center descrive una Availability Zone (o parte di essa): una Region è composta da due o più AZ fisicamente separate.","Corretto — Una Region AWS è un'area geografica che contiene due o più Availability Zone isolate, ciascuna composta da uno o più data center.","Le edge location sono endpoint CDN/DNS per CloudFront e Route 53: non fanno parte della gerarchia infrastrutturale Region/AZ.","Una connessione di rete dedicata tra on-premises e AWS descrive AWS Direct Connect, non la definizione di una Region AWS."]},
  "222": {"h":"5be177ed","question":"Che cos'è una Availability Zone AWS?","options":["Una edge location di una rete globale di distribuzione dei contenuti (CDN)","Uno o più data center distinti all'interno di una Region","Un account di fatturazione separato per team diversi","Una connessione di rete privata virtuale"],"explanation":"Una Availability Zone (AZ) è costituita da uno o più data center fisici all'interno di una Region AWS, con alimentazione, raffreddamento e rete indipendenti. Le AZ di una Region sono collegate da link a bassa latenza, il che consente architetture ad alta disponibilità.","optionExplanations":["Una località di una rete globale di distribuzione dei contenuti descrive una Edge Location: è usata per il caching CDN e il DNS, non come data center di calcolo principale.","Corretto — Una AZ è costituita da uno o più data center fisici all'interno di una Region, con alimentazione, raffreddamento e rete indipendenti, collegata alle altre AZ tramite link a bassa latenza.","Un account di fatturazione separato descrive la struttura degli account AWS: le Availability Zone sono infrastruttura fisica, non entità di fatturazione.","Una connessione di rete privata virtuale descrive AWS VPN o Direct Connect, non un componente fisico dell'infrastruttura dei data center."]},
  "223": {"h":"f3c5f205","question":"Il piano di disaster recovery di un'azienda stabilisce che, dopo un disservizio, non possono andare persi più di 15 minuti di dati transazionali. Quale termine descrive questo requisito?","options":["Recovery Time Objective (RTO)","Recovery Point Objective (RPO)","Mean Time Between Failures (MTBF)","Service Level Agreement (SLA)"],"explanation":"Il Recovery Point Objective (RPO) è la quantità massima accettabile di perdita di dati, misurata come tempo tra l'ultimo punto di ripristino e il disservizio. Un RPO di 15 minuti significa che backup o replica devono acquisire i dati almeno ogni 15 minuti. L'RTO, invece, misura la rapidità con cui il servizio deve essere ripristinato.","optionExplanations":["L'RTO è il tempo massimo accettabile per ripristinare il servizio dopo un disservizio. Descrive il downtime, non quanti dati possono andare persi.","Corretto — L'RPO definisce la perdita massima accettabile di dati misurata in tempo, quindi un limite di 15 minuti di dati persi è un requisito di RPO.","L'MTBF è una metrica di affidabilità relativa al tempo medio tra i guasti dei componenti. Non definisce quanti dati possono andare persi in un disastro.","Uno SLA è un impegno tra provider e cliente sulla disponibilità o sulle prestazioni del servizio, non un obiettivo di ripristino per la perdita di dati."]},
  "224": {"h":"b6a34971","question":"Un'azienda deve eseguire un workload con requisiti di latenza estremamente bassa in una specifica città in cui non è presente una Region AWS. Quale opzione dell'infrastruttura AWS dovrebbe prendere in considerazione?","options":["AWS Outposts","AWS Local Zones","AWS Wavelength","AWS Edge Locations"],"explanation":"Le AWS Local Zones portano servizi di calcolo, storage e database più vicino ai grandi centri abitati in cui non esiste una Region AWS completa. Sono estensioni di una Region, ideali per workload sensibili alla latenza come il rendering multimediale o il gaming in tempo reale.","optionExplanations":["AWS Outposts porta l'hardware AWS nel data center on-premises del cliente: non viene collocato da AWS nelle aree metropolitane per servire la popolazione di una città.","Corretto — Le AWS Local Zones sono estensioni dell'infrastruttura di proprietà AWS collocate nelle grandi città, che offrono un sottoinsieme di servizi AWS con latenza di pochi millisecondi verso gli utenti locali.","AWS Wavelength è integrato nelle reti di telecomunicazione 5G per il mobile edge computing: è pensato per la latenza dei dispositivi mobili, non per workload di area metropolitana.","Le AWS Edge Locations servono il caching CDN di CloudFront e il DNS di Route 53: non eseguono workload di calcolo generici per applicazioni sensibili alla latenza."]},
  "225": {"h":"210b25f7","question":"Una banca deve mantenere i dati dei clienti nel proprio data center a causa di un requisito normativo. Vuole comunque eseguire Amazon EC2 e Amazon EBS localmente, gestiti da AWS e usando le stesse API, la stessa console e gli stessi strumenti che usa nel Cloud AWS. Quale servizio AWS dovrebbe usare la banca?","options":["AWS Direct Connect","AWS Local Zones","AWS Outposts","AWS Snowball"],"explanation":"AWS Outposts fornisce infrastruttura gestita da AWS installata nel data center del cliente. La banca può eseguire servizi AWS come EC2 ed EBS on-premises, mantenere i dati nella propria struttura e usare le stesse API e gli stessi strumenti del cloud.","optionExplanations":["Direct Connect è una connessione di rete privata tra un data center e AWS. Non esegue servizi AWS all'interno della struttura della banca, quindi i dati verrebbero comunque archiviati in AWS.","Le Local Zones sono siti di proprietà AWS vicini alle grandi città. I dati si troverebbero in una struttura AWS, non nel data center della banca.","Corretto — Outposts colloca infrastruttura e servizi AWS all'interno del data center della banca, così i dati restano on-premises.","I dispositivi Snowball servono principalmente a trasferire dati verso AWS o all'elaborazione edge in località non connesse. Non sono un'estensione permanente dell'infrastruttura AWS in un data center."]},
  "226": {"h":"dc725ce9","question":"Quale principio di progettazione AWS raccomanda di costruire sistemi in cui i singoli componenti non dipendono direttamente l'uno dall'altro, ma comunicano tramite code o API?","options":["Progettare per il guasto","Implementare l'elasticità","Disaccoppiare i componenti","Pensare in parallelo"],"explanation":"Disaccoppiare significa che i componenti interagiscono tramite interfacce a basso accoppiamento (code, API, event bus) invece che con chiamate dirette. Se un componente si guasta o scala, i guasti non si propagano a cascata agli altri. SQS è uno strumento comune per il disaccoppiamento nelle architetture AWS.","optionExplanations":["«Progettare per il guasto» significa presumere che i componenti si guasteranno e costruire ridondanza per gestire tali guasti: riguarda la resilienza, non specificamente la riduzione delle dipendenze dirette.","«Implementare l'elasticità» significa scalare automaticamente la capacità in base alla domanda: riguarda l'adeguamento delle risorse, non la riduzione delle dipendenze tra componenti.","Corretto — «Disaccoppiare i componenti» significa usare code (SQS) o API tra i componenti, così che non dipendano direttamente l'uno dall'altro, riducendo i guasti a cascata.","«Pensare in parallelo» significa eseguire attività in modo concorrente per migliorare il throughput: riguarda l'ottimizzazione delle prestazioni, non la riduzione delle dipendenze tra componenti."]},
  "227": {"h":"dbc89056","question":"Un'azienda fintech sta valutando il proprio nuovo workload di pagamenti rispetto all'AWS Well-Architected Framework. Vuole indicazioni sulla gestione di identità e autorizzazioni, sulla protezione dei dati at rest e in transit e sul rilevamento e la risposta agli incidenti di sicurezza. Quale pilastro dovrebbe consultare l'azienda?","options":["Reliability","Operational Excellence","Security","Performance Efficiency"],"explanation":"Il pilastro Security riguarda la protezione di dati, sistemi e asset. Copre la gestione delle identità e degli accessi, i controlli di rilevamento, la protezione dell'infrastruttura, la protezione dei dati e la risposta agli incidenti: gli ambiti su cui l'azienda fintech vuole indicazioni.","optionExplanations":["Reliability riguarda il ripristino dopo i guasti e la capacità di soddisfare la domanda, non le identità, la protezione dei dati e la risposta agli incidenti di sicurezza.","Operational Excellence riguarda in generale la gestione e il miglioramento delle operazioni. La gestione delle identità e la protezione dei dati rientrano in un altro pilastro.","Corretto — Il pilastro Security copre la gestione delle identità e degli accessi, la protezione dei dati at rest e in transit e il rilevamento e la risposta agli incidenti di sicurezza.","Performance Efficiency riguarda l'uso efficiente delle risorse di calcolo, non la protezione dei dati e la gestione delle identità."]},
  "228": {"h":"4d72fc99","question":"Quale pilastro dell'AWS Well-Architected Framework si concentra sull'uso efficiente delle risorse di calcolo per soddisfare i requisiti del sistema e sul mantenimento dell'efficienza al variare della domanda?","options":["Cost Optimization","Reliability","Performance Efficiency","Sustainability"],"explanation":"Performance Efficiency si concentra sulla scelta dei tipi e delle dimensioni di risorse adeguati, sul monitoraggio delle prestazioni e su decisioni basate sui dati per mantenere l'efficienza. Ciò include l'uso di architetture serverless e la scelta del tipo di database giusto per ogni workload.","optionExplanations":["Cost Optimization si concentra sull'evitare spese inutili: pur essendo legato all'efficienza, il suo obiettivo è ridurre i costi, non mantenere le prestazioni al variare della domanda.","Reliability si concentra sul ripristino dopo i guasti e sul rispetto degli obiettivi di disponibilità, non sulla scelta dei tipi di risorse adeguati per l'efficienza delle prestazioni.","Corretto — Performance Efficiency si concentra sull'uso dei tipi e delle dimensioni di risorse adeguati per soddisfare in modo efficiente i requisiti del sistema, inclusa l'adozione di serverless e di database specifici per ogni scopo.","Sustainability si concentra sulla riduzione dell'impatto ambientale, non sul mantenimento dell'efficienza delle prestazioni al variare della domanda."]},
  "229": {"h":"2579ee9b","question":"Un'azienda globale di pagamenti richiede downtime e perdita di dati quasi nulli in caso di guasto di un'intera Region AWS, e accetta il costo più alto per ottenerlo. Quale strategia di disaster recovery dovrebbe scegliere?","options":["Backup and restore da snapshot","Pilot light in una seconda Region","Warm standby in una seconda Region","Multi-site active/active"],"explanation":"Il multi-site active/active esegue l'intero workload in due o più Region contemporaneamente, con tutte che servono traffico. Se una Region si guasta, le altre proseguono immediatamente, garantendo l'RTO e l'RPO più bassi tra tutte le strategie, ma anche il costo più alto.","optionExplanations":["Il backup and restore è la strategia meno costosa, ma il ripristino di infrastruttura e dati richiede più tempo di tutte, quindi non può garantire un downtime quasi nullo.","Il pilot light mantiene in esecuzione solo i componenti principali, quindi i server applicativi devono essere avviati e scalati prima che il ripristino sia completo. Ciò causa più downtime di quanto consentito dal requisito.","Il warm standby riduce il tempo di ripristino, ma la copia ridotta deve comunque essere scalata e il traffico spostato, quindi non raggiunge un downtime quasi nullo.","Corretto — Il multi-site active/active serve traffico da più Region contemporaneamente, quindi un guasto regionale causa downtime e perdita di dati quasi nulli, al costo più alto."]},
  "230": {"h":"90d86c74","question":"Un'azienda sta scomponendo una grande applicazione monolitica in microservizi su AWS. Quali delle seguenti sono caratteristiche di un'architettura a microservizi? (Seleziona DUE)","options":["Ogni servizio può essere distribuito indipendentemente dagli altri","Tutti i servizi condividono un'unica codebase e vengono rilasciati insieme","Ogni servizio può essere scalato indipendentemente in base alla propria domanda","Tutti i servizi devono essere scritti nello stesso linguaggio di programmazione","Un guasto in un qualsiasi servizio blocca sempre l'intera applicazione"],"explanation":"In un'architettura a microservizi, un'applicazione è composta da servizi piccoli e a basso accoppiamento che comunicano tramite API ben definite. Ogni servizio può essere sviluppato, distribuito e scalato in modo indipendente, il che accelera i rilasci e limita l'impatto dei guasti.","optionExplanations":["Corretto — Il deployment indipendente è una caratteristica fondamentale dei microservizi; un team può rilasciare il proprio servizio senza ridistribuire il resto dell'applicazione.","Un'unica codebase condivisa e rilasciata tutta insieme descrive un'applicazione monolitica, che è proprio ciò da cui l'azienda si sta allontanando.","Corretto — Ogni microservizio può scalare autonomamente in base alla propria domanda, invece di scalare l'intera applicazione come un'unica unità.","I microservizi comunicano tramite API, quindi ogni servizio può usare il linguaggio e la tecnologia più adatti al proprio compito.","Il basso accoppiamento tra microservizi serve a isolare i guasti, quindi un problema in un servizio non dovrebbe bloccare l'intera applicazione."]},
  "231": {"h":"de1544fc","question":"Il fondatore di una startup nota che AWS ha ridotto i prezzi molte volte e che la startup paga molto meno per unità di calcolo di quanto pagherebbe acquistando server propri. Quale affermazione spiega MEGLIO questo vantaggio?","options":["Gli utenti possono aumentare e ridurre l'infrastruttura in base alle esigenze, in pochi minuti","AWS trasferisce i risparmi dell'enorme utilizzo aggregato sotto forma di prezzi più bassi","Le aziende possono distribuire applicazioni in molte Region in tutto il mondo","Le organizzazioni smettono di pagare per capacità che resta inutilizzata"],"explanation":"Questo è il vantaggio delle enormi economie di scala. Poiché AWS aggrega l'utilizzo di un numero molto elevato di clienti, ottiene efficienze di acquisto e operative che si traducono in prezzi pay-as-you-go più bassi: costi unitari che una singola startup non potrebbe ottenere da sola.","optionExplanations":["Scalare rapidamente in aumento e in diminuzione descrive l'elasticità, che non spiega perché il prezzo unitario in sé sia più basso.","Corretto — L'enorme utilizzo aggregato di AWS genera economie di scala, e questi risparmi vengono trasferiti sotto forma di prezzi più bassi.","Distribuire in molte Region descrive il diventare globali in pochi minuti, che non ha relazione con prezzi unitari più bassi.","Non pagare per capacità inutilizzata deriva dal pagare solo ciò che si usa; non spiega perché AWS possa ridurre ripetutamente i prezzi."]},
  "232": {"h":"5e523a88","question":"Il sito web di un'azienda registra picchi di traffico imprevedibili. Invece di effettuare il provisioning dei server per il carico di picco, l'azienda vuole pagare solo l'utilizzo effettivo. Quale concetto cloud descrive MEGLIO questo approccio?","options":["Alta disponibilità","Elasticità","Durabilità","Multi-tenancy"],"explanation":"L'elasticità consente al sistema di aggiungere automaticamente capacità durante i picchi e di rimuoverla quando la domanda cala, pagando solo ciò che viene effettivamente usato. Questo elimina la necessità di sovradimensionare per la domanda di picco.","optionExplanations":["L'alta disponibilità garantisce che il sistema resti accessibile con downtime minimo: riguarda uptime e ridondanza, non l'adeguamento automatico della capacità ai picchi di traffico.","Corretto — L'elasticità aggiunge automaticamente capacità durante i picchi di traffico e la rimuove quando la domanda cala, così si paga solo l'utilizzo effettivo e non si sovradimensiona mai.","La durabilità si riferisce all'integrità a lungo termine dei dati archiviati (che non vengano persi): riguarda la persistenza dei dati, non l'adeguamento della capacità ai picchi di traffico.","Multi-tenancy significa che più clienti condividono l'hardware sottostante: è una caratteristica del modello di cloud computing, non un concetto di progettazione per gestire i picchi di traffico."]},
  "233": {"h":"9827c1f2","question":"Un'azienda che sta iniziando l'adozione del cloud vuole assicurarsi che i propri dati e workload cloud soddisfino obiettivi di riservatezza, integrità e disponibilità, con capacità come gestione delle identità, rilevamento delle minacce e risposta agli incidenti. Quale prospettiva dell'AWS Cloud Adoption Framework (AWS CAF) si concentra su queste capacità?","options":["Security","Operations","Governance","Platform"],"explanation":"La prospettiva Security dell'AWS CAF aiuta le organizzazioni a garantire riservatezza, integrità e disponibilità dei propri dati e workload cloud. Le sue capacità includono gestione delle identità e degli accessi, rilevamento delle minacce, protezione dell'infrastruttura, protezione dei dati e risposta agli incidenti.","optionExplanations":["Corretto — La prospettiva Security si concentra su riservatezza, integrità e disponibilità, con capacità come gestione delle identità, rilevamento delle minacce e risposta agli incidenti.","La prospettiva Operations si concentra sull'erogazione dei servizi cloud ai livelli di servizio concordati, inclusi osservabilità, gestione degli eventi e processi di gestione di incidenti e problemi.","La prospettiva Governance si concentra sull'orchestrazione delle iniziative cloud, sulla gestione di benefici e rischi e sul controllo della spesa cloud e del portafoglio applicativo.","La prospettiva Platform si concentra sulla costruzione di una piattaforma di cloud ibrido scalabile di livello enterprise e sulla modernizzazione dei workload, non sulle capacità di sicurezza."]},
  "234": {"h":"8c7519c9","question":"Per un servizio gestito come Amazon RDS, quale attività svolge AWS che il cliente dovrebbe invece svolgere con un database autogestito su EC2?","options":["Creare gli schemi del database","Gestire le credenziali degli utenti del database","Applicare le patch al software del motore di database","Scrivere le query SQL"],"explanation":"Con Amazon RDS (un servizio gestito), AWS si occupa delle patch del motore di database, dei backup, del provisioning dell'hardware e della manutenzione del sistema operativo. Il cliente resta responsabile della progettazione degli schemi, delle autorizzazioni degli utenti e del tuning delle query, ma non delle patch del motore sottostante.","optionExplanations":["Creare gli schemi del database è sempre responsabilità del cliente: è una decisione di progettazione che AWS non gestisce mai, sia con RDS sia con un database autogestito.","Gestire le credenziali degli utenti del database è responsabilità del cliente: anche con RDS, è il cliente a controllare chi ha accesso al proprio database.","Corretto — In RDS le patch del software del motore di database sono gestite da AWS (il «gestito» di servizio gestito). Con un database autogestito su EC2, il cliente deve applicarle manualmente.","Scrivere le query SQL è sempre responsabilità del cliente: è logica applicativa che AWS non gestisce mai."]},
  "235": {"h":"a2e00504","question":"Quale modello di deployment cloud è il MIGLIORE per un'azienda che ha bisogno del pieno controllo sulla propria infrastruttura ma vuole la flessibilità di espandersi su AWS nei periodi di alta domanda?","options":["Solo cloud pubblico","Solo cloud privato","Cloud ibrido","Cloud di comunità"],"explanation":"Il cloud ibrido combina un'infrastruttura on-premises (privata) con il cloud pubblico. Questo modello offre alle aziende pieno controllo e residenza dei dati per i workload sensibili, consentendo al contempo di espandersi su AWS quando la domanda supera la capacità on-premises.","optionExplanations":["Il solo cloud pubblico sposterebbe tutti i workload su AWS: non garantisce il pieno controllo sui workload sensibili né consente di mantenerli on-premises.","Il solo cloud privato mantiene tutto on-premises: non consente di espandersi su AWS durante i picchi di domanda.","Corretto — Il cloud ibrido combina il controllo on-premises per i workload sensibili con la possibilità di espandersi su AWS per ottenere capacità aggiuntiva nei periodi di alta domanda.","Il cloud di comunità è condiviso tra organizzazioni con esigenze comuni: non descrive la combinazione di infrastruttura on-premises e cloud pubblico per la capacità nei picchi."]},
  "236": {"h":"0652b297","question":"Quale delle seguenti azioni aiuta un'azienda a «smettere di stimare la capacità» quando migra ad AWS?","options":["Acquistare Reserved Instances triennali dimensionate per il picco di carico previsto","Usare Auto Scaling per adeguare la capacità alla domanda effettiva","Distribuire le risorse in più Region","Usare AWS Direct Connect per una connettività privata verso AWS"],"explanation":"Auto Scaling elimina la necessità di stimare la capacità di picco. Le risorse aumentano quando la domanda cresce e diminuiscono quando cala, garantendo in ogni momento la capacità giusta senza sovradimensionamento né sottodimensionamento.","optionExplanations":["Acquistare Reserved Instances triennali dimensionate per il picco previsto vincola a una capacità fissa: implica comunque stimare la domanda futura e non si adegua dinamicamente all'utilizzo effettivo.","Corretto — Con Auto Scaling le risorse aumentano automaticamente quando la domanda cresce e diminuiscono quando cala, eliminando la necessità di stimare manualmente e predisporre la capacità di picco.","Distribuire le risorse in più Region migliora la disponibilità globale, ma non elimina la necessità di predisporre la capacità corretta in ogni Region.","Usare AWS Direct Connect migliora le prestazioni della connettività di rete: non aiuta ad adeguare la capacità alla domanda effettiva."]},
  "237": {"h":"737d99cd","question":"Qual è il principale vantaggio del modello di prezzo pay-as-you-go di AWS rispetto alla tradizionale infrastruttura on-premises?","options":["Garantisce un costo mensile fisso e prevedibile","Sostituisce il CapEx iniziale con un OpEx variabile e continuativo","Elimina tutti i costi infrastrutturali per il cliente","Offre accesso gratuito e illimitato nel tempo a ogni servizio AWS"],"explanation":"Il pay-as-you-go converte il CapEx (acquisto di server) in OpEx (pagamento in base all'utilizzo). Questo migliora il flusso di cassa, elimina il rischio finanziario di acquistare troppo e allinea i costi al valore di business effettivamente generato.","optionExplanations":["Il pay-as-you-go non garantisce un costo mensile fisso: la fattura varia in base all'utilizzo, l'opposto di un costo fisso.","Corretto — Il pay-as-you-go converte un grande CapEx iniziale (acquisto di server) in un OpEx continuativo più contenuto (pagamento per ciò che si usa), migliorando il flusso di cassa e riducendo il rischio finanziario.","Il pay-as-you-go non elimina tutti i costi infrastrutturali: si paga comunque per le risorse consumate; cambia solo la struttura dei costi (variabili anziché fissi).","Il pay-as-you-go addebita ciò che si usa. L'utilizzo gratuito deriva solo dalle offerte AWS Free Tier, un programma separato con i propri limiti."]},
  "238": {"h":"93e5b5df","question":"Prima di lanciare un nuovo workload, gli architetti di un'azienda vogliono rispondere a una serie strutturata di domande su di esso, confrontarlo con le best practice AWS nei sei pilastri e ottenere un elenco di problemi ad alto rischio con un piano di miglioramento. Vogliono anche registrare delle milestone man mano che risolvono i problemi. Quale servizio AWS dovrebbero usare?","options":["AWS Trusted Advisor","AWS Well-Architected Tool","AWS Config","AWS Service Catalog"],"explanation":"L'AWS Well-Architected Tool consente ai team di valutare un workload rispetto ai pilastri del Well-Architected Framework rispondendo a delle domande. Identifica i problemi ad alto rischio, fornisce indicazioni di miglioramento e tiene traccia dei progressi tramite milestone.","optionExplanations":["Trusted Advisor esegue controlli automatici sulle risorse dell'account. Non effettua una revisione architetturale di un workload basata su domande rispetto ai pilastri del framework.","Corretto — Il Well-Architected Tool valuta un workload rispetto ai sei pilastri, elenca i problemi ad alto rischio e tiene traccia dei miglioramenti con le milestone.","AWS Config registra le configurazioni delle risorse e le valuta rispetto a delle regole. Non valuta un'architettura rispetto ai pilastri Well-Architected.","Service Catalog consente alle organizzazioni di offrire prodotti pre-approvati che i team possono distribuire. Non valuta l'architettura di un workload."]},
  "239": {"h":"99a327e0","question":"Quale affermazione descrive MEGLIO come è organizzata l'infrastruttura globale AWS?","options":["Ogni Region contiene più Availability Zone isolate","Ogni Availability Zone contiene più Region AWS","Le edge location sono i data center all'interno di ogni Region","Ogni Region è un unico grande data center in una sola città"],"explanation":"Una Region AWS è un'area geografica che contiene più Availability Zone fisicamente separate e isolate, ciascuna composta da uno o più data center. Le edge location sono una rete separata di siti usata da servizi come CloudFront e Route 53 per distribuire contenuti vicino agli utenti.","optionExplanations":["Corretto — ogni Region è composta da più Availability Zone isolate tra loro ma collegate da link a bassa latenza.","Questa affermazione inverte la gerarchia: sono le Region a contenere le Availability Zone, non il contrario.","Le edge location sono siti separati, per lo più nelle grandi città, usati per la distribuzione dei contenuti e il DNS; non sono i data center che compongono una Region.","Una Region non è un singolo data center; contiene più Availability Zone, ciascuna con uno o più data center."]},
  "240": {"h":"bdcfcb9c","question":"Un'azienda vuole eseguire workload su AWS ma deve garantire che, per requisiti normativi, i dati non lascino mai un determinato paese. Quale caratteristica dell'infrastruttura AWS aiuta a soddisfare questo requisito?","options":["Availability Zone","AWS Regions","Edge Locations","AWS Local Zones"],"explanation":"I dati in AWS non vengono replicati automaticamente tra Region, a meno che i clienti non configurino esplicitamente la replica cross-region. Scegliendo una Region situata nel paese richiesto, i clienti possono garantire che i dati restino entro i confini di quel paese ai fini della compliance.","optionExplanations":["Le Availability Zone si trovano all'interno di una singola Region: aiutano l'alta disponibilità all'interno della Region, ma non determinano il paese in cui sono archiviati i dati.","Corretto — Selezionando una Region AWS situata nel paese richiesto, i dati non lasciano automaticamente quella Region, soddisfacendo i requisiti di residenza dei dati.","Le Edge Locations sono endpoint CDN usati per il caching: elaborano le richieste ma non sono il luogo in cui sono archiviati i dati principali, quindi non determinano la residenza dei dati.","Le AWS Local Zones sono estensioni di una Region nelle aree metropolitane: possono aiutare con la latenza, ma non riguardano specificamente la compliance sulla residenza transfrontaliera dei dati."]},
  "241": {"h":"0540c3c3","question":"Un'azienda ha un piano di disaster recovery documentato, ma non lo ha mai effettivamente provato. Un auditor avverte che il piano potrebbe non funzionare durante un disservizio reale. L'azienda decide di simulare regolarmente i guasti e di automatizzare i passaggi di ripristino per dimostrare che funzionano. Quale principio di architettura cloud sta applicando l'azienda?","options":["Implementare l'elasticità con Auto Scaling","Testare le procedure di ripristino","Disaccoppiare i componenti applicativi","Progettare per il guasto"],"explanation":"«Testare le procedure di ripristino» è un principio di progettazione del pilastro Reliability. Nel cloud è possibile simulare i guasti, eseguire regolarmente esercitazioni di ripristino e automatizzare il ripristino, così da sapere che le procedure funzionano prima che si verifichi un incidente reale: è ciò che richiede la preoccupazione dell'auditor.","optionExplanations":["L'elasticità adegua la capacità alla domanda. Non verifica se il piano di disaster recovery funziona.","Corretto — Simulare regolarmente i guasti e automatizzare il ripristino per dimostrare che il piano funziona è il principio «testare le procedure di ripristino».","Il disaccoppiamento riduce le dipendenze tra componenti. Non affronta la questione della validazione del piano di ripristino.","Progettare per il guasto significa integrare la ridondanza nell'architettura. Il problema dell'azienda è che il suo piano di ripristino esistente non è mai stato testato."]},
  "242": {"h":"c10503b8","question":"Quale modello cloud fornisce un'infrastruttura condivisa usata da diverse organizzazioni con esigenze comuni, come sicurezza, compliance o giurisdizione?","options":["Cloud pubblico","Cloud privato","Cloud ibrido","Cloud di comunità"],"explanation":"Il cloud di comunità è un modello meno diffuso in cui l'infrastruttura è condivisa tra diverse organizzazioni con esigenze comuni (ad es. enti governativi che condividono un cloud conforme a FedRAMP, o organizzazioni sanitarie che condividono un'infrastruttura HIPAA).","optionExplanations":["Il cloud pubblico è un'infrastruttura condivisa gestita da un cloud provider che serve molti clienti diversi: non serve specificamente organizzazioni con esigenze comuni di compliance o giurisdizione.","Il cloud privato è dedicato a una singola organizzazione: non descrive un modello di infrastruttura condivisa tra più organizzazioni.","Il cloud ibrido combina infrastruttura on-premises e cloud pubblico: non descrive un modello di infrastruttura condivisa per organizzazioni con esigenze comuni.","Corretto — Il cloud di comunità è un'infrastruttura condivisa tra diverse organizzazioni con esigenze comuni (sicurezza, compliance, giurisdizione), come enti governativi o organizzazioni sanitarie."]},
  "243": {"h":"a9477020","question":"Quando un web server si comporta in modo anomalo, il team operativo di un'azienda attualmente vi accede e lo corregge a mano, così le configurazioni dei server divergono gradualmente. Il team ora vuole terminare qualsiasi istanza non integra e avviarne una nuova da una AMI standard. Quale pratica sta adottando il team?","options":["Infrastruttura immutabile","Applicazione delle patch ai server in loco","Scalabilità verticale","Ripristino di istanze con stato"],"explanation":"Infrastruttura immutabile significa sostituire i componenti invece di modificarli sul posto. Avviare nuove istanze da una AMI standard (ad esempio con EC2 Auto Scaling che sostituisce le istanze non integre) mantiene tutti i server coerenti ed elimina la deriva di configurazione.","optionExplanations":["Corretto — sostituire i server non integri con nuove istanze da un'immagine standard, invece di modificarli, è infrastruttura immutabile.","Applicare le patch ai server in loco è ciò che il team fa oggi ed è la causa della deriva di configurazione che vuole eliminare.","La scalabilità verticale consiste nel cambiare la dimensione di un'istanza, rendendola più grande o più piccola; non sostituisce i server non integri.","Ripristinare un'istanza mantenendone lo stato esistente preserva la configurazione divergente, invece di ripartire da un'immagine standard e pulita."]},
  "244": {"h":"c45e0f36","question":"Quali dei seguenti sono pilastri dell'AWS Well-Architected Framework? (Seleziona DUE)","options":["Cost Optimization","Speed and Agility","Security","Global Deployment"],"explanation":"I sei pilastri sono: Operational Excellence, Security, Reliability, Performance Efficiency, Cost Optimization e Sustainability. «Speed and Agility» e «Global Deployment» sono vantaggi del cloud, non pilastri Well-Architected.","optionExplanations":["Corretto — Cost Optimization è uno dei sei pilastri dell'AWS Well-Architected Framework.","«Speed and Agility» è un vantaggio del cloud computing (uno dei sei vantaggi del cloud), non uno dei sei pilastri del Well-Architected Framework.","Corretto — Security è uno dei sei pilastri dell'AWS Well-Architected Framework.","«Global Deployment» è un vantaggio del cloud («diventare globali in pochi minuti»), non uno dei sei pilastri del Well-Architected Framework."]},
  "245": {"h":"5b4077d2","question":"AWS consente ai clienti di aumentare le risorse (come CPU e RAM) di una singola istanza per gestire un carico maggiore. Come si chiama questo tipo di scalabilità?","options":["Scalabilità orizzontale","Scalabilità verticale","Scalabilità elastica","Auto scaling"],"explanation":"La scalabilità verticale (scale up/down) consiste nell'aumentare o ridurre la dimensione di una singola risorsa (ad es. passando da t3.medium a t3.xlarge). La scalabilità orizzontale (scale out/in) aggiunge o rimuove istanze. AWS supporta entrambe, ma quella orizzontale è preferibile per la tolleranza ai guasti.","optionExplanations":["La scalabilità orizzontale (scale out) aggiunge altre istanze: non aumenta la dimensione di una singola istanza esistente.","Corretto — La scalabilità verticale (scale up/down) consiste nell'aumentare o ridurre CPU/RAM di una singola risorsa, ad esempio passando a un tipo di istanza EC2 più grande.","La scalabilità elastica descrive la capacità di scalare automaticamente in entrambe le direzioni: può riferirsi sia a quella orizzontale sia a quella verticale, non specificamente all'aumento di dimensione di una singola istanza.","L'auto scaling è il meccanismo AWS per implementare automaticamente la scalabilità orizzontale: aggiunge/rimuove istanze in base alla domanda, non ridimensiona una singola istanza."]},
  "246": {"h":"1deb65be","question":"Aggiungere altre istanze EC2 dietro un load balancer per gestire un aumento del traffico è un esempio di quale strategia di scalabilità?","options":["Scalabilità verticale","Scalabilità orizzontale","Scalabilità pianificata","Scalabilità manuale"],"explanation":"La scalabilità orizzontale (scale out) aggiunge altre istanze per distribuire il carico. Insieme a un load balancer, migliora sia la capacità sia la tolleranza ai guasti. È l'approccio cloud-native preferito perché evita i single point of failure.","optionExplanations":["La scalabilità verticale porta un singolo server a una dimensione maggiore: aggiungere altre istanze EC2 dietro un load balancer è l'opposto (aggiungere istanze, non ingrandirne una).","Corretto — Aggiungere altre istanze EC2 dietro un load balancer è scalabilità orizzontale (scale out), che distribuisce il carico su più istanze per ottenere maggiore capacità e tolleranza ai guasti.","La scalabilità pianificata adegua la capacità in orari prestabiliti: aggiungere istanze in risposta a un aumento del traffico è reattivo, non basato su una pianificazione.","La scalabilità manuale richiede che sia una persona a prendere la decisione: Auto Scaling dietro un load balancer è tipicamente automatizzato in base alle metriche CloudWatch."]},
  "247": {"h":"126414eb","question":"Quale delle seguenti affermazioni sulle Region AWS è CORRETTA?","options":["Tutti i servizi AWS sono disponibili in ogni Region","Le Region AWS sono collegate tra loro solo tramite internet pubblico","Ogni Region è isolata dalle altre Region per la tolleranza ai guasti","Una Region AWS è costituita da un unico data center"],"explanation":"Le Region AWS sono isolate geograficamente. Un guasto in una Region non si ripercuote automaticamente sulle altre. Non tutti i servizi sono disponibili in ogni Region. Le Region sono collegate tramite la rete backbone globale di AWS, non solo tramite internet pubblico. Ogni Region ha più AZ (data center).","optionExplanations":["Non tutti i servizi AWS sono disponibili in ogni Region: i nuovi servizi di solito vengono lanciati prima in alcune Region e poi si estendono nel tempo.","Le Region AWS sono collegate principalmente tramite la rete backbone globale di AWS (fibra privata), non solo tramite internet pubblico, il che offre una connettività tra Region più affidabile e veloce.","Corretto — Ogni Region AWS è isolata geograficamente dalle altre per garantire la tolleranza ai guasti; un guasto in una Region non si ripercuote automaticamente sulle altre.","Una Region AWS non è costituita da un unico data center: ogni Region contiene più Availability Zone fisicamente separate (due o più), ciascuna delle quali può avere più data center."]},
  "248": {"h":"412f79ae","question":"In un'architettura AWS a basso accoppiamento, come comunicano tipicamente i componenti per ridurre al minimo le dipendenze?","options":["I componenti comunicano direttamente tramite indirizzi IP hardcoded","I componenti interagiscono tramite code o API, non direttamente","Tutti i componenti applicativi girano insieme su un unico grande server","I database risiedono sugli stessi host dei server applicativi"],"explanation":"Basso accoppiamento significa che i componenti interagiscono tramite interfacce minime e ben definite (come code SQS o API Gateway). Questo limita il raggio d'impatto: se un componente si guasta o deve scalare, non costringe gli altri componenti a cambiare o a guastarsi.","optionExplanations":["Gli indirizzi IP hardcoded creano un accoppiamento stretto: se l'IP cambia, tutti i componenti che vi fanno riferimento devono essere aggiornati, creando dipendenze fragili.","Corretto — Basso accoppiamento significa che i componenti comunicano tramite code (SQS) o API, riducendo al minimo le dipendenze dirette, così che il guasto o la scalabilità di un componente non influiscano sugli altri.","Eseguire tutti i componenti su un unico grande server crea un accoppiamento stretto e un single point of failure: l'opposto di un'architettura a basso accoppiamento.","Collocare i database sugli stessi host dei server applicativi crea un accoppiamento stretto: database e applicazione condividono la stessa sorte e non possono scalare o guastarsi in modo indipendente."]},
  "249": {"h":"a0874953","question":"Un'azienda sta spostando applicazioni basate su Windows su Amazon EC2. Le applicazioni richiedono Microsoft Active Directory per l'aggiunta al dominio, i Group Policy e l'autenticazione Kerberos, e l'azienda non vuole installare e mantenere i propri domain controller. Quale servizio AWS dovrebbe usare l'azienda?","options":["AWS Identity and Access Management (IAM)","AWS Directory Service","Amazon Cognito user pools","AWS IAM Identity Center"],"explanation":"AWS Directory Service for Microsoft Active Directory (AWS Managed Microsoft AD) fornisce un Active Directory completamente gestito su AWS. Le istanze EC2 possono essere aggiunte al dominio e usare Group Policy e Kerberos, mentre AWS gestisce i domain controller.","optionExplanations":["IAM controlla l'accesso alle risorse e alle API AWS. Non è un Active Directory e non può fornire aggiunta al dominio, Group Policy o Kerberos per le applicazioni Windows.","Corretto — AWS Managed Microsoft AD fornisce alle applicazioni un vero Active Directory per aggiunta al dominio, Group Policy e Kerberos, senza che l'azienda debba gestire domain controller.","Gli Amazon Cognito user pools gestiscono l'accesso dei clienti di app web e mobile. Non forniscono funzionalità di Active Directory per i server Windows.","IAM Identity Center fornisce il single sign-on agli account e alle applicazioni AWS, ma non è una directory a cui i server Windows possano essere aggiunti per Group Policy e Kerberos."]},
  "250": {"h":"7243834b","question":"Quale entità IAM dovrebbe usare un'applicazione in esecuzione su un'istanza EC2 che deve accedere ad Amazon S3 senza incorporare credenziali nel codice?","options":["Utente IAM con access key memorizzate nell'applicazione","Gruppo IAM assegnato all'istanza","Ruolo IAM assegnato all'istanza EC2","Credenziali dell'account root"],"explanation":"I ruoli IAM forniscono credenziali temporanee ruotate automaticamente da AWS. Assegnare un ruolo a un'istanza EC2 tramite un instance profile è il modo sicuro e raccomandato per concedere autorizzazioni AWS alle applicazioni, senza credenziali a lungo termine memorizzate nel codice.","optionExplanations":["Memorizzare le access key nell'applicazione crea credenziali statiche a lungo termine che possono essere estratte se il codice o l'istanza vengono compromessi: è proprio la pratica che i ruoli IAM sono pensati per sostituire.","I gruppi IAM servono a organizzare gli utenti IAM e applicare policy comuni: non possono essere assegnati alle istanze EC2 né fornire credenziali AWS all'istanza.","Corretto — Un ruolo IAM assegnato a un'istanza EC2 tramite un instance profile fornisce credenziali temporanee tramite il servizio di metadati, senza credenziali a lungo termine memorizzate nel codice.","Usare le credenziali dell'account root su un'istanza EC2 è un rischio di sicurezza estremo: root ha accesso illimitato e le sue credenziali non dovrebbero mai essere memorizzate su istanze o in applicazioni."]},
  "251": {"h":"d2485107","question":"Qual è lo scopo di una IAM policy?","options":["Definire il budget di fatturazione di un account AWS","Consentire o negare azioni sulle risorse AWS","Creare reti virtuali in AWS","Monitorare le chiamate API effettuate in un account AWS"],"explanation":"Le IAM policy sono documenti JSON che definiscono i permessi: quali azioni (ad es. s3:GetObject) sono consentite o negate, su quali risorse e a quali condizioni. Le policy vengono associate a utenti, gruppi o ruoli.","optionExplanations":["I budget di fatturazione si gestiscono con AWS Budgets — le IAM policy controllano i permessi di accesso alle API, non i limiti di spesa.","Corretto — le IAM policy specificano quali azioni AWS sono consentite o negate, su quali risorse e a quali condizioni, e costituiscono il meccanismo centrale di controllo dei permessi in AWS.","Le reti virtuali si creano con Amazon VPC — le IAM policy controllano chi può chiamare quali API, non la creazione dell'infrastruttura di rete.","Il monitoraggio delle chiamate API è compito di AWS CloudTrail — le IAM policy controllano quali azioni sono consentite, non ciò che viene osservato o registrato."]},
  "252": {"h":"186de0aa","question":"Uno sviluppatore deve eseguire comandi AWS CLI dal proprio portatile usando un utente IAM. Quali credenziali usa l'AWS CLI per firmare queste richieste programmatiche?","options":["La password della console e il codice MFA dell'utente IAM","Un access key ID e una secret access key","Una key pair di Amazon EC2 (chiave pubblica e privata)","L'ID dell'account AWS e l'indirizzo email del root user"],"explanation":"L'accesso programmatico tramite AWS CLI, SDK o API viene firmato con una access key, composta da un access key ID e da una secret access key. Queste chiavi vanno protette e ruotate, e AWS raccomanda di usare, quando possibile, credenziali temporanee come gli IAM role o IAM Identity Center.","optionExplanations":["Password e codice MFA servono ad accedere alla AWS Management Console, non a firmare le richieste dell'AWS CLI o delle API.","Corretto — l'AWS CLI firma le richieste programmatiche con una access key composta da un access key ID e da una secret access key.","Una key pair EC2 serve ad accedere alle istanze EC2 via SSH o a decifrare le password Windows. Non può autenticare le chiamate alle API AWS.","L'ID dell'account e l'email del root identificano l'account ma non sono credenziali per firmare le richieste API; inoltre il root user non va usato per il lavoro quotidiano."]},
  "253": {"h":"2d8379c9","question":"Il team di sicurezza di un'azienda propone di associare delle service control policy (SCP) alle unità organizzative in AWS Organizations, in modo che gli account di sviluppo non possano mai usare servizi non approvati dall'azienda. Un manager chiede che cosa faccia esattamente una SCP. Quale risposta è corretta?","options":["Concede permessi agli utenti IAM all'interno di un account","Stabilisce i permessi massimi per gli account dell'organizzazione","È una policy di fatturazione che limita la spesa mensile di ogni account","È una policy di rete che controlla il traffico in una VPC"],"explanation":"Le SCP definiscono i permessi massimi disponibili per gli account di un'organizzazione o di un'unità organizzativa. Non concedono permessi di per sé: agiscono come guardrail, per cui anche se una IAM policy in un account membro consente un'azione, la SCP può bloccarla.","optionExplanations":["Le SCP non concedono mai permessi. I permessi li concedono le IAM policy; le SCP limitano soltanto ciò che può essere consentito.","Corretto — una SCP stabilisce i permessi massimi per gli account a cui si applica, agendo da guardrail per tutta l'organizzazione.","Le SCP controllano i permessi, non la spesa. Limiti di spesa e avvisi si gestiscono con strumenti come AWS Budgets.","Le SCP non filtrano il traffico di rete. Il traffico di una VPC si controlla con security group e network ACL."]},
  "254": {"h":"8143464a","question":"Quale servizio AWS registra le chiamate API effettuate nell'account AWS, fornendo uno storico a fini di governance, conformità e audit?","options":["Amazon CloudWatch","AWS CloudTrail","AWS Config","Amazon GuardDuty"],"explanation":"AWS CloudTrail registra tutte le chiamate API ai servizi AWS (chi ha fatto cosa, quando e da dove). Questi log possono essere archiviati in S3 e analizzati per audit di sicurezza, requisiti di conformità e troubleshooting.","optionExplanations":["Amazon CloudWatch monitora metriche di prestazione e log — non registra lo storico delle chiamate API né traccia chi ha chiamato quale API di un servizio AWS.","Corretto — AWS CloudTrail registra tutte le chiamate API con identità del chiamante, timestamp, IP di origine e parametri, archiviandole in S3 per governance, conformità e audit.","AWS Config registra le modifiche alla configurazione delle risorse — traccia come appaiono le risorse nel tempo, non l'identità di chi ha effettuato ogni chiamata API.","Amazon GuardDuty analizza i log (compresi quelli di CloudTrail) alla ricerca di minacce — è un sistema di rilevamento delle minacce, non il servizio che registra i log delle chiamate API."]},
  "255": {"h":"3b2c507c","question":"Un'applicazione in esecuzione su istanze Amazon EC2 deve leggere file da un bucket Amazon S3. Uno sviluppatore intende salvare le access key di un utente IAM in un file di configurazione su ogni istanza. Che cosa dovrebbe fare invece l'azienda per seguire le best practice di sicurezza AWS?","options":["Associare un IAM role alle istanze","Usare le access key del root user","Rendere il bucket S3 leggibile pubblicamente","Inviare le chiavi via email a ogni amministratore"],"explanation":"Un IAM role associato alle istanze EC2 fornisce all'applicazione credenziali temporanee che AWS ruota automaticamente, così sulle istanze non vengono memorizzate access key a lungo termine. La policy del ruolo può concedere solo i permessi S3 di cui l'applicazione ha bisogno.","optionExplanations":["Corretto — un IAM role fornisce alle istanze credenziali temporanee e ruotate automaticamente, quindi non serve memorizzare access key.","Le chiavi del root user hanno accesso illimitato all'account e non devono mai essere usate dalle applicazioni.","Un bucket pubblico consentirebbe a chiunque su internet di leggere i file, una soluzione molto meno sicura.","Condividere chiavi a lungo termine via email aumenta il rischio di fughe e lascia comunque le chiavi memorizzate sulle istanze."]},
  "256": {"h":"e19ad681","question":"Quale servizio AWS usa il machine learning per analizzare continuamente VPC Flow Logs, eventi CloudTrail e log DNS, al fine di rilevare attività malevole e comportamenti non autorizzati?","options":["AWS Shield","Amazon Inspector","Amazon GuardDuty","AWS WAF"],"explanation":"Amazon GuardDuty è un servizio di rilevamento delle minacce che usa ML e threat intelligence per identificare attività sospette (come mining di criptovalute, esfiltrazione di dati o istanze compromesse) analizzando più fonti di dati AWS.","optionExplanations":["AWS Shield fornisce protezione DDoS ai livelli di rete e di trasporto — non analizza log con il ML né rileva minacce comportamentali all'interno degli account.","Amazon Inspector cerca vulnerabilità software nelle istanze EC2 e nelle immagini container — valuta vulnerabilità statiche, non schemi comportamentali che indicano minacce in corso.","Corretto — Amazon GuardDuty usa ML e threat intelligence per analizzare VPC Flow Logs, eventi CloudTrail e log DNS alla ricerca di minacce comportamentali come cryptomining e compromissione delle credenziali.","AWS WAF filtra il traffico delle applicazioni web in base a regole — protegge dagli exploit a livello applicativo, non rileva minacce comportamentali a livello di account."]},
  "257": {"h":"efcd64e8","question":"È stata annunciata una vulnerabilità molto pubblicizzata in una diffusa libreria open source. Il team di sicurezza di un'azienda deve individuare rapidamente quali delle proprie istanze EC2 e immagini container in Amazon ECR contengono il pacchetto vulnerabile, e vuole che i workload vengano nuovamente analizzati in automatico ogni volta che vengono pubblicate nuove vulnerabilità. Quale servizio AWS dovrebbe usare il team?","options":["Amazon GuardDuty","Amazon Inspector","AWS Shield","Amazon Macie"],"explanation":"Amazon Inspector è un servizio automatizzato di gestione delle vulnerabilità che analizza continuamente le istanze EC2 e le immagini container in Amazon ECR alla ricerca di vulnerabilità software note (CVE) e di esposizioni di rete involontarie. Ripete automaticamente la scansione quando vengono pubblicate nuove CVE, così il team può vedere quali workload sono coinvolti.","optionExplanations":["Amazon GuardDuty rileva attività malevole analizzando log come CloudTrail e VPC Flow Logs. Non censisce i pacchetti software installati alla ricerca di vulnerabilità note.","Corretto — Amazon Inspector analizza continuamente le istanze EC2 e le immagini container in ECR alla ricerca di vulnerabilità note e ripete automaticamente la scansione quando vengono pubblicate nuove CVE.","AWS Shield protegge dagli attacchi DDoS. Non analizza i workload alla ricerca di pacchetti software vulnerabili.","Amazon Macie individua dati sensibili come le PII in Amazon S3. Non analizza istanze EC2 o immagini container alla ricerca di vulnerabilità."]},
  "258": {"h":"c7430641","question":"Un team di sicurezza vuole individuare, classificare e proteggere automaticamente i dati sensibili, come le PII, archiviati in Amazon S3. Quale servizio AWS dovrebbe usare?","options":["Amazon GuardDuty","AWS Config","Amazon Macie","AWS Secrets Manager"],"explanation":"Amazon Macie usa il ML per individuare e classificare automaticamente i dati sensibili in S3 (come PII, dati finanziari o credenziali). Genera avvisi quando i dati sensibili sono esposti o accessibili in modo improprio.","optionExplanations":["Amazon GuardDuty analizza CloudTrail e i log di rete alla ricerca di minacce comportamentali — non esamina il contenuto degli oggetti S3 per individuare e classificare PII o dati sensibili.","AWS Config valuta la configurazione delle risorse rispetto a regole di conformità — non analizza il contenuto degli oggetti S3 alla ricerca di dati sensibili.","Corretto — Amazon Macie usa il ML per individuare e classificare dati sensibili (PII, dati finanziari, credenziali) in S3, generando avvisi quando i dati sono esposti o accessibili in modo improprio.","AWS Secrets Manager archivia e ruota i secret delle applicazioni — non analizza i bucket S3 alla ricerca di dati sensibili né classifica il contenuto archiviato."]},
  "259": {"h":"8afda6e5","question":"Un'azienda usa AWS Organizations. Il team di rete vuole condividere in modo sicuro le subnet di una VPC centrale con gli altri account dell'organizzazione, invece di creare reti duplicate in ogni account. Quale servizio AWS dovrebbe usare il team?","options":["AWS Resource Access Manager","AWS IAM Identity Center","AWS Firewall Manager","AWS Control Tower Account Factory"],"explanation":"AWS Resource Access Manager (AWS RAM) consente di condividere in modo sicuro le risorse AWS supportate, come le subnet VPC e i transit gateway, con altri account AWS o con l'intera organizzazione. In questo modo si evita di duplicare le risorse in ogni account, mentre l'account proprietario ne mantiene il controllo.","optionExplanations":["Corretto — AWS RAM condivide in modo sicuro risorse come le subnet VPC con altri account o con l'intera organizzazione, evitando risorse duplicate.","IAM Identity Center gestisce l'accesso del personale agli account AWS e alle applicazioni. Non condivide risorse come le subnet tra account.","Firewall Manager gestisce centralmente regole firewall come le regole AWS WAF e i security group tra più account, ma non condivide subnet VPC.","Control Tower Account Factory crea nuovi account AWS preconfigurati. Non condivide risorse di rete esistenti tra account."]},
  "260": {"h":"599fefa8","question":"Quale servizio AWS fornisce un web application firewall gestito che protegge dagli exploit web più comuni, come SQL injection e cross-site scripting?","options":["AWS Shield","Amazon GuardDuty","AWS WAF","AWS Network Firewall"],"explanation":"AWS WAF (Web Application Firewall) consente di definire regole per consentire, bloccare o contare le richieste web in base a condizioni come indirizzo IP, header HTTP, query string o pattern dell'URI. Protegge dalle minacce della OWASP Top 10.","optionExplanations":["AWS Shield fornisce protezione DDoS ai livelli 3 e 4 — non ispeziona né filtra il contenuto delle richieste alle applicazioni web, come pattern di SQL injection o XSS.","Amazon GuardDuty analizza i log alla ricerca di minacce comportamentali — rileva le minacce a posteriori ma non blocca in tempo reale le richieste web in base al loro contenuto.","Corretto — AWS WAF crea regole per consentire, bloccare o contare le richieste HTTP/S in base a IP, header, URI o query string, proteggendo da SQL injection, XSS e OWASP Top 10.","AWS Network Firewall offre ispezione stateful dei pacchetti e filtraggio di domini/URL a livello di VPC — è un firewall di livello rete, non un web application firewall progettato per gli exploit HTTP."]},
  "261": {"h":"679c9027","question":"Quale servizio AWS consente la gestione centralizzata delle regole firewall su più account e risorse in AWS Organizations?","options":["AWS WAF","AWS Shield Advanced","AWS Firewall Manager","Amazon Inspector"],"explanation":"AWS Firewall Manager consente agli amministratori della sicurezza di configurare e gestire centralmente regole AWS WAF, protezioni Shield Advanced, security group delle VPC e policy di AWS Network Firewall su tutti gli account di un'organizzazione AWS Organizations.","optionExplanations":["AWS WAF crea regole di web application firewall per singole risorse — di per sé non offre una gestione centralizzata su più account di un'organizzazione.","AWS Shield Advanced fornisce una protezione DDoS avanzata — è un servizio di protezione specifico, non uno strumento di gestione multi-account per distribuire policy di sicurezza.","Corretto — AWS Firewall Manager gestisce centralmente regole WAF, Shield Advanced, Security Group e policy di Network Firewall su tutti gli account di AWS Organizations.","Amazon Inspector analizza i workload alla ricerca di vulnerabilità software — non gestisce centralmente regole firewall o policy di sicurezza tra account."]},
  "262": {"h":"6637cb6a","question":"Un'azienda ha decine di account AWS in AWS Organizations. Il suo team di sicurezza vuole un unico punto in cui vedere e prioritizzare i finding di sicurezza e i risultati dei controlli di conformità di tutti questi account, invece di accedere a ciascun account. Quale servizio AWS dovrebbe usare?","options":["AWS Config","Amazon GuardDuty","AWS Security Hub","AWS Trusted Advisor"],"explanation":"AWS Security Hub aggrega, organizza e prioritizza i finding di sicurezza provenienti dai servizi AWS e dagli strumenti dei partner ed esegue controlli di conformità automatizzati. Con un account amministratore delegato offre una vista centralizzata della postura di sicurezza di tutti gli account di un'organizzazione.","optionExplanations":["AWS Config registra e valuta la configurazione delle risorse, ma non è il punto centrale per prioritizzare i finding di sicurezza di più servizi.","GuardDuty è una delle fonti di finding sulle minacce; non aggrega i finding di altri servizi né esegue controlli di conformità rispetto a standard.","Corretto — Security Hub centralizza in un'unica vista i finding di sicurezza e i risultati di conformità di tutti gli account.","Trusted Advisor fornisce raccomandazioni basate sulle best practice, ma non è una dashboard centrale per i finding di sicurezza e lo stato di conformità tra account."]},
  "263": {"h":"5f38f187","question":"Quale servizio AWS aiuta ad archiviare, ruotare e recuperare in modo sicuro credenziali di database, API key e altri secret?","options":["AWS KMS","AWS Systems Manager Parameter Store","AWS Secrets Manager","AWS Certificate Manager"],"explanation":"AWS Secrets Manager è progettato specificamente per la gestione del ciclo di vita dei secret: archiviazione, rotazione (automatica) e recupero. Si integra nativamente con RDS, Redshift e DocumentDB per la rotazione automatica delle password.","optionExplanations":["AWS KMS gestisce chiavi crittografiche — cifra e decifra dati ma non archivia credenziali di database né offre la rotazione automatica dei secret applicativi.","AWS Systems Manager Parameter Store può archiviare dati di configurazione, compresi alcuni secret — ma non supporta nativamente la rotazione automatica delle credenziali di database senza funzioni Lambda personalizzate.","Corretto — AWS Secrets Manager archivia, ruota (automaticamente per RDS, Redshift, DocumentDB) e recupera i secret, con integrazione nativa con i database.","AWS Certificate Manager emette e gestisce certificati SSL/TLS — non archivia password di database o API key né offre funzionalità di rotazione dei secret."]},
  "264": {"h":"2276b0f5","question":"Un'azienda vuole cifrare i dati in Amazon S3 e Amazon EBS con chiavi di crittografia che crea e controlla, compresa la possibilità di disabilitarle o ruotarle. Vuole un servizio completamente gestito, integrato in questi servizi AWS, e non ha bisogno di hardware dedicato single-tenant. Quale servizio AWS dovrebbe usare l'azienda?","options":["AWS Secrets Manager","AWS Certificate Manager (ACM)","AWS Key Management Service","AWS CloudHSM"],"explanation":"AWS KMS è un servizio gestito per creare e controllare chiavi di crittografia. Si integra con la maggior parte dei servizi AWS, compresi S3 ed EBS, e AWS gestisce gli hardware security module che proteggono le chiavi, così l'azienda non deve gestire alcun hardware.","optionExplanations":["Secrets Manager archivia e ruota secret come password di database e API key. Non è il servizio che S3 ed EBS usano per le loro chiavi di crittografia.","ACM emette e gestisce certificati SSL/TLS per la crittografia in transito. Non gestisce le chiavi per i dati in S3 o EBS.","Corretto — KMS consente all'azienda di creare e controllare le proprie chiavi, è integrato in S3 ed EBS ed è completamente gestito.","CloudHSM fornisce HSM dedicati single-tenant le cui chiavi sono gestite dal cliente. È più di quanto serva all'azienda e non è l'opzione integrata più semplice."]},
  "265": {"h":"54262249","question":"Un'azienda necessita di hardware security module (HSM) dedicati e single-tenant per conformità normativa. Quale servizio AWS soddisfa questo requisito?","options":["AWS KMS","AWS Secrets Manager","AWS CloudHSM","AWS Certificate Manager"],"explanation":"AWS CloudHSM fornisce appliance HSM dedicate nel cloud AWS. A differenza di KMS (multi-tenant), CloudHSM dà al cliente il controllo esclusivo dell'hardware HSM, soddisfacendo requisiti normativi stringenti come FIPS 140-2 Level 3.","optionExplanations":["AWS KMS è un servizio condiviso multi-tenant in cui l'hardware HSM è gestito da AWS — non fornisce gli hardware security module dedicati e single-tenant richiesti da una conformità normativa stringente.","AWS Secrets Manager archivia e ruota secret — non fornisce hardware HSM né capacità crittografiche FIPS 140-2 Level 3.","Corretto — AWS CloudHSM fornisce appliance HSM dedicate single-tenant sotto il controllo esclusivo del cliente, soddisfacendo requisiti normativi stringenti (FIPS 140-2 Level 3).","AWS Certificate Manager gestisce certificati SSL/TLS — non fornisce hardware HSM dedicato per le operazioni crittografiche."]},
  "266": {"h":"b8315653","question":"Quale servizio AWS emette, gestisce e distribuisce certificati SSL/TLS da usare con servizi AWS come CloudFront ed Elastic Load Balancing?","options":["AWS KMS","AWS Secrets Manager con rotazione","AWS Certificate Manager","AWS IAM"],"explanation":"AWS Certificate Manager (ACM) gestisce emissione, rinnovo e distribuzione di certificati SSL/TLS pubblici e privati. I certificati da usare con CloudFront ed ELB sono gratuiti e, se gestiti da ACM, vengono rinnovati automaticamente.","optionExplanations":["AWS KMS gestisce chiavi di crittografia dei dati — non emette né gestisce certificati SSL/TLS per le comunicazioni HTTPS.","AWS Secrets Manager archivia secret applicativi come password e API key — non emette né rinnova automaticamente certificati SSL/TLS per i servizi web.","Corretto — AWS Certificate Manager emette, gestisce e rinnova automaticamente i certificati SSL/TLS. I certificati pubblici per CloudFront ed ELB sono forniti gratuitamente.","AWS IAM può importare e archiviare certificati da usare con alcuni servizi, ma non li rinnova automaticamente né ne emette di nuovi come fa ACM."]},
  "267": {"h":"d235cb52","question":"Una startup non ha personale dedicato alla sicurezza. Vuole un controllo automatico del proprio account AWS rispetto alle best practice AWS — ad esempio se il root user ha l'MFA e se qualche bucket S3 o security group è aperto a tutti — con raccomandazioni, senza dover scrivere o configurare alcuna regola. Quale servizio AWS dovrebbe usare la startup?","options":["Amazon Inspector","Regole personalizzate di AWS Config","AWS Trusted Advisor","Amazon GuardDuty"],"explanation":"AWS Trusted Advisor esamina l'account AWS e fornisce raccomandazioni basate sulle best practice AWS. I suoi controlli di sicurezza coprono elementi come l'MFA sul root user, i permessi dei bucket S3 e i security group con accesso illimitato, senza regole da scrivere.","optionExplanations":["Amazon Inspector analizza istanze EC2, immagini container e funzioni Lambda alla ricerca di vulnerabilità software. Non verifica impostazioni a livello di account come l'MFA del root.","Le regole personalizzate di AWS Config potrebbero valutare queste impostazioni, ma la startup dovrebbe scriverle e mantenerle da sé, cosa che vuole evitare.","Corretto — Trusted Advisor verifica l'account rispetto alle best practice AWS, compresi MFA del root, bucket S3 aperti e security group senza restrizioni, e fornisce raccomandazioni.","Amazon GuardDuty rileva minacce e attività malevole. Non verifica se la configurazione dell'account segue le best practice."]},
  "268": {"h":"ff94754f","question":"Un security group consente il traffico HTTPS in ingresso da internet ma non ha regole in uscita corrispondenti alle risposte. Gli utenti ricevono comunque le risposte del web server. Perché funziona?","options":["I security group sono stateful e consentono il traffico di ritorno","Le network ACL aggiungono automaticamente la regola in uscita","AWS Shield Standard consente le risposte per impostazione predefinita","L'internet gateway riscrive le regole in uscita"],"explanation":"I security group sono stateful: se una richiesta in ingresso è consentita, il traffico di risposta viene automaticamente consentito in uscita, indipendentemente dalle regole in uscita. Le network ACL sono stateless, quindi richiedono regole esplicite in entrambe le direzioni.","optionExplanations":["Corretto — i security group tengono traccia delle connessioni, quindi le risposte alle richieste in ingresso consentite sono consentite automaticamente.","Le network ACL sono stateless e non aggiungono mai regole automaticamente; richiedono regole esplicite sia in ingresso sia in uscita.","Shield Standard protegge dagli attacchi DDoS; non controlla le regole di traffico dei security group.","Un internet gateway instrada il traffico tra la VPC e internet; non modifica le regole dei security group."]},
  "269": {"h":"a96b024f","question":"In base allo Shared Responsibility Model di AWS, chi è responsabile della crittografia dei dati at rest archiviati in Amazon S3?","options":["Solo AWS","Solo il cliente","AWS e il cliente condividono questa responsabilità","Nessuno dei due — i dati S3 non sono mai cifrati"],"explanation":"S3 cifra per impostazione predefinita tutti i nuovi oggetti (responsabilità di AWS), ma i clienti controllano anche la propria crittografia: scelgono la gestione delle chiavi (SSE-S3, SSE-KMS, SSE-C), impostano le bucket policy e gestiscono le proprie chiavi di crittografia. Si tratta di una responsabilità condivisa.","optionExplanations":["«Solo AWS» non è corretto — anche se AWS applica la crittografia predefinita ai nuovi oggetti, i clienti mantengono il controllo sulla scelta della gestione delle chiavi (SSE-KMS, SSE-S3 o SSE-C) e sulle bucket policy.","«Solo il cliente» non è corretto — AWS fornisce e gestisce il meccanismo di crittografia predefinito di S3 (AES-256), facendo la propria parte nella crittografia.","Corretto — la crittografia at rest in S3 è condivisa: AWS cifra gli oggetti per impostazione predefinita (può usare chiavi gestite da AWS), mentre i clienti controllano il tipo di crittografia, la gestione delle chiavi e le policy di accesso.","Che i dati S3 non siano mai cifrati è falso — da gennaio 2023 Amazon S3 applica la crittografia predefinita (SSE-S3) a tutti i nuovi oggetti."]},
  "270": {"h":"231b5652","question":"Quale best practice di sicurezza raccomanda di concedere agli utenti solo i permessi necessari per svolgere il proprio lavoro e nulla di più?","options":["Defense in depth","Least privilege","Security by obscurity","Zero trust"],"explanation":"Il principio del least privilege consiste nel concedere i permessi minimi necessari per un'attività. In IAM significa scrivere policy granulari che consentono solo le azioni necessarie su risorse specifiche, riducendo il raggio d'impatto in caso di credenziali compromesse.","optionExplanations":["La defense in depth applica più livelli di sicurezza — è una strategia di sicurezza più ampia, non riguarda specificamente la concessione agli utenti dei soli permessi minimi necessari.","Corretto — il least privilege consiste nel concedere solo i permessi minimi necessari per la specifica mansione, riducendo l'esposizione in caso di credenziali compromesse.","La security by obscurity si basa sull'occultamento delle informazioni per garantire la sicurezza — non è una best practice raccomandata e non descrive la concessione dei permessi minimi.","Lo zero trust verifica ogni richiesta di accesso indipendentemente dalla provenienza — è un modello di rete/accesso, non riguarda specificamente la limitazione dei permessi al minimo necessario."]},
  "271": {"h":"422fe169","question":"Quale funzionalità AWS aggiunge un secondo livello di sicurezza all'accesso all'account AWS richiedendo un codice monouso generato da un dispositivo hardware o virtuale?","options":["Le IAM access key per la CLI e gli SDK","L'autenticazione a più fattori","I security group sulle istanze EC2","AWS Shield"],"explanation":"L'MFA richiede qualcosa che si conosce (la password) più qualcosa che si possiede (il dispositivo MFA). AWS raccomanda vivamente di abilitare l'MFA sull'account root e su tutti gli utenti IAM privilegiati per proteggersi dalla compromissione delle password.","optionExplanations":["Le IAM access key sono credenziali (access key ID + secret) per l'accesso programmatico — sono credenziali a lungo termine, non un secondo livello di sicurezza per l'accesso alla console.","Corretto — l'MFA richiede, oltre alla password, un codice monouso generato da un dispositivo fisico o virtuale, fornendo un secondo fattore di autenticazione.","I security group sono firewall a livello di rete che controllano il traffico verso le istanze — non sono un meccanismo di autenticazione per l'accesso all'account AWS.","AWS Shield fornisce protezione DDoS — non ha nulla a che vedere con la sicurezza dell'accesso all'account o con l'aggiunta di un secondo fattore di autenticazione."]},
  "272": {"h":"a1cd24fd","question":"Il team di sicurezza di un'azienda deve sapere ogni volta che cambiano i permessi di uno specifico bucket S3. Quale servizio AWS può generare automaticamente un avviso quando si verificano modifiche di configurazione?","options":["Amazon GuardDuty","Event history di AWS CloudTrail","Regole di AWS Config","Amazon Macie"],"explanation":"AWS Config registra le modifiche di configurazione e può attivare le Config Rules per valutarne la conformità. Una notifica SNS o una funzione Lambda può avvisare il team ogni volta che la configurazione di una risorsa (come l'ACL di un bucket S3) cambia in modo non conforme alla policy.","optionExplanations":["Amazon GuardDuty rileva minacce comportamentali tramite l'analisi dei log — non monitora le modifiche di configurazione delle risorse, come le modifiche ai permessi dei bucket S3.","AWS CloudTrail registra la chiamata API che ha modificato i permessi S3 — ma non valuta automaticamente la conformità della configurazione né genera avvisi quando un'impostazione viola la policy.","Corretto — AWS Config registra le modifiche di configurazione e può attivare regole e notifiche SNS quando una risorsa (come i permessi di un bucket S3) cambia in modo non conforme alla policy.","Amazon Macie individua dati sensibili nel contenuto di S3 — non monitora né segnala le modifiche ai permessi o alla configurazione dei bucket S3."]},
  "273": {"h":"13d23cc3","question":"Un team di sicurezza usa già i security group sulle proprie istanze EC2. Come ulteriore livello di difesa, vuole regole che si applichino automaticamente a tutte le risorse di una subnet, senza costi aggiuntivi, e accetta che le regole in ingresso e in uscita vengano valutate separatamente perché il controllo è stateless. Quale funzionalità della VPC dovrebbe usare?","options":["Security group","AWS WAF","Network ACL","AWS Network Firewall"],"explanation":"Le network ACL sono firewall stateless che operano a livello di subnet di una VPC, senza costi aggiuntivi. Le regole in ingresso e in uscita vengono valutate in modo indipendente, quindi il traffico di ritorno deve essere consentito esplicitamente. Sono complementari ai security group, che sono stateful e operano a livello di istanza.","optionExplanations":["I security group sono stateful e operano a livello di istanza; il team li usa già e vuole un ulteriore livello a livello di subnet.","AWS WAF filtra le richieste HTTP e HTTPS verso le applicazioni web; non è un filtro stateless a livello di subnet per tutto il traffico.","Corretto — le network ACL sono firewall gratuiti, stateless e a livello di subnet, che aggiungono un livello di difesa oltre ai security group.","Network Firewall è un servizio firewall gestito e stateful con costi separati, quindi non soddisfa la richiesta di un controllo gratuito e stateless."]},
  "274": {"h":"ad1f435c","question":"Quale delle seguenti affermazioni descrive MEGLIO la differenza tra i Security Group e le Network ACL di AWS?","options":["I Security Group sono stateless a livello di istanza; le NACL sono stateful a livello di subnet","I Security Group sono stateful a livello di istanza; le NACL sono stateless a livello di subnet","I Security Group controllano l'accesso ai bucket S3; le NACL controllano l'accesso alle istanze EC2","Hanno funzionalità identiche e si applicano allo stesso livello"],"explanation":"I Security Group sono stateful (il traffico di ritorno è consentito automaticamente) e sono associati a istanze EC2/ENI. Le NACL sono stateless (il traffico di ritorno va consentito esplicitamente) e si applicano a livello di subnet, interessando tutte le risorse di quella subnet.","optionExplanations":["I Security Group sono stateful (non stateless) e le NACL sono stateless (non stateful) — questa risposta inverte le caratteristiche.","Corretto — i Security Group sono stateful e operano a livello di istanza/ENI; le NACL sono stateless e operano a livello di subnet, interessando tutte le risorse della subnet.","I Security Group controllano il traffico verso le istanze EC2 (e altre risorse), non specificamente S3; le NACL filtrano tutto il traffico IP a livello di subnet, non specificamente EC2 — questa distinzione è errata.","Security Group e NACL non sono identici — differiscono per comportamento stateful/stateless, livello di applicazione (istanza o subnet) e ordine di valutazione delle regole."]},
  "275": {"h":"20152624","question":"Una software house esegue la propria applicazione SaaS su AWS e vuole venderla alle agenzie del governo federale degli Stati Uniti. Le agenzie richiedono che i servizi cloud sottostanti siano autorizzati nell'ambito del programma governativo che standardizza le valutazioni di sicurezza dei cloud provider. Di quale programma di conformità si tratta?","options":["PCI DSS","HIPAA","FedRAMP","SOC 2"],"explanation":"FedRAMP (Federal Risk and Authorization Management Program) è il programma del governo statunitense che standardizza la valutazione di sicurezza e l'autorizzazione dei servizi cloud usati dalle agenzie federali. Molti servizi AWS dispongono di autorizzazioni FedRAMP.","optionExplanations":["PCI DSS è uno standard per le organizzazioni che trattano dati di carte di pagamento. Non è il programma di autorizzazione federale statunitense.","HIPAA è una legge statunitense che tutela le informazioni sanitarie. Non è il programma usato dalle agenzie federali per autorizzare i servizi cloud.","Corretto — FedRAMP è il programma federale statunitense per l'autorizzazione dei servizi cloud usati dalle agenzie governative.","SOC 2 è un report di audit indipendente sui controlli di sicurezza e disponibilità. È molto diffuso, ma non è il programma di autorizzazione del governo federale."]},
  "276": {"h":"b94e3cd7","question":"Un'azienda carica nuovi oggetti in un bucket Amazon S3 senza specificare alcuna impostazione di crittografia. Come sono protetti at rest questi oggetti?","options":["Archiviati non cifrati finché non si attiva la crittografia predefinita","Cifrati per impostazione predefinita con chiavi gestite da S3 (SSE-S3)","Cifrati con una customer managed key in AWS KMS","Cifrati dall'AWS SDK sul client prima del caricamento"],"explanation":"Amazon S3 cifra automaticamente tutti i nuovi oggetti con la crittografia lato server tramite chiavi gestite da Amazon S3 (SSE-S3), come livello base di crittografia per ogni bucket. I clienti possono scegliere un'opzione diversa, come SSE-KMS, se hanno bisogno di maggiore controllo sulle chiavi.","optionExplanations":["S3 applica automaticamente la crittografia SSE-S3 a tutti i nuovi oggetti, quindi i nuovi caricamenti non sono mai archiviati non cifrati.","Corretto — S3 cifra at rest ogni nuovo oggetto per impostazione predefinita con SSE-S3, usando chiavi gestite da Amazon S3.","Una customer managed key KMS viene usata solo se il cliente configura SSE-KMS con quella chiave; non è l'impostazione predefinita.","La crittografia lato client avviene solo quando il cliente cifra esplicitamente i dati prima del caricamento. L'SDK non lo fa per impostazione predefinita."]},
  "277": {"h":"8681ed76","question":"Un'azienda sanitaria vuole archiviare dati dei pazienti su AWS e deve firmare un Business Associate Agreement (BAA) con AWS per essere conforme a HIPAA. Dove può consultare e accettare questo accordo?","options":["AWS Support","AWS Trusted Advisor","AWS Artifact","AWS Organizations"],"explanation":"AWS Artifact mette a disposizione il BAA HIPAA come accordo che i clienti possono esaminare e accettare direttamente nel portale. Una volta accettato, i servizi AWS idonei possono essere usati per archiviare ed elaborare PHI in conformità a HIPAA.","optionExplanations":["AWS Support gestisce i ticket di supporto tecnico — non fornisce accordi legali di conformità come i BAA per HIPAA.","AWS Trusted Advisor fornisce raccomandazioni basate sulle best practice — non gestisce accordi legali di conformità né la firma di documenti.","Corretto — AWS Artifact fornisce il Business Associate Agreement (BAA) HIPAA, che i clienti possono esaminare e accettare online per abilitare i servizi idonei HIPAA per i PHI.","AWS Organizations gestisce la governance degli account — non fornisce né gestisce accordi legali di conformità come il BAA HIPAA."]},
  "278": {"h":"1a572175","question":"Quale servizio AWS può rilevare quando le credenziali del root user di un account AWS o le access key di un utente IAM sono state pubblicate su GitHub?","options":["Amazon GuardDuty","Amazon Inspector","AWS Security Hub","Amazon Macie"],"explanation":"Amazon GuardDuty monitora i feed di threat intelligence e rileva comportamenti anomali, compresa l'esposizione di credenziali. Uno dei suoi finding identifica specificamente quando le credenziali AWS compaiono in repository pubblici, generando un avviso.","optionExplanations":["Corretto — Amazon GuardDuty monitora i feed di threat intelligence e genera finding quando le credenziali AWS (root o IAM) vengono pubblicate, ad esempio su GitHub.","Amazon Inspector analizza istanze EC2 e container alla ricerca di vulnerabilità software — non monitora la threat intelligence esterna né rileva credenziali esposte pubblicamente.","AWS Security Hub aggrega i finding di sicurezza — riceverebbe e mostrerebbe il finding di GuardDuty, ma non rileva di per sé l'esposizione di credenziali su GitHub.","Amazon Macie individua dati sensibili in S3 — analizza il contenuto degli oggetti S3, non repository esterni come GitHub, alla ricerca di credenziali esposte."]},
  "279": {"h":"5acafeb4","question":"Un'azienda consente ai propri sviluppatori di creare IAM role per le proprie applicazioni in un unico account AWS standalone che non fa parte di AWS Organizations. Il team di sicurezza vuole garantire che qualsiasi ruolo creato da uno sviluppatore non possa mai superare un insieme definito di permessi massimi, anche se gli viene associata una policy più ampia. Quale funzionalità IAM soddisfa questo requisito?","options":["IAM group","Service control policy (SCP)","Permissions boundary","Policy basate sulle risorse"],"explanation":"Un permissions boundary stabilisce i permessi massimi che un utente o un ruolo IAM può avere. Anche se viene associata una policy basata sull'identità più ampia, i permessi effettivi non possono superare il boundary, il che consente all'azienda di delegare in sicurezza la creazione dei ruoli agli sviluppatori.","optionExplanations":["Gli IAM group sono un modo per assegnare permessi a più utenti. Non limitano i permessi dei ruoli creati dagli sviluppatori.","Le SCP stabiliscono i permessi massimi per gli account in AWS Organizations. L'account standalone dell'azienda non fa parte di un'organizzazione e le SCP non si applicano a singoli ruoli.","Corretto — un permissions boundary limita i permessi massimi di un utente o ruolo IAM, indipendentemente dalle policy che vi sono associate.","Le policy basate sulle risorse sono associate a risorse, come i bucket S3, per concedere l'accesso. Non limitano i permessi massimi di un ruolo."]},
  "280": {"h":"b3127ff7","question":"Quale funzionalità di Amazon S3 protegge dalla cancellazione accidentale o malevola degli oggetti mantenendo più versioni di ciascun oggetto?","options":["S3 Replication","S3 Lifecycle Policies","S3 Versioning","S3 Object Lock"],"explanation":"S3 Versioning conserva ogni versione di un oggetto in un bucket. Se un oggetto viene cancellato o sovrascritto, le versioni precedenti vengono mantenute e possono essere ripristinate. È una funzionalità chiave per la protezione dei dati.","optionExplanations":["S3 Replication copia gli oggetti in un altro bucket (nella stessa Region o in una diversa) — protegge dai guasti di una Region ma non mantiene più versioni di ciascun oggetto nello stesso bucket.","S3 Lifecycle Policies spostano o fanno scadere automaticamente gli oggetti — gestiscono il ciclo di vita in base all'età o alla storage class, non mantengono le versioni precedenti per il ripristino.","Corretto — S3 Versioning conserva tutte le versioni di ogni oggetto. Gli oggetti cancellati o sovrascritti possono essere recuperati accedendo a una versione precedente.","S3 Object Lock impedisce la cancellazione o la modifica durante un periodo di conservazione — impone l'immutabilità ma non mantiene di per sé più versioni dello stesso oggetto."]},
  "281": {"h":"d0c4f373","question":"Un'azienda usa AWS IAM Identity Center per dare al proprio personale accesso a molti account AWS. Un amministratore vuole definire una sola volta un insieme di permessi e poi assegnarlo a gruppi di utenti su diversi di questi account. Quale funzionalità dovrebbe usare l'amministratore?","options":["Permission set","Service control policy (SCP)","IAM permissions boundary","Bucket policy S3"],"explanation":"In IAM Identity Center, un permission set è un modello composto da una o più IAM policy che definisce ciò che gli utenti possono fare in un account. Quando viene assegnato a utenti o gruppi per account specifici, IAM Identity Center crea i corrispondenti IAM role in quegli account, così i permessi vengono definiti una sola volta e riutilizzati.","optionExplanations":["Corretto — i permission set consentono a un amministratore di definire i permessi una sola volta in IAM Identity Center e di assegnarli a utenti e gruppi su più account.","Le SCP stabiliscono i permessi massimi disponibili per gli account di un'organizzazione, ma da sole non concedono mai permessi agli utenti.","I permissions boundary limitano i permessi massimi di un singolo utente o ruolo IAM all'interno di un account. Non concedono accesso tra account.","Le bucket policy S3 controllano l'accesso a un singolo bucket S3. Non sono un modo per assegnare un insieme riutilizzabile di permessi agli utenti del personale."]},
  "282": {"h":"0d0b8edd","question":"Quale servizio AWS aggrega e centralizza i dati di log provenienti da servizi AWS, server on-premises e strumenti di terze parti per l'analisi di sicurezza?","options":["AWS CloudTrail","Amazon CloudWatch Logs","Amazon OpenSearch Service (in precedenza Elasticsearch)","AWS Security Lake"],"explanation":"AWS Security Lake centralizza automaticamente i dati di sicurezza provenienti da ambienti AWS, provider SaaS e sistemi on-premises in un data lake dedicato nel proprio account, usando l'Open Cybersecurity Schema Framework (OCSF), e consente analisi di sicurezza unificate.","optionExplanations":["AWS CloudTrail registra lo storico delle chiamate API — cattura gli eventi delle API AWS ma non aggrega dati di provider SaaS, sistemi on-premises e strumenti di terze parti in un data lake unificato.","Amazon CloudWatch Logs raccoglie e archivia i dati di log di servizi e applicazioni AWS — non è progettato come data lake di sicurezza che aggrega dati da più fonti esterne.","Amazon OpenSearch Service offre ricerca e analisi — può analizzare dati di sicurezza ma non centralizza e normalizza automaticamente i dati di sicurezza provenienti da più fonti.","Corretto — AWS Security Lake centralizza automaticamente i dati di sicurezza (usando OCSF) provenienti da AWS, provider SaaS e sistemi on-premises in un data lake di sicurezza dedicato nell'account del cliente."]},
  "283": {"h":"0aad5cfa","question":"Una piccola startup ha creato il proprio account AWS con l'indirizzo email del fondatore, e tutti e cinque gli ingegneri accedono come root user con una password condivisa per il lavoro quotidiano. L'azienda vuole mettere in sicurezza il root user. Quali azioni dovrebbe intraprendere? (Seleziona DUE)","options":["Abilitare l'MFA sul root user","Continuare a usare il root user per le attività amministrative quotidiane","Creare identità individuali per il lavoro quotidiano e custodire al sicuro le credenziali root","Condividere le credenziali root solo con il team di sicurezza"],"explanation":"AWS raccomanda di abilitare l'MFA sul root user, così che per l'accesso sia richiesto un secondo fattore, e di assegnare a ogni persona la propria identità (utenti IAM o AWS IAM Identity Center) per il lavoro quotidiano. Le credenziali root vanno conservate in modo sicuro e usate solo per le poche attività che le richiedono.","optionExplanations":["Corretto — l'MFA sul root user richiede un secondo fattore per l'accesso, proteggendo l'account anche in caso di fuga della password.","Usare il root user per il lavoro quotidiano è proprio il rischio che la startup corre oggi; il root va riservato alle attività che lo richiedono.","Corretto — le identità individuali per il lavoro quotidiano danno a ogni ingegnere solo l'accesso necessario, e le credenziali root possono essere custodite al sicuro.","Condividere le credenziali root con qualsiasi gruppo significa comunque che più persone hanno accesso illimitato e che le singole azioni non sono riconducibili a una persona."]},
  "284": {"h":"4a9ce8c7","question":"Quale servizio AWS fornisce un accesso single sign-on (SSO) centralizzato a più account AWS e applicazioni aziendali?","options":["AWS IAM","User pool di Amazon Cognito","AWS IAM Identity Center","AWS Directory Service"],"explanation":"AWS IAM Identity Center (in precedenza AWS SSO) fornisce un SSO centralizzato verso tutti gli account AWS di un'organizzazione e verso applicazioni SaaS di terze parti. Gli utenti accedono una sola volta e raggiungono più account/applicazioni senza credenziali separate.","optionExplanations":["AWS IAM gestisce identità e permessi all'interno dei singoli account — non fornisce un SSO centralizzato su più account o verso applicazioni di terze parti.","Amazon Cognito fornisce l'autenticazione per applicazioni web e mobile rivolte ai consumatori — non è progettato per l'accesso SSO dei dipendenti a più account AWS.","Corretto — AWS IAM Identity Center (in precedenza AWS SSO) fornisce un single sign-on centralizzato a più account AWS e applicazioni aziendali da un unico portale.","AWS Directory Service fornisce Active Directory gestito — può fungere da fonte di identità per IAM Identity Center ma non fornisce di per sé il portale SSO e la gestione degli accessi."]},
  "285": {"h":"d5df399f","question":"Una startup del settore fitness sta sviluppando un'app mobile per il pubblico. Vuole che i clienti possano registrarsi e accedere con un indirizzo email oppure con il proprio account Google o Facebook, senza dover realizzare e gestire un proprio database utenti. Quale servizio AWS dovrebbe usare la startup?","options":["AWS IAM Identity Center","AWS Directory Service","Amazon Cognito","AWS Identity and Access Management (IAM)"],"explanation":"Amazon Cognito fornisce registrazione, accesso e gestione degli utenti per app web e mobile. Supporta identity provider social come Google e Facebook e può scalare fino a milioni di utenti, così la startup non deve realizzare un proprio archivio utenti.","optionExplanations":["IAM Identity Center fornisce il single sign-on del personale di un'azienda verso account AWS e applicazioni aziendali. Non è pensato per i clienti pubblici di un'app mobile.","Directory Service fornisce Microsoft Active Directory gestito, tipicamente per utenti aziendali e workload Windows. Non è progettato per la registrazione pubblica con login social.","Corretto — Cognito gestisce registrazione e accesso degli utenti dell'app, compresa la federazione con Google e Facebook.","IAM controlla l'accesso alle risorse AWS per persone e workload dell'azienda. Non si usa per gestire gli utenti finali di un'app mobile pubblica."]},
  "286": {"h":"fa95f288","question":"Un'azienda vuole garantire che tutte le chiamate API ai servizi AWS nel proprio account vengano registrate e conservate per 90 giorni a fini di audit. Quale servizio offre questa funzionalità?","options":["Amazon CloudWatch","AWS Config","AWS CloudTrail","AWS X-Ray"],"explanation":"AWS CloudTrail registra tutta l'attività delle API. Configurando un Trail, i log vengono archiviati in S3 e possono essere conservati per qualsiasi periodo. CloudTrail si integra inoltre con CloudWatch Logs per il monitoraggio in tempo reale e con CloudWatch Logs Insights per le interrogazioni.","optionExplanations":["Amazon CloudWatch monitora metriche di prestazione e log applicativi — non registra lo storico delle chiamate API né archivia log di audit su chi ha chiamato quale servizio AWS.","AWS Config registra le modifiche di configurazione delle risorse — traccia come appaiono le risorse, non lo storico completo delle chiamate API con l'identità del chiamante a fini di audit.","Corretto — AWS CloudTrail registra tutte le chiamate API e, con un Trail configurato, le archivia in S3 per qualsiasi periodo di conservazione, fornendo il log di audit di 90 giorni richiesto.","AWS X-Ray traccia le richieste attraverso applicazioni distribuite — fornisce informazioni sulle prestazioni delle applicazioni, non log di audit delle chiamate alle API AWS a fini di conformità."]},
  "287": {"h":"00afc3c4","question":"Quale funzionalità di sicurezza di rete AWS agisce come firewall virtuale a livello di istanza EC2, controllando il traffico in ingresso e in uscita?","options":["Network ACL","AWS WAF","Security Group","AWS Network Firewall"],"explanation":"I Security Group sono firewall virtuali stateful applicati alle istanze EC2 (tramite le ENI). Controllano quale traffico è consentito in ingresso e in uscita in base a porta, protocollo e IP di origine/destinazione. Il traffico di ritorno è consentito automaticamente (stateful).","optionExplanations":["Le Network ACL operano a livello di subnet e sono stateless — filtrano tutto il traffico di una subnet, non le singole istanze, e richiedono regole esplicite in entrambe le direzioni.","AWS WAF è un web application firewall per il traffico HTTP/S a livello applicativo — non opera a livello di istanza come firewall di rete virtuale.","Corretto — i Security Group sono firewall virtuali stateful a livello di istanza EC2/ENI, che consentono automaticamente il traffico di ritorno delle connessioni permesse.","AWS Network Firewall fornisce ispezione stateful e prevenzione delle intrusioni a livello di VPC — protegge intere VPC/subnet, non singole istanze, ed è un servizio più avanzato dei Security Group."]},
  "288": {"h":"59a511b4","question":"Un attaccante sta inviando una raffica di richieste HTTPS a un'applicazione web ospitata su AWS, nel tentativo di sovraccaricarla. Quale servizio AWS offre protezione specifica contro gli attacchi DDoS a livello applicativo (Layer 7)?","options":["AWS Shield Standard","Shield Advanced con AWS WAF","Rilevamento delle minacce di Amazon GuardDuty","Amazon Inspector"],"explanation":"AWS Shield Standard protegge dagli attacchi di livello 3/4. Per gli attacchi DDoS sofisticati di livello 7 (applicativo), i clienti hanno bisogno di Shield Advanced combinato con AWS WAF per rilevare e filtrare i pattern di traffico HTTP/HTTPS malevolo.","optionExplanations":["AWS Shield Standard protegge solo dagli attacchi DDoS di livello 3 e 4 — non rileva né mitiga gli attacchi HTTP flood a livello applicativo (Layer 7).","Corretto — per gli attacchi DDoS di livello 7, Shield Advanced offre un rilevamento avanzato e il team di risposta DDoS, mentre AWS WAF filtra i pattern di traffico HTTP/HTTPS malevolo.","Amazon GuardDuty rileva le minacce tramite l'analisi dei log — individua schemi sospetti a posteriori ma non blocca in tempo reale il traffico DDoS a livello applicativo.","Amazon Inspector cerca vulnerabilità software — non ha alcuna capacità di rilevamento o mitigazione DDoS a nessun livello."]},
  "289": {"h":"a88abcec","question":"In base allo Shared Responsibility Model di AWS, quale delle seguenti attività è responsabilità del cliente per un database Amazon RDS?","options":["Applicare le patch al motore del database e al sistema operativo","Gestire l'hardware fisico degli host nel data center","Gestire i DB security group e le credenziali degli utenti","Sostituire i dischi guasti nel livello di storage"],"explanation":"Per RDS (servizio gestito), AWS si occupa di patching, hardware e backup. Il cliente è responsabile di: configurare l'accesso di rete (security group/NACL), gestire gli utenti del database, scegliere la crittografia dei dati e definire le IAM policy.","optionExplanations":["Il patching del motore del database è responsabilità di AWS per RDS — è parte essenziale dell'offerta di «servizio gestito» ed elimina questo onere operativo per il cliente.","La gestione dell'hardware fisico degli host è responsabilità di AWS — i clienti non interagiscono mai con i server fisici che eseguono le istanze RDS né li gestiscono.","Corretto — configurare i security group, gestire le credenziali di accesso al database e impostare le opzioni di crittografia sono responsabilità del cliente anche con un servizio gestito come RDS.","La sostituzione dei dischi guasti è responsabilità di AWS — la manutenzione dell'hardware fisico di storage rientra in ciò che AWS gestisce nel servizio gestito."]},
  "290": {"h":"2f6b56bc","question":"Un'azienda protegge la propria applicazione web con AWS WAF all'edge, network ACL sulle subnet, security group sulle istanze e crittografia per i dati archiviati. Se uno di questi controlli fallisce o è configurato in modo errato, gli altri continuano a proteggere l'applicazione. Quale principio di progettazione della sicurezza dimostra questo approccio?","options":["Least privilege","Defense in depth","Automatizzare le best practice di sicurezza","Proteggere i dati in transito e at rest"],"explanation":"La defense in depth consiste nell'applicare controlli di sicurezza su più livelli — edge, rete, subnet, istanza, applicazione e dati — così che, se un livello fallisce, gli altri continuino a proteggere il sistema. I controlli stratificati dell'azienda sono un esempio diretto di questo principio del pilastro Security.","optionExplanations":["Il least privilege consiste nel concedere solo i permessi necessari per un'attività. Non descrive la stratificazione di più controlli indipendenti.","Corretto — combinare controlli a livello di edge, subnet, istanza e dati, in modo che un singolo guasto non esponga l'applicazione, è defense in depth.","Automatizzare le best practice di sicurezza significa implementare i controlli come codice. Lo scenario descrive più livelli di protezione, non l'automazione.","La crittografia dei dati è solo uno dei livelli dello scenario. Il principio descritto è l'uso combinato di molti livelli."]},
  "291": {"h":"f449fff1","question":"Quale servizio AWS si usa per rilevare e rispondere alla compromissione di account AWS analizzando schemi comportamentali e threat intelligence?","options":["Amazon Inspector","AWS Config","Amazon GuardDuty","AWS Trusted Advisor"],"explanation":"GuardDuty usa il ML e una threat intelligence curata per identificare minacce come chiamate API insolite, deployment non autorizzati, attività di mining di criptovalute e credenziali IAM compromesse, analizzando CloudTrail, VPC Flow Logs e log DNS.","optionExplanations":["Amazon Inspector cerca vulnerabilità software note (CVE) — valuta vulnerabilità statiche, non schemi comportamentali che indicano compromissioni in corso dell'account.","AWS Config valuta la configurazione delle risorse rispetto a regole di conformità — non analizza schemi comportamentali nei log per rilevare compromissioni dell'account.","Corretto — GuardDuty analizza CloudTrail, VPC Flow Logs e log DNS usando ML e threat intelligence per rilevare compromissioni dell'account, chiamate API insolite e cryptomining.","AWS Trusted Advisor fornisce raccomandazioni basate sulle best practice — non analizza i dati di log alla ricerca di minacce comportamentali o indicatori di compromissione dell'account."]},
  "292": {"h":"67009a65","question":"Un'azienda deve verificare che il proprio ambiente AWS sia conforme agli standard PCI DSS. Quale servizio AWS aiuta fornendo controlli di conformità automatizzati rispetto agli standard PCI DSS?","options":["Report di conformità di AWS Artifact","AWS Security Hub","Amazon GuardDuty","AWS Config"],"explanation":"AWS Security Hub supporta standard di conformità integrati, tra cui PCI DSS, CIS AWS Foundations e AWS Foundational Security Best Practices. Esegue controlli automatizzati e assegna all'account un punteggio rispetto a ciascuno standard.","optionExplanations":["AWS Artifact fornisce report di conformità AWS scaricabili (PCI DSS AOC, report SOC) — documenta la conformità di AWS stessa, non esegue controlli automatizzati rispetto agli standard sugli ambienti dei clienti.","Corretto — AWS Security Hub fornisce controlli di conformità automatizzati rispetto a PCI DSS, CIS e altri standard, eseguendo verifiche continue e producendo un punteggio di conformità.","Amazon GuardDuty rileva minacce comportamentali — identifica incidenti di sicurezza in corso, non l'aderenza a standard come PCI DSS.","AWS Config valuta la configurazione delle risorse rispetto a regole specifiche — può contribuire ai controlli di conformità PCI DSS ma non fornisce il punteggio di conformità integrato e basato sugli standard offerto da Security Hub."]},
  "293": {"h":"4cef5289","question":"Quale servizio AWS consente ai clienti di eseguire valutazioni di sicurezza automatizzate delle proprie istanze EC2 per verificare porte esposte e vulnerabilità software?","options":["AWS Trusted Advisor","Amazon Inspector","Amazon GuardDuty","AWS Config"],"explanation":"Amazon Inspector analizza automaticamente le istanze EC2 alla ricerca di percorsi di rete aperti (esposizione di rete involontaria) e di vulnerabilità CVE note nei pacchetti software installati, fornendo un punteggio di rischio e indicazioni per la correzione.","optionExplanations":["AWS Trusted Advisor verifica configurazioni di sicurezza di alto livello dell'account — non esegue scansioni dettagliate delle vulnerabilità di singole istanze EC2 o container.","Corretto — Amazon Inspector analizza automaticamente le istanze EC2 alla ricerca di vulnerabilità software (CVE) ed esposizioni di rete involontarie, fornendo punteggi di rischio e indicazioni per la correzione.","Amazon GuardDuty rileva minacce attive tramite l'analisi comportamentale dei log — identifica attacchi in corso, non vulnerabilità software statiche sulle istanze.","AWS Config valuta la configurazione delle risorse rispetto a regole di conformità — traccia lo stato della configurazione ma non cerca CVE nel software né problemi di raggiungibilità di rete."]},
  "294": {"h":"d66cea0d","question":"L'app mobile di un'azienda sanitaria invia informazioni sui pazienti a un'API in esecuzione su AWS. Un auditor richiede che i dati siano protetti mentre viaggiano su internet tra l'app e AWS. Quale approccio soddisfa questo requisito?","options":["Cifrare i volumi EBS con chiavi AWS KMS","Cifrare i dati in rete usando TLS","Cifrare gli oggetti S3 con crittografia lato server tramite KMS","Cifrare gli snapshot e i backup del database"],"explanation":"Proteggere i dati mentre si spostano su una rete significa applicare la crittografia in transito, tipicamente tramite TLS (HTTPS). I servizi AWS forniscono endpoint TLS e l'app dovrebbe connettersi all'API solo tramite HTTPS.","optionExplanations":["La crittografia EBS protegge i dati at rest sui volumi; non fa nulla per i dati che viaggiano tra l'app e AWS.","Corretto — TLS cifra i dati mentre si spostano sulla rete, ovvero applica la crittografia in transito.","La crittografia lato server di S3 protegge gli oggetti archiviati at rest, non i dati che viaggiano su internet.","Cifrare snapshot e backup protegge le copie archiviate at rest, non i dati in transito dall'app mobile."]},
  "295": {"h":"7ca4302e","question":"Quale best practice IAM raccomanda di creare un insieme univoco di credenziali per ogni singolo utente invece di condividere un unico account?","options":["Usare IAM role per tutti gli accessi","Creare utenti IAM individuali","Ruotare regolarmente le credenziali","Abilitare l'MFA per gli utenti privilegiati"],"explanation":"AWS raccomanda di creare utenti IAM individuali per ogni persona che necessita di accesso. Le credenziali condivise rendono impossibile attribuire le azioni a persone specifiche nei log di audit e creano rischi di sicurezza quando qualcuno lascia l'azienda.","optionExplanations":["Usare IAM role per tutti gli accessi è la scelta migliore per servizi e applicazioni — ma per gli utenti umani sono gli utenti IAM individuali (o IAM Identity Center) a garantire la responsabilità individuale e le credenziali univoche necessarie.","Corretto — utenti IAM individuali con credenziali univoche consentono la responsabilità individuale nei log di CloudTrail e permettono di revocare l'accesso a una singola persona senza impatti sugli altri.","Ruotare regolarmente le credenziali è una buona pratica di sicurezza — ma non affronta il problema di fondo, cioè creare identità univoche per ogni persona.","Abilitare l'MFA per gli utenti privilegiati è una best practice di sicurezza — ma riguarda la robustezza dell'autenticazione, non l'univocità delle credenziali per persona."]},
  "296": {"h":"2b8d7dfb","question":"Il team compliance di un'azienda si prepara agli audit raccogliendo a mano screenshot e fogli di calcolo per dimostrare come il proprio ambiente AWS rispetta le normative. Il team vuole un servizio che raccolga automaticamente queste evidenze dal proprio utilizzo di AWS, le mappi su framework come GDPR o SOC 2 e produca report di valutazione pronti per l'audit. Quale servizio AWS dovrebbe usare?","options":["AWS Trusted Advisor","AWS Artifact","AWS Audit Manager","AWS Config"],"explanation":"AWS Audit Manager raccoglie continuamente evidenze dall'utilizzo di AWS da parte del cliente e le mappa su framework di conformità predefiniti o personalizzati. Organizza le evidenze in report di valutazione per gli auditor, sostituendo la raccolta manuale.","optionExplanations":["Trusted Advisor raccomanda miglioramenti basati sulle best practice per costi, sicurezza e prestazioni. Non raccoglie evidenze di audit né crea report di valutazione.","Artifact fornisce i report di audit e gli accordi di AWS stessa, che coprono la parte di AWS nel modello di responsabilità condivisa. Non raccoglie evidenze su come l'azienda usa AWS.","Corretto — Audit Manager raccoglie automaticamente evidenze sull'utilizzo di AWS da parte dell'azienda, le mappa sui framework e produce report di valutazione.","AWS Config registra la configurazione delle risorse e valuta regole. Audit Manager può usare i dati di Config come evidenze, ma Config da solo non organizza le evidenze in report di audit basati sui framework."]},
  "297": {"h":"80af9900","question":"Che cosa significa il termine «data sovereignty» (sovranità dei dati) nel contesto di AWS?","options":["AWS possiede tutti i dati archiviati nel cloud","I dati sono soggetti alle leggi del Paese in cui sono archiviati","AWS esegue automaticamente il backup di tutti i dati dei clienti in più Paesi","I dati sono accessibili solo da dipendenti AWS autorizzati"],"explanation":"La sovranità dei dati significa che i dati sono soggetti alle leggi della giurisdizione in cui sono archiviati. Le Region AWS sono isolate e i dati non si spostano tra Region senza un'azione del cliente. I clienti scelgono la Region per soddisfare i requisiti di residenza e sovranità dei dati.","optionExplanations":["AWS non possiede i dati dei clienti archiviati nel cloud — il cliente ne mantiene sempre la proprietà. AWS è un responsabile del trattamento, non il proprietario dei dati.","Corretto — la sovranità dei dati significa che i dati sono soggetti alle leggi del Paese in cui risiedono, e i clienti controllano in quale Region AWS restano i loro dati per soddisfare tali requisiti.","AWS non replica automaticamente i dati in più Paesi — i dati restano nella Region selezionata, a meno che il cliente non configuri esplicitamente la replica cross-Region.","I dipendenti AWS non hanno accesso predefinito ai dati dei clienti — AWS applica controlli di accesso rigorosi e concede solo accessi limitati e registrati per scopi operativi, con il consenso del cliente."]},
  "298": {"h":"60b08122","question":"Dopo aver rilevato un'attività sospetta, un team di sicurezza ha bisogno, per la propria indagine, dei record del traffico IP in entrata e in uscita dalle interfacce di rete delle proprie istanze EC2 — compresi indirizzi IP di origine e destinazione, porte e se il traffico è stato accettato o rifiutato. Quale funzionalità dovrebbe abilitare il team?","options":["AWS CloudTrail","VPC Flow Logs","AWS Network Firewall","Amazon GuardDuty"],"explanation":"I VPC Flow Logs acquisiscono informazioni sul traffico IP in entrata e in uscita dalle interfacce di rete di una VPC, compresi indirizzi IP di origine e destinazione, porte, protocollo, byte e se il traffico è stato accettato o rifiutato. I record possono essere inviati a CloudWatch Logs o ad Amazon S3 per l'indagine.","optionExplanations":["AWS CloudTrail registra le chiamate API effettuate nell'account. Non registra il traffico di rete che raggiunge le istanze.","Corretto — i VPC Flow Logs registrano IP di origine e destinazione, porte e decisioni di accettazione/rifiuto per il traffico a livello di interfaccia di rete.","AWS Network Firewall filtra e ispeziona il traffico a livello di VPC. Il team ha bisogno dei record del traffico di ogni interfaccia di rete, ed è ciò che forniscono i flow log.","Amazon GuardDuty analizza dati come i flow log per produrre finding sulle minacce, ma non fornisce al team i record dei flussi veri e propri."]},
  "299": {"h":"489fa4c7","question":"Quale servizio AWS consente di definire regole che correggono automaticamente le configurazioni non conformi delle risorse AWS?","options":["AWS CloudTrail","Amazon GuardDuty","AWS Config con azioni di remediation","Scansione delle vulnerabilità di Amazon Inspector"],"explanation":"Le AWS Config Rules valutano la conformità della configurazione delle risorse. È possibile associare azioni di remediation (spesso documenti di Systems Manager Automation) per correggere automaticamente le risorse non conformi, ad esempio abilitando il versioning di un bucket S3 o cifrando volumi EBS non cifrati.","optionExplanations":["AWS CloudTrail registra lo storico delle chiamate API — non valuta la conformità delle configurazioni né attiva una remediation automatica quando le configurazioni violano le policy.","Amazon GuardDuty rileva minacce comportamentali — identifica incidenti di sicurezza ma non valuta la configurazione delle risorse né attiva la correzione delle configurazioni.","Corretto — le AWS Config Rules valutano le configurazioni e possono attivare azioni di remediation automatica (tramite Systems Manager Automation) per correggere le risorse non conformi.","Amazon Inspector cerca vulnerabilità software — non valuta la configurazione delle risorse rispetto a regole di conformità né attiva la correzione delle configurazioni."]},
  "300": {"h":"ac30a7d8","question":"Quali dei seguenti sono esempi di responsabilità del cliente in base allo Shared Responsibility Model di AWS? (Seleziona DUE)","options":["Gestire i permessi e le access key degli utenti IAM","Mantenere la sicurezza fisica dei data center AWS","Configurare la crittografia dei dati at rest in Amazon RDS","Applicare le patch all'hypervisor sugli host EC2"],"explanation":"I clienti sono responsabili di: gestione degli utenti IAM (permessi, rotazione delle access key, MFA) e scelte di crittografia dei dati (abilitare la crittografia RDS, gestire le chiavi KMS). AWS gestisce la sicurezza fisica dei data center e l'hypervisor.","optionExplanations":["Corretto — gestire i permessi e le access key degli utenti IAM è sempre responsabilità del cliente — AWS fornisce IAM ma non gestisce mai i permessi degli utenti né ruota le access key dei clienti.","Mantenere la sicurezza fisica dei data center è responsabilità di AWS — i clienti non hanno accesso fisico né responsabilità sulle strutture dei data center AWS.","Corretto — configurare la crittografia dei dati at rest in RDS (scegliere le impostazioni di crittografia, gestire le chiavi KMS) è responsabilità del cliente anche per i servizi gestiti.","Applicare le patch all'hypervisor sugli host EC2 è responsabilità di AWS — l'hypervisor fa parte del livello infrastrutturale interamente gestito da AWS."]},
  "301": {"h":"b8c76a9d","question":"Un'azienda di giochi online ha subito diversi attacchi DDoS di grandi dimensioni contro i propri server di gioco critici. Vuole avere a disposizione specialisti AWS di DDoS 24/7 e vuole che AWS contatti il proprio team in modo proattivo quando viene rilevato un attacco. Quale servizio AWS dovrebbe usare?","options":["AWS Shield Standard","AWS WAF","AWS Shield Advanced","Amazon GuardDuty"],"explanation":"AWS Shield Advanced è un servizio a pagamento che aggiunge l'accesso 24/7 allo Shield Response Team (SRT) di AWS, il coinvolgimento proattivo quando vengono rilevati attacchi sulle risorse protette, funzionalità avanzate di rilevamento e diagnostica e la protezione dai costi di scalabilità causati dagli attacchi DDoS.","optionExplanations":["Shield Standard è automatico e gratuito per tutti i clienti, ma non include l'accesso agli specialisti DDoS né il coinvolgimento proattivo.","AWS WAF filtra le richieste web in base a regole definite dall'utente; da solo non fornisce un team di risposta agli attacchi DDoS.","Corretto — Shield Advanced fornisce accesso 24/7 agli specialisti DDoS di AWS e un coinvolgimento proattivo durante gli attacchi.","GuardDuty rileva le minacce analizzando log e attività; non è un servizio di protezione DDoS con un team di risposta."]},
  "302": {"h":"6e87c933","question":"Quale delle seguenti opzioni descrive il concetto di 'security as code' in AWS?","options":["Rivedere manualmente i controlli di sicurezza ogni trimestre","Definire i controlli di sicurezza come infrastructure-as-code","Assumere sviluppatori per scrivere internamente software di sicurezza personalizzato","Usare AWS Shield per proteggere tutte le applicazioni dagli attacchi DDoS"],"explanation":"Security as code significa definire i controlli di sicurezza (IAM policy, security group, impostazioni di crittografia, ecc.) nel codice (CloudFormation, CDK, Terraform). Ciò consente il controllo di versione, i test automatizzati e un deployment coerente della sicurezza tra i vari ambienti.","optionExplanations":["Rivedere manualmente i controlli di sicurezza ogni trimestre è l'approccio tradizionale: è incoerente, soggetto a errori e l'opposto del modello di sicurezza automatizzato e basato sul codice.","Corretto — Security as code significa definire i controlli di sicurezza (IAM policy, security group, crittografia) in CloudFormation, CDK o Terraform, consentendo controllo di versione, test e deployment coerente.","Assumere sviluppatori per scrivere software di sicurezza è un'affermazione generica sullo sviluppo di sicurezza: non è lo specifico concetto AWS di definire i controlli di sicurezza tramite template IaC.","Usare AWS Shield per proteggere le applicazioni riguarda la protezione DDoS: non è il concetto di codificare i controlli di sicurezza come codice infrastrutturale riutilizzabile e sotto controllo di versione."]},
  "303": {"h":"2cc2963a","question":"I dipendenti di un'azienda accedono a un'applicazione interna con le credenziali della directory aziendale. Dopo l'accesso, l'applicazione ha bisogno, per ciascun dipendente, di credenziali AWS di breve durata che scadano automaticamente, in modo che non vengano memorizzate access key a lungo termine. Quale servizio AWS emette queste credenziali temporanee?","options":["AWS IAM Access Analyzer","AWS Security Token Service (AWS STS)","Amazon Cognito","AWS Directory Service"],"explanation":"AWS STS emette credenziali temporanee con privilegi limitati, ad esempio quando un utente federato assume un IAM role. È il servizio alla base della federazione delle identità con gli identity provider aziendali, e le sue credenziali scadono automaticamente.","optionExplanations":["IAM Access Analyzer identifica le risorse condivise all'esterno dell'account e aiuta a perfezionare le autorizzazioni. Non emette credenziali.","Corretto — STS emette per i dipendenti federati credenziali temporanee che scadono automaticamente.","Cognito è pensato per i clienti di app web e mobile, non per i dipendenti che accedono a uno strumento interno con la directory aziendale.","Directory Service fornisce directory gestite come Microsoft Active Directory. Autentica gli utenti ma non emette credenziali AWS temporanee."]},
  "304": {"h":"c4bbf435","question":"Quale servizio AWS analizza le IAM policy per identificare le risorse accessibili dall'esterno del proprio account AWS?","options":["AWS Config","Amazon GuardDuty","AWS IAM Access Analyzer","Scansioni di vulnerabilità di Amazon Inspector"],"explanation":"AWS IAM Access Analyzer identifica gli accessi non previsti alle risorse analizzando le policy basate sulle risorse (S3, KMS, Lambda, SQS, ecc.) e segnalando le policy che consentono l'accesso dall'esterno dell'account o dell'organizzazione.","optionExplanations":["AWS Config valuta le configurazioni delle risorse rispetto a regole di conformità: non analizza specificamente le policy IAM basate sulle risorse per individuare accessi esterni.","Amazon GuardDuty rileva le minacce tramite l'analisi dei log: può rilevare se entità esterne stanno accedendo attivamente alle risorse, ma non analizza in modo proattivo le policy alla ricerca di concessioni di accesso non previste.","Corretto — AWS IAM Access Analyzer analizza le policy basate sulle risorse per identificare quelle che concedono accesso dall'esterno dell'account o dell'organizzazione, segnalando gli accessi esterni non previsti.","Amazon Inspector cerca vulnerabilità software in EC2 e nei container: non analizza le IAM policy per individuare autorizzazioni di accesso esterno."]},
  "305": {"h":"789879c2","question":"Un'azienda esegue il proprio software di database su Amazon EC2 e spesso è in ritardo nell'applicare le patch di sicurezza del motore di database. Sta valutando di spostare il database su Amazon RDS. Quale vantaggio di sicurezza otterrebbe l'azienda con questo spostamento?","options":["L'azienda ottiene più controllo sulle versioni del software di database","AWS applica le patch del motore di database e del sistema operativo per l'azienda","AWS si fa carico della gestione degli account utente e delle password del database","L'azienda non ha più bisogno di security group per il database"],"explanation":"Con un servizio gestito come Amazon RDS, AWS applica le patch al motore di database e al sistema operativo sottostante, eliminando la finestra di tempo in cui le vulnerabilità non corrette restano esposte. L'azienda continua a gestire gli utenti del database, l'accesso di rete (security group) e i propri dati.","optionExplanations":["Passare a un servizio gestito dà all'azienda meno controllo, non di più, sul software sottostante. Inoltre non risolve il problema delle patch.","Corretto — Su Amazon RDS, AWS gestisce l'applicazione delle patch al motore di database e al sistema operativo, quindi l'azienda non è più in ritardo con le patch di sicurezza.","In base allo Shared Responsibility Model, l'azienda resta responsabile della gestione degli utenti del database e delle relative credenziali su Amazon RDS.","L'azienda continua a controllare l'accesso di rete a un database RDS tramite i security group. Questa responsabilità non passa ad AWS."]},
  "306": {"h":"37fbc030","question":"Quale servizio AWS fornisce controlli predefiniti delle best practice di sicurezza, organizzati in framework, per aiutare a mantenere una conformità continua?","options":["Amazon GuardDuty","AWS Audit Manager","AWS Security Hub","AWS Trusted Advisor"],"explanation":"AWS Security Hub fornisce controlli di sicurezza automatizzati mappati su standard di conformità (CIS, PCI DSS, NIST). Aggrega i risultati di GuardDuty, Inspector, Macie e altri servizi in una dashboard con un punteggio di sicurezza e priorità.","optionExplanations":["Amazon GuardDuty rileva minacce comportamentali: fornisce risultati in ingresso a Security Hub ma non esegue controlli rispetto a framework di conformità né fornisce un punteggio di sicurezza complessivo.","AWS Audit Manager mappa continuamente l'utilizzo sui framework di conformità e produce report di evidenze, ma è Security Hub il servizio che fornisce controlli di sicurezza automatizzati predefiniti rispetto agli standard di conformità.","Corretto — AWS Security Hub fornisce controlli automatizzati delle best practice di sicurezza mappati su CIS, PCI DSS, NIST e altri standard, con una dashboard di punteggio di sicurezza e priorità.","AWS Trusted Advisor fornisce raccomandazioni sulle best practice: non esegue controlli rispetto a framework di conformità né aggrega i risultati in un punteggio di sicurezza unificato."]},
  "307": {"h":"8ac4df3d","question":"Un'azienda vuole impedire a qualsiasi account della propria AWS Organization di disattivare il logging di CloudTrail. Qual è il controllo PIÙ efficace?","options":["Inviare avvisi email tramite SNS quando CloudTrail viene disattivato","Applicare una SCP che neghi cloudtrail:StopLogging e DeleteTrail","Usare IAM policy in ogni account membro per negare queste azioni","Abilitare regole di AWS Config per rilevare le modifiche a CloudTrail"],"explanation":"Le SCP applicate a livello di unità organizzativa o di root non possono essere scavalcate da alcuna IAM policy negli account membri, nemmeno dagli amministratori degli account. Una SCP che nega cloudtrail:StopLogging e cloudtrail:DeleteTrail impone il logging in tutta l'organizzazione.","optionExplanations":["Inviare avvisi email quando CloudTrail viene disattivato significa che il logging si è già interrotto: è un rilevamento reattivo, non un controllo preventivo che impedisce l'azione.","Corretto — Una SCP sulla root dell'organizzazione nega cloudtrail:StopLogging e cloudtrail:DeleteTrail in tutti gli account e non può essere scavalcata nemmeno dagli amministratori degli account.","Le IAM policy di ciascun account possono essere scavalcate dagli amministratori dell'account: non sono un controllo preventivo affidabile perché gli amministratori possono modificarle o rimuoverle.","AWS Config rileva le configurazioni non conformi a posteriori: c'è una finestra di tempo in cui CloudTrail è già disattivato prima che possa avvenire la correzione."]},
  "308": {"h":"da1d0e2d","question":"Quale funzionalità di AWS Key Management Service (KMS) consente di creare una traccia di chi ha usato quale chiave per decrittografare quali dati e quando?","options":["Rotazione automatica annuale delle chiavi","Autorizzazioni della key policy","Logging tramite AWS CloudTrail","Alias delle chiavi KMS"],"explanation":"Ogni chiamata API di KMS (Encrypt, Decrypt, GenerateDataKey, ecc.) viene registrata in AWS CloudTrail. Ciò fornisce una traccia di audit completa delle operazioni crittografiche: chi ha usato quale chiave, su quale risorsa, in quale momento; un elemento essenziale per la conformità e le analisi forensi.","optionExplanations":["La rotazione delle chiavi crea automaticamente nuovo materiale crittografico per una chiave KMS secondo una pianificazione: gestisce l'età della chiave, non la registrazione di chi l'ha usata per decrittografare i dati.","La key policy definisce chi può amministrare e usare una chiave KMS: controlla le autorizzazioni di accesso ma non fornisce una traccia di quando e da chi la chiave è stata usata.","Corretto — AWS CloudTrail registra ogni operazione crittografica di KMS (Encrypt, Decrypt, GenerateDataKey), fornendo una traccia di audit completa dell'utilizzo delle chiavi.","Gli alias delle chiavi KMS forniscono nomi leggibili per le chiavi: sono una comodità di gestione, non un meccanismo per tracciare la cronologia di utilizzo delle chiavi."]},
  "309": {"h":"d9ac8098","question":"Quale opzione di acquisto di Amazon EC2 offre lo sconto maggiore (fino al 90%) ma può essere interrotta da AWS con un preavviso di 2 minuti quando la capacità è necessaria?","options":["On-Demand Instances","Reserved Instances","Spot Instances","Dedicated Hosts"],"explanation":"Le EC2 Spot Instances usano la capacità inutilizzata di AWS con sconti fino al 90% rispetto all'On-Demand. AWS può recuperarle con un preavviso di 2 minuti quando la capacità serve altrove. Sono ideali per workload tolleranti ai guasti, stateless o batch.","optionExplanations":["Le On-Demand Instances sono fatturate al secondo senza impegno: hanno il costo unitario più alto e non offrono alcuno sconto rispetto alle Spot Instances.","Le Reserved Instances offrono sconti a fronte di impegni di 1 o 3 anni: garantiscono risparmi significativi ma non possono essere recuperate da AWS e richiedono un impegno.","Corretto — Le Spot Instances usano la capacità EC2 inutilizzata con uno sconto fino al 90%. AWS può interromperle con un preavviso di 2 minuti quando la capacità è necessaria.","I Dedicated Hosts sono l'opzione EC2 più costosa e forniscono un server fisico dedicato: non sono una strategia di ottimizzazione dei costi."]},
  "310": {"h":"2e882375","question":"Un'azienda esegue un'applicazione HR interna sugli stessi tipi di istanza EC2 in una sola Region, 24 ore su 24, e prevede che continui a funzionare invariata per i prossimi tre anni. È disposta a impegnarsi per un periodo di 1 o 3 anni in cambio di un forte sconto rispetto all'On-Demand. Quale opzione di acquisto EC2 dovrebbe scegliere?","options":["Spot Instances","On-Demand Instances","Reserved Instances","On-Demand Capacity Reservations"],"explanation":"Le Reserved Instances offrono uno sconto significativo rispetto ai prezzi On-Demand in cambio di un impegno di 1 o 3 anni su specifici attributi di istanza in una Region. Sono adatte a workload stabili e prevedibili, come un'applicazione che gira continuamente sugli stessi tipi di istanza. (I Savings Plans sono un'altra opzione basata su impegno per questo tipo di workload.)","optionExplanations":["Le Spot Instances possono essere interrotte quando AWS ha bisogno di recuperare la capacità, il che non si addice a un'applicazione che deve funzionare 24 ore su 24.","Le On-Demand Instances non richiedono impegno, ma non offrono lo sconto che l'azienda desidera in cambio di un impegno a lungo termine.","Corretto — Le Reserved Instances scambiano un impegno di 1 o 3 anni con un forte sconto, ideale per questo workload stabile e prevedibile.","Le On-Demand Capacity Reservations riservano capacità senza un impegno temporale, ma da sole sono fatturate alle tariffe On-Demand e non offrono sconti."]},
  "311": {"h":"adb69d0e","question":"Quale modello di prezzo del compute AWS offre la flessibilità di impegnarsi su una quantità costante di utilizzo di calcolo ($/ora) per 1 o 3 anni, applicabile a EC2, Lambda e Fargate?","options":["Reserved Instances","Spot Instances","Savings Plans","Dedicated Hosts"],"explanation":"Gli AWS Savings Plans offrono sconti flessibili (fino al 66%) a fronte dell'impegno su una quantità costante di utilizzo in $/ora per 1 o 3 anni. A differenza delle RI, i Savings Plans si applicano automaticamente a EC2 (qualsiasi famiglia di istanze/Region), Lambda e Fargate.","optionExplanations":["Le Reserved Instances sono legate a una specifica famiglia di istanze e Region: non hanno la flessibilità tra famiglie, Region e servizi diversi che offrono i Savings Plans.","Le Spot Instances offrono sconti ma possono essere interrotte: non sono un modello basato su impegno applicabile a Lambda e Fargate.","Corretto — I Savings Plans prevedono l'impegno su un importo di utilizzo in $/ora per 1-3 anni, applicando automaticamente gli sconti a EC2 (qualsiasi famiglia/Region), Lambda e Fargate.","I Dedicated Hosts sono server fisici allocati per la conformità alle licenze: non sono un modello flessibile di impegno in $/ora."]},
  "312": {"h":"832f2dea","question":"Un'azienda vuole spostare un database su Amazon EC2. La sua licenza software è calcolata in base al numero di socket e core fisici della CPU, e il fornitore richiede che l'azienda comunichi queste informazioni. L'azienda ha bisogno di un server fisico dedicato al proprio uso, con visibilità su socket e core. Quale opzione EC2 dovrebbe usare?","options":["Dedicated Instances","Spot Instances","Reserved Instances","Dedicated Hosts"],"explanation":"Gli EC2 Dedicated Hosts sono server fisici interamente dedicati a un solo cliente. Mostrano i socket, i core e l'ID host del server, informazioni di cui l'azienda ha bisogno per rispettare licenze legate all'hardware fisico.","optionExplanations":["Le Dedicated Instances girano su hardware dedicato a un solo cliente, ma non offrono visibilità su socket, core o host. Ciò non soddisfa il requisito di rendicontazione delle licenze.","Le Spot Instances usano capacità inutilizzata a prezzo scontato e possono essere interrotte. Non forniscono un server fisico dedicato.","Le Reserved Instances sono uno sconto di fatturazione a fronte di un impegno. Non forniscono un server dedicato né visibilità sul suo hardware.","Corretto — I Dedicated Hosts forniscono un intero server fisico con visibilità su socket e core ai fini delle licenze."]},
  "313": {"h":"755cb2db","question":"Quale servizio AWS fornisce un servizio di orchestrazione di container serverless e completamente gestito, che elimina la necessità di gestire l'infrastruttura sottostante per i cluster Kubernetes?","options":["Amazon ECS","Amazon EKS con launch type EC2","Amazon EKS con Fargate","AWS App Runner"],"explanation":"Amazon EKS con AWS Fargate è un'esperienza Kubernetes serverless. AWS gestisce il control plane e i nodi sottostanti: i clienti si limitano a definire ed eseguire i pod. Non ci sono istanze EC2 da provisionare, aggiornare o scalare.","optionExplanations":["Amazon ECS è il servizio proprietario di orchestrazione di container di AWS: non fornisce le API Kubernetes né un control plane Kubernetes gestito.","Amazon EKS con launch type EC2 richiede ai clienti di provisionare e gestire i worker node EC2: fornisce Kubernetes gestito ma non un'esperienza completamente serverless.","Corretto — Amazon EKS con Fargate è Kubernetes serverless: AWS gestisce sia il control plane sia l'infrastruttura dei nodi sottostanti. I clienti definiscono solo i pod.","AWS App Runner esegue il deployment di app containerizzate ma non è un servizio Kubernetes: è un'astrazione di livello più alto e più semplice, non una piattaforma di orchestrazione Kubernetes gestita."]},
  "314": {"h":"e61c822e","question":"Quale servizio AWS esegue container Docker senza richiedere la gestione dell'infrastruttura EC2 sottostante?","options":["Amazon EC2 con Docker installato","AWS Lambda","AWS Fargate","AWS Elastic Beanstalk"],"explanation":"AWS Fargate è un motore di calcolo serverless per container. Funziona con ECS ed EKS ed elimina la necessità di provisionare, configurare o scalare istanze EC2. Si definisce il container e Fargate si occupa del resto.","optionExplanations":["Amazon EC2 con Docker installato richiede la gestione del server EC2 sottostante: patch, capacity planning e gestione dell'infrastruttura sono tutti a carico del cliente.","AWS Lambda esegue singole funzioni di codice in risposta a eventi: non è progettato per eseguire container Docker con le loro specifiche configurazioni di risorse.","Corretto — AWS Fargate è un motore serverless per container: si definisce il container (immagine, CPU, memoria) e Fargate gestisce tutta l'infrastruttura EC2 sottostante.","AWS Elastic Beanstalk esegue il deployment di applicazioni web su istanze EC2 gestite: è un PaaS per applicazioni, non un motore serverless per container per workload Docker."]},
  "315": {"h":"40c156c1","question":"Un'azienda di videogiochi gestisce server di gioco dedicati e server web ad alte prestazioni le cui prestazioni sono limitate principalmente dalla potenza del processore. Quale categoria di istanze Amazon EC2 è la PIÙ adatta?","options":["Ottimizzate per la memoria","Ottimizzate per il calcolo","Ottimizzate per lo storage","Calcolo accelerato"],"explanation":"Le istanze ottimizzate per il calcolo offrono un rapporto elevato tra potenza del processore e memoria e sono progettate per applicazioni vincolate dalla CPU. Gli usi tipici includono server di gioco dedicati, server web ad alte prestazioni, elaborazione batch, transcodifica multimediale e modellazione scientifica.","optionExplanations":["Le istanze ottimizzate per la memoria sono progettate per workload che elaborano grandi set di dati in memoria, come i database in-memory, non per server di gioco vincolati dalla CPU.","Corretto — Le istanze ottimizzate per il calcolo offrono elevate prestazioni del processore per workload vincolati dalla CPU, come server di gioco e server web ad alte prestazioni.","Le istanze ottimizzate per lo storage offrono accessi sequenziali in lettura e scrittura molto elevati a grandi set di dati locali, che in questo caso non sono il collo di bottiglia.","Le istanze a calcolo accelerato usano acceleratori hardware come le GPU per attività come machine learning e grafica, non per servire richieste generiche vincolate dalla CPU."]},
  "316": {"h":"e7dcdcca","question":"Il team IT di un'azienda vuole che i dipendenti possano avviare solo risorse AWS pre-approvate, come uno stack standard di server web, da un catalogo self-service, rimanendo entro le regole di governance aziendali. Quale servizio AWS soddisfa questa esigenza?","options":["AWS Service Catalog","AWS Marketplace","AWS Config","AWS Elastic Beanstalk"],"explanation":"AWS Service Catalog consente alle organizzazioni di creare e gestire cataloghi di servizi IT approvati, definiti come template di infrastruttura. Gli utenti possono avviare autonomamente questi prodotti approvati, mentre gli amministratori controllano quali prodotti, versioni e configurazioni sono consentiti.","optionExplanations":["Corretto — Service Catalog fornisce un catalogo self-service curato di prodotti approvati, aiutando a imporre la governance e configurazioni coerenti.","AWS Marketplace è un catalogo di software e servizi di terze parti da acquistare. Non limita i dipendenti alle configurazioni di risorse approvate internamente.","AWS Config registra e valuta le configurazioni delle risorse dopo che sono state create. Non offre un catalogo self-service per avviare risorse approvate.","Elastic Beanstalk esegue il deployment e gestisce applicazioni web, ma non fornisce ai dipendenti un catalogo governato di prodotti pre-approvati."]},
  "317": {"h":"724e2ba5","question":"Uno studio di architettura conserva per molti anni i file dei progetti completati. I file vengono recuperati solo una o due volte l'anno, quando un cliente li richiede, ed è accettabile attendere diverse ore per un recupero. Lo studio vuole costi di storage inferiori rispetto alle classi di storage che offrono accesso in millisecondi. Quale classe di storage S3 dovrebbe usare lo studio?","options":["S3 Standard","S3 Standard-IA","S3 Glacier Flexible Retrieval","S3 Glacier Instant Retrieval"],"explanation":"S3 Glacier Flexible Retrieval è progettata per dati di archivio a cui si accede raramente, ad esempio una o due volte l'anno. I recuperi richiedono da minuti a ore e, in cambio, il costo di storage è inferiore rispetto alle classi che forniscono accesso in millisecondi.","optionExplanations":["S3 Standard è progettata per dati a cui si accede frequentemente, con accesso in millisecondi. È l'opzione più costosa per archivi recuperati raramente.","S3 Standard-IA offre accesso in millisecondi per dati a cui si accede di rado, ma il suo costo di storage è più alto di quello di una classe di archiviazione e lo studio non ha bisogno di un accesso rapido.","Corretto — S3 Glacier Flexible Retrieval è una classe di archiviazione a basso costo per dati a cui si accede una o due volte l'anno, quando sono accettabili recuperi da minuti a ore.","S3 Glacier Instant Retrieval fornisce accesso in millisecondi agli archivi, di cui lo studio non ha bisogno, e ha un costo di storage più alto di Glacier Flexible Retrieval."]},
  "318": {"h":"2e2fbb31","question":"Un'azienda vuole proteggere i propri server applicativi on-premises replicandoli continuamente su AWS, in modo da poter avviare rapidamente i server ripristinati in AWS se il suo data center dovesse guastarsi. Quale servizio AWS è progettato per questo scopo?","options":["AWS Elastic Disaster Recovery","AWS Backup","AWS DataSync","AWS Application Migration Service"],"explanation":"AWS Elastic Disaster Recovery replica continuamente server on-premises o basati su cloud in un'area di staging a basso costo in AWS. In caso di disastro, può avviare i server ripristinati in AWS in pochi minuti, riducendo i tempi di inattività e la perdita di dati.","optionExplanations":["Corretto — Elastic Disaster Recovery replica continuamente i server su AWS e avvia rapidamente le istanze di ripristino quando l'ambiente di origine si guasta.","AWS Backup pianifica e gestisce i backup in modo centralizzato. Non replica continuamente interi server per un failover rapido.","DataSync trasferisce file e oggetti tra sistemi di storage. Non replica né avvia interi server applicativi.","Application Migration Service replica i server per una migrazione lift-and-shift una tantum, non per una protezione continua di disaster recovery."]},
  "319": {"h":"aee07fcb","question":"Un ospedale archivia immagini mediche a cui si accede solo circa una volta al trimestre, ma quando un medico ne richiede una deve essere restituita in millisecondi. L'ospedale vuole il costo di storage più basso che soddisfi questo requisito. Quale classe di storage S3 dovrebbe usare?","options":["S3 Glacier Instant Retrieval","S3 Glacier Flexible Retrieval","S3 Glacier Deep Archive","S3 Standard"],"explanation":"S3 Glacier Instant Retrieval è progettata per dati di lunga durata a cui si accede raramente, ad esempio una volta al trimestre, ma che richiedono comunque un recupero in millisecondi. Offre un costo di storage inferiore a S3 Standard e S3 Standard-IA, con costi di recupero per richiesta più elevati.","optionExplanations":["Corretto — S3 Glacier Instant Retrieval fornisce accesso in millisecondi a dati usati raramente, con un basso costo di storage.","S3 Glacier Flexible Retrieval ha tempi di recupero da minuti a ore, quindi non può restituire le immagini in millisecondi.","S3 Glacier Deep Archive ha il costo di storage più basso ma il recupero richiede ore, il che non soddisfa il requisito dei millisecondi.","S3 Standard restituisce i dati in millisecondi, ma è progettata per dati a cui si accede frequentemente e ha un costo di storage più alto di Glacier Instant Retrieval."]},
  "320": {"h":"fa7fa80a","question":"Quale servizio di storage AWS fornisce volumi di storage a livello di blocco che possono essere collegati a una singola istanza EC2?","options":["Amazon S3","Amazon EFS","Amazon EBS","Amazon FSx"],"explanation":"Amazon EBS (Elastic Block Store) fornisce storage a blocchi persistente per le istanze EC2, simile a un disco rigido. I volumi EBS si collegano a un'istanza EC2 alla volta (tranne con Multi-Attach io1/io2) e persistono indipendentemente dal ciclo di vita dell'istanza.","optionExplanations":["Amazon S3 è uno storage a oggetti accessibile tramite API: non fornisce volumi di storage a livello di blocco collegabili alle istanze EC2.","Amazon EFS è un file system NFS condiviso per più istanze EC2: è uno storage a livello di file (NFS), non volumi a livello di blocco collegati a singole istanze.","Corretto — Amazon EBS fornisce volumi di storage a blocchi persistenti che si collegano a una singola istanza EC2 alla volta, funzionando come un disco rigido.","Amazon FSx fornisce file system gestiti (Lustre, Windows File Server, NetApp ONTAP): è un servizio di file system, non volumi di storage a blocchi grezzi per EC2."]},
  "321": {"h":"cf91ef82","question":"Uno sviluppatore ha eliminato per errore, pochi minuti fa, alcune righe importanti da un database Amazon RDS di produzione. Il team vuole ripristinare il database allo stato in cui si trovava subito prima dell'errore. Quale funzionalità di RDS dovrebbe usare?","options":["Point-in-time recovery dai backup automatici","Promozione di una read replica a istanza autonoma","Failover sull'istanza standby Multi-AZ","Abilitazione di Amazon RDS Performance Insights"],"explanation":"I backup automatici di RDS combinano snapshot giornalieri con i log delle transazioni, consentendo il point-in-time recovery a qualsiasi secondo all'interno del periodo di retention dei backup. Il ripristino crea una nuova istanza DB con i dati com'erano subito prima dell'eliminazione.","optionExplanations":["Corretto — Il point-in-time recovery usa i backup automatici per ripristinare il database a un momento specifico, ad esempio subito prima che le righe venissero eliminate.","Una read replica riceve le stesse modifiche dell'istanza primaria, quindi l'eliminazione è già stata replicata anche su di essa.","Lo standby Multi-AZ è mantenuto sincronizzato con l'istanza primaria, quindi contiene la stessa eliminazione e non può annullarla.","Performance Insights aiuta ad analizzare il carico del database e i problemi di prestazioni. Non può ripristinare dati eliminati."]},
  "322": {"h":"db95a9f2","question":"Un'azienda esegue un database MySQL on-premises e vuole spostarlo su un database AWS completamente gestito. Vuole un motore creato da AWS per il cloud, compatibile con MySQL, che offra un throughput superiore a MySQL standard e faccia crescere automaticamente il proprio storage. Quale servizio AWS soddisfa MEGLIO questi requisiti?","options":["Amazon RDS for MySQL","Amazon Aurora","Amazon DynamoDB","Amazon Redshift"],"explanation":"Amazon Aurora è un database relazionale cloud-native completamente gestito, creato da AWS e compatibile con MySQL e PostgreSQL. Il suo livello di storage distribuito offre prestazioni superiori a MySQL standard, replica i dati su più Availability Zone e fa crescere lo storage automaticamente.","optionExplanations":["RDS for MySQL è gestito, ma esegue il motore MySQL standard anziché un motore creato da AWS per un throughput più elevato.","Corretto — Aurora è il motore creato da AWS, compatibile con MySQL, con prestazioni superiori e storage che cresce automaticamente.","DynamoDB è un database NoSQL chiave-valore e a documenti, quindi non è compatibile con l'applicazione MySQL dell'azienda.","Redshift è un data warehouse per l'analisi, non un database compatibile con MySQL per le transazioni dell'applicazione."]},
  "323": {"h":"757f4177","question":"Quale servizio AWS fornisce un livello di caching in-memory completamente gestito, compatibile con Redis e Memcached, usato per ridurre il carico sul database?","options":["Amazon DynamoDB Accelerator (DAX)","Amazon RDS Read Replicas","Amazon ElastiCache","Amazon MemoryDB"],"explanation":"Amazon ElastiCache è un servizio di caching in-memory completamente gestito che supporta Redis e Memcached. Posizionare un livello di cache davanti a un database relazionale riduce la latenza di lettura da millisecondi a microsecondi e diminuisce il carico sul database.","optionExplanations":["Amazon DynamoDB Accelerator (DAX) è una cache in-memory specifica per DynamoDB: non supporta Redis/Memcached né memorizza nella cache dati di altri database come RDS.","Le Amazon RDS Read Replicas distribuiscono il traffico di lettura su database replica: riducono il carico sul database primario ma hanno comunque una latenza basata su disco, non risposte in-memory in microsecondi.","Corretto — Amazon ElastiCache fornisce caching in-memory gestito con Redis e Memcached, riducendo la latenza di lettura da millisecondi a microsecondi e abbassando il carico sul database.","Amazon MemoryDB for Redis è un database in-memory durevole compatibile con Redis: pur essendo correlato, è ElastiCache il principale servizio di caching in-memory per ridurre il carico sul database."]},
  "324": {"h":"ce5e8878","question":"Un'azienda di vendita al dettaglio vuole combinare diversi anni di dati di vendita provenienti da molti sistemi ed eseguire query SQL complesse per i report aziendali. Eseguire questi report sul database transazionale rallenta il negozio online. L'azienda ha bisogno di un servizio gestito progettato per l'analisi su set di dati molto grandi. Quale servizio AWS dovrebbe usare?","options":["Amazon RDS","Amazon DynamoDB","Amazon Redshift","Amazon Aurora"],"explanation":"Amazon Redshift è un data warehouse completamente gestito creato per l'analisi. Archivia i dati per colonne ed esegue le query in parallelo, così i report SQL complessi su grandi set di dati storici vengono eseguiti rapidamente senza influire sul database transazionale.","optionExplanations":["RDS è un database relazionale gestito per workload transazionali, ovvero dove i report lenti vengono già eseguiti. Non è un data warehouse per l'analisi su larga scala.","DynamoDB è un database NoSQL chiave-valore per ricerche transazionali rapide. Non è progettato per analisi SQL complesse su anni di dati.","Corretto — Redshift è un data warehouse progettato per query SQL analitiche complesse su grandi set di dati.","Aurora è un database relazionale ad alte prestazioni per workload transazionali. Non è un data warehouse dedicato."]},
  "325": {"h":"ab2c0052","question":"Quale servizio AWS fornisce la distribuzione di contenuti memorizzando nella cache copie dei contenuti nelle Edge Location di tutto il mondo per ridurre la latenza per gli utenti finali?","options":["AWS Global Accelerator","Amazon Route 53","Amazon CloudFront","AWS Direct Connect"],"explanation":"Amazon CloudFront è la Content Delivery Network (CDN) di AWS. Memorizza nella cache contenuti statici e dinamici in centinaia di Edge Location in tutto il mondo, servendo gli utenti dalla posizione più vicina e riducendo il carico sul server di origine e la latenza.","optionExplanations":["AWS Global Accelerator instrada il traffico sulla rete backbone globale di AWS: migliora le prestazioni TCP/UDP usando IP anycast ma non memorizza contenuti nella cache nelle Edge Location.","Amazon Route 53 è un servizio DNS per la risoluzione dei nomi di dominio: instrada il traffico verso gli endpoint ma non memorizza contenuti nella cache nelle Edge Location.","Corretto — Amazon CloudFront è il servizio CDN che memorizza nella cache i contenuti in centinaia di Edge Location in tutto il mondo, servendo gli utenti dalla posizione più vicina per ridurre la latenza.","AWS Direct Connect fornisce un collegamento privato dedicato tra l'ambiente on-premises e AWS: è un servizio di connettività, non una CDN per il caching dei contenuti."]},
  "326": {"h":"84a79e90","question":"Un'azienda di video in streaming vuole mostrare a ogni spettatore consigli personalizzati sui film in base alla sua cronologia di visualizzazione, senza bisogno di competenze interne di machine learning. Quale servizio AWS dovrebbe usare?","options":["Amazon Personalize","Amazon Comprehend","Amazon Rekognition","Amazon OpenSearch Service"],"explanation":"Amazon Personalize è un servizio di machine learning completamente gestito che genera raccomandazioni individuali in tempo reale a partire dai dati di interazione degli utenti. Usa lo stesso tipo di tecnologia impiegata da Amazon.com e non richiede alcuna esperienza pregressa di machine learning.","optionExplanations":["Corretto — Amazon Personalize crea modelli di raccomandazione a partire dalla cronologia delle interazioni degli utenti per fornire suggerimenti personalizzati.","Comprehend usa l'elaborazione del linguaggio naturale per individuare sentiment, entità e frasi chiave nel testo. Non genera raccomandazioni.","Rekognition analizza immagini e video per rilevare oggetti, volti e testo. Non consiglia contenuti in base alla cronologia di visualizzazione.","OpenSearch Service fornisce funzionalità di ricerca e analisi dei log. Non addestra modelli di raccomandazione a partire dalla cronologia di visualizzazione."]},
  "327": {"h":"72d10683","question":"Quale servizio AWS è un servizio web DNS (Domain Name System) scalabile e ad alta disponibilità che fornisce anche la registrazione di domini e i controlli di integrità (health check)?","options":["Amazon CloudFront","AWS Global Accelerator","Amazon Route 53","AWS Direct Connect"],"explanation":"Amazon Route 53 è il servizio DNS di AWS. Fornisce registrazione di domini, instradamento DNS e health check. Le routing policy includono Simple, Weighted, Latency-based, Geolocation, Geoproximity, Failover e Multivalue Answer.","optionExplanations":["Amazon CloudFront è una CDN per il caching dei contenuti: non fornisce instradamento DNS, registrazione di domini né health check.","AWS Global Accelerator fornisce IP anycast statici per l'instradamento del traffico applicativo: non fornisce servizi DNS né registrazione di domini.","Corretto — Amazon Route 53 è il servizio DNS scalabile che fornisce registrazione di domini, instradamento DNS con più policy e health check.","AWS Direct Connect fornisce una connessione di rete privata dedicata: è un servizio di connettività, non un servizio DNS."]},
  "328": {"h":"0a945dd2","question":"Una banca trasferisce ogni giorno grandi volumi di dati tra il proprio data center e AWS. Il team di compliance non consente che questo traffico passi sulla rete Internet pubblica e la banca ha bisogno di prestazioni di rete costanti. Quale servizio AWS dovrebbe usare la banca?","options":["AWS Site-to-Site VPN","Amazon VPC","AWS Direct Connect","AWS Transit Gateway"],"explanation":"AWS Direct Connect fornisce una connessione di rete privata dedicata tra un data center on-premises e AWS che non transita sulla rete Internet pubblica. Offre prestazioni di rete più costanti rispetto alle connessioni basate su Internet.","optionExplanations":["Site-to-Site VPN cifra il traffico, ma il tunnel transita comunque sulla rete Internet pubblica, cosa che il team di compliance non consente, e le sue prestazioni possono variare.","Amazon VPC è la rete isolata all'interno di AWS. Da sola non fornisce una connessione privata dal data center della banca.","Corretto — Direct Connect è una connessione privata dedicata che evita la rete Internet pubblica e fornisce prestazioni di rete costanti.","Transit Gateway è un hub che collega VPC e reti, ma ha comunque bisogno di una connessione come Direct Connect o VPN per raggiungere il data center."]},
  "329": {"h":"767164a8","question":"Quale servizio AWS fornisce una sezione logicamente isolata del cloud AWS in cui i clienti possono avviare risorse in una rete virtuale da loro definita?","options":["Amazon EC2","AWS Direct Connect","Amazon VPC","AWS Transit Gateway"],"explanation":"Amazon Virtual Private Cloud (VPC) è una rete logicamente isolata in AWS. I clienti controllano intervalli di indirizzi IP, subnet, tabelle di routing, internet gateway e impostazioni di sicurezza. Tutti gli account AWS dispongono di un VPC predefinito in ogni Region.","optionExplanations":["Amazon EC2 è un servizio di calcolo per macchine virtuali: non è il servizio di rete virtuale; le istanze EC2 vengono avviate all'interno di un VPC.","AWS Direct Connect fornisce un collegamento privato dedicato dall'ambiente on-premises ad AWS: è un servizio di connettività, non la definizione della rete virtuale isolata.","Corretto — Amazon VPC è la rete virtuale logicamente isolata definita dai clienti, con pieno controllo su intervalli IP, subnet, tabelle di routing e gateway.","AWS Transit Gateway collega più VPC tramite un hub centrale: instrada il traffico tra VPC ma non è il servizio che crea le reti virtuali isolate."]},
  "330": {"h":"070f1fbe","question":"I server di backend di un'azienda girano in una subnet privata. Devono chiamare l'API pubblica di un fornitore di pagamenti di terze parti su Internet, ma nessuno da Internet deve poter avviare una connessione verso questi server. Quale componente di rete AWS dovrebbe usare l'azienda?","options":["Solo un internet gateway","VPC peering","NAT gateway","AWS PrivateLink"],"explanation":"Un NAT gateway posizionato in una subnet pubblica consente alle risorse nelle subnet private di avviare connessioni in uscita verso Internet, come le chiamate a un'API esterna, bloccando al contempo le connessioni avviate da Internet.","optionExplanations":["Usare solo un internet gateway richiederebbe di collocare i server in una subnet pubblica con indirizzi IP pubblici, il che li renderebbe raggiungibili da Internet.","Il VPC peering collega privatamente due VPC; non fornisce accesso a un'API pubblica su Internet.","Corretto — un NAT gateway consente le chiamate in uscita verso l'API di pagamento bloccando le connessioni in ingresso da Internet.","PrivateLink fornisce accesso privato a servizi esposti tramite VPC endpoint, non un accesso generico in uscita a un'API pubblica su Internet."]},
  "331": {"h":"fb07e217","question":"Quale servizio AWS consente di collegare più VPC e reti on-premises tramite un hub centrale, semplificando la topologia di rete?","options":["VPC Peering","AWS Direct Connect","AWS Transit Gateway","AWS PrivateLink"],"explanation":"AWS Transit Gateway funge da router cloud per collegare più VPC e reti on-premises. Invece di creare una rete magliata completa di connessioni VPC peering, tutte le reti si collegano all'hub Transit Gateway, semplificando notevolmente le architetture di rete su larga scala.","optionExplanations":["Il VPC Peering collega direttamente due VPC: con molti VPC richiede una complessa rete magliata completa di connessioni, a differenza del più semplice modello hub-and-spoke di Transit Gateway.","AWS Direct Connect fornisce un collegamento privato dedicato dall'ambiente on-premises ad AWS: è un servizio di connettività fisica, non un hub di routing di rete per più VPC.","Corretto — AWS Transit Gateway funge da hub centrale che collega più VPC e reti on-premises, semplificando la topologia di rete su larga scala.","AWS PrivateLink fornisce connessioni private tramite endpoint per servizi specifici: espone privatamente singoli servizi, non è un hub di routing generico per più connessioni di rete."]},
  "332": {"h":"04c85019","question":"L'applicazione di un'azienda gira nelle subnet private di un VPC che non ha accesso a Internet. L'applicazione deve inviare messaggi ad Amazon SQS e il team di sicurezza richiede che questo traffico non transiti mai sulla rete Internet pubblica. Quale servizio o funzionalità AWS dovrebbe usare l'azienda?","options":["VPC peering","AWS Transit Gateway","AWS PrivateLink","Internet gateway"],"explanation":"AWS PrivateLink fornisce connettività privata ai servizi AWS tramite interface VPC endpoint. L'applicazione raggiunge Amazon SQS usando indirizzi IP privati all'interno del VPC, quindi il traffico rimane sulla rete AWS e non servono né un internet gateway né un NAT.","optionExplanations":["Il VPC peering collega due VPC tra loro. Non fornisce accesso privato a un servizio AWS come SQS.","Transit Gateway collega molti VPC e reti on-premises tramite un hub centrale. Da solo non fornisce accesso privato alle API dei servizi AWS.","Corretto — Un interface endpoint PrivateLink consente all'applicazione di raggiungere SQS in modo privato senza usare Internet.","Un internet gateway collega il VPC alla rete Internet pubblica, cosa che il team di sicurezza vieta per questo traffico."]},
  "333": {"h":"c54688e1","question":"Quale servizio AWS gestito di code di messaggi disaccoppia i componenti delle applicazioni distribuite consentendo l'elaborazione asincrona dei messaggi?","options":["Amazon SNS","Amazon EventBridge","Amazon SQS","AWS Step Functions"],"explanation":"Amazon SQS (Simple Queue Service) fornisce code di messaggi completamente gestite. I producer inviano messaggi a una coda; i consumer li prelevano ed elaborano in modo indipendente. Ciò disaccoppia i componenti e assorbe i picchi di traffico, ad esempio tra un livello web e un livello di elaborazione.","optionExplanations":["Amazon SNS è un servizio di notifica pub/sub che distribuisce i messaggi a più sottoscrittori contemporaneamente: non è una coda point-to-point in cui un solo consumer elabora ciascun messaggio.","Amazon EventBridge è un event bus che instrada gli eventi verso i target in base a regole: instrada eventi, non accoda messaggi per l'elaborazione indipendente da parte dei consumer.","Corretto — Amazon SQS fornisce code di messaggi gestite per una comunicazione asincrona e disaccoppiata tra componenti, conservando i messaggi finché i consumer non possono elaborarli.","AWS Step Functions orchestra workflow in più passaggi: è un servizio di workflow, non una coda di messaggi per disaccoppiare producer e consumer indipendenti."]},
  "334": {"h":"56330269","question":"Quale servizio AWS è un servizio di messaggistica pub/sub completamente gestito in grado di distribuire (fan-out) i messaggi a molti sottoscrittori contemporaneamente tramite email, SMS, Lambda, SQS ed endpoint HTTP?","options":["Amazon SQS","AWS Step Functions","Amazon SNS","Amazon Kinesis"],"explanation":"Amazon SNS (Simple Notification Service) è un servizio di messaggistica pub/sub. I publisher inviano messaggi a un topic; SNS li distribuisce a tutti i sottoscrittori (Lambda, SQS, email, SMS, HTTP). Viene usato per le notifiche push e le architetture fan-out.","optionExplanations":["Amazon SQS è una coda di messaggi point-to-point: un solo consumer elabora ciascun messaggio; non distribuisce i messaggi a più sottoscrittori contemporaneamente.","AWS Step Functions orchestra workflow: è un orchestratore di servizi, non un servizio di notifica pub/sub per distribuire messaggi a molti sottoscrittori.","Corretto — Amazon SNS è un servizio pub/sub che distribuisce contemporaneamente un singolo messaggio a tutti i sottoscrittori (Lambda, SQS, email, SMS, HTTP).","Amazon Kinesis serve per lo streaming di dati in tempo reale ad alto volume: non è un semplice servizio di notifica pub/sub per distribuire messaggi a più tipi di sottoscrittori."]},
  "335": {"h":"2bbfac2d","question":"L'applicazione di gestione dei sinistri di una compagnia assicurativa è composta da diverse funzioni AWS Lambda che devono essere eseguite in un ordine specifico, con alcuni passaggi eseguiti in parallelo. I passaggi non riusciti devono essere ritentati automaticamente e il team vuole una vista visuale del punto del processo in cui si trova ciascun sinistro. Quale servizio AWS dovrebbe usare l'azienda?","options":["Amazon SQS","Amazon SNS","Amazon EventBridge","AWS Step Functions"],"explanation":"AWS Step Functions coordina funzioni Lambda e altri servizi AWS in workflow visuali (state machine). Gestisce l'ordinamento, le diramazioni, i passaggi paralleli, i tentativi automatici e la gestione degli errori, e mostra in quale punto del workflow si trova ciascuna esecuzione.","optionExplanations":["Amazon SQS accoda i messaggi tra i componenti, ma non definisce l'ordine dei passaggi, le diramazioni parallele o i tentativi come un workflow visuale.","Amazon SNS invia notifiche a molti sottoscrittori. Non orchestra un processo in più passaggi né traccia l'avanzamento di ciascun sinistro.","Amazon EventBridge instrada gli eventi verso i target in base a regole, ma non gestisce l'ordine dei passaggi, le diramazioni parallele e i tentativi in un workflow visuale.","Corretto — Step Functions orchestra le funzioni Lambda in sequenza e in parallelo, ritenta i passaggi non riusciti e mostra visivamente l'avanzamento di ciascun sinistro."]},
  "336": {"h":"ca2823f4","question":"Quale servizio AWS è un event bus serverless che instrada gli eventi provenienti da servizi AWS, applicazioni SaaS e applicazioni personalizzate verso target come Lambda e SQS?","options":["Amazon SQS","Amazon SNS","Amazon Kinesis","Amazon EventBridge"],"explanation":"Amazon EventBridge (in precedenza CloudWatch Events) è un event bus serverless. Acquisisce eventi da servizi AWS, app personalizzate e partner SaaS, e applica regole per filtrarli e instradarli verso i target. Consente architetture event-driven a basso accoppiamento.","optionExplanations":["Amazon SQS è una coda di messaggi point-to-point: conserva i messaggi per un solo consumer, non è un event bus che instrada verso più target in base a regole.","Amazon SNS è un servizio di notifica pub/sub: distribuisce i messaggi a sottoscrittori preconfigurati, non è un event bus basato su regole integrato con applicazioni SaaS.","Amazon Kinesis elabora dati in streaming in tempo reale ad alto volume: è un servizio di streaming, non un bus di instradamento degli eventi basato su regole per sorgenti di eventi AWS e SaaS.","Corretto — Amazon EventBridge è un event bus serverless che instrada eventi da servizi AWS, app personalizzate e partner SaaS verso i target in base a regole configurabili."]},
  "337": {"h":"b86a4de4","question":"Un'azienda di giochi per dispositivi mobili vuole acquisire eventi come mosse e acquisti di milioni di giocatori nel momento in cui avvengono. Diverse sue applicazioni, tra cui una classifica in tempo reale e un sistema di rilevamento delle frodi, devono leggere ed elaborare gli stessi eventi entro pochi secondi. Quale servizio AWS dovrebbe usare?","options":["Amazon SQS","Amazon SNS","AWS Step Functions","Amazon Kinesis"],"explanation":"Amazon Kinesis (tramite Kinesis Data Streams) acquisisce in tempo reale grandi volumi di dati in streaming e li conserva per un certo periodo, in modo che più applicazioni consumer possano leggere ed elaborare gli stessi record in modo indipendente, entro pochi secondi dal loro arrivo.","optionExplanations":["SQS è una coda di messaggi in cui ciascun messaggio viene normalmente elaborato da un solo consumer e poi eliminato, quindi più applicazioni non possono leggere facilmente gli stessi eventi.","SNS invia notifiche push ai sottoscrittori ma non conserva un flusso di eventi che le applicazioni possano leggere e rielaborare.","Step Functions orchestra workflow in più passaggi; non è progettato per acquisire milioni di eventi in tempo reale.","Corretto — Kinesis acquisisce eventi in tempo reale su larga scala e consente a più applicazioni di elaborare lo stesso stream."]},
  "338": {"h":"03117e99","question":"Il team di un'app mobile vuole testare la propria app Android e iOS su un'ampia gamma di telefoni e tablet reali ospitati da AWS, senza dover acquistare e mantenere i dispositivi. Quale servizio AWS dovrebbe usare?","options":["AWS Device Farm","AWS Amplify","AWS AppSync","Amazon WorkSpaces"],"explanation":"AWS Device Farm è un servizio di test delle applicazioni che consente ai team di testare app web e mobile su dispositivi reali ospitati nel cloud AWS. I test possono essere eseguiti automaticamente su molti dispositivi, oppure gli sviluppatori possono interagire da remoto con un dispositivo per riprodurre i problemi.","optionExplanations":["Corretto — Device Farm esegue test automatici e manuali di app mobile e web su telefoni e tablet reali ospitati da AWS.","Amplify aiuta a creare, distribuire e ospitare il backend e il front-end di app web e mobile, ma non fornisce un parco di dispositivi reali per i test.","AppSync fornisce API GraphQL gestite per le app. Non ha alcuna funzionalità per testare le app su dispositivi fisici.","WorkSpaces fornisce desktop virtuali agli utenti, non telefoni e tablet reali per il test delle app."]},
  "339": {"h":"271368ab","question":"Quale servizio AWS di infrastructure as code consente di modellare e provisionare risorse AWS usando template JSON o YAML?","options":["AWS CDK","AWS Elastic Beanstalk","AWS CloudFormation","AWS Systems Manager"],"explanation":"AWS CloudFormation è un servizio IaC che provisiona e gestisce le risorse AWS a partire da template dichiarativi (JSON o YAML). I template definiscono lo stato desiderato; CloudFormation gestisce l'ordine delle dipendenze, il rollback e il rilevamento del drift.","optionExplanations":["AWS CDK (Cloud Development Kit) genera template CloudFormation usando linguaggi di programmazione: anche se il CDK è IaC, è CloudFormation il servizio sottostante che usa direttamente template JSON/YAML.","AWS Elastic Beanstalk esegue il deployment del codice applicativo e gestisce l'infrastruttura circostante: è un servizio PaaS, non un servizio IaC per definire configurazioni arbitrarie di risorse AWS.","Corretto — AWS CloudFormation provisiona e gestisce le risorse AWS a partire da template JSON o YAML, con ordinamento delle dipendenze, rollback e rilevamento del drift.","AWS Systems Manager gestisce attività operative come l'applicazione di patch e l'esecuzione di comandi sui nodi gestiti: non provisiona risorse a partire da template dichiarativi JSON o YAML."]},
  "340": {"h":"7196dab1","question":"Un'azienda di ricerca genomica deve eseguire ogni notte grandi job batch con Apache Spark, Apache Hive e Apache HBase su petabyte di dati. Vuole che sia AWS a provisionare e configurare i cluster, e vuole spegnerli al termine dei job in modo da pagare solo mentre sono in esecuzione. Quale servizio AWS soddisfa questi requisiti?","options":["Amazon Redshift","Amazon Athena","Amazon EMR","AWS Glue"],"explanation":"Amazon EMR è una piattaforma di cluster gestiti per eseguire framework big data open source, tra cui Spark, Hive e HBase. I cluster possono essere avviati per un job e terminati subito dopo, così l'azienda paga solo mentre l'elaborazione è in corso.","optionExplanations":["Redshift è un data warehouse per l'analisi SQL. Non esegue Spark, Hive e HBase su cluster gestiti.","Athena esegue query SQL serverless sui dati in S3. Non fornisce cluster che eseguono Hive e HBase.","Corretto — EMR esegue Spark, Hive e HBase su cluster gestiti che possono essere spenti al termine dei job.","Glue è un servizio serverless di integrazione dei dati (ETL). Non fornisce cluster che eseguono l'intero insieme di framework, come HBase."]},
  "341": {"h":"94249b41","question":"Quale servizio AWS consente di eseguire query SQL direttamente sui dati archiviati in Amazon S3 senza caricarli in un database?","options":["Amazon Redshift","Amazon EMR","Amazon Athena","AWS Glue"],"explanation":"Amazon Athena è un servizio di query interattivo e serverless che usa SQL standard per analizzare i dati direttamente in S3. Non c'è infrastruttura da gestire e si paga per TB di dati scansionati. Usa Presto e supporta JSON, CSV, Parquet, ORC e Avro.","optionExplanations":["Amazon Redshift è un data warehouse gestito che richiede il provisioning di cluster e il caricamento dei dati: non interroga i dati direttamente in S3 senza predisporre un'infrastruttura.","Amazon EMR richiede il provisioning e la gestione di cluster di istanze EC2: non è un servizio di query SQL serverless e privo di infrastruttura.","Corretto — Amazon Athena è un servizio di query SQL serverless che analizza i dati direttamente in S3 senza infrastruttura da gestire, pagando solo per TB di dati scansionati.","AWS Glue è un servizio ETL serverless per trasformare e spostare i dati: non è un servizio di query SQL per l'analisi ad hoc dei dati in S3."]},
  "342": {"h":"15a56da4","question":"Un'azienda ha dati in Amazon S3 e Amazon RDS in diversi formati. Prima che gli analisti li interroghino, l'azienda vuole individuare automaticamente gli schemi dei dati in un catalogo centrale ed eseguire job che puliscano e convertano i dati in un formato comune, senza gestire alcun server. Quale servizio AWS dovrebbe usare l'azienda?","options":["Amazon EMR","Amazon Athena","Amazon Kinesis","AWS Glue"],"explanation":"AWS Glue è un servizio serverless di integrazione dei dati (ETL). I suoi crawler individuano gli schemi e popolano l'AWS Glue Data Catalog, mentre i suoi job ETL puliscono, trasformano e spostano i dati tra data store come Amazon S3 e Amazon RDS.","optionExplanations":["Amazon EMR esegue framework big data come Apache Spark, ma non esplora automaticamente le sorgenti dati per creare un catalogo centrale degli schemi.","Amazon Athena esegue query SQL sui dati in S3. È ciò che gli analisti potrebbero usare in seguito, non il servizio che individua gli schemi e trasforma i dati.","Amazon Kinesis acquisisce ed elabora dati in streaming in tempo reale. L'azienda ha invece bisogno di catalogare e trasformare dati già archiviati.","Corretto — I crawler di AWS Glue catalogano gli schemi e i job ETL serverless di Glue puliscono e convertono i dati in un formato comune."]},
  "343": {"h":"b6a580e5","question":"Quale servizio AWS fornisce una piattaforma di machine learning completamente gestita per creare, addestrare ed eseguire il deployment di modelli ML su larga scala?","options":["AWS DeepLens","Amazon Rekognition","Amazon SageMaker","AWS Comprehend"],"explanation":"Amazon SageMaker è un servizio ML completamente gestito che fornisce strumenti per l'etichettatura dei dati, la creazione di modelli (notebook Jupyter), l'addestramento (distribuito), il tuning e il deployment (endpoint in tempo reale, batch transform). Si fa carico del lavoro pesante e indifferenziato del ML.","optionExplanations":["AWS DeepLens è una videocamera abilitata al deep learning: è un dispositivo hardware per l'inferenza ML all'edge, non una piattaforma ML completa per creare e addestrare modelli.","Amazon Rekognition è un servizio AI preconfezionato per la computer vision: fornisce specifiche funzionalità pre-addestrate, non una piattaforma end-to-end per creare modelli ML personalizzati.","Corretto — Amazon SageMaker fornisce una piattaforma ML completa che copre etichettatura dei dati, creazione dei modelli, addestramento distribuito, tuning degli iperparametri e deployment.","AWS Comprehend è un servizio NLP preconfezionato: fornisce specifiche funzionalità di analisi del testo, non una piattaforma ML generica per lo sviluppo di modelli personalizzati."]},
  "344": {"h":"e23ae4b7","question":"Quale servizio AI di AWS fornisce modelli pre-addestrati per l'analisi di immagini e video, come il rilevamento di oggetti, il riconoscimento facciale e la moderazione dei contenuti?","options":["Amazon Comprehend","Amazon Polly","Amazon Rekognition","Amazon Transcribe"],"explanation":"Amazon Rekognition usa il deep learning per analizzare immagini e video. Le funzionalità includono rilevamento di oggetti/scene, analisi facciale, riconoscimento di celebrità, rilevamento del testo e moderazione dei contenuti, tutto tramite API senza bisogno di competenze ML.","optionExplanations":["Amazon Comprehend esegue NLP sul testo: analizza il testo scritto per sentiment, entità e frasi chiave, non immagini o video.","Amazon Polly converte il testo in voce: è un servizio text-to-speech, non un servizio di analisi di immagini/video.","Corretto — Amazon Rekognition fornisce funzionalità di computer vision (rilevamento di oggetti, analisi facciale, testo nelle immagini, moderazione dei contenuti) tramite API senza competenze ML.","Amazon Transcribe converte l'audio parlato in testo: trascrive le parole pronunciate, non analizza contenuti visivi in immagini o video."]},
  "345": {"h":"2bef9805","question":"Un'azienda esegue software di fornitori come Microsoft e Oracle su AWS e on-premises. Vuole tracciare centralmente l'utilizzo delle licenze e impostare regole che impediscano di avviare più istanze di quante ne consentano le licenze. Quale servizio AWS dovrebbe usare?","options":["AWS License Manager","AWS Marketplace","AWS Config","AWS Systems Manager Inventory"],"explanation":"AWS License Manager aiuta a gestire le licenze software di fornitori come Microsoft, Oracle e SAP negli ambienti AWS e on-premises. Gli amministratori definiscono regole di licenza che tracciano l'utilizzo e possono bloccare l'avvio di nuove istanze che supererebbero i diritti di licenza.","optionExplanations":["Corretto — License Manager traccia centralmente l'utilizzo delle licenze e applica regole che possono bloccare gli avvii che superano i limiti di licenza.","AWS Marketplace serve a trovare e acquistare software di terze parti. Non traccia né fa rispettare i diritti di licenza esistenti.","AWS Config registra e valuta le configurazioni delle risorse, ma non definisce regole di licenza né blocca gli avvii in base al numero di licenze.","Systems Manager Inventory raccoglie l'inventario software dai nodi gestiti, ma non impone limiti di licenza sui nuovi avvii."]},
  "346": {"h":"1a4c2a45","question":"Un'azienda registra le proprie riunioni plenarie e i webinar. Vuole creare automaticamente trascrizioni testuali di queste registrazioni che indichino quale relatore ha detto cosa e riconoscano correttamente i nomi dei suoi prodotti. Quale servizio AWS dovrebbe usare?","options":["Amazon Polly","Amazon Translate","Amazon Lex","Amazon Transcribe"],"explanation":"Amazon Transcribe è un servizio di riconoscimento vocale automatico (ASR) che converte audio e video in testo. Può identificare i diversi relatori (speaker diarization) e usare vocabolari personalizzati in modo che i nomi dei prodotti e i termini specialistici vengano riconosciuti correttamente.","optionExplanations":["Polly converte il testo in voce, l'opposto di ciò di cui l'azienda ha bisogno.","Translate converte il testo da una lingua all'altra; non crea trascrizioni a partire dall'audio.","Lex crea chatbot conversazionali; non viene usato per trascrivere riunioni registrate.","Corretto — Transcribe converte le registrazioni in testo, etichetta i relatori e supporta vocabolari personalizzati per i nomi dei prodotti."]},
  "347": {"h":"b2c0cb96","question":"Quale servizio AWS usa l'elaborazione del linguaggio naturale per estrarre frasi chiave, sentiment, entità e lingua da un testo?","options":["Amazon Lex","Amazon Polly","Amazon Comprehend","Amazon Translate"],"explanation":"Amazon Comprehend è un servizio di elaborazione del linguaggio naturale (NLP) che estrae informazioni dal testo: frasi chiave, entità (persone, luoghi), sentiment (positivo/negativo), rilevamento della lingua e topic modeling, tutto tramite API.","optionExplanations":["Amazon Lex è un servizio per creare interfacce conversazionali (chatbot): elabora voce e testo per il dialogo, non per estrarre informazioni NLP come sentiment ed entità.","Amazon Polly converte il testo in audio vocale: non analizza né estrae informazioni dal contenuto testuale.","Corretto — Amazon Comprehend è il servizio NLP che estrae frasi chiave, entità, sentiment, lingua e argomenti dal testo senza richiedere competenze ML.","Amazon Translate esegue la traduzione linguistica: converte il testo da una lingua all'altra ma non estrae informazioni NLP come sentiment o riconoscimento delle entità."]},
  "348": {"h":"47821844","question":"Una banca vuole aggiungere un assistente virtuale al proprio sito web e alla propria linea telefonica. I clienti devono poter digitare o pronunciare richieste come «Qual è il saldo del mio conto?» e l'assistente deve capire cosa intendono e rispondere in modo conversazionale. Quale servizio AWS dovrebbe usare la banca per realizzarlo?","options":["Amazon Polly","Amazon Comprehend","Amazon Lex","Amazon Kendra"],"explanation":"Amazon Lex è un servizio completamente gestito per creare interfacce conversazionali (chatbot e voice bot). Fornisce riconoscimento vocale e comprensione del linguaggio naturale, usando la stessa tecnologia di Amazon Alexa, e può chiamare AWS Lambda per completare le richieste.","optionExplanations":["Polly converte il testo in una voce realistica. Non comprende le richieste dei clienti né gestisce una conversazione.","Comprehend estrae informazioni come sentiment e frasi chiave dal testo. Non crea bot conversazionali interattivi.","Corretto — Lex comprende le richieste digitate o pronunciate e gestisce la conversazione, che è ciò di cui ha bisogno l'assistente virtuale.","Kendra è un servizio di ricerca intelligente per trovare risposte nei documenti. Non è uno strumento per creare bot conversazionali."]},
  "349": {"h":"b5ef2393","question":"Quale servizio AWS fornisce un servizio di ricerca aziendale intelligente basato sul machine learning?","options":["Amazon Elasticsearch Service","Amazon Kendra","Amazon Comprehend","Amazon Lex"],"explanation":"Amazon Kendra è un servizio di ricerca aziendale basato sul ML che comprende le domande in linguaggio naturale ed esegue ricerche su contenuti non strutturati (documenti, FAQ, S3, SharePoint, Salesforce) per restituire risposte precise.","optionExplanations":["Amazon Elasticsearch Service (OpenSearch Service) fornisce ricerca e analisi su dati strutturati e semi-strutturati: richiede una configurazione più tecnica e non è progettato specificamente per la ricerca di documenti aziendali in linguaggio naturale.","Corretto — Amazon Kendra è il servizio di ricerca aziendale basato sul ML che comprende le domande in linguaggio naturale e restituisce risposte precise dai documenti aziendali non strutturati.","Amazon Comprehend esegue analisi NLP per estrarre informazioni dal testo: non effettua ricerche nei documenti aziendali né restituisce risposte a query in linguaggio naturale.","Amazon Lex crea interfacce di chatbot conversazionali: gestisce dialoghi e intenti ma non è un servizio di ricerca documentale per i repository di contenuti aziendali."]},
  "350": {"h":"ef4f07d5","question":"Un team di sviluppo crea immagini Docker nella propria pipeline CI. Ha bisogno di uno spazio privato e gestito in cui archiviare e versionare le immagini, in modo che Amazon ECS e Amazon EKS possano scaricarle, e non vuole gestire i propri server di registry. Quale servizio AWS dovrebbe usare il team?","options":["Amazon ECS","Amazon EKS","Amazon ECR","AWS Fargate"],"explanation":"Amazon Elastic Container Registry (Amazon ECR) è un registry di immagini container completamente gestito. Archivia, versiona e protegge le immagini container e si integra con Amazon ECS, Amazon EKS e AWS Fargate, così il team non deve gestire un proprio registry.","optionExplanations":["Amazon ECS esegue e orchestra i container. Scarica le immagini da un registry ma non le archivia.","Amazon EKS esegue Kubernetes. Scarica le immagini da un registry ma non è di per sé uno spazio in cui archiviare le immagini container.","Corretto — Amazon ECR è un registry privato gestito per archiviare e versionare le immagini container che ECS ed EKS possono scaricare.","AWS Fargate è un servizio di calcolo serverless che esegue container. Non archivia immagini container."]},
  "351": {"h":"0410d7d5","question":"Quale servizio AWS fornisce una piattaforma IoT gestita per connettere, gestire e proteggere miliardi di dispositivi IoT?","options":["AWS Greengrass","Amazon Kinesis","AWS IoT Core","Amazon SageMaker"],"explanation":"AWS IoT Core è un servizio cloud gestito che consente ai dispositivi connessi di interagire con le applicazioni cloud. Gestisce la connettività dei dispositivi (MQTT, HTTP), il brokering dei messaggi, la sicurezza (certificati X.509) e l'integrazione con i servizi AWS.","optionExplanations":["AWS Greengrass estende AWS ai dispositivi edge per l'elaborazione locale — è complementare a IoT Core ma non è la piattaforma IoT gestita centrale per la connettività dei dispositivi.","Amazon Kinesis elabora dati in streaming in tempo reale — può acquisire dati IoT ma non è una piattaforma gestita per la connettività, la gestione e la sicurezza dei dispositivi.","Corretto — AWS IoT Core è la piattaforma cloud gestita per connettere, gestire e proteggere i dispositivi IoT con MQTT/HTTP, certificati X.509 e integrazione con i servizi AWS.","Amazon SageMaker è una piattaforma di machine learning — può elaborare dati IoT ma non è il servizio di connettività e gestione dei dispositivi."]},
  "352": {"h":"73891c5c","question":"Quale servizio AWS offre un servizio gestito per eseguire streaming compatibile con Apache Kafka, completamente gestito e integrato con i servizi AWS?","options":["Amazon Kinesis Data Streams","Amazon SQS","Amazon MSK","AWS EventBridge"],"explanation":"Amazon MSK (Managed Streaming for Apache Kafka) è un servizio completamente gestito che semplifica la creazione e l'esecuzione di applicazioni che usano Apache Kafka. AWS si occupa di provisioning, configurazione e manutenzione dei broker Kafka e di ZooKeeper.","optionExplanations":["Amazon Kinesis Data Streams è il servizio di streaming proprietario di AWS — non è compatibile con Apache Kafka e richiederebbe modifiche al codice per migrare le applicazioni Kafka esistenti.","Amazon SQS è una coda di messaggi — non è una piattaforma di streaming e non è compatibile con Apache Kafka.","Corretto — Amazon MSK è il servizio di streaming compatibile con Apache Kafka completamente gestito, in cui AWS si occupa di provisioning e manutenzione dei broker Kafka e di ZooKeeper.","AWS EventBridge è un event bus per l'instradamento degli eventi — non è una piattaforma di streaming compatibile con Kafka."]},
  "353": {"h":"8c6729be","question":"Un'azienda si avvale di collaboratori esterni che lavorano dai propri laptop. Vuole fornire a ciascun collaboratore un desktop Windows persistente e completamente gestito nel cloud, in modo che i file aziendali non debbano mai essere archiviati sui dispositivi dei collaboratori. Quale servizio AWS dovrebbe usare?","options":["Amazon AppStream 2.0","Amazon WorkSpaces","AWS Client VPN","Amazon Connect"],"explanation":"Amazon WorkSpaces è un'offerta desktop-as-a-service (DaaS) completamente gestita. Ogni utente ottiene un desktop virtuale Windows o Linux persistente che gira in AWS ed è accessibile da molti tipi di dispositivi, mentre i dati restano nel cloud e AWS gestisce l'infrastruttura.","optionExplanations":["AppStream 2.0 trasmette in streaming singole applicazioni agli utenti invece di fornire a ciascun collaboratore un desktop completo e persistente.","Corretto — WorkSpaces fornisce a ciascun collaboratore un desktop cloud persistente, tenendo i file aziendali fuori dai loro laptop.","Client VPN collega i dispositivi alla rete aziendale, quindi i file potrebbero comunque finire sui laptop dei collaboratori; non fornisce desktop.","Amazon Connect è un servizio di contact center nel cloud, non un servizio di desktop virtuali."]},
  "354": {"h":"fc690a25","question":"Quale servizio AWS consente di trasmettere in streaming applicazioni desktop ai browser degli utenti, senza richiedere installazioni sui loro dispositivi?","options":["Amazon WorkSpaces","Amazon Connect","AWS AppStream 2.0","AWS WorkLink"],"explanation":"AWS AppStream 2.0 trasmette in streaming applicazioni desktop da AWS ai browser web degli utenti. Le applicazioni girano sull'infrastruttura AWS e vengono trasmesse come pixel — nessuna installazione richiesta sul dispositivo dell'utente, e i dati non lasciano mai AWS.","optionExplanations":["Amazon WorkSpaces fornisce desktop virtuali persistenti — trasmette un intero desktop, non applicazioni specifiche, e gli utenti hanno un proprio ambiente desktop dedicato.","Amazon Connect è un contact center basato sul cloud — non offre funzionalità di streaming di applicazioni.","Corretto — AWS AppStream 2.0 trasmette in streaming singole applicazioni desktop ai browser degli utenti senza installazione locale, con i dati che restano in AWS.","AWS WorkLink (ora dismesso) serviva ad accedere a siti web interni da dispositivi mobili — non era destinato allo streaming di applicazioni desktop."]},
  "355": {"h":"2075b6ef","question":"Un rivenditore online vuole attivare un call center di assistenza clienti nel giro di pochi giorni. I suoi operatori lavoreranno da casa e l'azienda non vuole acquistare hardware di telefonia né firmare contratti a lungo termine; vuole pagare solo in base all'utilizzo. Quale servizio AWS dovrebbe usare?","options":["Amazon WorkSpaces","Amazon Connect","Amazon Simple Email Service (Amazon SES)","AWS Wickr"],"explanation":"Amazon Connect è un servizio di contact center basato sul cloud. Le aziende possono configurarlo rapidamente, gli operatori hanno bisogno solo di un browser e di una connessione internet, e il prezzo è a consumo, senza hardware di telefonia né impegni a lungo termine.","optionExplanations":["WorkSpaces fornisce desktop virtuali che gli operatori remoti potrebbero usare, ma non offre instradamento delle chiamate né funzionalità di contact center.","Corretto — Connect fornisce un contact center cloud a consumo che gli operatori possono usare da casa.","SES invia e riceve email su larga scala. Non è un contact center telefonico.","Wickr è un servizio di messaggistica e collaborazione con crittografia end-to-end. Non è un contact center per i clienti."]},
  "356": {"h":"3b5ee556","question":"Quale servizio AWS rileva, classifica e migra automaticamente i workload on-premises su AWS con un downtime minimo?","options":["AWS Database Migration Service (DMS)","AWS Application Migration Service","AWS DataSync per il trasferimento di file","AWS Transfer Family (SFTP/FTPS)"],"explanation":"AWS Application Migration Service (AWS MGN) è il principale servizio di migrazione per le migrazioni lift-and-shift. Replica i server di origine in modo continuo e il cutover comporta un downtime minimo. Ha sostituito AWS Server Migration Service (SMS).","optionExplanations":["AWS DMS migra e replica database — non replica interi server né ne esegue il cutover per farli girare su AWS.","Corretto — AWS Application Migration Service (MGN) è il principale servizio di migrazione lift-and-shift: replica in modo continuo i server di origine e minimizza il downtime durante il cutover.","AWS DataSync trasferisce file tra lo storage on-premises e lo storage AWS — serve al trasferimento di dati, non alla migrazione di interi workload di server con cutover.","AWS Transfer Family fornisce trasferimento file gestito (SFTP, FTPS) — riguarda i protocolli di trasferimento file, non la migrazione di workload."]},
  "357": {"h":"bbe905ca","question":"Una società di videogiochi archivia i profili dei giocatori in Amazon DynamoDB. I suoi giocatori si trovano in Nord America, Europa e Asia. L'azienda vuole che ogni giocatore legga e scriva i dati del profilo in una AWS Region vicina, con le modifiche replicate automaticamente nelle altre Region. Quale opzione soddisfa questi requisiti?","options":["Amazon DynamoDB Accelerator (DAX)","Amazon DynamoDB global tables","Read replica cross-Region di Amazon RDS","Caching edge di Amazon CloudFront"],"explanation":"Le Amazon DynamoDB global tables replicano automaticamente una tabella nelle AWS Region scelte. Ogni replica accetta letture e scritture, quindi i giocatori usano la copia più vicina mentre le modifiche si propagano alle altre Region.","optionExplanations":["DAX è una cache in memoria che velocizza le letture di una tabella DynamoDB. Non crea copie scrivibili della tabella in altre Region.","Corretto — Le DynamoDB global tables mantengono repliche scrivibili di una tabella in più Region e replicano automaticamente le modifiche tra di esse.","Le read replica RDS sono per database relazionali e servono solo letture. L'azienda usa DynamoDB e ha bisogno di scritture locali in ogni Region.","CloudFront memorizza in cache i contenuti nelle edge location per velocizzarne la distribuzione. Non replica le scritture del database tra Region."]},
  "358": {"h":"73946d55","question":"Un'azienda deve trasferire una grande quantità di dati su AWS, ma la sua banda internet è troppo limitata per un trasferimento online. Quale opzione AWS spedisce all'azienda un dispositivo fisico per il trasferimento offline dei dati?","options":["AWS Storage Gateway","AWS DataSync","AWS Snowball Edge","AWS Transfer Family"],"explanation":"AWS Snowball Edge è un dispositivo fisico per il trasferimento offline dei dati. I clienti caricano i dati sul dispositivo e lo rispediscono ad AWS, che li importa in Amazon S3. Per dataset più grandi si possono usare in parallelo più dispositivi Snowball Edge.","optionExplanations":["AWS Storage Gateway collega online lo storage on-premises allo storage cloud AWS — non è un dispositivo fisico spedito ai clienti per il trasferimento offline di grandi volumi di dati.","AWS DataSync trasferisce dati online tra on-premises e AWS — opera su connessioni di rete, non come dispositivo fisico per il trasferimento offline di grandi volumi.","Corretto — AWS Snowball Edge è un dispositivo fisico spedito al cliente per il trasferimento offline dei dati, utile quando la banda internet è insufficiente.","AWS Transfer Family fornisce SFTP/FTPS gestito — è un servizio di trasferimento file online, non un dispositivo fisico per la migrazione di grandi volumi di dati."]},
  "359": {"h":"fa368d58","question":"Quale servizio AWS consente un trasferimento di dati automatizzato e accelerato tra lo storage on-premises e i servizi di storage AWS come S3, EFS e FSx?","options":["AWS Snowball","AWS Transfer Family","AWS DataSync","AWS Storage Gateway"],"explanation":"AWS DataSync è un servizio di trasferimento dati online che automatizza lo spostamento di dati tra on-premises e lo storage AWS (S3, EFS, FSx). Gestisce pianificazione, monitoraggio e crittografia, e può trasferire a velocità fino a 10 volte superiori rispetto agli strumenti open source.","optionExplanations":["AWS Snowball è un dispositivo fisico per il trasferimento offline dei dati — è pensato per i casi in cui la banda di rete è insufficiente, non per trasferimenti online accelerati.","AWS Transfer Family fornisce SFTP/FTPS/FTP gestito — riguarda i protocolli di trasferimento file, non la sincronizzazione automatizzata ad alta velocità tra storage on-premises e AWS.","Corretto — AWS DataSync automatizza e accelera il trasferimento online dei dati tra lo storage on-premises e i servizi di storage AWS (S3, EFS, FSx), con velocità fino a 10 volte superiori.","AWS Storage Gateway fornisce accesso allo storage cloud ibrido — serve per un accesso ibrido continuativo, non per trasferimenti di dati accelerati una tantum o pianificati."]},
  "360": {"h":"ba3573e2","question":"Un'azienda di logistica riceve ogni giorno file di spedizione da decine di partner commerciali, che li caricano via SFTP su un server on-premises. L'azienda vuole dismettere questo server lasciando che i partner continuino a usare SFTP senza modifiche, con i file archiviati direttamente in Amazon S3 e nessun server da gestire. Quale servizio AWS dovrebbe usare?","options":["AWS DataSync","AWS Transfer Family","AWS Storage Gateway","Amazon S3 Transfer Acceleration"],"explanation":"AWS Transfer Family è un servizio completamente gestito per il trasferimento di file tramite protocolli come SFTP, FTPS e FTP direttamente da e verso Amazon S3 o Amazon EFS. I partner mantengono i loro flussi SFTP esistenti e l'azienda non deve più gestire un server di trasferimento file.","optionExplanations":["DataSync sposta dati tra sistemi di storage, ad esempio durante una migrazione. Non fornisce ai partner esterni un endpoint SFTP gestito.","Corretto — Transfer Family fornisce un endpoint SFTP completamente gestito che archivia i file caricati direttamente in Amazon S3.","Storage Gateway offre alle applicazioni on-premises condivisioni di file basate su S3. Non è un endpoint SFTP gestito per partner esterni.","Transfer Acceleration velocizza i caricamenti su S3 su lunghe distanze, ma i partner dovrebbero passare da SFTP a caricamenti S3."]},
  "361": {"h":"857cdb88","question":"Quale funzionalità di Amazon EC2 distribuisce automaticamente il traffico applicativo in ingresso su più destinazioni (istanze EC2, container, funzioni Lambda)?","options":["Amazon Route 53","Auto Scaling Group","Elastic Load Balancing (ELB)","AWS Global Accelerator"],"explanation":"Elastic Load Balancing distribuisce automaticamente il traffico in ingresso su più destinazioni integre in una o più AZ. I tipi includono Application Load Balancer (HTTP/HTTPS), Network Load Balancer (TCP/UDP) e Gateway Load Balancer.","optionExplanations":["Amazon Route 53 è un servizio DNS — può effettuare un certo instradamento tramite record DNS, ma non distribuisce il traffico sulle destinazioni come fanno i load balancer.","Auto Scaling Group regola il numero di istanze EC2 in base alla domanda — gestisce la capacità, non la distribuzione del traffico in ingresso sulle destinazioni.","Corretto — Elastic Load Balancing distribuisce il traffico in ingresso su più destinazioni integre (EC2, container, Lambda) in una o più AZ.","AWS Global Accelerator instrada il traffico attraverso la rete globale AWS usando IP anycast — migliora le prestazioni globali ma non è un load balancer per Region che distribuisce il traffico sulle destinazioni."]},
  "362": {"h":"d792f95b","question":"Un negozio online vuole che la propria applicazione invii ai clienti, in modo automatico e su larga scala, email di conferma d'ordine e di reimpostazione della password, senza gestire server di posta propri. Quale servizio AWS dovrebbe usare?","options":["Amazon Simple Email Service (Amazon SES)","Amazon Simple Notification Service (Amazon SNS)","Amazon Simple Queue Service (Amazon SQS)","Amazon Connect"],"explanation":"Amazon SES è un servizio email nel cloud per inviare dalle applicazioni email transazionali, di marketing e di notifica senza gestire server di posta. È adatto a messaggi personalizzati come conferme d'ordine e reimpostazioni della password inviati a qualsiasi indirizzo dei clienti.","optionExplanations":["Corretto — Amazon SES consente alle applicazioni di inviare ai clienti, su larga scala, email transazionali personalizzate come le conferme d'ordine.","SNS può recapitare semplici notifiche a endpoint email che hanno confermato la sottoscrizione a un topic, ma non è pensato per email transazionali personalizzate ai clienti.","SQS è una coda di messaggi per disaccoppiare i componenti applicativi. Non recapita email ai clienti.","Amazon Connect è un servizio di contact center nel cloud per l'assistenza clienti via voce e chat, non per l'invio di email applicative."]},
  "363": {"h":"5039a7c8","question":"Un'azienda esegue molte funzioni AWS Lambda e molti volumi Amazon EBS. I suoi sviluppatori vogliono raccomandazioni sulla dimensione di memoria Lambda e sul tipo di volume EBS migliori, basate sull'effettivo utilizzo storico di ciascuna risorsa, per migliorare le prestazioni e ridurre i costi. Quale servizio AWS dovrebbero usare?","options":["AWS Trusted Advisor","AWS Compute Optimizer","AWS Cost Explorer","AWS Budgets"],"explanation":"AWS Compute Optimizer analizza le metriche di utilizzo storiche e usa il machine learning per raccomandare configurazioni ottimali per istanze EC2, Auto Scaling group, volumi EBS, funzioni Lambda e altro.","optionExplanations":["Trusted Advisor esegue controlli generali sulle best practice, ad esempio individuando risorse inattive. Non raccomanda la giusta dimensione di memoria Lambda in base allo storico di utilizzo.","Corretto — Compute Optimizer raccomanda dimensioni di memoria Lambda e tipi di volume EBS in base all'utilizzo storico.","Cost Explorer mostra andamenti e previsioni della spesa. Non raccomanda impostazioni di memoria Lambda né tipi di volume EBS.","Budgets invia avvisi quando costi o utilizzo superano delle soglie. Non fornisce raccomandazioni di dimensionamento."]},
  "364": {"h":"b9cc2646","question":"Quale servizio AWS fornisce un database relazionale completamente gestito che supporta sei motori di database: MySQL, MariaDB, PostgreSQL, Oracle, SQL Server e Amazon Aurora?","options":["Amazon DynamoDB","Amazon Aurora","Amazon RDS","Amazon Redshift"],"explanation":"Amazon RDS (Relational Database Service) è un servizio gestito per database relazionali. Si occupa di provisioning, patching, backup e scalabilità. Supporta MySQL, MariaDB, PostgreSQL, Oracle, SQL Server e i motori compatibili con Aurora.","optionExplanations":["Amazon DynamoDB è un database NoSQL — non supporta i motori MySQL, MariaDB, PostgreSQL, Oracle o SQL Server.","Amazon Aurora è un singolo motore (compatibile con MySQL/PostgreSQL) all'interno della famiglia RDS — non ospita da solo tutti e sei i motori elencati.","Corretto — Amazon RDS è il servizio di database relazionale gestito che supporta sei motori: MySQL, MariaDB, PostgreSQL, Oracle, SQL Server e Amazon Aurora.","Amazon Redshift è un data warehouse — non è un servizio di database relazionale generico che supporta più motori."]},
  "365": {"h":"8369a3e7","question":"Un'azienda di logistica modella la propria rete di fornitori, magazzini, porti e rotte di spedizione. Le sue applicazioni devono attraversare rapidamente molte relazioni, ad esempio per trovare tutti i fornitori coinvolti se un porto chiude. Quale servizio di database AWS completamente gestito è il PIÙ adatto a queste query su dati altamente connessi?","options":["Amazon DocumentDB","Amazon Neptune","Amazon Redshift","Amazon Keyspaces"],"explanation":"Amazon Neptune è un database a grafo completamente gestito, progettato per archiviare e interrogare dati altamente connessi. Attraversa in modo efficiente le relazioni, come fornitori, magazzini, porti e rotte, che sono il cuore delle query dell'azienda di logistica.","optionExplanations":["Amazon DocumentDB è un database documentale compatibile con MongoDB. Archivia documenti JSON e non è ottimizzato per attraversare molte relazioni.","Corretto — Amazon Neptune è un database a grafo progettato per attraversare dati altamente connessi, ad esempio per trovare tutti i fornitori coinvolti dalla chiusura di un porto.","Amazon Redshift è un data warehouse per query SQL analitiche su grandi dataset, non per attraversare molte relazioni in dati altamente connessi.","Amazon Keyspaces è un database wide-column compatibile con Apache Cassandra. Non è progettato per attraversare relazioni complesse."]},
  "366": {"h":"c7ec9615","question":"Una nave da ricerca trascorre settimane in mare senza connettività di rete. Gli scienziati devono eseguire workload di calcolo a bordo per elaborare i dati dei sensori e in seguito riportare i dati su AWS. Quale servizio AWS è progettato per questo scopo?","options":["Rack AWS Outposts","Dispositivi AWS Snowball Edge","AWS Local Zones","AWS Direct Connect"],"explanation":"I dispositivi AWS Snowball Edge forniscono storage e capacità di calcolo locali che funzionano in ambienti disconnessi e difficili; i dati raccolti sul dispositivo possono poi essere rispediti e importati in Amazon S3. Outposts richiede una connessione affidabile a una AWS Region.","optionExplanations":["AWS Outposts porta l'infrastruttura AWS in un data center, ma ha bisogno di una connessione stabile con la propria AWS Region di riferimento, che una nave in mare non ha.","Corretto — Snowball Edge offre calcolo e storage sul dispositivo per sedi edge disconnesse, e i dati possono essere rispediti ad AWS.","Le Local Zones sono infrastrutture gestite da AWS nelle aree metropolitane; non possono funzionare su una nave senza connettività.","Direct Connect è un collegamento di rete dedicato tra un data center e AWS; non funziona per una nave senza connettività."]},
  "367": {"h":"0d91b517","question":"Quale servizio AWS è un database documentale completamente gestito e compatibile con MongoDB?","options":["Amazon DynamoDB","Amazon Keyspaces","Amazon DocumentDB","Amazon Neptune"],"explanation":"Amazon DocumentDB (with MongoDB compatibility) è un database documentale completamente gestito. Implementa l'API MongoDB, quindi le applicazioni e i driver MongoDB esistenti funzionano senza modifiche significative al codice, mentre AWS gestisce disponibilità e scalabilità.","optionExplanations":["Amazon DynamoDB è un database NoSQL chiave-valore/documentale — usa API specifiche di AWS e non è compatibile con MongoDB.","Amazon Keyspaces è compatibile con Apache Cassandra — è un database wide-column, non un database documentale compatibile con MongoDB.","Corretto — Amazon DocumentDB è il database documentale completamente gestito e compatibile con MongoDB, che consente di migrare i workload MongoDB esistenti con modifiche minime al codice.","Amazon Neptune è un database a grafo — archivia relazioni, non documenti di tipo JSON in un formato compatibile con MongoDB."]},
  "368": {"h":"5ccb350f","question":"Quale servizio AWS fornisce un database scalabile, serverless, ad alta disponibilità e compatibile con Apache Cassandra?","options":["Amazon DynamoDB","Amazon DocumentDB","Amazon Neptune","Amazon Keyspaces"],"explanation":"Amazon Keyspaces è un servizio di database serverless, completamente gestito e compatibile con Cassandra. I workload Cassandra esistenti possono essere migrati con modifiche minime al codice. AWS si occupa di scalabilità, patching e disponibilità.","optionExplanations":["Amazon DynamoDB è un database NoSQL chiave-valore/documentale con API specifiche di AWS — non è compatibile con Apache Cassandra.","Amazon DocumentDB è compatibile con MongoDB — è pensato per workload documentali, non per workload wide-column Cassandra.","Amazon Neptune è un database a grafo — non è compatibile con Cassandra.","Corretto — Amazon Keyspaces è il servizio di database serverless, completamente gestito e compatibile con Cassandra, per migrare workload Cassandra con modifiche minime al codice."]},
  "369": {"h":"9e5882b1","question":"Un team operativo vuole monitorare il numero di errori del server restituiti dal proprio Application Load Balancer ed essere avvisato, o attivare un'azione automatica, quando gli errori superano un livello accettabile. Quale servizio AWS dovrebbe usare?","options":["AWS CloudTrail","Amazon GuardDuty","Amazon CloudWatch","AWS Config"],"explanation":"Amazon CloudWatch è il servizio AWS di monitoraggio e osservabilità. Raccoglie metriche, come il numero di errori del load balancer, e consente di creare allarmi che avvisano il team o attivano azioni (ad esempio tramite Amazon SNS, EC2 Auto Scaling o AWS Lambda) quando viene superata una soglia. Supporta anche il rilevamento delle anomalie sulle metriche.","optionExplanations":["CloudTrail registra le chiamate API effettuate nell'account a fini di audit; non monitora le metriche di errore delle applicazioni né genera allarmi su di esse.","GuardDuty rileva minacce alla sicurezza come attività sospette; non monitora i tassi di errore delle applicazioni.","Corretto — CloudWatch raccoglie le metriche di errore del load balancer e genera allarmi che possono avvisare il team o attivare azioni.","AWS Config registra e valuta le modifiche alla configurazione delle risorse; non tiene traccia delle metriche di errore nel tempo."]},
  "370": {"h":"2fd6b92c","question":"Quale servizio AWS fornisce operazioni automatizzate tramite runbook e playbook, consentendo di applicare patch, configurare e gestire su larga scala istanze EC2 e server on-premises?","options":["AWS CloudTrail","Amazon EC2 Auto Scaling","AWS Systems Manager","AWS Config"],"explanation":"AWS Systems Manager fornisce strumenti operativi per gestire risorse AWS e on-premises: gestione delle patch (Patch Manager), configurazione (State Manager), esecuzione di comandi (Run Command), archiviazione di parametri (Parameter Store) e altro.","optionExplanations":["AWS CloudTrail registra l'attività API nell'account a fini di audit — non applica patch, non configura e non esegue comandi sui server.","Amazon EC2 Auto Scaling regola il numero di istanze EC2 in base alla domanda — gestisce la capacità, non patching, esecuzione di comandi o gestione della configurazione.","Corretto — AWS Systems Manager fornisce runbook, gestione delle patch, esecuzione di comandi, gestione della configurazione e archiviazione di parametri per server AWS e on-premises.","AWS Config valuta le configurazioni delle risorse rispetto a regole di conformità — monitora la conformità ma non esegue attività operative come il patching o l'esecuzione di comandi remoti."]},
  "371": {"h":"f8b1a6a6","question":"Gli sviluppatori front-end di un'azienda stanno realizzando un'app mobile. Vogliono un unico endpoint GraphQL, in modo che una sola richiesta possa recuperare il profilo di un utente da Amazon DynamoDB e i suoi ordini da una funzione AWS Lambda, con aggiornamenti in tempo reale. Non vogliono gestire server GraphQL propri. Quale servizio AWS dovrebbero usare?","options":["Amazon API Gateway","AWS AppSync","AWS Step Functions","Amazon EventBridge"],"explanation":"AWS AppSync è un servizio GraphQL gestito. Si collega a sorgenti dati come DynamoDB, Lambda, Amazon RDS, Amazon OpenSearch Service e API HTTP, e supporta sottoscrizioni in tempo reale, così una sola richiesta può combinare dati da più sorgenti.","optionExplanations":["API Gateway crea e gestisce API REST, HTTP e WebSocket. Non è un servizio GraphQL gestito che combina più sorgenti dati in una sola query.","Corretto — AppSync fornisce un endpoint GraphQL gestito che combina in una sola richiesta dati da DynamoDB e Lambda, con aggiornamenti in tempo reale.","Step Functions coordina i passaggi di un workflow. Non fornisce un'API GraphQL per un'app mobile.","EventBridge instrada eventi tra applicazioni e servizi. Non serve query GraphQL ai client front-end."]},
  "372": {"h":"ac1389ee","question":"Quale servizio AWS fornisce una pipeline CI/CD completamente gestita per compilare, testare e distribuire applicazioni?","options":["AWS CloudFormation","AWS CodePipeline","AWS CodeBuild","AWS CodeDeploy"],"explanation":"AWS CodePipeline è un servizio di continuous delivery completamente gestito che orchestra le fasi di build, test e deploy. Si integra con CodeCommit, CodeBuild, CodeDeploy, GitHub, Jenkins e strumenti di terze parti per automatizzare le pipeline di rilascio.","optionExplanations":["AWS CloudFormation distribuisce infrastruttura come codice — può essere una fase di deploy in una pipeline, ma non è il servizio di orchestrazione della pipeline in sé.","Corretto — AWS CodePipeline orchestra le fasi CI/CD (build, test, deploy), integrandosi con CodeBuild, CodeDeploy, CodeCommit, GitHub e altri strumenti.","AWS CodeBuild compila il codice ed esegue i test — è una fase di build all'interno di una pipeline, non il servizio di orchestrazione che collega tutte le fasi.","AWS CodeDeploy automatizza i deployment su EC2/Lambda/ECS — è una fase di deploy, non l'orchestrazione complessiva della pipeline CI/CD."]},
  "373": {"h":"4131e51c","question":"Un'applicazione web gira su diverse istanze Amazon EC2 in due Availability Zone. L'azienda vuole che il traffico in ingresso sia distribuito tra le istanze e che le richieste smettano di essere inviate a qualsiasi istanza che non superi un health check. Quale servizio AWS dovrebbe usare?","options":["Amazon Route 53 Resolver","Elastic Load Balancing","Amazon CloudFront","AWS Direct Connect"],"explanation":"Elastic Load Balancing distribuisce automaticamente il traffico in ingresso sulle destinazioni integre in più Availability Zone e smette di instradare verso le destinazioni che non superano gli health check. È il modo standard per rendere altamente disponibile un livello web composto da più istanze.","optionExplanations":["Route 53 Resolver risponde alle query DNS all'interno e tra VPC e reti on-premises; non bilancia il traffico tra le istanze.","Corretto — Elastic Load Balancing distribuisce il traffico tra istanze EC2 in più AZ e invia le richieste solo alle destinazioni integre.","CloudFront memorizza in cache i contenuti nelle edge location; può stare davanti a un load balancer ma non esegue health check né bilancia le singole istanze.","Direct Connect è un collegamento di rete privato tra on-premises e AWS; non distribuisce il traffico applicativo."]},
  "374": {"h":"46354089","question":"Un servizio ordini di un e-commerce attualmente chiama direttamente i servizi di spedizione, fatturazione ed email, quindi quando uno di essi non è disponibile i nuovi ordini falliscono. L'azienda vuole che il servizio ordini pubblichi ogni evento d'ordine una sola volta e che ciascun servizio a valle lo riceva e lo elabori in modo indipendente, con i messaggi conservati in sicurezza mentre un servizio non è disponibile. Quali servizi AWS dovrebbe usare l'azienda? (Seleziona DUE)","options":["Amazon SQS","Amazon RDS","Amazon SNS","Amazon ElastiCache"],"explanation":"Amazon SNS e Amazon SQS insieme disaccoppiano i componenti (pattern fan-out). Il servizio ordini pubblica ogni evento una sola volta su un topic SNS, che lo recapita a una coda SQS per ciascun servizio a valle. Ogni coda conserva i messaggi finché il relativo servizio non è in grado di elaborarli, quindi un'interruzione di un servizio non fa più fallire gli ordini.","optionExplanations":["Corretto — Una coda SQS per ciascun servizio a valle conserva i messaggi finché quel servizio non è disponibile, così i servizi lavorano indipendentemente dal servizio ordini.","Amazon RDS è un database relazionale. Archivia dati ma non è un servizio di messaggistica per disaccoppiare i componenti applicativi.","Corretto — Un topic SNS consente al servizio ordini di pubblicare ogni evento una sola volta e lo distribuisce a ogni servizio a valle sottoscritto.","Amazon ElastiCache è una cache in memoria usata per velocizzare l'accesso ai dati. Non serve a recapitare messaggi tra componenti applicativi."]},
  "375": {"h":"95258ef1","question":"Quale funzionalità di Amazon S3 consente di ospitare un sito web statico (HTML, CSS, JavaScript) direttamente da un bucket S3?","options":["S3 Transfer Acceleration","S3 Object Lambda","S3 Static Website Hosting","S3 Replication"],"explanation":"S3 Static Website Hosting consente di servire un sito web statico direttamente da un bucket S3 con un dominio personalizzato. I file sono serviti via HTTP. Per HTTPS e CDN, si posiziona CloudFront davanti al bucket S3.","optionExplanations":["S3 Transfer Acceleration velocizza upload e download su S3 tramite le edge location di CloudFront — non ospita siti web statici direttamente dal bucket.","S3 Object Lambda trasforma i dati quando vengono recuperati da S3 usando Lambda — serve alla trasformazione dei dati, non all'hosting di siti web statici.","Corretto — S3 Static Website Hosting serve file HTML/CSS/JS direttamente da un bucket S3 come sito web statico, con endpoint HTTP (per HTTPS serve CloudFront).","S3 Replication copia oggetti tra bucket — fornisce ridondanza o distribuzione geografica, non funzionalità di hosting di siti web."]},
  "376": {"h":"b55dbd34","question":"Quale servizio AWS fornisce un servizio di message broker completamente gestito che supporta i protocolli Apache ActiveMQ e RabbitMQ?","options":["Amazon SQS","Amazon SNS","Amazon Kinesis","Amazon MQ"],"explanation":"Amazon MQ è un servizio di message broker gestito per Apache ActiveMQ e RabbitMQ. È pensato per migrare su AWS i workload di message broker esistenti con modifiche minime al codice. SQS e SNS sono le alternative native AWS per le nuove applicazioni.","optionExplanations":["Amazon SQS è un servizio di code di messaggi nativo AWS — usa una propria API, non i protocolli Apache ActiveMQ o RabbitMQ, quindi le app esistenti richiederebbero una riscrittura del codice per migrare.","Amazon SNS è un servizio di notifiche pub/sub nativo AWS — non supporta i protocolli ActiveMQ o RabbitMQ.","Amazon Kinesis serve allo streaming di dati in tempo reale — non è un message broker compatibile con ActiveMQ o RabbitMQ.","Corretto — Amazon MQ è il servizio di message broker gestito che supporta Apache ActiveMQ e RabbitMQ, consentendo di migrare i workload di message broker esistenti con modifiche minime al codice."]},
  "377": {"h":"4ec6e661","question":"Un processore di pagamenti esegue workload mission-critical in cui anche brevi interruzioni sono molto costose. Vuole che il proprio piano AWS Support fornisca ingegneri specialisti di dominio dedicati che conoscano le sue applicazioni, ingegneri di incident management che intervengano entro pochi minuti durante gli incidenti critici e revisioni continue della resilienza. Quale piano AWS Support soddisfa questi requisiti?","options":["Basic Support","AWS Business Support+","AWS Enterprise Support","AWS Unified Operations"],"explanation":"AWS Unified Operations è l'opzione di Support per i workload mission-critical che richiedono una resilienza superiore e competenze specifiche sulle applicazioni. Aggiunge ingegneri specialisti di dominio dedicati, ingegneri di incident management che rispondono entro pochi minuti agli incidenti critici e revisioni continue dell'architettura e della resilienza.","optionExplanations":["Basic Support comprende servizio clienti, documentazione, AWS re:Post e i controlli core di Trusted Advisor. Non prevede ingegneri assegnati ai workload dell'azienda.","Business Support+ è il piano minimo consigliato per i workload di produzione, con supporto tecnico 24/7, ma non prevede specialisti di dominio dedicati né ingegneri di incident management.","Enterprise Support fornisce un TAM dedicato e revisioni consulenziali per i workload business-critical, ma gli specialisti di dominio e gli ingegneri di incident management descritti fanno parte di Unified Operations.","Corretto — Unified Operations è pensato per i workload mission-critical, con ingegneri specialisti di dominio, ingegneri di incident management e revisioni continue della resilienza."]},
  "378": {"h":"f0be2c7f","question":"Un team di sviluppo arresta ogni sera e nei fine settimana le proprie istanze EC2 On-Demand con storage EBS per risparmiare. Mentre le istanze sono arrestate, quale costo continua a maturare?","options":["Costi orari di calcolo delle istanze","Costi di storage dei volumi EBS collegati","Costi di trasferimento dati per il traffico internet in ingresso","Costi di licenza inclusi nel prezzo orario dell'istanza"],"explanation":"Quando un'istanza con storage EBS viene arrestata, AWS smette di addebitare l'utilizzo dell'istanza, ma i suoi volumi EBS continuano a esistere e a generare costi di storage. Per eliminare anche questo costo, il team dovrebbe eliminare i volumi non più necessari, ad esempio dopo averne creato degli snapshot.","optionExplanations":["I costi di calcolo di un'istanza On-Demand si interrompono mentre l'istanza è nello stato arrestato.","Corretto — i volumi EBS restano allocati mentre l'istanza è arrestata, quindi il loro storage continua a essere fatturato.","Il trasferimento dati in ingresso da internet in genere non viene addebitato, e comunque un'istanza arrestata non riceve traffico.","Le licenze software incluse nel prezzo dell'istanza, come una licenza Windows, sono fatturate insieme all'utilizzo dell'istanza, quindi si interrompono anch'esse."]},
  "379": {"h":"a1772a76","question":"Una startup sposta una piccola API su AWS Lambda. L'API riceve pochissime richieste di notte e molte durante l'orario lavorativo. Come verrà addebitata alla startup l'esecuzione delle sue funzioni Lambda?","options":["Una tariffa mensile fissa per ogni funzione distribuita","Per richiesta e per durata di esecuzione","A ore per i server sottostanti, anche se inattivi","In base al picco mensile di utenti"],"explanation":"AWS Lambda addebita il numero di richieste e il tempo di esecuzione del codice, in base alla memoria allocata alla funzione. Con il modello on-demand predefinito non c'è alcun costo quando il codice non è in esecuzione, quindi le tranquille ore notturne costano pochissimo.","optionExplanations":["Lambda non prevede una tariffa mensile fissa per funzione; il costo dipende da quanto le funzioni vengono effettivamente usate.","Corretto — Lambda fattura ogni richiesta e la durata di ogni esecuzione, quindi il costo segue l'utilizzo effettivo.","Lambda è serverless: la startup non paga server inattivi, ma solo richieste e tempo di esecuzione.","Il prezzo di Lambda non si basa sul numero di utenti, ma sulle richieste e sulla durata di esecuzione."]},
  "380": {"h":"a1aec1a3","question":"Quale strumento AWS fornisce un'interfaccia visuale per esplorare i costi AWS, visualizzare gli andamenti della spesa e prevedere i costi futuri in base all'utilizzo storico?","options":["AWS Budgets","AWS Pricing Calculator","AWS Cost Explorer","AWS Cost and Usage Report"],"explanation":"AWS Cost Explorer fornisce grafici interattivi per analizzare i costi nel tempo (fino a 13 mesi di storico), suddividerli per servizio/tag/account, individuare tendenze e prevedere la spesa. È disponibile senza costi aggiuntivi.","optionExplanations":["AWS Budgets serve a impostare limiti di spesa e ricevere avvisi — fornisce il monitoraggio del budget, non una visualizzazione interattiva degli andamenti storici dei costi.","AWS Pricing Calculator stima i costi di architetture future prima del deployment — non visualizza l'utilizzo esistente né fa previsioni basate sui dati storici.","Corretto — AWS Cost Explorer fornisce una dashboard visuale interattiva per esplorare fino a 13 mesi di costi storici, filtrare per dimensione (servizio, tag, account) e prevedere la spesa futura.","Il Cost and Usage Report consegna dati grezzi su S3 — richiede uno strumento di analisi separato per la visualizzazione e non ha un'interfaccia grafica integrata."]},
  "381": {"h":"fc564729","question":"Un'azienda assegna a ciascun team di sviluppo un limite mensile di spesa AWS. I responsabili dei team vogliono un avviso via email o Amazon SNS non appena i costi effettivi superano il limite, oppure quando si prevede che lo superino prima della fine del mese. Quale servizio AWS dovrebbe usare l'azienda?","options":["AWS Cost Explorer","AWS Pricing Calculator","AWS Budgets","AWS Cost and Usage Report"],"explanation":"AWS Budgets consente di impostare budget personalizzati di costo, utilizzo o reservation e invia avvisi via email o Amazon SNS quando gli importi effettivi o previsti superano le soglie. Può anche eseguire budget action, come l'applicazione di policy IAM o SCP, quando un budget viene superato.","optionExplanations":["Cost Explorer visualizza e prevede la spesa, ma non è il servizio per definire soglie di budget e inviare avvisi.","Pricing Calculator stima il costo dei workload pianificati; non tiene traccia della spesa effettiva né invia avvisi.","Corretto — AWS Budgets avvisa i responsabili dei team quando i costi effettivi o previsti superano il loro limite mensile.","Il Cost and Usage Report fornisce file di dati di fatturazione dettagliati; non invia avvisi al superamento di soglie."]},
  "382": {"h":"77fe2fb7","question":"Un'azienda ha applicato alle proprie risorse AWS un tag «CostCenter». Il team finance vuole suddividere i costi in base a questo tag in AWS Cost Explorer, ma il tag non compare. Che cosa deve fare il team?","options":["Attivarlo come cost allocation tag","Rinominarlo in modo che inizi con aws:","Ricreare ogni risorsa con il tag","Passare a un piano Support a pagamento"],"explanation":"I tag definiti dall'utente devono essere attivati come cost allocation tag nella console Billing and Cost Management prima di poter essere usati per filtrare e raggruppare i costi in Cost Explorer e nei report di fatturazione. Nei dati di costo compaiono solo i tag applicati dopo l'attivazione.","optionExplanations":["Corretto — i tag definiti dall'utente compaiono in Cost Explorer e nei report di fatturazione solo dopo essere stati attivati come cost allocation tag.","Il prefisso aws: è riservato ai tag generati da AWS; i clienti non possono creare tag con questo prefisso.","Non è necessario ricreare le risorse; attivare il tag è sufficiente per i nuovi dati di costo.","I cost allocation tag sono disponibili senza alcun piano Support a pagamento."]},
  "383": {"h":"4dae96e1","question":"Un'azienda esegue su istanze Amazon EC2 On-Demand Linux un job batch che termina in circa 12 minuti. Un manager presume che l'azienda paghi ogni volta un'ora intera. Come viene effettivamente fatturato questo utilizzo?","options":["Al secondo, dopo un breve minimo","Per ora intera, arrotondata per eccesso","Per ogni giorno di esistenza dell'istanza","Una tariffa mensile fissa per istanza"],"explanation":"Le istanze On-Demand Linux sono fatturate al secondo con un minimo di un minuto, quindi l'azienda paga solo il tempo in cui le istanze sono effettivamente in esecuzione. Questo modello pay-as-you-go è uno dei principali vantaggi dei prezzi del cloud.","optionExplanations":["Corretto — le istanze On-Demand Linux usano la fatturazione al secondo con un breve minimo, quindi un job di 12 minuti non viene addebitato come un'ora intera.","L'arrotondamento orario non si applica alle istanze On-Demand Linux, che sono fatturate al secondo.","Le istanze EC2 sono fatturate per il tempo di esecuzione, non per ogni giorno in cui esistono.","Le istanze On-Demand non hanno una tariffa mensile fissa; si paga solo il tempo utilizzato."]},
  "384": {"h":"71ded18e","question":"Un'azienda ha recentemente acquisito altre due società, ciascuna con il proprio account AWS e il proprio metodo di pagamento. Il CFO vuole un'unica fattura mensile pagata da un solo account e vuole che l'utilizzo combinato di tutti gli account conti ai fini delle fasce di prezzo per volume. Quale servizio AWS dovrebbe usare l'azienda?","options":["AWS Cost Explorer","AWS Organizations","AWS Budgets","AWS Trusted Advisor"],"explanation":"AWS Organizations fornisce la fatturazione consolidata (consolidated billing). Il management account riceve e paga un'unica fattura per tutti gli account membri, e l'utilizzo viene sommato tra gli account, il che può far raggiungere prima fasce di prezzo per volume più basse.","optionExplanations":["Cost Explorer analizza e visualizza i costi. Non unisce account separati in un'unica fattura.","Corretto — La fatturazione consolidata di AWS Organizations fornisce un'unica fattura per tutti gli account e somma l'utilizzo ai fini delle fasce di prezzo per volume.","Budgets imposta soglie di spesa e invia avvisi. Non unisce la fatturazione tra account.","Trusted Advisor fornisce raccomandazioni sulle best practice. Non consolida la fatturazione né somma l'utilizzo."]},
  "385": {"h":"614a9e2a","question":"Un'azienda ha più account AWS per diversi reparti. Quale funzionalità AWS consente a tutti gli account di beneficiare degli acquisti di Reserved Instance di un reparto?","options":["AWS Budgets","Fatturazione consolidata","AWS Cost Explorer","AWS Pricing Calculator"],"explanation":"Con la fatturazione consolidata di AWS Organizations, gli sconti di Reserved Instance e Savings Plans sono condivisi tra tutti gli account collegati. Se l'account che ha effettuato l'acquisto non usa la capacità RI, lo sconto si applica all'utilizzo degli altri account collegati.","optionExplanations":["AWS Budgets monitora i livelli di spesa — non controlla il modo in cui gli sconti RI o Savings Plans sono condivisi tra gli account.","Corretto — Con la fatturazione consolidata, la capacità RI o Savings Plans non usata da un account collegato si applica automaticamente all'utilizzo idoneo degli altri account dell'organizzazione.","Cost Explorer mostra dove vengono applicati gli sconti ma è uno strumento di reportistica — non controlla il meccanismo di condivisione delle RI.","AWS Pricing Calculator stima i costi futuri — non può condividere impegni di prezzo o sconti tra account."]},
  "386": {"h":"4defcfe6","question":"Quale modello di prezzo AWS addebita al secondo il tempo di calcolo utilizzato, senza costi anticipati né impegni minimi?","options":["Prezzi Reserved","Prezzi Spot","Prezzi On-Demand","Prezzi Dedicated Host"],"explanation":"Il modello On-Demand addebita la capacità di calcolo al secondo (Linux) o all'ora, senza impegni a lungo termine. È l'opzione più flessibile e la più costosa per unità, ideale per workload imprevedibili o di breve durata.","optionExplanations":["I prezzi Reserved richiedono un impegno di 1 o 3 anni — non sono un modello flessibile senza impegno con pagamento al secondo.","I prezzi Spot offrono potenziali risparmi usando la capacità EC2 inutilizzata, ma le istanze possono essere interrotte in qualsiasi momento — non sono davvero flessibili per workload che richiedono disponibilità garantita.","Corretto — Il modello On-Demand addebita al secondo (Linux, minimo 60 s) o all'ora, senza costi anticipati né impegni, offrendo la massima flessibilità.","I prezzi Dedicated Host sono disponibili come On-Demand o Reserved e si applicano all'allocazione di un server fisico — non sono il modello generico e flessibile con pagamento al secondo descritto."]},
  "387": {"h":"94389003","question":"Uno studente crea un nuovo account AWS per imparare il cloud computing e non vuole pagare per il supporto. Lo studente verifica quale piano di supporto ha automaticamente l'account e conferma che include documentazione, whitepaper, AWS re:Post e l'AWS Health Dashboard. Quale piano AWS Support ha l'account?","options":["AWS Business Support+","AWS Enterprise Support","AWS Unified Operations","Basic Support"],"explanation":"AWS Basic Support è incluso automaticamente in ogni account AWS senza costi aggiuntivi. Fornisce servizio clienti 24/7, documentazione, whitepaper, AWS re:Post, i controlli core di AWS Trusted Advisor e una vista personalizzata dello stato dei servizi tramite AWS Health. Il supporto tecnico da parte degli ingegneri AWS richiede un piano a pagamento come Business Support+.","optionExplanations":["Business Support+ è un piano a pagamento per i workload di produzione che il titolare dell'account deve scegliere. Non è incluso automaticamente in un nuovo account.","Enterprise Support è un piano a pagamento per i workload business-critical. Non è incluso automaticamente in un nuovo account.","Unified Operations è un'opzione a pagamento per i workload mission-critical. Non è inclusa automaticamente in un nuovo account.","Corretto — Basic Support è incluso in ogni account AWS e fornisce documentazione, whitepaper, AWS re:Post e AWS Health."]},
  "388": {"h":"33b9ad8a","question":"Un'azienda esegue ogni notte un job di analisi su Amazon EC2. I risultati non sono sensibili alla latenza e l'azienda non ha requisiti di residenza dei dati. Vuole ridurre il costo del job senza cambiare il tipo di istanza né l'opzione di acquisto. Che cosa dovrebbe valutare l'azienda?","options":["Eseguire il job in una Region con prezzi più bassi","Eseguire il job in una AWS Local Zone vicina agli utenti","Passare l'account ad AWS Business Support+","Spostare il job in una edge location di Amazon CloudFront"],"explanation":"I prezzi AWS per lo stesso servizio e tipo di istanza possono variare tra Region. Quando latenza e residenza dei dati non sono vincoli, eseguire il workload in una Region con prezzi più bassi può ridurre i costi, purché l'azienda consideri anche eventuali costi di trasferimento dati tra Region.","optionExplanations":["Corretto — i prezzi variano a seconda della Region, quindi una Region con un prezzo più basso per lo stesso tipo di istanza può ridurre il costo del job.","Le Local Zones collocano la capacità di calcolo vicino agli utenti finali per una bassa latenza. Il job non è sensibile alla latenza e questa scelta non punta a prezzi più bassi.","Un piano Support aggiunge supporto tecnico. Non abbassa il prezzo delle istanze EC2.","Le edge location di CloudFront memorizzano in cache e distribuiscono contenuti. Non possono eseguire il job di analisi EC2 dell'azienda."]},
  "389": {"h":"38232e1a","question":"Un'azienda gestisce risorse di sviluppo e di produzione nello stesso account AWS. Vuole associare a ciascuna risorsa etichette come Environment e Owner, in modo da limitare gli sviluppatori alle risorse di sviluppo tramite condizioni IAM e suddividere la fattura per responsabile. Quale funzionalità AWS dovrebbe usare?","options":["AWS Resource Groups","Regole AWS Config","Tag delle risorse","OU di AWS Organizations"],"explanation":"I tag delle risorse sono etichette chiave-valore associate alle risorse AWS. I tag possono essere usati nelle condizioni delle policy IAM per controllare l'accesso (ad esempio, solo alle risorse con tag Environment=Development), e i cost allocation tag attivati consentono all'azienda di suddividere la fattura per responsabile negli strumenti di fatturazione come Cost Explorer.","optionExplanations":["Resource Groups organizza risorse che condividono già tag o altri criteri; non etichetta le risorse né controlla l'accesso da solo.","Le regole di Config valutano se le risorse rispettano le impostazioni desiderate (ad esempio, se i tag richiesti sono presenti); non etichettano le risorse.","Corretto — i tag etichettano ogni risorsa, possono essere usati nelle condizioni IAM e consentono l'allocazione dei costi per responsabile.","Le OU raggruppano account AWS all'interno di un'organizzazione; non possono separare risorse che si trovano nello stesso account."]},
  "390": {"h":"364ed008","question":"Un'azienda sta analizzando la propria fattura AWS e nota costi di trasferimento dati inaspettatamente elevati. Quale servizio AWS aiuterebbe MEGLIO a individuare esattamente quali risorse generano questi costi?","options":["AWS Budgets","AWS Pricing Calculator","AWS Cost and Usage Report con Athena","Controlli di cost optimization di AWS Trusted Advisor"],"explanation":"L'AWS Cost and Usage Report (CUR) fornisce il dettaglio voce per voce di ogni addebito, incluso il trasferimento dati, per ID risorsa. Interrogarlo con Athena consente di individuare esattamente quali istanze EC2 o NAT Gateway generano costi di trasferimento elevati.","optionExplanations":["AWS Budgets fornisce avvisi sulla spesa a livello complessivo — non individua quali risorse specifiche generano i costi inattesi.","AWS Pricing Calculator stima i costi futuri — non può analizzare i dati storici di fatturazione per individuare l'origine degli addebiti.","Corretto — Il CUR include gli ID delle risorse e suddivisioni dettagliate per tipo di utilizzo (compreso il trasferimento dati) per ogni addebito. Interrogarlo con Athena consente di individuare esattamente le risorse responsabili.","Trusted Advisor può segnalare alcuni schemi di costo elevato nei controlli Cost Optimization, ma non ha la granularità voce per voce per risorsa necessaria a individuare le origini specifiche dei costi di trasferimento dati."]},
  "391": {"h":"5197d08b","question":"Una piccola azienda usa solo il piano AWS Basic Support. Il suo team finance ha una domanda su un addebito inatteso nella fattura mensile. Che cosa può fare il team?","options":["Aprire un caso di supporto account e fatturazione senza costi aggiuntivi","Passare a Business Support+ prima che AWS risponda a domande di fatturazione","Chiedere al Technical Account Manager assegnato all'account","Pubblicare i dettagli della fattura su AWS re:Post solo per l'aiuto della community"],"explanation":"Ogni piano AWS Support, compreso il piano Basic gratuito, include un servizio clienti 24/7 per domande su account e fatturazione. Il team può aprire un caso di supporto account e fatturazione senza effettuare l'upgrade, mentre i casi di supporto tecnico richiedono un piano a pagamento.","optionExplanations":["Corretto — Basic Support include il servizio clienti per domande su account e fatturazione, quindi il team può aprire un caso di fatturazione senza costi aggiuntivi.","L'upgrade aggiunge il supporto tecnico. Le domande su account e fatturazione sono già coperte dal servizio clienti in ogni piano, incluso Basic.","Un Technical Account Manager dedicato è previsto con Enterprise Support, non con Basic Support, quindi questo account non ne ha uno.","re:Post è un sito di domande e risposte della community e non è il posto giusto per i dettagli privati di una fattura. Il servizio clienti AWS gestisce direttamente le domande di fatturazione."]},
  "392": {"h":"83bb05ad","question":"Un'azienda ha cinque account AWS, ciascuno dei quali usa una quantità moderata di storage Amazon S3. Il team finance vuole che gli account beneficino di prezzi a fasce più bassi in base al loro utilizzo combinato. Che cosa dovrebbe fare l'azienda?","options":["Abilitare la fatturazione consolidata con AWS Organizations","Acquistare un Savings Plan separato per ciascuno dei cinque account","Attivare i cost allocation tag in ogni account","Passare ogni account a Business Support+"],"explanation":"Con la fatturazione consolidata di AWS Organizations, l'utilizzo di tutti gli account viene sommato ai fini del prezzo, quindi l'organizzazione raggiunge prima le fasce di prezzo per volume (come le fasce di storage S3). I cost allocation tag servono solo a tracciare i costi; non modificano i prezzi.","optionExplanations":["Corretto — la fatturazione consolidata aggrega l'utilizzo di tutti gli account membri, quindi gli sconti per volume a fasce si applicano al totale combinato.","I Savings Plans offrono sconti sull'utilizzo di calcolo in cambio di un impegno; non sommano l'utilizzo di storage S3 tra gli account.","I cost allocation tag aiutano a classificare e rendicontare i costi; non abbassano il prezzo di alcun utilizzo.","I piani Support forniscono supporto tecnico; non hanno alcun effetto sulle fasce di prezzo per volume."]},
  "393": {"h":"dae99d7e","question":"Un'azienda con il piano AWS Enterprise Support ha domande complesse sulle proprie fatture e sulla struttura degli account. Quale risorsa AWS inclusa nel suo piano è specializzata in richieste su fatturazione e account?","options":["Il team AWS Trust & Safety","Il billing concierge di Enterprise","I consulenti di AWS Professional Services","Le società dell'AWS Partner Network"],"explanation":"Enterprise Support include un billing concierge white-glove: esperti di fatturazione e account che aiutano con fatture, struttura degli account e altre richieste di fatturazione. Il team Trust & Safety gestisce le segnalazioni di abusi, mentre Professional Services e i partner aiutano con progetti tecnici, non con le fatture.","optionExplanations":["Il team Trust & Safety gestisce le segnalazioni di abusi, come spam o attacchi provenienti da risorse AWS. Non risponde a domande di fatturazione.","Corretto — Enterprise Support include un billing concierge white-glove che aiuta con le richieste su fatturazione e account.","AWS Professional Services aiuta i clienti con progetti di migrazione e architettura. Non gestisce fatture e richieste sugli account.","L'AWS Partner Network è composta da partner terzi di consulenza e tecnologia. Non è il team AWS per il supporto alla fatturazione."]},
  "394": {"h":"337c75a7","question":"Quale offerta AWS rappresenta la rete globale di partner AWS (società di consulenza, ISV, rivenditori) che integrano i servizi AWS?","options":["Catalogo software di AWS Marketplace","AWS Knowledge Center","AWS Partner Network (APN)","Community AWS re:Post"],"explanation":"L'AWS Partner Network (APN) è la community globale dei partner AWS, che comprende i Consulting Partner (implementano soluzioni AWS) e i Technology Partner (prodotti software che girano su AWS o si integrano con esso). I partner APN sono verificati da AWS.","optionExplanations":["AWS Marketplace è uno store online per acquistare software di terze parti e prodotti SaaS — non è una rete di società partner certificate di consulenza e tecnologia.","L'AWS Knowledge Center è una raccolta di articoli che rispondono a domande comuni di supporto; non è una rete di società partner.","Corretto — L'AWS Partner Network (APN) è la community globale di Consulting Partner (società di implementazione) e Technology Partner (ISV) che sviluppano su AWS o lavorano con AWS.","AWS re:Post è un forum di domande e risposte della community — non è un programma per certificare o organizzare partner commerciali."]},
  "395": {"h":"8d3071fa","question":"Quale servizio AWS è un catalogo online di software di terze parti, prodotti SaaS e prodotti di dati che possono essere distribuiti direttamente negli account AWS?","options":["AWS Partner Network","AWS Service Catalog","AWS Marketplace","AWS License Manager"],"explanation":"AWS Marketplace è un catalogo digitale con migliaia di offerte software di fornitori indipendenti. I clienti possono trovare, provare, acquistare e distribuire software su AWS. Gli acquisti vengono fatturati tramite l'account AWS, semplificando l'approvvigionamento.","optionExplanations":["L'AWS Partner Network è un programma di certificazione per società partner di consulenza e tecnologia — non è uno store per acquistare prodotti software.","AWS Service Catalog consente alle organizzazioni di creare cataloghi interni di servizi IT approvati per i dipendenti — serve alla governance interna, non all'acquisto di prodotti di terze parti.","Corretto — AWS Marketplace è lo store digitale in cui i clienti possono trovare, provare, acquistare e distribuire migliaia di software e prodotti SaaS di terze parti, fatturati tramite il proprio account AWS.","AWS License Manager traccia e controlla l'utilizzo delle licenze software; non è un catalogo in cui scoprire e acquistare prodotti di terze parti."]},
  "396": {"h":"70549235","question":"Una piattaforma video archivia in Amazon S3 una libreria in rapida crescita. Senza aver sottoscritto alcun impegno, il team finance nota che il prezzo per GB pagato per lo storage diminuisce all'aumentare della quantità totale archiviata ogni mese. Quale principio di prezzo AWS spiega questo fenomeno?","options":["Pay-as-you-go","Pay less when you reserve","Pay less by using more","AWS Free Tier"],"explanation":"'Pay less by using more' si riferisce ai prezzi a fasce basati sul volume. Per servizi come lo storage Amazon S3 e il trasferimento dati, il prezzo unitario diminuisce all'aumentare dell'utilizzo, senza alcun impegno richiesto.","optionExplanations":["Pay-as-you-go significa pagare solo ciò che si usa, senza costi anticipati. Non spiega perché il prezzo unitario diminuisca all'aumentare del volume.","Pay less when you reserve richiede un impegno, come Reserved Instances o Savings Plans. Il team finance non ha sottoscritto alcun impegno.","Corretto — I prezzi a fasce abbassano il prezzo per GB all'aumentare del volume di storage, senza alcun impegno.","Il Free Tier offre ai clienti un utilizzo gratuito limitato. Non abbassa il prezzo unitario all'aumentare dell'utilizzo."]},
  "397": {"h":"f5f77c28","question":"Uno sviluppatore ha creato un account AWS con il piano Free. L'account si avvicina alla fine dei suoi primi sei mesi e lo sviluppatore vuole che i workload continuino a funzionare anche dopo. Che cosa deve fare lo sviluppatore?","options":["Passare l'account al piano Paid","Ottenere altri crediti provando altri servizi","Sottoscrivere AWS Business Support+","Abilitare la fatturazione consolidata per l'account"],"explanation":"Un account con il piano Free può usare i propri crediti per un massimo di sei mesi. Quando quel periodo termina o i crediti si esauriscono, l'account viene chiuso a meno che il titolare non lo passi al piano Paid. Dopo l'upgrade, le offerte sempre gratuite continuano ad applicarsi e il resto dell'utilizzo viene addebitato.","optionExplanations":["Corretto — passare al piano Paid mantiene l'account aperto dopo la fine del periodo del piano Free, con l'addebito dell'utilizzo che va oltre le offerte gratuite.","Esplorare i servizi può aggiungere crediti, ma il piano Free termina comunque dopo sei mesi e l'account viene chiuso se non si effettua l'upgrade.","Business Support+ è un piano di supporto tecnico. Acquistare il supporto non sostituisce il passaggio dell'account al piano Paid.","La fatturazione consolidata unisce le fatture degli account di un'organizzazione. Non estende il periodo del piano Free."]},
  "398": {"h":"8b24a968","question":"Prima di migrare su AWS, un'azienda intende replicare le dimensioni dei server che usa on-premises, molti dei quali acquistati anni fa per i picchi di domanda. Un consulente raccomanda di esaminare prima le effettive esigenze di CPU, memoria e storage di ciascun workload, e poi di scegliere il tipo e la dimensione di istanza con il miglior rapporto prestazioni/costo. Quale pratica di ottimizzazione dei costi sta raccomandando il consulente?","options":["Usare Spot Instances per tutti i workload","Right-sizing","Usare Reserved Instances per tutti i workload","Mantenere le dimensioni dei server on-premises"],"explanation":"Il right-sizing consiste nell'adattare tipi e dimensioni delle istanze alle effettive esigenze di prestazioni e capacità del workload al costo più basso. Analizzare l'utilizzo reale invece di replicare server on-premises sovradimensionati evita di pagare capacità inutilizzata. AWS Compute Optimizer può fornire raccomandazioni di right-sizing.","optionExplanations":["Le Spot Instances possono essere interrotte, quindi non sono adatte a tutti i workload. Il consiglio del consulente riguarda la scelta della dimensione giusta, non un'opzione di acquisto.","Corretto — Il right-sizing analizza le effettive esigenze di risorse e seleziona il tipo e la dimensione di istanza con il miglior rapporto prestazioni/costo.","Le Reserved Instances sono un impegno di prezzo. Impegnarsi su istanze sovradimensionate bloccherebbe proprio lo spreco che il consulente vuole eliminare.","Mantenere le dimensioni on-premises è il piano originale dell'azienda, che porterebbe in AWS server sovradimensionati. Il consulente raccomanda l'opposto."]},
  "399": {"h":"5d84acc2","question":"Un team operativo vuole essere avvisato quando AWS pianifica una manutenzione sugli host sottostanti delle proprie istanze EC2 o quando un problema di un servizio AWS interessa risorse del proprio account. Dove dovrebbe cercare il team questi eventi specifici dell'account?","options":["Metriche di Amazon CloudWatch","AWS Health Dashboard","AWS Trusted Advisor","Timeline di AWS Config"],"explanation":"L'AWS Health Dashboard mostra gli eventi AWS che interessano il proprio account e le proprie risorse, come manutenzioni pianificate o problemi dei servizi, insieme a indicazioni per la risoluzione; le stesse informazioni sono disponibili in modo programmatico tramite l'AWS Health API. Include anche una vista pubblica dello stato generale dei servizi AWS.","optionExplanations":["Le metriche di CloudWatch mostrano le prestazioni delle risorse, ma non riportano eventi lato AWS come la manutenzione pianificata degli host.","Corretto — l'AWS Health Dashboard elenca gli eventi AWS che interessano le risorse dell'account, comprese manutenzioni pianificate e problemi dei servizi.","Trusted Advisor fornisce raccomandazioni sulle best practice; non avvisa di manutenzioni o eventi dei servizi AWS.","AWS Config registra come cambiano nel tempo le configurazioni delle risorse; non riporta eventi dei servizi AWS."]},
  "400": {"h":"9fa2aae0","question":"Quali delle seguenti affermazioni sulle AWS Reserved Instances sono vere? (Seleziona DUE)","options":["Offrono uno sconto rispetto ai prezzi On-Demand in cambio di un impegno di 1 o 3 anni","Sono sempre legate a un'istanza specifica e non possono essere modificate dopo l'acquisto","Le RI Standard possono essere vendute sull'AWS Reserved Instance Marketplace se non servono più","Richiedono il pagamento anticipato dell'intero importo"],"explanation":"Le RI offrono sconti (fino al 72%) per impegni di 1 o 3 anni. Le RI Standard (non le Convertible) possono essere vendute sull'RI Marketplace se non servono più. Le opzioni di pagamento includono No Upfront, Partial Upfront e All Upfront — il pagamento anticipato completo non è obbligatorio. Le RI Convertible possono cambiare gli attributi dell'istanza.","optionExplanations":["Corretto — Le RI offrono sconti (fino al 72% per le Standard, fino al 54% per le Convertible) in cambio di un impegno di 1 o 3 anni.","Le Convertible Reserved Instances POSSONO essere modificate (famiglia di istanze, sistema operativo, tenancy) durante il periodo — l'affermazione che tutte le RI 'non possono essere modificate dopo l'acquisto' è errata.","Corretto — Le RI Standard (non le Convertible) possono essere messe in vendita sull'AWS Reserved Instance Marketplace prima della scadenza del periodo se non servono più.","Le RI offrono tre opzioni di pagamento: No Upfront, Partial Upfront e All Upfront — il pagamento anticipato completo è facoltativo, non obbligatorio."]},
  "401": {"h":"7b67b96e","question":"Durante una valutazione per la migrazione, un'azienda scopre un'applicazione interna di reportistica che nessuno usa da più di un anno. L'azienda vuole dismetterla invece di spostarla su AWS. Quale strategia di migrazione rappresenta questa scelta?","options":["Retain","Retire","Rehost","Relocate"],"explanation":"Retire significa dismettere le applicazioni non più necessarie, riducendo l'ambito, i costi e l'impegno della migrazione. Retain è il distrattore più vicino, ma significa mantenere per ora un'applicazione in esecuzione on-premises, non spegnerla.","optionExplanations":["Retain mantiene un'applicazione in esecuzione nel suo ambiente attuale, spesso per riconsiderarla in seguito. Qui l'azienda vuole spegnere l'applicazione.","Corretto — Retire significa dismettere le applicazioni che non forniscono più valore al business, così da non migrarle affatto.","Rehost sposta un'applicazione su AWS con poche o nessuna modifica. Un'applicazione inutilizzata non ha bisogno di essere spostata.","Relocate sposta l'infrastruttura (ad esempio workload basati su VMware) su AWS senza modifiche. Non spegne nulla."]},
  "402": {"h":"e4a969ed","question":"Il sistema ERP di un'azienda è stato aggiornato on-premises l'anno scorso e dipende da altri sistemi on-premises che non possono ancora essere spostati. L'azienda decide di lasciare il sistema ERP dov'è e di riconsiderare la migrazione in futuro. Quale strategia di migrazione sta usando l'azienda?","options":["Retire","Repurchase","Retain","Replatform"],"explanation":"Retain (a volte chiamata revisit) significa mantenere per ora un'applicazione nel suo ambiente di origine, spesso a causa di investimenti recenti o di dipendenze. Retire dismetterebbe il sistema, il che non è il caso qui, perché l'ERP è ancora necessario.","optionExplanations":["Retire significa dismettere l'applicazione. Il sistema ERP è ancora in uso e necessario al business.","Repurchase significa passare a un prodotto diverso, tipicamente una soluzione SaaS. L'azienda mantiene il suo attuale sistema ERP.","Corretto — Retain significa lasciare per ora l'applicazione dov'è e rivalutare la decisione in seguito, ad esempio dopo aver risolto le dipendenze.","Replatform sposta l'applicazione su AWS con alcune ottimizzazioni. L'azienda ha deciso di non spostarla ancora."]},
  "403": {"h":"4fd74933","question":"Un'azienda esegue centinaia di macchine virtuali su VMware vSphere on-premises. Vuole spostarle rapidamente su AWS senza acquistare nuovo hardware, riscrivere le applicazioni o cambiare le sue attuali operazioni VMware. Quale strategia di migrazione si adatta MEGLIO a questo obiettivo?","options":["Relocate","Refactor","Repurchase","Retire"],"explanation":"Relocate sposta l'infrastruttura nel cloud senza acquistare nuovo hardware, riscrivere le applicazioni o cambiare le operazioni esistenti, ad esempio spostando workload VMware su VMware Cloud on AWS. Refactor richiederebbe di riprogettare le applicazioni, cosa che l'azienda vuole evitare.","optionExplanations":["Corretto — Relocate sposta workload come le macchine virtuali basate su VMware su AWS senza nuovo hardware, modifiche al codice o cambiamenti alle operazioni esistenti.","Refactor significa riprogettare l'applicazione con funzionalità cloud-native. L'azienda non vuole riscrivere le sue applicazioni.","Repurchase sostituisce un'applicazione con un prodotto diverso, di solito SaaS. L'azienda vuole mantenere le sue macchine virtuali esistenti.","Retire significa dismettere le applicazioni. L'azienda vuole continuare a eseguire questi workload."]},
  "404": {"h":"27072ba5","question":"Un'azienda vuole fare il lift and shift di molti server fisici e virtuali su Amazon EC2. Vuole replicare i server in modo continuo, così che il cutover finale causi solo un downtime minimo. Quale servizio AWS dovrebbe usare l'azienda?","options":["AWS DataSync","AWS Transfer Family","AWS Database Migration Service (AWS DMS)","AWS Application Migration Service"],"explanation":"AWS Application Migration Service è il principale servizio AWS per il rehosting (lift and shift). Replica in modo continuo i server di origine su AWS e li avvia come istanze EC2 al momento del cutover con un downtime minimo. AWS DataSync sposta file e AWS DMS sposta database; nessuno dei due replica server interi.","optionExplanations":["AWS DataSync trasferisce file e oggetti tra sistemi di storage. Non replica server interi da eseguire come istanze EC2.","AWS Transfer Family fornisce endpoint SFTP, FTPS e FTP gestiti per lo scambio di file. Non replica server su Amazon EC2.","AWS DMS migra database, non interi server fisici o virtuali.","Corretto — AWS Application Migration Service replica in modo continuo i server su AWS e li avvia come istanze EC2, semplificando il rehosting con un downtime minimo al cutover."]},
  "405": {"h":"535b9a63","question":"Un'azienda vuole spostare il suo database Oracle on-premises su Amazon Aurora. Il database di origine deve restare pienamente operativo durante la migrazione per ridurre al minimo il downtime. Quale servizio AWS è progettato per questo compito?","options":["AWS Snowball Edge","AWS Application Migration Service","AWS Database Migration Service (AWS DMS)","Amazon S3 Transfer Acceleration"],"explanation":"AWS DMS migra database su AWS mentre il database di origine resta operativo, e supporta sia migrazioni tra lo stesso motore sia tra motori diversi, come da Oracle ad Aurora. AWS Application Migration Service serve per il rehosting di server interi, non per convertire un database a un motore diverso.","optionExplanations":["AWS Snowball Edge è un dispositivo fisico per spostare offline grandi quantità di dati. Non mantiene un database attivo sincronizzato con Aurora.","AWS Application Migration Service esegue il rehosting di server interi su EC2. Non migra i dati in un motore di database gestito come Aurora.","Corretto — AWS DMS migra database con un downtime minimo mentre l'origine resta operativa, comprese le migrazioni tra motori di database diversi.","S3 Transfer Acceleration velocizza gli upload su Amazon S3. Non è un servizio di migrazione di database."]},
  "406": {"h":"6fe8a187","question":"Un'azienda deve spostare su AWS diverse centinaia di terabyte di dati archiviati, come progetto una tantum. La sua connessione internet è lenta e un trasferimento online richiederebbe molti mesi. Quale opzione AWS è la PIÙ adatta?","options":["AWS Direct Connect","AWS DataSync","Amazon CloudFront","AWS Snowball Edge"],"explanation":"AWS Snowball Edge, parte della AWS Snow Family, è un dispositivo fisico che viene spedito al cliente, caricato con i dati e rispedito ad AWS per l'importazione. Evita i colli di bottiglia della rete per trasferimenti una tantum molto grandi. AWS DataSync è un servizio di trasferimento online, quindi resterebbe comunque limitato dalla connessione lenta.","optionExplanations":["AWS Direct Connect fornisce un collegamento di rete dedicato, ma richiede tempo per l'attivazione ed è pensato per una connettività continuativa, non per un trasferimento massivo una tantum.","AWS DataSync trasferisce i dati attraverso la rete, quindi resterebbe comunque limitato dalla connessione internet lenta.","Amazon CloudFront è una content delivery network per distribuire contenuti agli utenti. Non è uno strumento di migrazione dei dati.","Corretto — AWS Snowball Edge sposta offline grandi quantità di dati su un dispositivo fisico, evitando la rete lenta per una migrazione una tantum."]},
  "407": {"h":"31ad81bb","question":"Un'azienda ha usato l'AWS Cloud Adoption Framework (AWS CAF) per definire la sua visione del cloud e allineare i suoi dirigenti sui cambiamenti necessari. Ora sta eseguendo in produzione un piccolo numero di progetti pilota per dimostrare un primo valore di business. In quale fase del percorso di trasformazione cloud si trova l'azienda?","options":["Envision","Align","Launch","Scale"],"explanation":"L'AWS CAF descrive quattro fasi iterative della trasformazione cloud: Envision, Align, Launch e Scale. Nella fase Launch, un'organizzazione realizza iniziative pilota in produzione e dimostra un valore di business incrementale. Poi applica ciò che ha imparato prima di espandersi nella fase Scale.","optionExplanations":["La fase Envision identifica e prioritizza le opportunità di trasformazione che supportano gli obiettivi di business. L'azienda ha già definito la sua visione.","La fase Align identifica le lacune di capacità tra le prospettive del CAF e crea un piano d'azione con gli stakeholder. L'azienda ha già allineato i suoi dirigenti.","Corretto — La fase Launch realizza iniziative pilota in produzione e dimostra un valore di business incrementale.","La fase Scale estende i progetti pilota di successo in produzione fino alla scala e all'impatto di business desiderati. L'azienda sta ancora eseguendo solo pochi progetti pilota."]},
  "408": {"h":"70dce267","question":"Un'azienda sta iniziando il suo percorso verso il cloud. I manager temono che i dipendenti non abbiano competenze cloud e che i team oppongano resistenza ai nuovi modi di lavorare. Quale prospettiva dell'AWS Cloud Adoption Framework (AWS CAF) affronta queste preoccupazioni?","options":["Governance","People","Platform","Operations"],"explanation":"La prospettiva People funge da ponte tra tecnologia e business, concentrandosi su cultura, struttura organizzativa, leadership, competenze del personale e gestione del cambiamento. Governance si concentra su gestione dei programmi, rischio e gestione finanziaria del cloud, non sulle competenze e sulla cultura del personale.","optionExplanations":["La prospettiva Governance si concentra sull'orchestrazione delle iniziative cloud, sulla gestione del rischio e sulla gestione finanziaria del cloud, non su competenze e cultura.","Corretto — La prospettiva People copre la cultura, il cambiamento organizzativo, la leadership e lo sviluppo delle competenze cloud del personale.","La prospettiva Platform si concentra sulla costruzione della piattaforma e dell'architettura cloud dal punto di vista tecnico, non su formazione e cultura.","La prospettiva Operations si concentra sull'esecuzione e sul supporto dei servizi cloud ai livelli concordati, non sulle competenze del personale o sulla resistenza al cambiamento."]},
  "409": {"h":"2a7d1821","question":"Un'azienda vuole orchestrare le sue iniziative cloud in modo da massimizzare i benefici di business riducendo al minimo i rischi della trasformazione. Vuole anche gestire la spesa cloud e il portafoglio applicativo. Quale prospettiva dell'AWS CAF corrisponde MEGLIO a questi obiettivi?","options":["Security","Business","People","Governance"],"explanation":"La prospettiva Governance aiuta a orchestrare le iniziative cloud massimizzando i benefici e riducendo al minimo i rischi, con capacità come la gestione dei programmi, la gestione del rischio, la gestione finanziaria del cloud e la gestione del portafoglio applicativo. La prospettiva Business si concentra sull'assicurare che gli investimenti cloud supportino i risultati e la strategia di business, non sul governo del programma in sé.","optionExplanations":["La prospettiva Security si concentra su riservatezza, integrità e disponibilità di dati e workload, non sulla gestione del programma e della spesa.","La prospettiva Business assicura che gli investimenti cloud accelerino i risultati di business. La gestione di rischio, spesa e programma fa parte di Governance.","La prospettiva People si concentra su cultura, competenze e cambiamento organizzativo, non sulla spesa cloud o sulla gestione del rischio.","Corretto — La prospettiva Governance copre la gestione dei programmi, la gestione del rischio, la gestione finanziaria del cloud e la gestione del portafoglio applicativo."]},
  "410": {"h":"7afb7738","question":"Gli architetti e gli ingegneri di un'azienda devono progettare un ambiente cloud ibrido scalabile, modernizzare i workload esistenti e configurare pipeline automatizzate per il deployment di applicazioni cloud-native. Quale prospettiva dell'AWS CAF si concentra su queste attività?","options":["Platform","Operations","Security","Business"],"explanation":"La prospettiva Platform aiuta a costruire una piattaforma cloud ibrida scalabile di livello enterprise, a modernizzare i workload esistenti e a implementare soluzioni cloud-native. La prospettiva Operations si concentra sull'esecuzione e sul supporto di quei servizi una volta in funzione, ad esempio con monitoraggio e gestione degli incidenti.","optionExplanations":["Corretto — La prospettiva Platform copre l'architettura e l'ingegneria della piattaforma, la modernizzazione dei workload e la realizzazione di soluzioni cloud-native.","La prospettiva Operations si concentra sull'erogazione dei servizi cloud ai livelli concordati, inclusi osservabilità e gestione degli incidenti, piuttosto che sulla progettazione della piattaforma.","La prospettiva Security si concentra sulla protezione di dati e workload, non sulla progettazione della piattaforma cloud nel suo complesso.","La prospettiva Business si concentra sulla strategia e sui risultati di business, non sulla progettazione tecnica della piattaforma."]},
  "411": {"h":"3bce6769","question":"Dopo la migrazione su AWS, il team IT di un'azienda vuole definire i livelli di servizio, monitorare lo stato di salute dei workload e impostare processi di gestione degli incidenti e dei problemi. Quale prospettiva dell'AWS CAF si concentra su queste capacità?","options":["Platform","People","Business","Operations"],"explanation":"La prospettiva Operations aiuta a garantire che i servizi cloud siano erogati a un livello che soddisfa le esigenze del business, con capacità come l'osservabilità, la gestione degli incidenti e dei problemi e la gestione dei livelli di servizio. La prospettiva Platform riguarda la costruzione dell'ambiente cloud piuttosto che la sua gestione quotidiana.","optionExplanations":["La prospettiva Platform si concentra sulla costruzione della piattaforma cloud e sulla modernizzazione dei workload, non sulle operazioni quotidiane dei servizi.","La prospettiva People si concentra su cultura, competenze e cambiamento organizzativo, non su monitoraggio o gestione degli incidenti.","La prospettiva Business si concentra sulla strategia e sui risultati di business, non sui processi operativi.","Corretto — La prospettiva Operations copre l'osservabilità, la gestione degli incidenti e dei problemi e il rispetto dei livelli di servizio concordati."]},
  "412": {"h":"58298d64","question":"La direzione di un'azienda chiede quali risultati di business l'AWS Cloud Adoption Framework (AWS CAF) può aiutare a ottenere. Quali dei seguenti sono benefici descritti dall'AWS CAF? (Seleziona DUE)","options":["Eliminazione di tutte le responsabilità di sicurezza del cliente","Riduzione del rischio di business","Downtime zero garantito per i workload migrati","Aumento dell'efficienza operativa","Nessuna ulteriore necessità di formare il personale IT"],"explanation":"L'AWS CAF descrive quattro risultati di business della trasformazione digitale: riduzione del rischio di business, miglioramento delle prestazioni ambientali, sociali e di governance (ESG), aumento dei ricavi e aumento dell'efficienza operativa. Il framework non elimina le responsabilità di sicurezza del cliente, non garantisce downtime zero e non elimina la necessità di formazione; anzi, la prospettiva People sottolinea lo sviluppo delle competenze.","optionExplanations":["Secondo lo Shared Responsibility Model, i clienti mantengono sempre responsabilità di sicurezza nel cloud. L'AWS CAF non cambia questo aspetto.","Corretto — La riduzione del rischio di business è uno dei risultati di business identificati dall'AWS CAF.","Nessun framework può garantire downtime zero. La disponibilità dipende da come i workload sono progettati e gestiti.","Corretto — L'aumento dell'efficienza operativa è uno dei risultati di business identificati dall'AWS CAF.","La prospettiva People dell'AWS CAF insiste sullo sviluppo delle competenze cloud, quindi la formazione resta importante."]},
  "413": {"h":"359ce90e","question":"Un'azienda vuole ridurre l'impatto ambientale dei suoi workload su AWS. Quale azione è MEGLIO allineata al pilastro Sustainability dell'AWS Well-Architected Framework?","options":["Effettuare sempre il provisioning delle risorse per il carico di picco","Distribuire copie di ogni workload in tutte le Region","Dimensionare correttamente le risorse per massimizzarne l'utilizzo","Tenere gli ambienti di sviluppo attivi 24 ore su 24"],"explanation":"Un principio di progettazione chiave della Sustainability è massimizzare l'utilizzo: dimensionare correttamente le risorse ed eliminare la capacità inattiva significa che servono meno hardware ed energia per lo stesso lavoro. Effettuare permanentemente il provisioning per il carico di picco o tenere in esecuzione ambienti inattivi spreca risorse e aumenta l'impatto ambientale.","optionExplanations":["Effettuare sempre il provisioning per il carico di picco lascia le risorse inattive per la maggior parte del tempo, sprecando energia.","Distribuire ogni workload in tutte le Region senza un'esigenza di business moltiplica l'uso delle risorse e il relativo impatto ambientale.","Corretto — Dimensionare correttamente le risorse e massimizzarne l'utilizzo riduce le risorse totali necessarie, ed è un principio di progettazione fondamentale della Sustainability.","Gli ambienti di sviluppo in esecuzione quando nessuno li usa consumano risorse inutilmente. Arrestarli quando sono inattivi è più sostenibile."]},
  "414": {"h":"ba834fbc","question":"Un'azienda effettua il deployment di grandi release applicative solo poche volte all'anno. Queste release sono rischiose e difficili da annullare (rollback) quando qualcosa va storto. Quale pilastro dell'AWS Well-Architected Framework raccomanda invece di apportare modifiche frequenti, piccole e reversibili?","options":["Cost Optimization","Performance Efficiency","Operational Excellence","Sustainability"],"explanation":"Apportare modifiche frequenti, piccole e reversibili è un principio di progettazione del pilastro Operational Excellence, che si concentra sull'esecuzione e sul miglioramento dei workload e dei processi che li supportano. Le modifiche più piccole sono più facili da testare e da annullare. Gli altri pilastri si concentrano su costi, uso efficiente delle risorse e impatto ambientale.","optionExplanations":["Cost Optimization si concentra sull'evitare costi non necessari, non su come vengono distribuite le modifiche.","Performance Efficiency si concentra sull'uso efficiente delle risorse di calcolo al variare della domanda, non sulle pratiche di rilascio.","Corretto — Apportare modifiche frequenti, piccole e reversibili è un principio di progettazione del pilastro Operational Excellence.","Sustainability si concentra sulla riduzione dell'impatto ambientale, non sulle pratiche di deployment."]},
  "415": {"h":"6512e515","question":"Un'azienda del settore retail non ha esperti di machine learning. Invece di costruire i propri modelli, usa un servizio di AI gestito di AWS per aggiungere raccomandazioni di prodotto al suo sito web. Quale principio di progettazione Well-Architected di AWS rappresenta questo approccio?","options":["Smettere di indovinare la capacità","Implementare una solida base di gestione delle identità","Analizzare e attribuire la spesa","Democratizzare le tecnologie avanzate"],"explanation":"Democratizzare le tecnologie avanzate è un principio di progettazione di Performance Efficiency: tecnologie complesse come il machine learning vengono utilizzate come servizi gestiti, così i team non hanno bisogno di competenze interne approfondite. Le altre opzioni sono principi di progettazione validi di altri pilastri, ma non descrivono l'uso di servizi gestiti per accedere a tecnologie avanzate.","optionExplanations":["Smettere di indovinare la capacità riguarda il dimensionamento in base alla domanda reale, non l'uso di servizi di AI gestiti.","Implementare una solida base di gestione delle identità è un principio del pilastro Security relativo alla gestione degli accessi.","Analizzare e attribuire la spesa è un principio di Cost Optimization che serve a capire chi genera i costi.","Corretto — Democratizzare le tecnologie avanzate significa utilizzare tecnologie complesse, come il machine learning, come servizi gestiti, così che i team possano usarle senza competenze specialistiche."]},
  "416": {"h":"b056cd91","question":"Un'azienda nota che la maggior parte delle sue istanze Amazon EC2 funziona con un utilizzo di CPU e memoria molto basso. Quale azione ridurrebbe MEGLIO i costi senza influire sulle prestazioni dell'applicazione?","options":["Ridimensionare le istanze verso tipi più piccoli","Acquistare Dedicated Hosts per le istanze","Passare a istanze più grandi per avere più margine","Aggiungere altre istanze a ogni Auto Scaling group"],"explanation":"Il rightsizing consiste nell'adattare tipi e dimensioni delle istanze ai requisiti effettivi del workload. Quando le istanze sono sottoutilizzate, passare a tipi di istanza più piccoli riduce i costi pur soddisfacendo le esigenze di prestazioni. Dedicated Hosts, istanze più grandi o più istanze aumenterebbero tutti i costi.","optionExplanations":["Corretto — Il rightsizing delle istanze sottoutilizzate verso tipi più piccoli riduce i costi pur soddisfacendo le esigenze di prestazioni del workload.","I Dedicated Hosts sono server fisici dedicati a un singolo cliente, usati principalmente per esigenze di licenze o di conformità. Non risolvono il sottoutilizzo e di solito costano di più.","Istanze più grandi peggiorerebbero il sottoutilizzo e aumenterebbero i costi.","Aggiungere altre istanze aumenta i costi quando quelle esistenti sono già sottoutilizzate."]},
  "417": {"h":"cdca8f9e","question":"Un'azienda ha già pagato licenze software i cui termini ne consentono l'uso nel cloud. Vuole usare queste licenze esistenti su AWS per non pagare due volte le stesse licenze. Quale approccio di licensing dovrebbe usare l'azienda?","options":["Istanze con licenza inclusa","Bring your own license (BYOL)","Spot Instances con software incluso","Prodotti AWS Marketplace a consumo (pay-as-you-go)"],"explanation":"Con il bring your own license (BYOL), un'azienda usa su AWS licenze che già possiede, purché i termini della licenza lo consentano. Con le opzioni a licenza inclusa, il costo della licenza fa parte del prezzo AWS, quindi l'azienda pagherebbe di nuovo licenze che già possiede.","optionExplanations":["Le istanze con licenza inclusa comprendono il costo della licenza nel prezzo AWS, quindi l'azienda pagherebbe di nuovo licenze che già possiede.","Corretto — Il BYOL consente all'azienda di riutilizzare su AWS le sue licenze idonee esistenti invece di pagarne di nuove.","Le Spot Instances sono un'opzione di prezzo per la capacità EC2 inutilizzata. Non riutilizzano licenze software esistenti.","I prodotti AWS Marketplace a consumo addebitano il software tramite AWS, quindi l'azienda pagherebbe di nuovo le licenze."]},
  "418": {"h":"93292124","question":"Un'azienda sta preparando un confronto del costo totale di proprietà (TCO) tra il suo data center on-premises e AWS. Oltre all'hardware dei server, quali costi on-premises dovrebbero essere inclusi per un confronto accurato? (Seleziona DUE)","options":["Canoni dei piani AWS Support","Costi Amazon EC2 On-Demand","Alimentazione e raffreddamento del data center","Trasferimento dati in uscita da AWS verso internet","Tempo del personale IT dedicato alla manutenzione dell'hardware"],"explanation":"Un confronto TCO corretto include tutti i costi on-premises, non solo l'acquisto dei server: strutture, alimentazione e raffreddamento, rete e il lavoro necessario per la manutenzione dell'hardware. Questi costi indiretti vengono spesso trascurati, facendo sembrare l'on-premises più economico di quanto sia in realtà. AWS Support, i costi EC2 e il trasferimento dati in uscita appartengono al lato AWS del confronto.","optionExplanations":["I canoni dei piani AWS Support sono un costo AWS, non un costo on-premises.","I costi EC2 On-Demand sono un costo AWS, non un costo on-premises.","Corretto — Alimentazione e raffreddamento sono costi indiretti on-premises significativi che devono essere inclusi in un confronto TCO.","Il trasferimento dati in uscita da AWS è un costo AWS, non un costo on-premises.","Corretto — Il tempo del personale dedicato alla manutenzione dell'hardware è un costo di manodopera on-premises che dovrebbe essere incluso nel TCO."]},
  "419": {"h":"a0150f11","question":"Un'applicazione web memorizza i dati di sessione degli utenti nella memoria di ciascun web server. Quando l'Auto Scaling rimuove un'istanza, gli utenti su quell'istanza perdono la sessione. Quale modifica supporta MEGLIO l'elasticità?","options":["Disattivare lo scale-in per l'Auto Scaling group","Conservare i dati di sessione in uno store esterno condiviso","Spostare l'applicazione su un'unica istanza più grande","Salvare i dati di sessione sul disco locale di ogni istanza"],"explanation":"Memorizzare lo stato della sessione al di fuori dei web server, ad esempio in Amazon DynamoDB o Amazon ElastiCache, rende il livello web stateless. Qualsiasi istanza può così servire qualsiasi utente e le istanze possono essere aggiunte o rimosse liberamente. Disattivare lo scale-in evita il sintomo ma elimina l'elasticità.","optionExplanations":["Disattivare lo scale-in evita la perdita delle sessioni ma impedisce all'applicazione di ridurre la capacità, eliminando l'elasticità e aumentando i costi.","Corretto — Conservare i dati di sessione in uno store esterno condiviso rende i web server stateless, così le istanze possono scalare in entrambe le direzioni senza perdere le sessioni degli utenti.","Un'unica istanza più grande elimina lo scaling orizzontale e crea un single point of failure.","I dati di sessione su un disco locale vanno comunque persi quando l'istanza viene terminata, quindi i server restano stateful."]},
  "420": {"h":"72dccaaf","question":"Un servizio ordini chiama direttamente un servizio di inventario e attende una risposta. Quando il servizio di inventario è lento, i nuovi ordini falliscono. Quale servizio AWS potrebbe aggiungere l'azienda tra i due servizi per disaccoppiarli?","options":["Amazon CloudFront","Amazon Route 53","Amazon SQS","AWS Direct Connect"],"explanation":"Amazon SQS è una coda di messaggi gestita. Il servizio ordini può inserire messaggi nella coda e il servizio di inventario li elabora al proprio ritmo, così un rallentamento in un componente non causa errori nell'altro. Questo applica il principio di progettazione dell'accoppiamento debole (loose coupling). CloudFront, Route 53 e Direct Connect non fanno da buffer per i messaggi tra componenti applicativi.","optionExplanations":["Amazon CloudFront distribuisce contenuti agli utenti con bassa latenza. Non fa da buffer per le richieste tra servizi applicativi.","Amazon Route 53 è un servizio DNS. Instrada il traffico ma non disaccoppia servizi che si chiamano direttamente.","Corretto — Una coda SQS fa da buffer per le richieste tra i servizi, così possono lavorare in modo indipendente: questo è l'accoppiamento debole.","AWS Direct Connect è una connessione di rete dedicata verso AWS. Non disaccoppia i componenti applicativi."]},
  "421": {"h":"96702100","question":"Un'azienda sta valutando il suo workload rispetto al pilastro Reliability dell'AWS Well-Architected Framework. Quali azioni seguono i principi di progettazione di questo pilastro? (Seleziona DUE)","options":["Ripristinare automaticamente il servizio in caso di guasto","Usare un'unica grande istanza per ridurre i componenti","Apportare modifiche manuali in produzione per risolvere i problemi","Scalare orizzontalmente per aumentare la disponibilità","Mantenere sempre la capacità dimensionata per il picco"],"explanation":"I principi di progettazione della Reliability includono il ripristino automatico in caso di guasto, il test delle procedure di ripristino, lo scaling orizzontale per aumentare la disponibilità complessiva del workload, smettere di indovinare la capacità e gestire le modifiche tramite automazione. Sostituire una grande risorsa con più risorse più piccole riduce l'impatto di un singolo guasto. Le modifiche manuali e il provisioning permanente per il picco vanno contro questi principi.","optionExplanations":["Corretto — Il ripristino automatico in caso di guasto, ad esempio tramite monitoraggio e risposte automatizzate, è un principio di progettazione della Reliability.","Un'unica grande istanza è un single point of failure. La Reliability raccomanda invece più risorse più piccole.","La Reliability raccomanda di gestire le modifiche tramite automazione, non con modifiche manuali in produzione.","Corretto — Lo scaling orizzontale con più risorse più piccole riduce l'impatto di un singolo guasto e aumenta la disponibilità.","La Reliability raccomanda di smettere di indovinare la capacità e di scalare in base alla domanda, non di mantenere permanentemente la capacità di picco."]},
  "422": {"h":"17f6d92d","question":"Un'azienda vuole creare ambienti applicativi identici in diverse Region AWS. Vuole che ogni ambiente sia costruito a partire da template in modo ripetibile, senza configurazione manuale nella console. Quale servizio AWS supporta MEGLIO questa automazione?","options":["AWS Trusted Advisor","AWS Config","AWS CloudFormation","AWS Health Dashboard"],"explanation":"AWS CloudFormation è un servizio di infrastructure as code: le risorse sono descritte in template e distribuite ogni volta allo stesso modo, in qualsiasi Region o account. Questo applica il principio di progettazione dell'automazione. AWS Config registra e valuta le configurazioni delle risorse ma non crea ambienti.","optionExplanations":["AWS Trusted Advisor fornisce raccomandazioni sulle best practice. Non crea infrastruttura.","AWS Config registra e valuta le configurazioni delle risorse. Non effettua il provisioning di ambienti a partire da template.","Corretto — AWS CloudFormation effettua il provisioning delle risorse a partire da template (infrastructure as code), così è possibile creare ripetutamente ambienti identici in qualsiasi Region.","AWS Health Dashboard mostra gli eventi che possono influire sui servizi e sugli account AWS. Non effettua il provisioning di risorse."]},
  "423": {"h":"2098228d","question":"Un'azienda prevede di spostare il suo database Oracle on-premises su Amazon Aurora PostgreSQL per smettere di pagare licenze di database commerciali. Prima di spostare i dati, il suo team deve convertire lo schema del database e le stored procedure in un formato supportato da PostgreSQL. Quale strumento AWS è progettato per questa conversione?","options":["AWS Application Migration Service (AWS MGN)","AWS Glue Data Catalog","AWS Schema Conversion Tool (AWS SCT)","AWS DataSync"],"explanation":"AWS Schema Conversion Tool (AWS SCT) converte lo schema di un database di origine, comprese viste, stored procedure e funzioni, in un formato compatibile con un motore di destinazione diverso. Si usa per migrazioni eterogenee come da Oracle ad Amazon Aurora PostgreSQL; i dati veri e propri vengono poi tipicamente spostati con AWS Database Migration Service (AWS DMS).","optionExplanations":["AWS Application Migration Service esegue il rehosting di server interi su Amazon EC2 senza modifiche. Non converte uno schema di database verso un motore diverso.","L'AWS Glue Data Catalog memorizza i metadati delle sorgenti dati per l'analisi. Non converte schemi o codice Oracle in PostgreSQL.","Corretto — AWS SCT converte lo schema e il codice del database, come le stored procedure, dal motore di origine al motore di destinazione.","AWS DataSync copia file e oggetti tra sistemi di storage. Non converte schemi di database né stored procedure."]},
  "424": {"h":"0ef7da89","question":"Secondo il pilastro Sustainability dell'AWS Well-Architected Framework, come è condivisa la responsabilità per la sostenibilità tra AWS e il cliente?","options":["AWS è l'unico responsabile di tutta la sostenibilità","Il cliente è l'unico responsabile di tutta la sostenibilità","La sostenibilità non fa parte del modello condiviso","AWS: sostenibilità del cloud; cliente: nel cloud"],"explanation":"Il pilastro Sustainability usa un modello di responsabilità condivisa: AWS è responsabile della sostenibilità del cloud (data center, hardware ed energia efficienti) e i clienti sono responsabili della sostenibilità nel cloud (quanto efficientemente progettano e usano i loro workload). I clienti hanno quindi comunque un ruolo importante, ad esempio dimensionando correttamente le risorse ed eliminando quelle inattive.","optionExplanations":["AWS ottimizza la propria infrastruttura, ma anche i clienti influiscono sulla sostenibilità attraverso il modo in cui progettano e usano i workload.","I clienti non controllano i data center di AWS né l'approvvigionamento energetico, quindi non possono esserne gli unici responsabili.","Il pilastro Sustainability descrive esplicitamente un modello di responsabilità condivisa per la sostenibilità.","Corretto — AWS è responsabile della sostenibilità del cloud, mentre i clienti sono responsabili della sostenibilità nel cloud, attraverso la progettazione dei workload e l'uso delle risorse."]},
  "425": {"h":"c803fa6a","question":"Secondo l'AWS Shared Responsibility Model, alcuni controlli sono condivisi, cioè AWS e il cliente ne gestiscono ciascuno una parte nel proprio livello. Quale dei seguenti è un esempio di controllo condiviso?","options":["Gestione delle patch","Sicurezza fisica dei data center","Classificazione dei dati del cliente","Distruzione dei dispositivi di storage guasti"],"explanation":"La gestione delle patch è un controllo condiviso: AWS applica le patch e corregge le vulnerabilità all'interno dell'infrastruttura, mentre i clienti applicano le patch ai loro sistemi operativi guest e alle loro applicazioni. La sicurezza fisica e la distruzione dei supporti sono controlli ereditati gestiti interamente da AWS, mentre la classificazione dei dati è compito esclusivo del cliente.","optionExplanations":["Corretto — AWS applica le patch all'infrastruttura che gestisce e i clienti le applicano ai propri sistemi operativi guest e alle proprie applicazioni.","La sicurezza fisica dei data center è un controllo ereditato gestito interamente da AWS; i clienti non vi hanno alcun ruolo.","Decidere come classificare i dati è responsabilità esclusiva del cliente, non un controllo condiviso.","La distruzione sicura dei supporti di storage guasti avviene all'interno delle strutture AWS ed è responsabilità esclusiva di AWS."]},
  "426": {"h":"552d228a","question":"Un'azienda segue la best practice di usare identità IAM invece dell'utente root dell'account AWS per il lavoro quotidiano. Quali attività possono essere eseguite SOLO accedendo come utente root? (Seleziona DUE)","options":["Creare un nuovo utente IAM con permessi di amministratore","Abilitare MFA Delete su un bucket Amazon S3","Chiudere l'account AWS","Abilitare un trail AWS CloudTrail per tutte le Region","Avviare istanze Amazon EC2 in una nuova Region"],"explanation":"Un piccolo insieme di attività richiede le credenziali dell'utente root, tra cui la chiusura dell'account AWS e l'abilitazione di MFA Delete su un bucket Amazon S3. La creazione di utenti IAM, la configurazione di CloudTrail e l'avvio di istanze EC2 possono essere eseguiti da identità IAM con i permessi adeguati; per questo l'utente root dovrebbe essere messo al sicuro e non usato quotidianamente.","optionExplanations":["Un'identità IAM con permessi IAM può creare altri utenti IAM, quindi non serve l'utente root.","Corretto — l'abilitazione di MFA Delete nella configurazione del versioning di un bucket S3 può essere eseguita solo con le credenziali dell'utente root.","Corretto — la chiusura dell'account AWS è un'attività riservata all'utente root.","Qualsiasi identità IAM con i permessi CloudTrail adeguati può creare e configurare trail.","L'avvio di istanze EC2 in qualsiasi Region richiede solo i permessi IAM adeguati, non le credenziali root."]},
  "427": {"h":"db8ae7e3","question":"Un'azienda sta assumendo 20 nuovi sviluppatori che necessitano tutti dello stesso insieme di permessi AWS. Qual è il modo PIÙ efficiente per gestire i loro permessi in IAM?","options":["Associare separatamente la stessa inline policy all'utente IAM di ogni sviluppatore","Creare un gruppo IAM con la policy richiesta e aggiungervi gli utenti","Condividere le credenziali di un unico utente IAM tra tutti gli sviluppatori","Dare a ogni sviluppatore le credenziali dell'utente root con MFA"],"explanation":"I gruppi IAM consentono di associare una policy una sola volta e di applicarla a ogni membro, così aggiungere o rimuovere uno sviluppatore è un'unica operazione e i permessi restano coerenti. Associare inline policy a ogni utente funziona, ma è ripetitivo e soggetto a errori, mentre condividere le credenziali o l'utente root compromette la tracciabilità e il principio del privilegio minimo.","optionExplanations":["Tecnicamente funzionerebbe, ma mantenere 20 inline policy separate è inefficiente e rende probabile che i permessi divergano nel tempo.","Corretto — un gruppo centralizza i permessi; i nuovi sviluppatori entrano semplicemente nel gruppo ed ereditano le sue policy.","La condivisione delle credenziali elimina la responsabilità individuale, perché CloudTrail non può distinguere quale persona ha effettuato ciascuna chiamata.","L'utente root ha accesso illimitato e non dovrebbe mai essere condiviso né usato per il lavoro di sviluppo quotidiano, nemmeno con MFA."]},
  "428": {"h":"29a0f990","question":"Un'applicazione deve memorizzare valori di configurazione come gli hostname dei database e i feature flag, più alcuni valori cifrati, in una struttura gerarchica. La rotazione automatica non è richiesta e l'azienda vuole evitare costi aggiuntivi. Quale servizio AWS soddisfa MEGLIO queste esigenze?","options":["AWS Secrets Manager con rotazione automatica","AWS CloudHSM","AWS Systems Manager Parameter Store","Amazon S3 Glacier"],"explanation":"Systems Manager Parameter Store offre uno storage gerarchico per i dati di configurazione e può memorizzare valori cifrati con AWS KMS come parametri SecureString, con i parametri standard senza costi aggiuntivi. Secrets Manager è la scelta migliore quando è richiesta la rotazione automatica integrata dei secret, ma viene addebitato per ogni secret.","optionExplanations":["Qui la rotazione di Secrets Manager non è necessaria e Secrets Manager viene addebitato per ogni secret, quindi non è la soluzione più economica.","CloudHSM fornisce moduli di sicurezza hardware dedicati per la gestione delle chiavi, non uno store per i valori di configurazione delle applicazioni.","Corretto — Parameter Store offre storage gerarchico della configurazione, cifratura KMS opzionale e nessun costo aggiuntivo per i parametri standard.","S3 Glacier è progettato per l'archiviazione a basso costo, non per recuperare valori di configurazione durante l'esecuzione dell'applicazione."]},
  "429": {"h":"56c9734b","question":"Un'azienda cifra i dati con AWS Key Management Service (AWS KMS). Il suo team di sicurezza vuole scrivere la propria key policy, decidere chi può usare ciascuna chiave e poter disabilitare una chiave se necessario. Quale tipo di chiave KMS dovrebbe usare l'azienda?","options":["AWS managed keys","AWS owned keys","Chiavi gestite da Amazon S3 (SSE-S3)","Customer managed keys"],"explanation":"Le customer managed keys sono create e controllate dal cliente, che può definire le key policy, abilitare o disabilitare la chiave, configurare la rotazione e pianificarne l'eliminazione. Le AWS managed keys sono create nell'account per conto di un servizio AWS, ma le loro key policy non possono essere modificate dal cliente.","optionExplanations":["Le AWS managed keys sono visibili nell'account, ma il cliente non può modificarne le key policy né disabilitarle.","Le AWS owned keys sono di proprietà di AWS e gestite da AWS su molti account; i clienti non possono visualizzarle né controllarle.","SSE-S3 usa chiavi gestite interamente da Amazon S3, quindi l'azienda non può scrivere key policy né disabilitare le chiavi.","Corretto — le customer managed keys offrono il pieno controllo su key policy, abilitazione o disabilitazione, rotazione ed eliminazione."]},
  "430": {"h":"10d45503","question":"Un'azienda deve garantire che i dati memorizzati sui volumi Amazon EBS collegati alle sue istanze Amazon EC2 siano cifrati a riposo. Che cosa dovrebbe fare l'azienda?","options":["Abilitare la cifratura di Amazon EBS, che usa chiavi AWS KMS","Richiedere un certificato pubblico ad AWS Certificate Manager","Attivare AWS Shield Advanced per le istanze","Abilitare Amazon Macie sui volumi EBS"],"explanation":"La cifratura di Amazon EBS cifra i dati a riposo sul volume, così come i suoi snapshot, usando chiavi AWS KMS. I certificati ACM proteggono i dati in transito con TLS, Shield protegge dagli attacchi DDoS e Macie individua i dati sensibili in Amazon S3, quindi nessuno di questi cifra i volumi EBS.","optionExplanations":["Corretto — la cifratura EBS protegge i dati a riposo sul volume e sui suoi snapshot usando chiavi AWS KMS.","I certificati ACM abilitano TLS per i dati in transito; non cifrano i dati memorizzati sui volumi EBS.","Shield Advanced protegge dagli attacchi DDoS e non ha nulla a che fare con la cifratura dei dati memorizzati.","Macie individua e classifica i dati sensibili in Amazon S3; non cifra i volumi EBS."]},
  "431": {"h":"5e9ec6ea","question":"Amazon GuardDuty ha segnalato chiamate API sospette provenienti da un utente IAM. Il team di sicurezza vuole ora indagare sulla causa principale analizzando e visualizzando come l'utente, gli indirizzi IP e le risorse hanno interagito nel tempo. Quale servizio AWS dovrebbe usare il team?","options":["AWS Config","Amazon Macie","Amazon Detective","AWS Artifact"],"explanation":"Amazon Detective raccoglie automaticamente i dati di log (come CloudTrail, VPC Flow Logs e i finding di GuardDuty) e costruisce un grafo di collegamenti, così i team di sicurezza possono indagare sulla causa principale dei finding e vedere come le entità hanno interagito nel tempo. GuardDuty rileva le minacce; Detective aiuta a indagarle.","optionExplanations":["AWS Config registra le modifiche di configurazione delle risorse e valuta regole di conformità — non costruisce grafi di comportamento per indagare sui finding di sicurezza.","Amazon Macie individua e protegge i dati sensibili in Amazon S3 — non è progettato per indagare su attività API sospette.","Corretto — Amazon Detective analizza e visualizza i dati di sicurezza per aiutare a indagare sulla causa principale di finding come quelli di GuardDuty.","AWS Artifact fornisce accesso on demand ai report di conformità e agli accordi di AWS — non ha funzionalità di indagine."]},
  "432": {"h":"3748cb76","question":"Un'azienda si sta preparando a un imminente audit esterno e vuole raccogliere in modo continuo e automatico le evidenze su come vengono usate le sue risorse AWS, mappate su framework di conformità predefiniti. Quale servizio AWS dovrebbe usare?","options":["AWS Artifact","Amazon Inspector","AWS Audit Manager","AWS Trusted Advisor"],"explanation":"AWS Audit Manager raccoglie in modo continuo le evidenze dall'uso di AWS da parte del cliente e le organizza secondo framework predefiniti o personalizzati per semplificare la preparazione degli audit. AWS Artifact, invece, fornisce i report di conformità e gli accordi di AWS stessa, non evidenze sulle risorse del cliente.","optionExplanations":["Artifact fornisce i report di conformità e gli accordi di AWS, non evidenze su come il cliente usa le proprie risorse.","Inspector analizza i workload alla ricerca di vulnerabilità software; non raccoglie evidenze di audit in base a framework.","Corretto — Audit Manager automatizza la raccolta di evidenze dall'ambiente AWS del cliente e le mappa sui framework di conformità.","Trusted Advisor fornisce raccomandazioni sulle best practice, ma non raccoglie né organizza evidenze di audit."]},
  "433": {"h":"b5d92b20","question":"Un account membro di AWS Organizations ha un utente IAM a cui è associata la policy AdministratorAccess. Una service control policy (SCP) applicata all'account nega tutte le azioni al di fuori della Region eu-west-1. Che cosa succede quando l'utente prova ad avviare un'istanza EC2 in us-east-1?","options":["La richiesta ha successo perché la policy IAM concede l'accesso completo","La richiesta ha successo solo se l'utente ha l'MFA abilitata","La richiesta viene negata perché la SCP pone limiti all'account","La richiesta viene reindirizzata automaticamente alla Region eu-west-1"],"explanation":"Le SCP stabiliscono i permessi massimi disponibili in un account membro, quindi un'azione, per avere successo, deve essere consentita sia dalla SCP sia dalla policy IAM. Poiché la SCP nega le azioni al di fuori di eu-west-1, nemmeno un amministratore di quell'account può avviare istanze in us-east-1.","optionExplanations":["Le policy IAM non possono concedere più di quanto consenta la SCP; il deny della SCP prevale sulla policy di amministratore.","L'MFA non scavalca una SCP; la restrizione sulla Region si applica indipendentemente da come l'utente si è autenticato.","Corretto — i permessi effettivi sono limitati dalla SCP, quindi l'azione al di fuori di eu-west-1 viene negata.","AWS non reindirizza le richieste API verso un'altra Region; la richiesta viene semplicemente negata."]},
  "434": {"h":"b50f7ffe","question":"Un'azienda esegue un'applicazione web dietro Amazon CloudFront e vuole bloccare tutte le richieste provenienti da specifici paesi in cui non opera. Quale servizio AWS può farlo?","options":["AWS WAF","Amazon GuardDuty","AWS Shield Standard","Amazon Inspector"],"explanation":"AWS WAF supporta regole di corrispondenza geografica che consentono o bloccano le richieste web in base al paese di provenienza, e si integra con CloudFront. Shield Standard offre una protezione DDoS automatica a livello di rete, ma non permette di scrivere regole di consenso o blocco basate sul paese.","optionExplanations":["Corretto — AWS WAF può usare condizioni di corrispondenza geografica per bloccare le richieste provenienti dai paesi selezionati.","GuardDuty rileva le minacce e genera finding, ma non filtra le richieste web in ingresso.","Shield Standard mitiga automaticamente gli attacchi DDoS più comuni, ma non fornisce regole personalizzate di blocco per paese.","Inspector cerca vulnerabilità software e non filtra il traffico web."]},
  "435": {"h":"928d1ab0","question":"Un'azienda vuole proteggere diverse sue risorse con web ACL di AWS WAF. A quali risorse può essere associato AWS WAF? (Seleziona TRE)","options":["Distribuzioni Amazon CloudFront","Application Load Balancer","Volumi Amazon EBS","REST API di Amazon API Gateway","Vault di Amazon S3 Glacier"],"explanation":"AWS WAF ispeziona le richieste HTTP e HTTPS, quindi viene associato a risorse che ricevono traffico web, come le distribuzioni CloudFront, gli Application Load Balancer e le REST API di API Gateway. Le risorse di storage come i volumi EBS e i vault Glacier non ricevono richieste web, quindi WAF non può esservi collegato.","optionExplanations":["Corretto — le web ACL di WAF possono essere associate a CloudFront per filtrare le richieste nelle edge location.","Corretto — gli Application Load Balancer sono un punto comune a cui collegare le web ACL di WAF.","I volumi EBS sono storage a blocchi collegato alle istanze EC2 e non ricevono richieste web, quindi WAF non può proteggerli.","Corretto — WAF può filtrare le richieste inviate alle REST API di API Gateway.","I vault Glacier sono storage di archiviazione e non possono essere associati a una web ACL di WAF."]},
  "436": {"h":"78ddb420","question":"Un team di sicurezza nota traffico malevolo proveniente da uno specifico indirizzo IP e vuole NEGARE esplicitamente a quell'indirizzo di raggiungere qualsiasi istanza in una subnet. Quale funzionalità del VPC dovrebbe usare?","options":["Una regola in ingresso di un security group","Una route verso un internet gateway","Una regola di network ACL","Una policy di VPC endpoint"],"explanation":"Le network ACL operano a livello di subnet e supportano regole sia di allow sia di deny, quindi possono bloccare esplicitamente uno specifico indirizzo IP per tutte le istanze della subnet. I security group supportano solo regole di allow; non è possibile scrivere una regola che neghi un determinato indirizzo.","optionExplanations":["I security group supportano solo regole di allow, quindi non possono negare esplicitamente uno specifico indirizzo IP.","Le route controllano dove viene inviato il traffico; non si usano per bloccare uno specifico indirizzo IP di origine.","Corretto — le network ACL supportano regole di deny esplicite e si applicano a tutte le istanze della subnet.","Le policy di VPC endpoint controllano l'accesso ai servizi AWS tramite un endpoint, non il traffico in ingresso da un indirizzo IP internet."]},
  "437": {"h":"8e4fdc1f","question":"Uno sviluppatore crea un nuovo security group personalizzato e non vi aggiunge alcuna regola. Qual è il comportamento predefinito di questo security group?","options":["Tutto il traffico in ingresso e in uscita è negato","Tutto il traffico in ingresso e in uscita è consentito","HTTP e HTTPS in ingresso sono consentiti; il resto del traffico è negato","Il traffico in ingresso è negato; il traffico in uscita è consentito"],"explanation":"Un security group appena creato non ha regole in ingresso, quindi tutto il traffico in ingresso è negato, e include una regola in uscita predefinita che consente tutto il traffico in uscita. Poiché i security group sono stateful, le risposte alle richieste in uscita consentite vengono automaticamente lasciate rientrare.","optionExplanations":["In un nuovo security group il traffico in uscita è consentito per impostazione predefinita, quindi non tutto è negato.","Il traffico in ingresso non è consentito finché non si aggiungono esplicitamente regole in ingresso.","Nessuna porta in ingresso, comprese HTTP e HTTPS, è aperta per impostazione predefinita.","Corretto — i nuovi security group negano tutto il traffico in ingresso e consentono tutto il traffico in uscita finché non si modificano le regole."]},
  "438": {"h":"13752de8","question":"Un nuovo team di sicurezza cloud vuole restare aggiornato su best practice, annunci e indicazioni di AWS in materia di sicurezza. Quali risorse AWS sono pensate per questo scopo? (Seleziona DUE)","options":["AWS Pricing Calculator","AWS Security Blog","AWS Compute Optimizer","AWS Security Center","AWS Cost Explorer"],"explanation":"L'AWS Security Blog pubblica articoli, annunci e guide pratiche su temi di sicurezza, e l'AWS Security Center (la sezione dedicata alla sicurezza del sito web di AWS) raccoglie risorse, bollettini e informazioni sulle best practice di sicurezza. Le altre opzioni sono strumenti per i costi e l'ottimizzazione delle risorse.","optionExplanations":["Il Pricing Calculator stima i costi e non fornisce indicazioni sulla sicurezza.","Corretto — l'AWS Security Blog pubblica best practice di sicurezza, annunci e guide passo passo.","Compute Optimizer fornisce raccomandazioni di rightsizing per le risorse di calcolo; non è una fonte di informazioni sulla sicurezza.","Corretto — l'AWS Security Center raccoglie risorse, bollettini e indicazioni sulle best practice di sicurezza di AWS.","Cost Explorer analizza spesa e utilizzo, non informazioni sulla sicurezza."]},
  "439": {"h":"92dca508","question":"Un amministratore continua a ricevere errori «Access Denied» e vuole trovare articoli e video redatti da AWS che rispondono alle domande più comuni ricevute da AWS Support. Quale risorsa dovrebbe usare l'amministratore?","options":["AWS Artifact","AWS Knowledge Center","AWS Health Dashboard","Controlli di AWS Trusted Advisor"],"explanation":"L'AWS Knowledge Center, ora ospitato su AWS re:Post, contiene articoli e video che rispondono alle domande e richieste più frequenti ricevute da AWS Support, compresa la risoluzione degli errori di accesso. L'AWS Health Dashboard segnala gli eventi dei servizi che riguardano l'account, invece di rispondere a domande pratiche.","optionExplanations":["Artifact fornisce report di conformità e accordi, non articoli di troubleshooting.","Corretto — il Knowledge Center offre risposte redatte da AWS alle domande e ai problemi più comuni dei clienti.","L'Health Dashboard mostra gli eventi dei servizi e le modifiche pianificate che riguardano le risorse, non articoli pratici.","Trusted Advisor verifica l'account rispetto alle best practice, ma non fornisce una raccolta di articoli di troubleshooting."]},
  "440": {"h":"307d27f2","question":"Una startup usa il piano AWS Basic Support. Quali controlli di AWS Trusted Advisor sono disponibili senza costi aggiuntivi? (Seleziona DUE)","options":["Low utilization Amazon EC2 instances","MFA on root account","Amazon EC2 Reserved Instance lease expiration","Security groups – specific ports unrestricted","Underutilized Amazon EBS volumes"],"explanation":"Tutti i clienti AWS, compresi quelli con Basic Support, hanno accesso ai controlli principali (core checks) di AWS Trusted Advisor, che includono controlli di sicurezza come MFA on root account e i security group con porte senza restrizioni, oltre ai controlli sulle service quota. I controlli di ottimizzazione dei costi, come le istanze EC2 a basso utilizzo, non fanno parte dei controlli principali, quindi non sono disponibili con Basic Support.","optionExplanations":["Low utilization EC2 instances è un controllo di ottimizzazione dei costi, non uno dei controlli principali inclusi con Basic Support.","Corretto — MFA on root account è uno dei controlli di sicurezza principali disponibili per ogni cliente.","Reserved Instance lease expiration è un controllo di ottimizzazione dei costi, non uno dei controlli principali inclusi con Basic Support.","Corretto — la verifica dei security group che consentono accesso senza restrizioni a porte specifiche è un controllo di sicurezza principale.","Underutilized EBS volumes è un controllo di ottimizzazione dei costi, non uno dei controlli principali inclusi con Basic Support."]},
  "441": {"h":"7e8b46ba","question":"Un auditor di sicurezza chiede l'elenco di tutti gli utenti IAM di un account, indicando per ciascuno se ha una password, access key attive e un dispositivo MFA. Quale funzionalità di IAM fornisce queste informazioni in un unico file scaricabile?","options":["IAM credential report","Cronologia degli eventi di AWS CloudTrail","IAM permissions boundary","AWS Config conformance pack"],"explanation":"L'IAM credential report elenca ogni utente IAM dell'account insieme allo stato delle sue credenziali, comprese password, access key e dispositivi MFA. La cronologia degli eventi di CloudTrail mostra l'attività API, non un riepilogo dello stato delle credenziali di ciascun utente.","optionExplanations":["Corretto — il credential report è un file scaricabile che elenca tutti gli utenti e lo stato delle loro password, access key e dispositivi MFA.","La cronologia degli eventi di CloudTrail registra le chiamate API; non riepiloga quali credenziali ha ciascun utente.","Un permissions boundary limita i permessi massimi di un'identità; non riporta lo stato delle credenziali.","I conformance pack raggruppano regole AWS Config per la valutazione della conformità, non un inventario delle credenziali degli utenti IAM."]},
  "442": {"h":"a6d1bbd5","question":"Uno sviluppatore sta creando una funzione AWS Lambda che deve scrivere elementi in una tabella Amazon DynamoDB. Qual è il modo PIÙ sicuro per concedere questo permesso alla funzione?","options":["Memorizzare le access key di un utente IAM nel codice della funzione","Assegnare un execution role IAM con permessi di scrittura su DynamoDB","Rendere la tabella DynamoDB accessibile pubblicamente","Usare le access key dell'utente root come variabili d'ambiente"],"explanation":"Un execution role di Lambda fornisce alla funzione credenziali temporanee ruotate automaticamente, e la policy del ruolo può essere limitata alle sole azioni DynamoDB necessarie. Inserire access key a lungo termine nel codice o nelle variabili d'ambiente comporta il rischio di fughe e rende difficile la rotazione.","optionExplanations":["Le access key a lungo termine scritte nel codice possono trapelare attraverso il controllo di versione e devono essere ruotate manualmente.","Corretto — un execution role fornisce credenziali temporanee, ruotate automaticamente, con i soli permessi di cui la funzione ha bisogno.","Alle tabelle DynamoDB si accede tramite chiamate API autorizzate da IAM; aprire l'accesso in modo ampio violerebbe il principio del privilegio minimo.","Le access key dell'utente root non dovrebbero proprio esistere, e usarle in una funzione le darebbe accesso illimitato."]},
  "443": {"h":"66a3d832","question":"La policy di sicurezza di un'azienda richiede che tutte le password degli utenti IAM abbiano una lunghezza minima e includano numeri e simboli. Come può l'azienda imporre questo requisito?","options":["Creare una regola AWS Config che reimposta le password deboli","Abilitare AWS Shield Advanced sull'account","Attivare Amazon GuardDuty per l'account","Impostare una password policy dell'account IAM"],"explanation":"IAM consente agli amministratori di definire una password policy dell'account che impone requisiti come la lunghezza minima, i tipi di carattere obbligatori e la scadenza delle password per gli utenti IAM. AWS Config può valutare se esiste una policy, ma il requisito vero e proprio viene imposto tramite la password policy di IAM.","optionExplanations":["Le regole Config possono valutare se una password policy soddisfa i requisiti, ma Config non reimposta né impone direttamente le password degli utenti.","Shield Advanced protegge dagli attacchi DDoS e non ha alcun ruolo nei requisiti delle password.","GuardDuty rileva le minacce a partire dai log di attività; non imposta requisiti per le password.","Corretto — la password policy dell'account IAM impone regole di lunghezza e complessità per le password degli utenti IAM."]},
  "444": {"h":"7a29e596","question":"Durante una revisione di sicurezza, un'azienda scopre che anni fa erano state create access key per l'utente root del suo account AWS. Che cosa raccomanda AWS?","options":["Ruotare le access key root ogni mese","Eliminare le access key dell'utente root","Condividere le chiavi solo con gli amministratori senior","Memorizzare le chiavi nel file di configurazione dell'applicazione"],"explanation":"AWS raccomanda che l'utente root non abbia affatto access key, perché concedono accesso illimitato all'account e non possono essere limitate dalle policy IAM. L'accesso programmatico dovrebbe invece usare ruoli IAM o utenti IAM con permessi secondo il privilegio minimo; ruotare le chiavi lascia comunque in essere una credenziale ad alto rischio non necessaria.","optionExplanations":["Ruotarle riduce in parte il rischio, ma la best practice è non avere affatto access key root.","Corretto — le access key dell'utente root dovrebbero essere eliminate e il lavoro programmatico dovrebbe invece usare ruoli o utenti IAM.","Condividere le credenziali root, anche con un gruppo ristretto, compromette la tracciabilità e lascia esposta una credenziale illimitata.","Memorizzare chiavi potenti a lungo termine in file di configurazione aumenta notevolmente la probabilità di una fuga."]},
  "445": {"h":"9f17dd5d","question":"Un'azienda sta spostando un'applicazione da istanze Amazon EC2 a funzioni AWS Lambda. Secondo lo Shared Responsibility Model, quali responsabilità passano dall'azienda ad AWS dopo la migrazione? (Seleziona DUE)","options":["Applicare le patch al sistema operativo che esegue il codice","Proteggere il codice applicativo delle funzioni","Effettuare il provisioning e lo scaling dei server sottostanti","Definire i permessi IAM per le funzioni","Classificare e proteggere i dati elaborati dalle funzioni"],"explanation":"Con Lambda, AWS gestisce i server, il sistema operativo e la capacità, quindi l'applicazione delle patch al sistema operativo e il provisioning e lo scaling dei server passano ad AWS. Il cliente resta responsabile del codice delle sue funzioni, dei permessi IAM concessi alle funzioni e della protezione dei suoi dati.","optionExplanations":["Corretto — Lambda funziona su un'infrastruttura in cui è AWS a gestire il sistema operativo e ad applicarne le patch.","Il codice applicativo è sempre responsabilità del cliente, sia che giri su EC2 sia su Lambda.","Corretto — AWS effettua il provisioning e lo scaling della capacità di calcolo che esegue le funzioni Lambda.","I clienti continuano a definire gli execution role IAM e le resource policy delle loro funzioni.","La classificazione e la protezione dei dati restano sempre responsabilità del cliente."]},
  "446": {"h":"48d31da7","question":"Un'azienda memorizza file di marketing in Amazon S3. Secondo l'AWS Shared Responsibility Model, chi è responsabile di garantire che il bucket non venga reso accidentalmente leggibile pubblicamente?","options":["AWS, perché Amazon S3 è un servizio di storage completamente gestito","Il team di AWS Support assegnato all'account","Il cliente, che controlla le impostazioni di accesso del bucket","AWS e il cliente in egual misura, come controllo condiviso"],"explanation":"Anche per un servizio gestito come S3, è il cliente a controllare chi può accedere ai suoi dati tramite bucket policy, ACL e impostazioni di Block Public Access. AWS protegge l'infrastruttura di storage, ma la configurazione degli accessi è sicurezza nel cloud e spetta al cliente.","optionExplanations":["AWS gestisce l'infrastruttura di S3, ma non decide chi debba poter leggere i dati del cliente.","AWS Support può dare consigli, ma non è responsabile della configurazione degli accessi ai bucket dei clienti.","Corretto — il controllo degli accessi tramite bucket policy e impostazioni di accesso pubblico è responsabilità del cliente.","La configurazione degli accessi ai bucket non è un controllo condiviso; spetta al cliente, mentre AWS protegge il servizio sottostante."]},
  "447": {"h":"c61549a2","question":"Per un'indagine forense, un team di sicurezza deve dimostrare che i file di log di AWS CloudTrail memorizzati in Amazon S3 non sono stati modificati o eliminati dopo che CloudTrail li ha consegnati. Quale funzionalità dovrebbe usare il team?","options":["Amazon S3 Transfer Acceleration","Convalida dell'integrità dei file di log di CloudTrail","Monitoraggio dettagliato di Amazon CloudWatch","Cronologia delle configurazioni di AWS Config"],"explanation":"La convalida dell'integrità dei file di log di CloudTrail crea file digest con hash e firma digitale che consentono di verificare se i file di log sono stati modificati, eliminati o lasciati invariati dopo la consegna. La cronologia delle configurazioni di AWS Config traccia le impostazioni delle risorse nel tempo, ma non può dimostrare che i file di log siano integri.","optionExplanations":["Transfer Acceleration velocizza gli upload su S3; non verifica l'integrità dei file di log memorizzati.","Corretto — la convalida dell'integrità usa file digest firmati per rilevare se i file di log di CloudTrail sono stati modificati o eliminati.","Il monitoraggio dettagliato aumenta la frequenza delle metriche di CloudWatch e non ha nulla a che fare con l'integrità dei file di log.","La cronologia di Config registra le configurazioni delle risorse nel tempo, ma non può dimostrare che i file di log non siano stati manomessi."]},
  "448": {"h":"2803dd17","question":"Un utente appartiene a un gruppo IAM la cui policy consente tutte le azioni di Amazon S3. Un'altra policy associata direttamente all'utente nega esplicitamente l'azione s3:DeleteObject. Che cosa succede quando l'utente prova a eliminare un oggetto?","options":["La richiesta è consentita perché la policy del gruppo consente tutte le azioni S3","La richiesta è consentita perché le policy di gruppo hanno la priorità","La richiesta è consentita solo se il bucket ha il versioning attivo","La richiesta è negata perché un deny esplicito prevale su qualsiasi allow"],"explanation":"Nella valutazione delle policy IAM, un deny esplicito in qualsiasi policy applicabile prevale sempre su qualsiasi allow, indipendentemente da dove provenga l'allow. Pertanto l'utente può eseguire altre azioni S3 ma non può eliminare oggetti.","optionExplanations":["Un allow, per quanto ampio, non prevale mai su un deny esplicito presente in un'altra policy applicabile.","Le policy di gruppo non hanno priorità sulle policy dell'utente; tutte le policy vengono valutate insieme e i deny espliciti prevalgono.","Il versioning influisce su ciò che accade agli oggetti eliminati, non sul fatto che IAM consenta o meno la richiesta di eliminazione.","Corretto — nella valutazione delle policy IAM un deny esplicito ha sempre la precedenza su qualsiasi allow."]},
  "449": {"h":"175de231","question":"Un'azienda usa Amazon GuardDuty e vuole isolare automaticamente un'istanza EC2 ogni volta che GuardDuty segnala un finding ad alta gravità che la riguarda, senza interventi manuali. Quale approccio dovrebbe usare l'azienda?","options":["Usare una regola EventBridge che invoca una funzione Lambda","Abilitare AWS Shield Advanced per leggere i finding di GuardDuty","Configurare Amazon Macie per arrestare automaticamente l'istanza","Creare un trail CloudTrail che termina l'istanza"],"explanation":"GuardDuty invia i suoi finding ad Amazon EventBridge, dove una regola può intercettare i finding ad alta gravità e attivare una funzione AWS Lambda che esegue la remediation, ad esempio cambiando il security group dell'istanza. CloudTrail registra solo l'attività API e non può eseguire azioni di remediation da solo.","optionExplanations":["Corretto — EventBridge può intercettare i finding di GuardDuty e invocare una funzione Lambda per la remediation automatica.","Shield Advanced protegge dagli attacchi DDoS; non agisce sui finding di GuardDuty.","Macie individua i dati sensibili in Amazon S3 e non gestisce istanze EC2.","CloudTrail registra le chiamate API a fini di audit, ma non può eseguire azioni come isolare o terminare istanze."]},
  "450": {"h":"83e41e93","question":"Un'azienda esegue web server e database server in security group separati. Il database deve accettare connessioni solo dai web server, anche quando l'Auto Scaling aggiunge o rimuove web server. Qual è il modo MIGLIORE per configurarlo?","options":["Consentire la porta del database da 0.0.0.0/0 nel security group del database","Aggiungere l'IP privato di ogni web server al security group del database","Usare il security group del livello web come origine nella regola del database","Collocare entrambi i livelli nella stessa subnet e rimuovere tutte le regole dei security group"],"explanation":"Una regola di security group può usare un altro security group come origine, consentendo automaticamente il traffico da qualsiasi istanza di quel gruppo, indipendentemente da quante istanze l'Auto Scaling aggiunga o rimuova. Elencare i singoli indirizzi IP richiederebbe aggiornamenti continui al cambiare delle istanze.","optionExplanations":["Consentire 0.0.0.0/0 esporrebbe il database a qualsiasi origine, violando il principio del privilegio minimo.","Le regole sui singoli IP smettono di funzionare ogni volta che l'Auto Scaling avvia o termina web server e devono essere aggiornate a mano.","Corretto — fare riferimento al security group del livello web copre automaticamente ogni web server attuale e futuro.","Trovarsi nella stessa subnet non concede l'accesso; senza regole, il security group bloccherebbe del tutto il traffico in ingresso."]},
  "451": {"h":"325e7edc","question":"Un'azienda sanitaria vuole eseguire su AWS workload che elaborano informazioni sanitarie protette (PHI). Quale affermazione sulla conformità HIPAA su AWS è corretta?","options":["AWS certifica ogni applicazione del cliente come conforme a HIPAA","Qualsiasi servizio AWS può elaborare PHI senza ulteriori passaggi","La conformità HIPAA si ottiene abilitando Amazon GuardDuty","Usare servizi idonei HIPAA e configurarli in modo sicuro"],"explanation":"AWS offre servizi idonei HIPAA (HIPAA eligible) e un Business Associate Addendum, ma è il cliente a dover usare tali servizi e configurarli, ad esempio con crittografia e controlli di accesso, per soddisfare i requisiti HIPAA. AWS non certifica le applicazioni dei clienti; la conformità resta una responsabilità condivisa.","optionExplanations":["AWS non certifica le singole applicazioni dei clienti; il cliente resta responsabile della propria conformità.","Per elaborare PHI vanno usati solo servizi idonei HIPAA, che devono inoltre essere configurati in modo appropriato.","GuardDuty è un servizio di rilevamento delle minacce; abilitarlo non rende un workload conforme a HIPAA.","Corretto — i clienti usano servizi idonei HIPAA e sono responsabili di configurarli per soddisfare i requisiti HIPAA."]},
  "452": {"h":"12ffe0e2","question":"La policy di un'azienda stabilisce che i file sensibili devono essere cifrati prima di lasciare i server dell'azienda, in modo che AWS non riceva mai dati non cifrati. Quale approccio soddisfa questo requisito?","options":["Crittografia lato server con chiavi gestite da Amazon S3","Crittografia lato client prima del caricamento su Amazon S3","Crittografia lato server con chiavi AWS KMS","Abilitare solo HTTPS sul bucket S3"],"explanation":"Con la crittografia lato client, l'azienda cifra i dati prima di inviarli ad AWS, quindi i dati arrivano già cifrati. Le opzioni di crittografia lato server cifrano i dati dopo che Amazon S3 li ha ricevuti, e HTTPS protegge i dati solo mentre transitano in rete.","optionExplanations":["SSE-S3 cifra i dati dopo che S3 li ha ricevuti, quindi AWS riceve comunque il testo in chiaro attraverso la connessione.","Corretto — la crittografia lato client garantisce che i dati siano cifrati prima di lasciare i server dell'azienda.","Anche SSE-KMS cifra i dati lato server dopo che S3 li ha ricevuti, il che non rispetta la policy.","HTTPS cifra solo i dati in transito; S3 riceve e gestisce comunque il contenuto non cifrato all'endpoint."]},
  "453": {"h":"25679ead","question":"Un'azienda ha spostato gran parte della logica applicativa su funzioni AWS Lambda e immagini di container archiviate in Amazon ECR. Vuole rilevare automaticamente le vulnerabilità software note in questi workload. Quale servizio AWS dovrebbe usare?","options":["Amazon Macie","AWS Artifact","Amazon Inspector","AWS Shield Standard"],"explanation":"Amazon Inspector analizza in modo automatico e continuo istanze EC2, immagini di container in Amazon ECR e funzioni AWS Lambda alla ricerca di vulnerabilità software note. Macie si concentra sull'individuazione di dati sensibili in S3, non sulle vulnerabilità software.","optionExplanations":["Macie individua dati sensibili come le PII in Amazon S3; non analizza il codice alla ricerca di vulnerabilità.","Artifact fornisce report di conformità e accordi AWS, non la scansione delle vulnerabilità.","Corretto — Inspector analizza funzioni Lambda e immagini di container in ECR alla ricerca di vulnerabilità software note.","Shield Standard protegge dagli attacchi DDoS più comuni e non analizza i pacchetti software."]},
  "454": {"h":"ca1a961a","question":"Un'azienda con molti account AWS in AWS Organizations vuole registrare centralmente l'attività API di tutti gli account, in modo che gli amministratori dei singoli account membri non possano disattivare o alterare la registrazione. Quale approccio soddisfa MEGLIO questo requisito?","options":["Creare un organization trail archiviato in un account di log archive","Chiedere a ogni amministratore di account di abilitare la cronologia eventi di CloudTrail","Abilitare Amazon Macie in ogni account membro","Usare AWS Trusted Advisor per raccogliere i log da ogni account"],"explanation":"Un organization trail creato dal management account registra l'attività di tutti gli account membri, e gli account membri non possono modificarlo né eliminarlo; recapitare i log in un account di log archive separato li protegge ulteriormente dalle manomissioni. Affidarsi alle impostazioni di ciascun account permetterebbe agli amministratori locali di modificarle.","optionExplanations":["Corretto — un organization trail copre ogni account membro, non può essere modificato dagli account membri e può archiviare i log in un account di archivio separato.","Affidarsi a ogni amministratore lascia la registrazione sotto controllo locale e non crea un archivio di log centrale e resistente alle manomissioni.","Macie individua dati sensibili in S3; non registra l'attività API.","Trusted Advisor fornisce controlli sulle best practice e non raccoglie né archivia log dell'attività API."]},
  "455": {"h":"dbc0b470","question":"Un amministratore di sistema vuole automatizzare la creazione di bucket Amazon S3 eseguendo comandi da script su una workstation locale. Quale strumento è il PIÙ appropriato?","options":["AWS Command Line Interface (AWS CLI)","AWS Management Console","AWS Health Dashboard","Controlli sulle best practice di AWS Trusted Advisor"],"explanation":"La AWS CLI è uno strumento a riga di comando unificato che consente di gestire i servizi AWS digitando comandi o eseguendoli da script di shell, il che la rende ideale per l'automazione. La AWS Management Console offre lo stesso tipo di controllo ma tramite browser web con interazione punta-e-clicca, quindi non è adatta allo scripting.","optionExplanations":["Corretto — La AWS CLI consente di chiamare le API dei servizi AWS da un terminale e da script, così le attività ripetitive come la creazione di bucket possono essere automatizzate.","La Management Console è un'interfaccia web grafica pensata per l'uso interattivo; non può essere pilotata da script locali.","L'AWS Health Dashboard mostra eventi e stato dei servizi che possono influire sull'account; non crea risorse.","AWS Trusted Advisor fornisce raccomandazioni sulle best practice; non effettua il provisioning di bucket S3."]},
  "456": {"h":"4d10b404","question":"Un team di sviluppo sta scrivendo un'applicazione Python che deve caricare file su Amazon S3 e leggere elementi da Amazon DynamoDB. Quale opzione consente agli sviluppatori di chiamare questi servizi direttamente dal codice dell'applicazione?","options":["Stack e template di AWS CloudFormation","AWS Software Development Kits (SDK)","AWS Elastic Beanstalk","AWS Systems Manager"],"explanation":"Gli AWS SDK forniscono librerie specifiche per linguaggio (Python, Java, JavaScript, .NET, Go e altri) che incapsulano le API AWS, così le applicazioni possono chiamare servizi come S3 e DynamoDB dal codice. CloudFormation effettua il provisioning dell'infrastruttura a partire da template, ma non viene usato dal codice applicativo per leggere o scrivere dati a runtime.","optionExplanations":["CloudFormation effettua il provisioning e la configurazione delle risorse a partire da template; non è una libreria usata dal codice in esecuzione per leggere e scrivere dati.","Corretto — Gli AWS SDK (come Boto3 per Python) offrono agli sviluppatori funzioni native del linguaggio per chiamare dal codice le API di S3, DynamoDB e altri servizi AWS.","Elastic Beanstalk distribuisce e gestisce applicazioni su AWS; non fornisce una libreria API per chiamare S3 o DynamoDB.","Systems Manager serve a gestire e operare istanze e server, non a dare al codice applicativo l'accesso alle API dei servizi."]},
  "457": {"h":"c06920c2","question":"Gli sviluppatori di un'azienda vogliono definire la propria infrastruttura AWS come codice usando un linguaggio di programmazione familiare, come TypeScript o Python, invece di scrivere template JSON o YAML. Quale servizio AWS dovrebbero usare?","options":["AWS CodeDeploy","AWS Service Catalog","AWS Cloud Development Kit (AWS CDK)","Amazon CodeGuru Reviewer e Profiler"],"explanation":"AWS CDK è un framework open source che consente agli sviluppatori di modellare l'infrastruttura cloud con linguaggi di programmazione familiari; il CDK poi sintetizza template AWS CloudFormation e li distribuisce. CodeDeploy automatizza i deployment delle applicazioni, ma non definisce l'infrastruttura sottostante.","optionExplanations":["CodeDeploy automatizza il deployment del codice applicativo sulle risorse di calcolo; non consente di definire l'infrastruttura in un linguaggio di programmazione.","AWS Service Catalog consente agli amministratori di pubblicare prodotti approvati che gli utenti possono avviare — non è un framework per definire l'infrastruttura con linguaggi di programmazione.","Corretto — AWS CDK consente di definire l'infrastruttura in linguaggi come TypeScript, Python, Java e C#, e genera dietro le quinte template CloudFormation.","Amazon CodeGuru fornisce revisioni del codice e raccomandazioni sulle prestazioni; non effettua il provisioning dell'infrastruttura."]},
  "458": {"h":"cc096291","question":"Un'azienda sanitaria in Germania deve mantenere tutti i dati dei pazienti entro i confini tedeschi a causa delle normative locali. Cosa dovrebbe fare l'azienda PER PRIMA COSA quando distribuisce i propri workload su AWS?","options":["Usare Amazon CloudFront per servire i dati da edge location in Germania","Abilitare la S3 Cross-Region Replication verso una Region fuori dall'Unione Europea","Distribuire su più Availability Zone in una qualsiasi Region a basso costo","Selezionare una AWS Region situata in Germania per archiviare ed elaborare i dati"],"explanation":"I requisiti di residenza dei dati e di conformità sono spesso il primo fattore nella scelta di una AWS Region, perché i dati archiviati in una Region vi restano a meno che il cliente non li sposti. Scegliere la Region di Francoforte (situata in Germania) soddisfa il requisito, mentre scegliere una Region solo per il basso costo potrebbe collocare i dati fuori dal Paese.","optionExplanations":["CloudFront memorizza in cache copie dei contenuti nelle edge location per una distribuzione più rapida; non determina dove vengono archiviati ed elaborati i dati di riferimento.","Replicare i dati in una Region fuori dall'UE sposterebbe i dati dei pazienti fuori dalla Germania, violando il requisito normativo.","Più AZ migliorano la disponibilità, ma scegliere una Region solo in base al prezzo ignora il requisito che i dati restino in Germania.","Corretto — I clienti AWS scelgono la Region in cui risiedono i propri dati, quindi selezionare una Region situata in Germania mantiene i dati entro i confini tedeschi."]},
  "459": {"h":"4849c125","question":"Un'azienda sta scegliendo quale AWS Region usare per una nuova applicazione rivolta ai clienti. Quali fattori dovrebbe considerare l'azienda nel prendere questa decisione? (Seleziona DUE)","options":["La vicinanza della Region agli utenti dell'applicazione","Il numero di utenti IAM nell'account dell'azienda","La disponibilità nella Region dei servizi e delle funzionalità AWS necessari","Il piano di AWS Support acquistato dall'azienda","Il numero di edge location nel mondo"],"explanation":"I fattori chiave nella scelta di una Region includono conformità e residenza dei dati, vicinanza agli utenti (latenza), disponibilità dei servizi e delle funzionalità necessari e prezzi, che variano da Region a Region. Utenti IAM e piani di Support sono a livello di account e globali, quindi non cambiano tra le Region.","optionExplanations":["Corretto — Collocare l'applicazione in una Region vicina agli utenti riduce la latenza di rete e migliora l'esperienza utente.","IAM è un servizio globale; il numero di utenti IAM non dipende dalla scelta della Region né la influenza.","Corretto — Non tutti i servizi o le funzionalità AWS sono disponibili in ogni Region, quindi l'azienda deve verificare che i servizi di cui ha bisogno siano offerti nella Region scelta.","Un piano di AWS Support si applica all'intero account, indipendentemente dalle Region utilizzate.","La rete globale di edge location è condivisa da tutte le Region, quindi non distingue una Region dall'altra."]},
  "460": {"h":"a56a1a11","question":"Un'azienda esegue la propria applicazione web su istanze Amazon EC2 in una singola Availability Zone. L'azienda vuole che l'applicazione continui a funzionare anche se un data center subisce un'interruzione. Cosa dovrebbe fare l'azienda?","options":["Passare a un tipo di istanza più grande nella stessa Availability Zone","Avviare istanze in almeno due Availability Zone dietro un load balancer","Archiviare i file statici dell'applicazione nelle edge location di Amazon CloudFront","Acquistare Reserved Instances per tutte le istanze nella Availability Zone"],"explanation":"Ogni Availability Zone è composta da uno o più data center distinti con alimentazione e rete indipendenti, quindi distribuire le istanze su più AZ (con un load balancer che ripartisce il traffico) protegge dal guasto di una AZ. Un'istanza più grande nella stessa AZ si guasta comunque se quella AZ subisce un'interruzione.","optionExplanations":["Un'istanza più grande nella stessa AZ resta un single point of failure se quella AZ diventa indisponibile.","Corretto — Eseguire istanze in due o più AZ dietro Elastic Load Balancing consente di indirizzare il traffico verso istanze integre se una AZ si guasta.","CloudFront può memorizzare in cache i contenuti statici, ma i server applicativi resterebbero comunque in una sola AZ.","Le Reserved Instances riducono i costi; non aggiungono ridondanza né proteggono da un'interruzione di una AZ."]},
  "461": {"h":"dd87b822","question":"Un'azienda media ha bisogno di una latenza nell'ordine di pochi millisecondi per le workstation di montaggio video in una grande città lontana dalla AWS Region più vicina. L'azienda vuole continuare a usare i servizi AWS. Quale opzione dell'infrastruttura AWS è la PIÙ adatta?","options":["Edge location di Amazon CloudFront","Una Availability Zone aggiuntiva nella Region più vicina","AWS Local Zones","Location di AWS Direct Connect"],"explanation":"Le AWS Local Zones collocano risorse di calcolo, storage e altri servizi AWS selezionati più vicino a grandi centri abitati e industriali, consentendo una latenza molto bassa per applicazioni come la produzione multimediale e il gaming. Le edge location di CloudFront memorizzano in cache e distribuiscono contenuti, ma non eseguono workload di calcolo generici come le istanze EC2 per il montaggio.","optionExplanations":["Le edge location servono principalmente a memorizzare in cache e distribuire contenuti; non ospitano workload di workstation basati su EC2.","I clienti non possono creare Availability Zone; le AZ esistono solo all'interno delle AWS Region, che in questo caso sono lontane dalla città.","Corretto — Le Local Zones estendono una AWS Region in un'area metropolitana, così i workload sensibili alla latenza possono essere eseguiti vicino agli utenti finali.","Le location di Direct Connect forniscono connettività di rete privata verso AWS; non eseguono risorse di calcolo vicino agli utenti."]},
  "462": {"h":"8e3b4672","question":"Un'azienda manifatturiera deve elaborare i dati nel proprio stabilimento con latenza molto bassa e non può spostare i dati all'esterno, ma vuole usare le stesse API e gli stessi strumenti AWS che usa nel cloud. Quale servizio AWS dovrebbe usare?","options":["AWS Outposts","AWS Storage Gateway","Amazon Lightsail","AWS Local Zones"],"explanation":"AWS Outposts porta infrastruttura e servizi progettati da AWS nel data center o nella struttura on-premises del cliente, così i workload possono essere eseguiti localmente con le stesse API, gli stessi strumenti e la stessa console AWS. Le Local Zones si trovano in strutture gestite da AWS, quindi i dati lascerebbero comunque lo stabilimento.","optionExplanations":["Corretto — Outposts porta infrastruttura, servizi e API AWS nella sede on-premises del cliente per esigenze di bassa latenza e residenza dei dati.","Storage Gateway collega le applicazioni on-premises allo storage cloud; non esegue servizi di calcolo AWS in loco.","Lightsail è un servizio cloud semplificato eseguito nelle AWS Region, non presso la sede del cliente.","Le Local Zones sono siti gestiti da AWS vicino alle aree metropolitane; i dati verrebbero comunque elaborati fuori dallo stabilimento."]},
  "463": {"h":"5db6742d","question":"Un'azienda prevede di eseguire un grande database in memoria su Amazon EC2. Il workload richiede molta RAM rispetto alla CPU. Quale categoria di famiglie di istanze EC2 è la PIÙ adatta?","options":["Ottimizzate per il calcolo","Ottimizzate per lo storage","Calcolo accelerato","Ottimizzate per la memoria"],"explanation":"Le istanze ottimizzate per la memoria sono progettate per offrire prestazioni elevate a workload che elaborano grandi insiemi di dati in memoria, come database in memoria e analisi big data in tempo reale. Le istanze ottimizzate per il calcolo privilegiano invece prestazioni CPU elevate rispetto alla memoria.","optionExplanations":["Le istanze ottimizzate per il calcolo offrono un rapporto CPU/memoria elevato, adatto all'elaborazione batch o a web server ad alte prestazioni, non a database che richiedono molta RAM.","Le istanze ottimizzate per lo storage sono progettate per un accesso sequenziale in lettura/scrittura elevato a grandi insiemi di dati locali, non principalmente per grandi quantità di RAM.","Le istanze a calcolo accelerato usano acceleratori hardware come le GPU, di cui un database in memoria non ha bisogno.","Corretto — Le istanze ottimizzate per la memoria offrono molta memoria per vCPU, il che è adatto ai database in memoria."]},
  "464": {"h":"1e9e0e07","question":"Un'azienda vuole eseguire container Docker su AWS usando un servizio di orchestrazione dei container AWS completamente gestito, ma deve poter scegliere i tipi di istanza EC2 specifici che ospitano i container. Quale opzione soddisfa questi requisiti?","options":["AWS Lambda","Amazon ECS con il launch type EC2","Amazon Elastic Container Registry (ECR)","AWS App Runner"],"explanation":"Amazon ECS è il servizio di orchestrazione dei container di AWS. Con il launch type EC2, i container vengono eseguiti su un cluster di istanze EC2 che il cliente sceglie e gestisce, mantenendo il controllo sui tipi di istanza; con il launch type Fargate, invece, è AWS a gestire le risorse di calcolo sottostanti.","optionExplanations":["Lambda esegue funzioni senza server e non consente di scegliere i tipi di istanza EC2 che ospitano il workload.","Corretto — ECS con il launch type EC2 orchestra i container su istanze EC2 selezionate dall'azienda, che mantiene così il controllo sui tipi di istanza.","Amazon ECR è un registry di immagini di container; archivia le immagini ma non esegue né orchestra i container.","App Runner astrae completamente l'infrastruttura, quindi l'azienda non può scegliere i tipi di istanza EC2 sottostanti."]},
  "465": {"h":"e492521c","question":"Un'azienda ha un'applicazione legacy che rimane in esecuzione continuativamente per settimane, richiede una configurazione personalizzata del sistema operativo e necessita di software installato a livello di sistema operativo. Quale servizio di calcolo è il PIÙ appropriato?","options":["AWS Lambda","AWS Fargate","Amazon EC2","AWS Step Functions"],"explanation":"Amazon EC2 fornisce server virtuali con pieno controllo sul sistema operativo, quindi è adatto ad applicazioni di lunga durata che richiedono personalizzazioni a livello di sistema operativo. Lambda è pensato per funzioni brevi e guidate dagli eventi, con una durata massima per invocazione e senza possibilità di configurare il sistema operativo sottostante.","optionExplanations":["Le funzioni Lambda hanno una durata massima di esecuzione per invocazione e non danno accesso al sistema operativo sottostante.","Fargate esegue container senza esporre il sistema operativo host, quindi non è possibile una configurazione a livello di sistema operativo.","Corretto — Le istanze EC2 offrono pieno controllo amministrativo sul sistema operativo e possono restare in esecuzione per tutto il tempo necessario.","Step Functions coordina workflow tra servizi; non è un ambiente di calcolo per ospitare un'applicazione."]},
  "466": {"h":"dc3466eb","question":"Un'azienda gestisce autonomamente un database MySQL su Amazon EC2. Il team operativo dedica troppo tempo a patching, backup e provisioning dell'hardware. Quale servizio ridurrebbe questo impegno operativo continuando a usare MySQL?","options":["Amazon RDS for MySQL","Amazon DynamoDB in modalità on-demand","Amazon Redshift","Amazon Neptune"],"explanation":"Amazon RDS è un servizio di database relazionale gestito che automatizza attività come provisioning dell'hardware, configurazione del database, patching e backup, e supporta il motore MySQL. Anche DynamoDB è gestito, ma è un database NoSQL, quindi l'applicazione andrebbe riprogettata.","optionExplanations":["Corretto — Amazon RDS for MySQL mantiene lo stesso motore di database mentre AWS si occupa di patching, backup automatici e provisioning.","DynamoDB è un database NoSQL chiave-valore e documentale, quindi migrarvi un'applicazione MySQL richiederebbe modifiche significative.","Redshift è un data warehouse per l'analisi, non un sostituto di un database MySQL transazionale.","Neptune è un database a grafo, che non corrisponde a un workload relazionale MySQL."]},
  "467": {"h":"62c9b27d","question":"Un'applicazione usa Amazon RDS. Query di reportistica pesanti vengono eseguite durante l'orario lavorativo e rallentano il database primario, che gestisce anche gli ordini dei clienti. Qual è il modo PIÙ appropriato per scaricare queste query di reportistica?","options":["Abilitare il deployment Multi-AZ e inviare le query all'istanza standby","Creare una read replica RDS e inviarle le query di reportistica","Spostare le tabelle del database su Amazon S3 Glacier","Aumentare la dimensione dello storage dell'istanza primaria"],"explanation":"Le read replica RDS sono copie in sola lettura del database primario che possono servire workload con molte letture, come la reportistica, riducendo il carico sul primario. In un deployment Multi-AZ standard, l'istanza standby esiste per il failover e non può servire traffico in lettura.","optionExplanations":["La standby in un deployment Multi-AZ standard viene usata solo per il failover e non accetta query in lettura.","Corretto — Una read replica riceve copie dei dati e può servire le query di reportistica, così il primario può concentrarsi sugli ordini.","S3 Glacier è uno storage di archiviazione; non può servire query di reportistica di un database.","Aggiungere storage non riduce il carico di query che la reportistica impone all'istanza primaria."]},
  "468": {"h":"279721e0","question":"Un'azienda deve scegliere tra Amazon RDS e Amazon DynamoDB per una nuova applicazione. Quali caratteristiche del workload farebbero preferire Amazon DynamoDB? (Seleziona DUE)","options":["L'applicazione richiede join SQL complessi tra molte tabelle correlate","L'applicazione deve essere eseguita su un motore di database Oracle","I dati hanno uno schema flessibile e vengono letti tramite chiave","Il team deve eseguire grandi report analitici su dati storici","Il workload deve scalare a volumi di richieste molto elevati con bassa latenza costante"],"explanation":"DynamoDB è un database NoSQL serverless chiave-valore e documentale, quindi è adatto a dati con schema flessibile letti tramite chiave e a workload che richiedono una scala enorme con latenza costante nell'ordine di pochi millisecondi. Join complessi e motori relazionali specifici come Oracle indicano Amazon RDS, mentre la grande reportistica analitica indica un data warehouse come Amazon Redshift.","optionExplanations":["I join complessi tra tabelle correlate sono un punto di forza dei database relazionali come Amazon RDS, non di DynamoDB.","Oracle è un motore relazionale disponibile su Amazon RDS; DynamoDB non esegue Oracle.","Corretto — DynamoDB archivia elementi senza uno schema fisso ed è ottimizzato per un accesso rapido tramite chiave.","La grande reportistica analitica su dati storici è più adatta a un data warehouse come Amazon Redshift.","Corretto — DynamoDB scala automaticamente a volumi di richieste molto elevati mantenendo una bassa latenza costante."]},
  "469": {"h":"226fb518","question":"Un'azienda sta progettando una VPC per un'applicazione a due livelli. I web server devono essere raggiungibili da internet, ma i server di database NON devono essere direttamente raggiungibili da internet. Dove dovrebbero essere collocati i server di database?","options":["In una subnet pubblica con una route verso un internet gateway","In una edge location di Amazon CloudFront","In una subnet privata senza route verso un internet gateway","Nella VPC predefinita di un altro account AWS nella stessa Region"],"explanation":"Una subnet privata non ha una route verso un internet gateway, quindi le risorse al suo interno non sono raggiungibili direttamente da internet: è la collocazione tipica dei database. Le subnet pubbliche hanno una route verso un internet gateway e vengono usate per risorse esposte a internet, come web server o load balancer.","optionExplanations":["Una subnet pubblica instrada verso un internet gateway, che è esattamente ciò che i server di database devono evitare.","Le edge location servono alla distribuzione dei contenuti e non possono ospitare server di database.","Corretto — Collocare i database in una subnet privata li rende irraggiungibili da internet, mentre il livello web può comunque connettersi a essi all'interno della VPC.","Spostare i database nella VPC predefinita di un altro account aggiunge complessità e non li rende di per sé privati."]},
  "470": {"h":"6ec911fa","question":"I dipendenti di un'azienda lavorano da casa e hanno bisogno di un accesso sicuro e cifrato dai propri laptop alle risorse all'interno di una Amazon VPC. Quale servizio AWS è progettato per questo caso d'uso?","options":["AWS Direct Connect","AWS Client VPN","AWS Transit Gateway","Amazon Route 53"],"explanation":"AWS Client VPN è un servizio VPN gestito basato su client che consente ai singoli utenti di connettersi in modo sicuro dai propri dispositivi alle risorse AWS. Direct Connect è una connessione privata dedicata tra una rete aziendale o un data center e AWS, non una soluzione per singoli laptop remoti.","optionExplanations":["Direct Connect collega la rete di un data center o di un ufficio ad AWS tramite una connessione dedicata; non serve i singoli laptop remoti.","Corretto — Client VPN offre agli utenti remoti connessioni cifrate dai propri dispositivi verso una VPC.","Transit Gateway collega VPC e reti on-premises tramite un hub centrale; non è un servizio VPN client per utenti remoti.","Route 53 è un servizio DNS; non crea connessioni cifrate per i lavoratori da remoto."]},
  "471": {"h":"14a7b1af","question":"Un'azienda ha due VPC nella stessa AWS Region: una per la propria applicazione e una per uno strumento di reportistica condiviso. L'azienda vuole che le istanze nelle due VPC comunichino usando indirizzi IP privati. Qual è il modo PIÙ SEMPLICE per ottenere questo risultato?","options":["Creare una connessione di VPC peering tra le due VPC","Collegare un internet gateway a entrambe le VPC","Configurare una AWS Site-to-Site VPN tra le due VPC","Configurare una distribuzione Amazon CloudFront"],"explanation":"Una connessione di VPC peering è una connessione di rete tra due VPC che consente di instradare il traffico tra loro usando indirizzi IP privati, ed è l'opzione più semplice per collegare solo due VPC. Transit Gateway diventa utile quando occorre collegare molte VPC e reti tramite un hub.","optionExplanations":["Corretto — Il VPC peering collega privatamente due VPC, così le istanze possono comunicare usando indirizzi IP privati.","Gli internet gateway forniscono l'accesso a internet; il traffico uscirebbe dalla rete privata e userebbe IP pubblici.","Una Site-to-Site VPN collega reti on-premises ad AWS; non è il modo semplice per collegare due VPC.","CloudFront è una content delivery network e non fornisce instradamento privato tra VPC."]},
  "472": {"h":"bd4fc047","question":"Un'azienda archivia file di log in Amazon S3. I log vengono consultati spesso durante i primi 30 giorni, raramente in seguito, e devono essere eliminati dopo 5 anni. Come può l'azienda gestire tutto questo automaticamente con il MINOR impegno operativo?","options":["Scrivere uno script personalizzato su un'istanza Amazon EC2 che sposta ed elimina gli oggetti","Abilitare S3 Versioning sul bucket","Usare la S3 Cross-Region Replication verso un altro bucket","Creare una configurazione S3 Lifecycle per la transizione e la scadenza degli oggetti"],"explanation":"Le regole S3 Lifecycle possono spostare automaticamente gli oggetti verso classi di storage più economiche dopo un numero definito di giorni e farli scadere (eliminarli) quando non servono più. Uno script personalizzato potrebbe fare lo stesso, ma aggiunge server e codice da mantenere.","optionExplanations":["Uno script personalizzato su EC2 funziona ma aggiunge infrastruttura e codice da mantenere, quindi non è l'opzione con il minor impegno.","Il versioning conserva più versioni degli oggetti; non li sposta in classi più economiche né li elimina secondo una pianificazione.","La Cross-Region Replication copia gli oggetti in un altro bucket; aumenta lo storage invece di spostare o eliminare i dati.","Corretto — Le regole Lifecycle possono spostare i log in una classe di storage più economica dopo 30 giorni ed eliminarli dopo 5 anni senza alcun lavoro manuale continuativo."]},
  "473": {"h":"f8a24147","question":"Un'azienda finanziaria deve conservare i dati dei conti chiusi per 10 anni per rispettare le normative. I dati non verranno quasi mai letti, e un recupero entro 12 ore è accettabile. Quale classe di storage Amazon S3 è la PIÙ conveniente?","options":["S3 Standard-Infrequent Access","S3 Glacier Deep Archive","S3 Glacier Instant Retrieval","S3 Intelligent-Tiering"],"explanation":"S3 Glacier Deep Archive è la classe di storage S3 dal costo più basso ed è progettata per la conservazione a lungo termine di dati consultati raramente, con un recupero tipicamente entro 12 ore. Glacier Instant Retrieval restituisce i dati in millisecondi, ma l'archiviazione costa più di Deep Archive, il che qui non è necessario.","optionExplanations":["Standard-IA offre accesso immediato a un prezzo di archiviazione più alto, cosa non necessaria per dati che non vengono quasi mai letti.","Corretto — Glacier Deep Archive ha il costo di archiviazione più basso in S3 e i suoi tempi di recupero rientrano nel requisito delle 12 ore.","Glacier Instant Retrieval offre accesso in millisecondi, una caratteristica di cui l'azienda non ha bisogno, a un costo di archiviazione superiore a Deep Archive.","Intelligent-Tiering è ideale per modelli di accesso sconosciuti o variabili; per dati notoriamente da archiviare, Deep Archive è più economico."]},
  "474": {"h":"3c10b781","question":"Un'azienda archivia immagini in miniatura che possono essere facilmente rigenerate dagli originali. Le miniature vengono consultate raramente, ma devono essere disponibili immediatamente quando richieste. Quale classe di storage S3 è la PIÙ conveniente?","options":["S3 One Zone-Infrequent Access","S3 Standard","S3 Glacier Deep Archive","S3 Glacier Flexible Retrieval con recuperi bulk"],"explanation":"S3 One Zone-IA archivia i dati in una singola Availability Zone a un costo inferiore rispetto a Standard-IA, il che è adatto a dati consultati raramente che possono essere ricreati se quella AZ viene persa. Offre comunque accesso in millisecondi, a differenza delle classi di archiviazione Glacier che richiedono tempo per il recupero.","optionExplanations":["Corretto — One Zone-IA è più economica perché i dati sono conservati in una sola AZ, un rischio accettabile per miniature ricreabili che richiedono comunque accesso immediato.","S3 Standard è progettata per dati consultati di frequente e costa più delle classi ad accesso infrequente.","I recuperi da Deep Archive richiedono ore, il che non soddisfa l'esigenza di accesso immediato.","Glacier Flexible Retrieval richiede un ripristino che dura da minuti a ore, quindi l'accesso non è immediato."]},
  "475": {"h":"5dc787ee","question":"Un'azienda vuole eseguire backup point-in-time dei volumi Amazon EBS collegati alle proprie istanze EC2, in modo da poterli ripristinare in seguito o creare nuovi volumi a partire da essi. Quale funzionalità dovrebbe usare l'azienda?","options":["EC2 instance store","Replica di Amazon EFS","Snapshot di Amazon EBS","S3 Transfer Acceleration"],"explanation":"Gli snapshot di Amazon EBS sono backup incrementali point-in-time dei volumi EBS, archiviati in modo durevole in Amazon S3 (gestito da AWS), che possono essere usati per ripristinare o creare nuovi volumi. L'instance store è uno storage a blocchi temporaneo e non è un meccanismo di backup.","optionExplanations":["L'instance store è uno storage temporaneo fisicamente collegato all'host, e i suoi dati vanno persi quando l'istanza viene arrestata; non è una funzionalità di backup.","La replica di EFS copia file system EFS, non volumi EBS.","Corretto — Gli snapshot EBS catturano lo stato di un volume in un determinato momento e possono essere usati per ripristinare o creare nuovi volumi.","Transfer Acceleration velocizza i caricamenti su S3 su lunghe distanze; non esegue il backup dei volumi EBS."]},
  "476": {"h":"d16adcc3","question":"Un team di ricerca esegue simulazioni di high performance computing (HPC) che richiedono un file system condiviso con throughput molto elevato per molti nodi di calcolo contemporaneamente. Quale servizio di storage AWS è progettato per questo tipo di workload?","options":["Amazon FSx for Windows File Server","Amazon S3 Glacier Flexible Retrieval","AWS Storage Gateway","Amazon FSx for Lustre"],"explanation":"Amazon FSx for Lustre fornisce un file system ad alte prestazioni completamente gestito, basato sul file system open source Lustre, usato per HPC, machine learning ed elaborazione multimediale che richiedono un accesso condiviso rapido. FSx for Windows File Server è rivolto a workload Windows che usano il protocollo SMB, non al throughput HPC.","optionExplanations":["FSx for Windows File Server è pensato per applicazioni Windows che richiedono SMB e Active Directory, non per cluster HPC.","Glacier Flexible Retrieval è uno storage di archiviazione con ritardi di recupero e non è un file system per nodi di calcolo.","Storage Gateway collega ambienti on-premises allo storage AWS; non è un file system ad alto throughput per HPC.","Corretto — FSx for Lustre offre il throughput molto elevato e l'accesso condiviso richiesti dalle simulazioni HPC."]},
  "477": {"h":"44089f1a","question":"Uno sviluppatore sta valutando l'instance store di Amazon EC2 per dati temporanei. Quali affermazioni sull'instance store sono corrette? (Seleziona DUE)","options":["I dati vanno persi quando l'istanza viene arrestata o terminata","I dati vengono replicati automaticamente in un'altra Availability Zone","Il volume può essere scollegato e collegato a un'altra istanza","Lo storage è fisicamente collegato al computer host","L'instance store è lo stesso servizio di Amazon EFS"],"explanation":"L'instance store fornisce storage a blocchi temporaneo su dischi fisicamente collegati al computer host, il che garantisce una latenza molto bassa. I suoi dati non persistono quando l'istanza viene arrestata, ibernata o terminata, quindi è adatto a cache, buffer e dati temporanei, non a dati che devono essere conservati.","optionExplanations":["Corretto — L'instance store è effimero, quindi i suoi dati vanno persi quando l'istanza viene arrestata o terminata.","L'instance store non è replicato tra AZ; uno storage durevole e replicato richiede servizi come snapshot EBS, EFS o S3.","I volumi instance store non possono essere scollegati e spostati su un'altra istanza, a differenza dei volumi EBS.","Corretto — I dischi dell'instance store sono fisicamente collegati all'host che esegue l'istanza.","Amazon EFS è un file system di rete gestito condiviso da molte istanze; è un servizio distinto dall'instance store."]},
  "478": {"h":"2f07c811","question":"Gli analisti di business di un'azienda retail vogliono creare dashboard interattive e visualizzazioni dei dati di vendita senza gestire alcun server. Quale servizio AWS dovrebbero usare?","options":["Amazon QuickSight","Amazon Athena","AWS Glue","Amazon EMR"],"explanation":"Amazon QuickSight è un servizio di business intelligence serverless su scala cloud per creare dashboard e visualizzazioni interattive. Athena può interrogare i dati con SQL, ma non fornisce dashboard per gli utenti di business.","optionExplanations":["Corretto — QuickSight è il servizio di business intelligence di AWS per creare dashboard interattive e report visivi.","Athena esegue query SQL sui dati in S3, ma da solo non crea dashboard né report visivi.","Glue prepara e cataloga i dati tramite job ETL; non crea visualizzazioni per gli analisti.","EMR esegue framework big data come Spark e Hadoop; non è uno strumento per creare dashboard."]},
  "479": {"h":"4722fffd","question":"Un'azienda vuole acquisire dati di clickstream in streaming e recapitarli automaticamente in Amazon S3 per un'analisi successiva, senza scrivere né gestire applicazioni consumer personalizzate. Quale servizio AWS è il PIÙ adatto?","options":["Code standard di Amazon SQS","Amazon Data Firehose","Topic di Amazon SNS","AWS Batch"],"explanation":"Amazon Data Firehose (in precedenza Amazon Kinesis Data Firehose) è un servizio completamente gestito che acquisisce dati in streaming e li recapita a destinazioni come Amazon S3, Amazon Redshift e Amazon OpenSearch Service. Anche Kinesis Data Streams serve per i dati in streaming, ma normalmente richiede di sviluppare applicazioni consumer per elaborare lo stream.","optionExplanations":["SQS è una coda di messaggi per disaccoppiare i componenti; non recapita automaticamente dati in streaming su S3.","Corretto — Data Firehose acquisisce dati in streaming e li carica in destinazioni come S3 senza codice consumer da gestire.","SNS è un servizio di notifica publish/subscribe, non un servizio di recapito di dati in streaming su S3.","AWS Batch esegue job di calcolo batch; non acquisisce né recapita continuamente dati in streaming."]},
  "480": {"h":"e7c4b1b1","question":"Un'azienda archivia file di log applicativi in formato CSV in Amazon S3. Gli analisti vogliono eseguire query SQL direttamente su questi file e poi visualizzare i risultati in dashboard interattive, usando servizi serverless. Quali servizi AWS andrebbero usati insieme? (Seleziona DUE)","options":["Amazon Neptune","Amazon Athena","Amazon Kinesis Data Streams","Amazon QuickSight","Amazon EC2"],"explanation":"Amazon Athena esegue query SQL standard direttamente sui dati in Amazon S3 senza caricarli in un database, e Amazon QuickSight può usare Athena come origine dati per creare dashboard. Entrambi sono serverless, quindi non c'è infrastruttura da gestire.","optionExplanations":["Neptune è un database a grafo per dati altamente connessi; non interroga file CSV in S3.","Corretto — Athena interroga i file CSV in S3 con SQL, senza server da gestire.","Kinesis Data Streams acquisisce dati in streaming in tempo reale; i log sono già archiviati in S3.","Corretto — QuickSight si collega ad Athena e trasforma i risultati delle query in dashboard interattive.","EC2 richiederebbe la gestione di server, il che è in contrasto con il requisito serverless."]},
  "481": {"h":"b5db9c33","question":"Un negozio online riceve recensioni dei prodotti in molte lingue e vuole convertirle automaticamente in inglese affinché il team di supporto possa leggerle. Quale servizio AWS dovrebbe usare l'azienda?","options":["Amazon Polly","Amazon Lex","Amazon Textract","Amazon Translate"],"explanation":"Amazon Translate è un servizio di traduzione automatica neurale che traduce testi da una lingua all'altra. Amazon Polly trasforma il testo in voce ma non cambia la lingua del testo.","optionExplanations":["Polly converte il testo in voce realistica; non traduce testi tra lingue.","Lex crea chatbot conversazionali; non è progettato per tradurre recensioni scritte.","Textract estrae testo e dati da documenti scansionati; non traduce il testo che individua.","Corretto — Amazon Translate traduce automaticamente il testo da una lingua a un'altra, ad esempio le recensioni in inglese."]},
  "482": {"h":"1f734ec2","question":"Una startup vuole aggiungere alla propria applicazione funzionalità di AI generativa, come il riassunto di testi, chiamando foundation model di diversi provider di AI tramite un'unica API, senza gestire alcuna infrastruttura. Quale servizio AWS dovrebbe usare?","options":["Amazon Comprehend","Amazon Rekognition","Amazon Bedrock","Amazon Kendra"],"explanation":"Amazon Bedrock è un servizio completamente gestito che fornisce accesso a foundation model di Amazon e di aziende leader nell'AI tramite un'unica API, così gli sviluppatori possono creare applicazioni di AI generativa senza gestire infrastruttura. Amazon Comprehend offre funzionalità predefinite di elaborazione del linguaggio naturale, come l'analisi del sentiment, ma non è una piattaforma per usare foundation model.","optionExplanations":["Comprehend svolge attività di NLP come il rilevamento di sentiment ed entità; non fornisce accesso a più foundation model.","Rekognition analizza immagini e video; non è un servizio di AI generativa per il riassunto di testi.","Corretto — Bedrock offre accesso serverless a una scelta di foundation model tramite un'unica API per casi d'uso di AI generativa.","Kendra è un servizio di ricerca aziendale intelligente, non un servizio per chiamare foundation model di provider diversi."]},
  "483": {"h":"d163031d","question":"Gli sviluppatori di un'azienda vogliono un assistente basato sull'AI generativa che suggerisca codice nel loro IDE, spieghi il codice e risponda a domande sullo sviluppo su AWS. Quale servizio AWS offre tutto questo?","options":["Amazon Q Developer","AWS CodeBuild","Amazon SageMaker","AWS X-Ray"],"explanation":"Amazon Q Developer è un assistente basato sull'AI generativa che aiuta gli sviluppatori a scrivere, spiegare e trasformare codice e risponde a domande su AWS, anche all'interno degli IDE più diffusi. SageMaker è una piattaforma per creare e addestrare i propri modelli di ML, non un assistente di programmazione pronto all'uso.","optionExplanations":["Corretto — Amazon Q Developer fornisce suggerimenti di codice basati sull'AI e risposte su AWS direttamente nell'IDE dello sviluppatore e nella console.","CodeBuild compila il codice ed esegue i test in un servizio di build gestito; non suggerisce codice.","SageMaker serve a creare, addestrare e distribuire modelli di ML personalizzati, non a fungere da assistente di programmazione pronto all'uso.","X-Ray traccia le richieste attraverso applicazioni distribuite; non genera né spiega codice."]},
  "484": {"h":"a88b281a","question":"Un call center vuole convertire in testo le chiamate registrate dei clienti e poi determinare se il tono di ciascun cliente era positivo o negativo. Quali servizi AWS andrebbero combinati? (Seleziona DUE)","options":["Amazon Polly","Amazon Transcribe","Amazon Rekognition","Amazon Textract","Amazon Comprehend"],"explanation":"Amazon Transcribe converte in testo il parlato delle registrazioni audio, e Amazon Comprehend usa l'elaborazione del linguaggio naturale per rilevare il sentiment in quel testo. Polly fa l'opposto di Transcribe, trasformando il testo in voce.","optionExplanations":["Polly converte il testo in voce, l'opposto di ciò di cui il call center ha bisogno.","Corretto — Transcribe esegue il riconoscimento vocale automatico, producendo trascrizioni testuali dalle registrazioni delle chiamate.","Rekognition analizza immagini e video, non l'audio né il sentiment del testo.","Textract estrae testo da documenti e moduli scansionati, non da registrazioni audio.","Corretto — Comprehend analizza le trascrizioni e determina il sentiment, ad esempio positivo, negativo, neutro o misto."]},
  "485": {"h":"5e5c7ed0","question":"Un'azienda vuole eseguire automaticamente una funzione AWS Lambda ogni notte alle 2:00 per ripulire i file temporanei, senza gestire alcun server. Quale servizio AWS può attivare la funzione secondo questa pianificazione?","options":["Amazon SQS","AWS Config","Amazon EventBridge","Amazon CloudFront"],"explanation":"Amazon EventBridge può invocare target come le funzioni Lambda secondo una pianificazione basata su espressioni cron o rate (tramite EventBridge Scheduler o regole pianificate), oltre che in risposta a eventi. SQS mantiene i messaggi in una coda ma non avvia job in base all'ora del giorno.","optionExplanations":["SQS accoda messaggi per i consumer; non ha un meccanismo integrato per avviare una funzione a un orario stabilito ogni notte.","AWS Config registra e valuta le configurazioni delle risorse; non è uno scheduler di job.","Corretto — EventBridge supporta pianificazioni in stile cron che possono invocare una funzione Lambda a un orario fisso ogni giorno.","CloudFront è una content delivery network e non può pianificare l'esecuzione di funzioni Lambda."]},
  "486": {"h":"b7cfd129","question":"L'applicazione di un'azienda è composta da molti microservizi, e gli utenti segnalano che alcune richieste sono lente. Gli sviluppatori vogliono tracciare ogni richiesta mentre attraversa i servizi per individuare dove si verifica il ritardo. Quale servizio AWS dovrebbero usare?","options":["AWS X-Ray","AWS CloudTrail","AWS Trusted Advisor","Amazon Inspector"],"explanation":"AWS X-Ray raccoglie dati sulle richieste mentre attraversano un'applicazione e mostra una mappa dei servizi e le tracce, aiutando gli sviluppatori a individuare colli di bottiglia e errori nei sistemi distribuiti. CloudTrail registra le chiamate API effettuate nell'account, utile per l'audit ma non per tracciare le richieste applicative.","optionExplanations":["Corretto — X-Ray traccia le richieste end-to-end attraverso i microservizi per mostrare dove si verificano latenza ed errori.","CloudTrail registra l'attività API di AWS a fini di audit; non traccia le richieste all'interno dell'applicazione.","Trusted Advisor fornisce controlli sulle best practice a livello di account; non analizza le singole richieste applicative.","Amazon Inspector analizza i workload alla ricerca di vulnerabilità software; non è uno strumento di tracciamento delle prestazioni."]},
  "487": {"h":"0d88c904","question":"Un amministratore vuole eseguire comandi AWS CLI da un browser web mentre è connesso alla AWS Management Console, senza installare o configurare nulla sul computer locale. Quale servizio AWS offre questa possibilità?","options":["AWS Systems Manager Session Manager","Amazon WorkSpaces","Amazon Lightsail","AWS CloudShell"],"explanation":"AWS CloudShell è una shell basata su browser avviata dalla Management Console, già autenticata con le credenziali della console dell'utente e fornita con la AWS CLI e gli strumenti più comuni preinstallati. Amazon WorkSpaces fornisce desktop virtuali completi, molto più di quanto serva per eseguire qualche comando CLI.","optionExplanations":["Session Manager apre sessioni shell sulle istanze gestite; non è un ambiente AWS CLI preconfigurato per l'utente connesso.","WorkSpaces fornisce desktop virtuali completi, il che non è necessario solo per eseguire comandi CLI da un browser.","Amazon Lightsail offre server virtuali semplici e pacchetti — non è una shell basata su browser per eseguire comandi AWS CLI dalla console.","Corretto — CloudShell apre nel browser una riga di comando già autenticata con la AWS CLI già installata."]},
  "488": {"h":"56f88993","question":"Un piccolo team di sviluppatori front-end vuole creare, distribuire e ospitare rapidamente un'applicazione web full-stack con funzionalità come l'accesso degli utenti e il continuous deployment basato su Git, senza una profonda esperienza nel cloud. Quale servizio AWS è progettato per questo?","options":["AWS Batch","AWS Amplify","Amazon EMR","AWS Outposts"],"explanation":"AWS Amplify fornisce strumenti e un servizio di hosting che consentono agli sviluppatori front-end web e mobile di creare, distribuire e ospitare applicazioni full-stack, inclusi autenticazione e CI/CD basata su Git. AWS Batch, invece, serve per eseguire job di calcolo batch su larga scala.","optionExplanations":["AWS Batch esegue job di calcolo batch; non è un framework per creare e ospitare applicazioni web.","Corretto — Amplify aiuta gli sviluppatori front-end a creare, collegare a un backend e ospitare applicazioni web e mobile full-stack con deployment basati su Git.","EMR elabora big data con framework come Spark e Hadoop; non ospita applicazioni web.","Outposts porta l'infrastruttura AWS on-premises; non semplifica la creazione e l'hosting di applicazioni front-end."]},
  "489": {"h":"2972ab48","question":"La spesa AWS di un'azienda è irregolare, quindi è difficile fissare soglie di budget. Il team finanziario vuole ricevere un avviso automatico quando la spesa mostra un picco insolito rispetto all'andamento normale. Quale servizio AWS dovrebbe usare?","options":["AWS Budgets","AWS Cost Anomaly Detection","AWS Cost and Usage Report","AWS Pricing Calculator"],"explanation":"AWS Cost Anomaly Detection usa il machine learning per apprendere l'andamento normale della spesa di un account e invia avvisi quando rileva picchi di costo insoliti, con un'analisi della causa principale. Anche AWS Budgets serve per gli avvisi, ma confronta la spesa con soglie definite manualmente.","optionExplanations":["AWS Budgets avvisa quando costi o utilizzo superano soglie impostate manualmente — non apprende l'andamento normale per rilevare anomalie.","Corretto — AWS Cost Anomaly Detection usa il machine learning per rilevare spese insolite e notificarle al team, senza soglie fisse.","L'AWS Cost and Usage Report fornisce i dati di fatturazione più dettagliati per l'analisi — non invia avvisi sui picchi di spesa.","L'AWS Pricing Calculator stima il costo delle architetture pianificate — non monitora la spesa effettiva."]},
  "490": {"h":"0fd62477","question":"Un'azienda usa AWS Organizations con la fatturazione consolidata per cinque account AWS. Quale account è responsabile del pagamento degli addebiti sostenuti da tutti gli account?","options":["Ogni account membro paga la propria fattura","L'account con l'utilizzo mensile più elevato","Il management account dell'organizzazione","Un account di fatturazione separato creato da AWS Support"],"explanation":"Con la fatturazione consolidata, il management account (in precedenza payer account) riceve un'unica fattura combinata e paga gli addebiti di tutti gli account membri. Gli account membri vedono comunque il proprio utilizzo, ma non pagano AWS separatamente.","optionExplanations":["Con la fatturazione consolidata, gli account membri non pagano AWS direttamente; i loro addebiti confluiscono in un'unica fattura.","Il volume di utilizzo non determina chi paga; il ruolo di pagatore spetta a un account specifico dell'organizzazione.","Corretto — Il management account paga l'utilizzo di tutti gli account membri dell'organizzazione.","AWS Support non crea account di fatturazione; è il management account dell'organizzazione a gestire il pagamento."]},
  "491": {"h":"17196397","question":"Un rivenditore AWS gestisce molti account di clienti in un'unica organizzazione. Vuole raggruppare gli account per cliente e mostrare a ciascun cliente una fattura basata sulle proprie tariffe personalizzate. Quale servizio AWS dovrebbe usare?","options":["AWS Billing Conductor","AWS Cost Explorer","AWS Pricing Calculator","AWS Budgets"],"explanation":"AWS Billing Conductor consente di raggruppare gli account in gruppi di fatturazione e di applicare regole di prezzo personalizzate per produrre fatture pro forma per showback o chargeback. Cost Explorer mostra i costi AWS effettivi ma non può applicare tariffe proprie per creare fatture specifiche per cliente.","optionExplanations":["Corretto — AWS Billing Conductor crea gruppi di fatturazione e applica tariffe personalizzate per produrre dati di fatturazione pro forma personalizzati.","Cost Explorer visualizza costi e utilizzo AWS effettivi, ma non può applicare le tariffe proprie di un rivenditore.","Il Pricing Calculator stima i costi futuri dei workload pianificati; non produce fatture per account esistenti.","AWS Budgets invia avvisi quando costi o utilizzo superano delle soglie; non crea fatture personalizzate."]},
  "492": {"h":"62f90332","question":"Un'azienda nota che indirizzi IP appartenenti ad AWS inviano spam e attaccano il suo sito web. Chi dovrebbe contattare l'azienda per segnalare questa attività?","options":["AWS Professional Services","Il TAM di AWS Enterprise Support","AWS Partner Network","Il team AWS Trust & Safety"],"explanation":"Il team AWS Trust & Safety gestisce le segnalazioni di abusi provenienti da risorse AWS, come spam, port scanning, attacchi denial-of-service o hosting di malware. Chiunque può segnalare sospetti abusi a questo team, anche senza un piano di supporto a pagamento.","optionExplanations":["AWS Professional Services aiuta i clienti con migrazioni e progetti; non indaga sulle segnalazioni di abuso.","Un Technical Account Manager supporta l'account Enterprise dell'azienda stessa e non è il canale per segnalare abusi da parte di altri utenti AWS.","L'AWS Partner Network è un programma di partner di consulenza e tecnologici, non un canale di segnalazione degli abusi.","Corretto — Il team AWS Trust & Safety indaga sulle segnalazioni di risorse AWS usate per attività abusive o illegali."]},
  "493": {"h":"edca7869","question":"Un retailer deve avere la certezza di poter avviare un numero specifico di istanze EC2 in una Availability Zone durante una promozione festiva di due settimane. Non vuole un impegno di 1 o 3 anni. Quale opzione soddisfa questi requisiti?","options":["Spot Instances in quella Availability Zone","On-Demand Capacity Reservations","Compute Savings Plans","Standard Reserved Instances"],"explanation":"Le On-Demand Capacity Reservations riservano capacità EC2 in una specifica Availability Zone per qualsiasi durata, senza impegno a lungo termine, e possono essere annullate in qualsiasi momento. Savings Plans e Reserved Instances riducono i costi ma richiedono un impegno di 1 o 3 anni, e i Savings Plans non riservano capacità.","optionExplanations":["Le Spot Instances possono essere interrotte quando AWS ha bisogno della capacità, quindi non possono garantire capacità durante la promozione.","Corretto — Le On-Demand Capacity Reservations garantiscono capacità in una Availability Zone scelta senza impegno a lungo termine.","I Compute Savings Plans richiedono un impegno di 1 o 3 anni e forniscono uno sconto, non capacità riservata.","Le Standard Reserved Instances richiedono una durata di 1 o 3 anni, che il retailer non vuole per un evento di due settimane."]},
  "494": {"h":"36bad2d7","question":"Un'azienda eseguirà la stessa famiglia di istanze EC2 in una singola AWS Region per i prossimi tre anni, ma le dimensioni delle istanze potrebbero cambiare. Quale Savings Plan offre lo sconto MAGGIORE per questo utilizzo?","options":["EC2 Instance Savings Plans","Compute Savings Plans","Amazon SageMaker Savings Plans","AWS Lambda Savings Plans"],"explanation":"Gli EC2 Instance Savings Plans offrono lo sconto più alto tra i Savings Plans in cambio dell'impegno su una famiglia di istanze in una Region, consentendo comunque di cambiare dimensione, sistema operativo e tenancy. I Compute Savings Plans sono più flessibili tra famiglie, Region, Fargate e Lambda, ma il loro sconto è inferiore.","optionExplanations":["Corretto — Gli EC2 Instance Savings Plans offrono lo sconto più elevato tra i Savings Plans per una famiglia di istanze fissa in una Region.","I Compute Savings Plans aggiungono una flessibilità di cui l'azienda non ha bisogno e offrono uno sconto inferiore.","I SageMaker Savings Plans si applicano solo all'utilizzo di Amazon SageMaker, non alle istanze EC2 generiche.","Non esiste un Savings Plan separato per Lambda; l'utilizzo di Lambda è coperto dai Compute Savings Plans, e qui non è rilevante per le istanze EC2."]},
  "495": {"h":"10386824","question":"Un'azienda sospetta che molte delle sue istanze EC2 e dei suoi volumi EBS siano più grandi del necessario. Quale servizio AWS analizza le metriche di utilizzo e raccomanda risorse dimensionate meglio?","options":["AWS Budgets","AWS Pricing Calculator","AWS Compute Optimizer","AWS Cost and Usage Report"],"explanation":"AWS Compute Optimizer applica il machine learning ai dati storici di utilizzo per raccomandare il corretto dimensionamento di istanze EC2, Auto Scaling group, volumi EBS, funzioni Lambda e altro. Il Cost and Usage Report fornisce dati di fatturazione dettagliati ma non genera raccomandazioni di dimensionamento.","optionExplanations":["AWS Budgets invia avvisi su soglie di spesa o utilizzo; non analizza l'utilizzo delle risorse per raccomandarne le dimensioni.","Il Pricing Calculator stima i costi delle architetture pianificate; non esamina l'utilizzo delle risorse in esecuzione.","Corretto — AWS Compute Optimizer raccomanda le dimensioni ottimali delle risorse in base alle metriche di utilizzo effettive.","Il Cost and Usage Report contiene voci di fatturazione dettagliate ma non fornisce raccomandazioni di right-sizing."]},
  "496": {"h":"6bd926b0","question":"Un retailer esegue su AWS workload critici per il business e sta preparando il lancio di un prodotto importante. Vuole che il proprio piano di AWS Support includa un aiuto consulenziale, come il supporto per questo evento di lancio pianificato, le Well-Architected review e una revisione proattiva della sicurezza. Quale opzione soddisfa questi requisiti?","options":["Basic Support","AWS Business Support+","AWS Enterprise Support","La community AWS re:Post"],"explanation":"Enterprise Support è progettato per workload critici per il business e include revisioni consulenziali: Well-Architected review, revisioni proattive della sicurezza, supporto per eventi pianificati e lanci e un piano di supporto strategico. Fornisce inoltre un Technical Account Manager dedicato, mentre Basic Support e Business Support+ non includono queste revisioni consulenziali.","optionExplanations":["Basic Support fornisce assistenza clienti, documentazione e i controlli principali di Trusted Advisor, ma nessuna revisione consulenziale né supporto ai lanci.","Business Support+ offre supporto tecnico 24/7 e indicazioni architetturali per i workload di produzione, ma le revisioni consulenziali e il supporto agli eventi pianificati sono funzionalità di Enterprise Support.","Corretto — Enterprise Support include revisioni consulenziali come le Well-Architected review, le revisioni proattive della sicurezza e il supporto a eventi pianificati e lanci.","re:Post fornisce risposte della community alle domande. Non offre revisioni strutturate né supporto ai lanci per i workload dell'azienda."]},
  "497": {"h":"c7bd236b","question":"Una grande azienda sta pianificando una complessa migrazione del data center e vuole lavorare direttamente con un team globale di esperti dipendenti di AWS. Quale offerta AWS dovrebbe coinvolgere?","options":["AWS Marketplace Professional Services","AWS Marketplace","AWS Professional Services","Consulenti dell'AWS Partner Network (APN)"],"explanation":"AWS Professional Services è un team globale di esperti AWS che aiuta i clienti a raggiungere risultati di business come grandi migrazioni, spesso lavorando al fianco degli AWS Partner.","optionExplanations":["AWS Marketplace Professional Services elenca consulenti e fornitori di servizi di terze parti; l'azienda vuole esperti dipendenti di AWS stessa.","AWS Marketplace è un catalogo per acquistare software e servizi di terze parti, non un rapporto diretto con gli esperti di AWS.","Corretto — AWS Professional Services è il team di esperti di AWS che aiuta i clienti in grandi iniziative come le migrazioni.","I partner di consulenza APN sono aziende terze, non esperti dipendenti direttamente da AWS."]},
  "498": {"h":"216eadbc","question":"Le regole di conformità di un'azienda richiedono che le sue istanze EC2 vengano eseguite su hardware non condiviso con altri clienti AWS. L'azienda non ha bisogno di controllare il posizionamento delle istanze su specifici server fisici né di licenze legate al server. Quale opzione è la PIÙ conveniente?","options":["Dedicated Hosts","Dedicated Instances","Spot Instances","On-Demand Capacity Reservations"],"explanation":"Le Dedicated Instances vengono eseguite su hardware dedicato a un singolo cliente, il che soddisfa il requisito di isolamento senza pagare un intero server fisico. Anche i Dedicated Hosts forniscono isolamento, ma aggiungono visibilità e controllo a livello di host per le licenze software legate al server, di cui l'azienda non ha bisogno.","optionExplanations":["I Dedicated Hosts forniscono un intero server fisico con controllo a livello di host per le licenze, il che costa più del necessario in questo caso.","Corretto — Le Dedicated Instances soddisfano il requisito di hardware single-tenant senza il costo aggiuntivo di un intero Dedicated Host.","Le Spot Instances vengono eseguite per impostazione predefinita su hardware condiviso e possono essere interrotte, quindi non rispettano la regola di conformità.","Le Capacity Reservations garantiscono capacità ma non forniscono di per sé hardware dedicato a un unico cliente."]},
  "499": {"h":"c380bb9e","question":"Un'azienda sta esaminando gli addebiti per il trasferimento dati nella propria fattura AWS. Quali tipi di trasferimento dati comportano tipicamente un addebito? (Seleziona DUE)","options":["Dati trasferiti da Amazon EC2 verso internet","Dati trasferiti in Amazon EC2 da internet","Dati trasferiti tra EC2 e Amazon S3 nella stessa Region","Dati trasferiti tra due AWS Region diverse","Dati caricati dall'ambiente on-premises in Amazon S3 tramite internet"],"explanation":"AWS in genere non addebita i dati trasferiti in AWS da internet, ma addebita i dati trasferiti verso internet e i dati trasferiti tra AWS Region. Anche il trasferimento dati tra EC2 e S3 all'interno della stessa Region è generalmente gratuito.","optionExplanations":["Corretto — I dati trasferiti da AWS verso internet vengono addebitati.","Il trasferimento dati in ingresso da internet verso AWS è generalmente gratuito.","Il trasferimento dati tra Amazon EC2 e Amazon S3 all'interno della stessa Region generalmente non viene addebitato.","Corretto — I dati trasferiti tra AWS Region comportano addebiti per il trasferimento dati.","Il caricamento di dati in Amazon S3 da internet è un trasferimento in ingresso, generalmente gratuito."]},
  "500": {"h":"15f8305f","question":"Un'applicazione web ha un utilizzo di base costante di EC2 tutto l'anno, più picchi di traffico imprevedibili per alcuni giorni ogni mese. L'azienda vuole ridurre i costi senza rischiare interruzioni. Quali DUE azioni dovrebbe intraprendere? (Seleziona DUE)","options":["Eseguire il carico di base su Spot Instances","Coprire il carico di base con un Savings Plan","Acquistare Reserved Instances dimensionate per i picchi","Spostare tutte le istanze su Dedicated Hosts","Usare On-Demand Instances per i picchi"],"explanation":"Una strategia di costo comune consiste nel coprire l'utilizzo costante e prevedibile con uno sconto basato su impegno, come un Savings Plan, e nel gestire i picchi brevi e imprevedibili con On-Demand Instances, che non richiedono impegno. Le Spot Instances potrebbero essere interrotte, e dimensionare gli impegni sull'utilizzo di picco lascerebbe capacità pagata inutilizzata per gran parte del mese.","optionExplanations":["Le Spot Instances possono essere interrotte, quindi non sono adatte a un carico di base che deve funzionare senza interruzioni.","Corretto — Un Savings Plan offre uno sconto per un utilizzo di base costante e prevedibile in cambio di un impegno di 1 o 3 anni.","Reserved Instances dimensionate per i picchi resterebbero sottoutilizzate per gran parte del mese, sprecando l'impegno.","I Dedicated Hosts costano di più e sono pensati per esigenze di isolamento o di licenza, non per ridurre i costi.","Corretto — Le On-Demand Instances gestiscono picchi brevi e imprevedibili senza impegno a lungo termine."]},
};
